// Fiches de départ du guide d'animation (chargées à la demande par index.html)
window.ANIMATION_SEED = {"fiches": {"JSP2|Les règles et précautions d'emploi des tuyaux": {"cycle": "JSP2", "bloc": "Eteindre un incendie", "item": "Les règles et précautions d'emploi des tuyaux", "objectif": "Citer le rôle et le rangement de chaque tuyau, puis repérer et corriger en binôme au moins 5 erreurs sur un établissement piégé en 10 min.", "pointsCles": ["Le chemin de l'eau : point d'eau → engin-pompe → division → lance", "Alimentation (point d'eau → engin) : Ø110 ou Ø70 · manœuvre (engin → division) : Ø70 · attaque (division → lance) : Ø45 ou Ø25", "Lecture : Ø45/20 m = diamètre intérieur 45 mm, longueur 20 m", "Rangements : Ø25 semi-rigide sur le dévidoir tournant · Ø45 en écheveau Z ou O · Ø70/20 en écheveau Z · Ø70/40 sur le dévidoir mobile · Ø110/20 en couronne double", "Le moins de tuyaux possible : chaque tuyau en plus fait perdre de la pression", "Pas de plis, de coudes ni de torsions : l'eau passe mal", "Une réserve au point d'attaque pour pouvoir avancer avec la lance", "Le long des murs et des trottoirs, sans enchevêtrement, traversées de route protégées par un dispositif de franchissement", "Protéger les tuyaux des débris coupants", "Après usage : rincer, contrôler (coupures, raccords), faire sécher, remplacer par des tuyaux secs"], "materiel": "FPTGP (ou CCFU) : tuyaux Ø25 du dévidoir tournant, Ø45/20 en Z et en O, Ø70/20 en Z, Ø70/40 du dévidoir mobile, Ø110/20, division d'alimentation, LDV 40 · dispositif de franchissement · plots, 2 seaux, chrono.", "activites": [{"titre": "Le chemin de l'eau", "duree": "10 min", "prep": "Tous les tuyaux sortis et posés en vrac, 3 pancartes : ALIMENTATION / MANŒUVRE / ATTAQUE.", "deroule": ["Les JSP dessinent au sol (plots) le chemin point d'eau → engin → division → lance.", "Par binôme, ils prennent un tuyau, lisent son diamètre et sa longueur.", "Ils le posent sous la bonne pancarte et disent comment il est rangé (Z, O, couronne, dévidoir)."], "phrase": "Chaque tuyau a sa place sur le chemin de l'eau.", "securite": ""}, {"titre": "Chasse aux erreurs", "duree": "15 min", "prep": "Un établissement de l'engin à une LDV 40 avec 6 pièges : tuyau plié, torsion, sur des débris coupants, en travers de la route sans protection, enchevêtré avec un autre, pas de réserve à la lance.", "deroule": ["Chaque binôme a 2 min pour trouver une erreur.", "Il explique le risque (moins d'eau, tuyau percé ou écrasé…).", "Il la corrige. On passe au binôme suivant."], "phrase": "Chaque erreur, c'est moins d'eau pour le binôme à la lance.", "securite": "Sans eau. Gilet haute visibilité si l'exercice est près d'une voie."}, {"titre": "Relais du débit", "duree": "15 min", "prep": "2 établissements identiques en Ø45 (l'un avec un pli et une torsion volontaires), 2 seaux, chrono.", "deroule": ["Deux équipes, une par établissement.", "Mise en eau à faible pression, ouverture progressive par l'animateur : chacun remplit son seau.", "On compare les temps : « Pourquoi l'équipe B est plus lente ? »", "Les JSP trouvent les défauts, les corrigent et on refait un essai."], "phrase": "Ce seau qui se remplit lentement, c'est ton binôme qui manque d'eau.", "securite": "Pression faible, animateur au refoulement. Personne devant la lance, jamais de jet vers une personne."}, {"titre": "Reconditionner les tuyaux", "duree": "5 min", "prep": "Les tuyaux mouillés de l'atelier précédent.", "deroule": ["Rincer, contrôler les raccords et chercher les coupures.", "Mettre à sécher et remettre des tuyaux secs dans l'engin."], "phrase": "", "securite": "Gants."}], "questions": [{"q": "Quels sont les 3 types d'établissement ?", "r": "Alimentation, manœuvre, attaque."}, {"q": "Quels tuyaux pour l'alimentation ?", "r": "Ø110 ou Ø70, du point d'eau à l'engin-pompe."}, {"q": "Quels tuyaux pour l'attaque ?", "r": "Ø45 ou Ø25, de la division (ou de l'engin) à la lance."}, {"q": "Que veut dire Ø45/20 m ?", "r": "Diamètre intérieur 45 mm, longueur 20 m."}, {"q": "Comment est rangé un tuyau de Ø70/20 m ?", "r": "Plié en écheveau Z."}, {"q": "Pourquoi utiliser le moins de tuyaux possible ?", "r": "Chaque tuyau en plus fait perdre de la pression."}, {"q": "Pourquoi garder une réserve au point d'attaque ?", "r": "Pour pouvoir avancer avec la lance."}, {"q": "Un tuyau doit traverser une route : que fais-tu ?", "r": "On le protège avec un dispositif de franchissement et on le signale."}, {"q": "Que fait-on des tuyaux après l'intervention ?", "r": "Rincer, contrôler, faire sécher, remettre des tuyaux secs."}], "quiz": [{"q": "Quel tuyau va du point d'eau à l'engin-pompe ?", "bonne": "Un tuyau d'alimentation (Ø110 ou Ø70)", "fausses": ["Un tuyau d'attaque Ø25", "Un tuyau d'attaque Ø45", "Le tuyau du dévidoir tournant"], "expl": ""}, {"q": "Quels diamètres pour l'établissement d'attaque ?", "bonne": "Ø45 ou Ø25", "fausses": ["Ø110 ou Ø150", "Ø70 ou Ø110", "Ø10 ou Ø15"], "expl": "De la division à la lance."}, {"q": "Comment est rangé un Ø70/20 m ?", "bonne": "En écheveau Z", "fausses": ["En couronne double", "Sur le dévidoir tournant", "À plat dans un coffre"], "expl": ""}, {"q": "Pourquoi éviter les plis et les torsions ?", "bonne": "L'eau passe mal", "fausses": ["Ça fait du bruit", "Le tuyau devient plus long", "Ça va plus vite"], "expl": ""}, {"q": "Pourquoi établir le moins de tuyaux possible ?", "bonne": "Chaque tuyau fait perdre de la pression", "fausses": ["Pour économiser l'eau", "Pour faire joli", "Ça n'a aucune importance"], "expl": ""}, {"q": "Où établir les tuyaux dans une rue ?", "bonne": "Le long des murs et des trottoirs", "fausses": ["Au milieu de la route", "En zigzag", "Sous les voitures garées"], "expl": "Pour ne gêner personne et ne pas être écrasé."}, {"q": "Pourquoi une réserve de tuyau au point d'attaque ?", "bonne": "Pour pouvoir avancer avec la lance", "fausses": ["Pour avoir plus de pression", "Pour s'asseoir dessus", "Pour faire un nœud"], "expl": ""}, {"q": "Que veut dire Ø45/20 m ?", "bonne": "45 mm de diamètre, 20 m de long", "fausses": ["45 m de long, 20 mm de diamètre", "45 bars, 20 litres", "45 litres par minute pendant 20 min"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les établissements » (charte SDIS 34), parties 1 et 2 · RNF JSP/JMP v1.1 fiche JSP2 INC C6 · RDMI SDIS 34 v6 (avril 2026) § 7.1 à 7.8"}, "JSP3|Les moyens facilitant l'action des secours": {"cycle": "JSP3", "bloc": "Sécuriser la zone d'intervention", "item": "Les moyens facilitant l'action des secours", "objectif": "Nommer les façades A à D d'un bâtiment et citer, lors d'une visite ou sur photos, au moins 6 aménagements ou équipements qui aident les secours, avec leur utilité (1 erreur admise).", "pointsCles": ["La cartographie du FPT (rues, points d'eau, accès, bâtiments à risque) se lit pendant le trajet ; elle est obligatoire même avec un GPS", "Les bâtiments à risque (collège, maison de retraite, cave coopérative…) ont un plan préparé à l'avance : accès, façades, points d'eau, coupures, locaux dangereux, nombre de personnes", "Façades : A = entrée principale (ou choisie par le 1er chef), puis B, C, D dans le sens des aiguilles d'une montre (« façade C, 1er étage »)", "Voie engins (route large, solide, hauteur suffisante) et voie échelles (zone plate au pied de la façade) : doivent rester libres", "Familles d'habitation : 1re (maison R+1), 2e (jusqu'à R+3), 3e (jusqu'à 28 m), 4e (jusqu'à 50 m) : plus c'est haut, plus il y a de protections", "Escaliers encloisonnés, murs et portes coupe-feu, recoupements : une porte coupe-feu ne se cale jamais ouverte", "Espace d'attente sécurisé (ERP, en général 2 par étage) : on le vérifie toujours lors des recherches", "Colonne sèche (vide, l'engin la remplit en bas) ou en charge (déjà pleine) : une prise à chaque étage pour la lance", "Moyens de secours du bâtiment : RIA, sprinklage, extincteurs, désenfumage, alarme, portes automatiques", "Caméra thermique (2 dans le FPTGP, portée par l'équipier) : ne voit pas à travers une vitre, un mur ou l'eau ; trousseau du secteur, clés gaz croix / étoile, clé triangulaire d'ascenseur"], "materiel": "FPTGP du CIS : cartographie opérationnelle, trousseau opérationnel (clés gaz croix et étoile, clés du secteur), clé triangulaire d'ascenseur, caméra thermique. Grille d'observation papier, plan ou vue aérienne du centre et du collège, objet chaud (bouillotte), tablette avec photos (colonne sèche, RIA, sprinkler, EAS, porte coupe-feu).", "activites": [{"titre": "Lire la carte du FPT", "duree": "10 min", "prep": "Cartographie de l'engin ouverte sur une table.", "deroule": ["Chaque binôme retrouve le centre, le collège et les 2 points d'eau les plus proches du collège.", "Il annonce l'itinéraire comme dans l'engin pendant le trajet.", "Bonus : repérer un bâtiment qui a un plan spécial."], "phrase": "On arrive en sachant déjà beaucoup.", "securite": ""}, {"titre": "Visite et chasse aux équipements", "duree": "20 min", "prep": "Visite du centre ou du collège préparée avec le responsable. Grille d'observation : façades A-D, voie engins / échelles, escaliers, portes coupe-feu, EAS, extincteurs, RIA, sprinklers, désenfumage, alarme, plans affichés, colonne sèche, points d'eau, coupures.", "deroule": ["Les binômes nomment d'abord les façades A, B, C, D.", "Ils cochent chaque équipement trouvé et notent où il est.", "Retour en groupe : chacun explique à quoi sert un équipement trouvé."], "phrase": "Tout ce qui est prévu pour nous aider, il faut le reconnaître en arrivant.", "securite": "On ne touche à aucun équipement sans l'accord du responsable."}, {"titre": "La caméra thermique", "duree": "10 min", "prep": "Caméra thermique du FPT, un objet chaud caché dans une pièce, une vitre.", "deroule": ["Un binôme cherche l'objet chaud avec la caméra (l'équipier la porte).", "Démonstration : main posée puis retirée d'une table, camarade derrière une vitre (on ne le voit pas).", "Conclusion : la caméra aide, elle ne remplace pas la ligne de vie ni le binôme."], "phrase": "La caméra voit la chaleur, pas à travers la vitre.", "securite": "Matériel fragile : manipulé sous le contrôle de l'animateur."}], "questions": [{"q": "Comment se nomme l'entrée principale d'un bâtiment ?", "r": "La façade A ; puis B, C, D dans le sens des aiguilles d'une montre."}, {"q": "Pourquoi lit-on la carte même avec un GPS ?", "r": "Elle contient des informations absentes du GPS (points d'eau, accès, bâtiments à risque)."}, {"q": "Que trouve-t-on sur le plan d'un bâtiment à risque ?", "r": "Accès et façades, points d'eau, coupures gaz / électricité / eau, locaux dangereux, nombre de personnes, équipements de secours."}, {"q": "À quoi sert la voie échelles ?", "r": "À installer la grande échelle au pied de la façade ; elle doit rester libre."}, {"q": "Pourquoi un escalier encloisonné ?", "r": "Pour que la fumée et le feu n'y entrent pas."}, {"q": "Qu'est-ce qu'un espace d'attente sécurisé ?", "r": "Un endroit protégé où une personne qui ne peut pas descendre attend les secours."}, {"q": "Qu'est-ce qu'une colonne sèche ?", "r": "Un tuyau fixe dans l'immeuble, alimenté en bas par l'engin, avec une prise à chaque étage."}, {"q": "Que fait un sprinkler ?", "r": "Il arrose tout seul quand il fait trop chaud au-dessus du feu."}, {"q": "Que ne voit pas la caméra thermique ?", "r": "À travers une vitre, un mur ou de l'eau."}, {"q": "Que contient le trousseau du secteur ?", "r": "Clés gaz croix et étoile, clés et télécommandes du secteur ; plus la clé triangulaire d'ascenseur."}], "quiz": [{"q": "La façade A, c'est…", "bonne": "L'entrée principale (ou celle choisie par le 1er chef)", "fausses": ["Toujours la façade nord", "La façade la plus haute", "La façade arrière"], "expl": "Puis B, C, D dans le sens des aiguilles d'une montre."}, {"q": "Une voiture est garée sur la voie échelles :", "bonne": "On le signale au chef", "fausses": ["Ce n'est pas grave", "On la pousse soi-même", "On installe l'échelle dessus"], "expl": "Un accès bloqué fait perdre de précieuses minutes."}, {"q": "Une porte coupe-feu…", "bonne": "Doit rester fermée", "fausses": ["Se cale ouverte pour aérer", "Sert seulement la nuit", "Se démonte en cas de feu"], "expl": ""}, {"q": "Une colonne sèche est…", "bonne": "Vide : l'engin la remplit par le bas", "fausses": ["Toujours pleine d'eau", "Un poteau dans la rue", "Un tuyau souple dans l'escalier"], "expl": "En charge (humide) = déjà pleine."}, {"q": "Un sprinkler…", "bonne": "Arrose seul quand il fait trop chaud", "fausses": ["Est utilisé par les pompiers", "Détecte le gaz", "Ouvre les portes"], "expl": ""}, {"q": "Combien de caméras thermiques dans le FPTGP ?", "bonne": "2", "fausses": ["0", "1", "5"], "expl": "Portées par l'équipier du binôme."}, {"q": "La caméra thermique ne voit pas…", "bonne": "À travers une vitre", "fausses": ["Une victime dans la fumée", "Un point chaud dans un mur", "Le foyer depuis l'extérieur"], "expl": "Ni à travers un mur ou l'eau."}, {"q": "Lors des recherches dans un ERP, on vérifie toujours…", "bonne": "Les espaces d'attente sécurisés", "fausses": ["Les distributeurs", "Le parking vélo", "La boîte aux lettres"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les moyens facilitant l'action des secours » (charte SDIS 34) · RDMI SDIS 34 v6 ch.4 et ETB 3.6 ; RDEB SDIS 34 v2 §2.22 (façades) et §3.11 (EAS) ; FAT FPTGP"}, "JSP4|Les fumées d'incendie": {"cycle": "JSP4", "bloc": "Sécuriser la zone d'intervention", "item": "Les fumées d'incendie", "objectif": "Citer les 5 dangers des fumées, lire une fumée (quantité, vitesse, épaisseur, couleur) et expliquer la stratification et l'effet des ouvertures — 10 min, 1 erreur admise.", "pointsCles": ["Les fumées sont chaudes, opaques, mobiles, inflammables et toxiques (RDEB § 2.24)", "La fumée, c'est du combustible : elle contient des gaz qui brûlent et peut s'enflammer", "Toxiques : le monoxyde de carbone (CO) est sans couleur, sans odeur, sans goût", "Stratification : fumées chaudes en haut, air plus frais en bas ; la limite s'appelle le plan neutre", "Plan neutre qui descend = la pièce chauffe dangereusement : alerte ! On reste bas", "Trop d'eau ou eau mal placée : la vapeur casse les couches et tout redescend sur nous", "Lire les fumées (RDEB § 2.23) : quantité (combustible), vitesse (pression), épaisseur (inflammabilité), couleur (jaunâtres ou grises qui « respirent » = feu qui manque d'air)", "Une porte ouverte donne de l'air au feu ; fermée, elle retient feu et fumées ; toute ouverture se décide lance prête, avec l'accord du chef", "ARI gardé aussi au déblai ; après le feu : EPI sales séparés (sac), nettoyage selon « je sais, je sens, je vois », douche au retour au CIS"], "materiel": "Tablette avec photos et vidéos pédagogiques de fumées (ENSOSP / SDIS), un verre ou un bocal transparent et de l'eau colorée pour illustrer la stratification si besoin, ruban pour lire le vent, plots, sac « EPI sales ».", "activites": [{"titre": "Les fumées parlent", "duree": "15 min", "prep": "Une série de photos/vidéos de fumées sortant de bâtiments.", "deroule": ["Tu montres une photo.", "Chaque binôme décrit : quantité, vitesse, épaisseur, couleur.", "Il conclut : feu qui a de l'air ou qui en manque ? danger ?", "Arrête la vidéo avant l'embrasement et fais dire les signes."], "phrase": "La fumée te dit ce que fait le feu.", "securite": ""}, {"titre": "Le plan neutre", "duree": "10 min", "prep": "Un mur ou une porte de garage, un ruban mobile pour figurer le plan neutre, les JSP debout.", "deroule": ["Tu places le ruban à une hauteur : les JSP prennent la bonne position (debout, accroupi, quatre pattes).", "Tu fais descendre le ruban : à partir de quand faut-il alerter ?", "Discussion : que se passe-t-il si on envoie trop d'eau ?"], "phrase": "Plus le plan neutre descend, plus c'est grave.", "securite": ""}, {"titre": "Vrai ou faux — course aux engins", "duree": "15 min", "prep": "Deux engins à l'arrêt (FPTGP = vrai, VSAV = faux) à 15-20 m. Liste d'affirmations.", "deroule": ["Tu lis une affirmation (« une fumée claire est sans danger », « fermer la porte ralentit le feu »…).", "Les JSP courent vers le FPTGP si c'est vrai, le VSAV si c'est faux.", "Ceux qui se trompent expliquent, un camarade corrige."], "phrase": "", "securite": "Engins à l'arrêt, clés retirées. On touche, on ne monte pas."}], "questions": [{"q": "Cite les 5 dangers des fumées.", "r": "Chaudes, opaques, mobiles, inflammables, toxiques."}, {"q": "Pourquoi une fumée peut-elle s'enflammer ?", "r": "Elle contient des gaz combustibles qui n'ont pas encore brûlé."}, {"q": "Où se trouvent les fumées chaudes dans une pièce ?", "r": "En haut : on se tient en bas."}, {"q": "Qu'est-ce que le plan neutre ?", "r": "La limite entre la couche de fumées et l'air plus frais."}, {"q": "Que veut dire un plan neutre qui descend vite ?", "r": "La pièce chauffe dangereusement : on alerte."}, {"q": "Que regarde-t-on quand on lit les fumées ?", "r": "Quantité, vitesse, épaisseur, couleur."}, {"q": "Que se passe-t-il si on ouvre une porte ?", "r": "L'air entre en bas, les fumées sortent en haut, le feu reprend de la force."}, {"q": "Pourquoi le CO est-il piégeux ?", "r": "Il est sans couleur, sans odeur, sans goût."}], "quiz": [{"q": "Laquelle N'EST PAS une caractéristique des fumées ?", "bonne": "Froides", "fausses": ["Toxiques", "Inflammables", "Opaques"], "expl": "Chaudes, opaques, mobiles, inflammables, toxiques."}, {"q": "Dans une pièce enfumée, l'air le plus frais est…", "bonne": "En bas", "fausses": ["En haut", "Au milieu", "Partout pareil"], "expl": "Stratification."}, {"q": "Le plan neutre descend vite :", "bonne": "Alerte, la pièce chauffe", "fausses": ["Tout va bien", "Le feu est éteint", "Il faut ouvrir les fenêtres sans ordre"], "expl": ""}, {"q": "Trop d'eau mal placée dans les fumées…", "bonne": "Casse les couches, tout redescend", "fausses": ["Éteint toujours le feu", "Refroidit sans risque", "Fait monter les fumées"], "expl": "La vapeur déstratifie."}, {"q": "Fumées jaunâtres qui sortent par saccades :", "bonne": "Feu qui manque d'air", "fausses": ["Feu presque éteint", "Simple vapeur d'eau", "Feu de cheminée normal"], "expl": "Risque d'explosion de fumées."}, {"q": "Quel gaz des fumées est sans odeur et sans couleur ?", "bonne": "Le monoxyde de carbone (CO)", "fausses": ["L'oxygène", "La vapeur d'eau", "L'azote"], "expl": ""}, {"q": "Ouvrir une porte sur un feu…", "bonne": "Lui donne de l'air", "fausses": ["L'étouffe", "Ne change rien", "Fait baisser la chaleur"], "expl": "Toute ouverture : lance prête et accord du chef."}], "statut": "brouillon", "source": "Cours 2026 « Les phénomènes thermiques et les techniques d'intervention » (charte SDIS 34), partie 1 · RDEB v2 (avril 2026) § 2.23-2.24, § 4.2 · RNF INC C1 — stratification et lecture des fumées : doctrine nationale (GDO incendies de structures), à valider avec le formateur"}, "JSP2|Les établissements de lances de plein pied": {"cycle": "JSP2", "bloc": "Eteindre un incendie", "item": "Les établissements de lances de plein pied", "objectif": "En binôme, réaliser de plain-pied une LDT (ETB 1.1), une prise d'eau (ETB 2.1) et une LDV 40 (ETB 3.2) en annonçant les ordres, sans erreur de sécurité.", "pointsCles": ["Pour les JSP2 : ETB 1 (LDT), ETB 2 (prise d'eau) et ETB 3 uniquement de plain-pied, à l'entraînement, sans feu réel", "LDT (ETB 1.1) : lance du dévidoir tournant (LDV 150) pour les petits feux, limitée à 40 m ; le conducteur ouvre l'eau", "LDV 40 : lance d'attaque principale des binômes, sur tuyau Ø45 · LDV 65 : gros débit, sur tuyau Ø70", "Prise d'eau (ETB 2) : de l'engin-pompe à la division d'alimentation ; avec la caisse jusqu'à 40 m (60 m avec un tuyau de plus) ; vannes de la division fermées avant d'ouvrir l'eau", "LDV 40 de plain-pied (ETB 3.2) : chef d'équipe = tuyau Ø45 en O + LDV 40 ; équipier = 2 tuyaux Ø45 en Z, raccorde et vient doubler le porte-lance", "Ordres : « En reconnaissance ! » · « Établissez ! » · « Ouvrez ! / Fermez ! » · « Raccordez-Ouvrez ! »", "Où en est la lance : à disposition, en cours d'établissement, à sec, en attente (en eau, prête), en manœuvre", "Sécurité : ne pas établir dans l'axe d'une porte ou d'une fenêtre, avoir de l'eau avant la zone dangereuse, baliser et gilet sur la route", "Binôme : chef d'équipe et équipier toujours ensemble, contrôle mutuel des EPI, on rend compte au chef d'agrès", "Un ordre bien compris, c'est un ordre que l'on peut répéter"], "materiel": "FPTGP (ou CCFU) : dévidoir tournant Ø25 + LDV 150, tuyaux Ø45 en O et en Z, LDV 40, 2 tuyaux Ø70 et division d'alimentation (caisse), plots « point d'attaque » · tenue complète, gants, casque jugulaire attachée.", "activites": [{"titre": "Le chef d'agrès, c'est toi", "duree": "10 min", "prep": "Cartes avec les ordres (« En reconnaissance ! », « Établissez ! », « Ouvrez ! », « Raccordez-Ouvrez ! ») et cartes avec les 5 états de la lance.", "deroule": ["Un JSP tire une carte et donne l'ordre à voix haute, engin en marche pour le bruit.", "Le binôme répète l'ordre et mime l'action.", "L'animateur montre une lance (à sec, en eau…) : les JSP disent son état."], "phrase": "Un ordre bien compris, c'est un ordre que l'on peut répéter.", "securite": "Engin à l'arrêt, frein serré, JSP loin des échappements."}, {"titre": "Ateliers tournants ETB 1.1 / 2.1 / 3.2", "duree": "30 min", "prep": "3 postes : LDT de 40 m · prise d'eau avec la caisse · LDV 40 de plain-pied. Un animateur par poste.", "deroule": ["Chaque binôme passe sur les 3 postes (10 min chacun).", "On inverse les rôles chef d'équipe / équipier à chaque passage.", "Débrief court : règles d'établissement respectées ? ordres clairs ? vannes fermées avant la mise en eau ?"], "phrase": "On établit bien, on établit en sécurité.", "securite": "Tenue complète, gants, casque jugulaire attachée. Pression adaptée, ouverture de la lance progressive, jamais de jet vers une personne."}, {"titre": "Le binôme muet", "duree": "5 min", "prep": "Une LDV 40 établie à sec.", "deroule": ["Le chef d'équipe guide son équipier uniquement par gestes pour avancer, reculer, s'arrêter.", "On change les rôles."], "phrase": "", "securite": "Sans eau, on marche, on ne court pas."}], "questions": [{"q": "Quels établissements fait-on en JSP2 ?", "r": "ETB 1 (LDT), ETB 2 (prise d'eau) et ETB 3 de plain-pied."}, {"q": "Quelle est la longueur maximale de la LDT ?", "r": "40 m."}, {"q": "Qui ouvre l'eau de la LDT ?", "r": "Le conducteur."}, {"q": "Que porte le chef d'équipe pour la LDV 40 ?", "r": "Un tuyau Ø45 en O et la LDV 40."}, {"q": "Que fait l'équipier pour la LDV 40 ?", "r": "Il pose 2 tuyaux Ø45 en Z, raccorde, puis vient doubler le porte-lance."}, {"q": "Que vérifier avant d'ouvrir l'eau sur une division ?", "r": "Que les vannes de la division sont fermées."}, {"q": "Que veut dire une lance « en attente » ?", "r": "Elle est en eau, prête à fonctionner."}, {"q": "Que fait le binôme à l'ordre « Établissez ! » ?", "r": "Il réalise l'établissement demandé."}, {"q": "Pourquoi ne pas établir dans l'axe d'une porte ?", "r": "Le feu ou les fumées peuvent en sortir brutalement."}], "quiz": [{"q": "Quelle lance est limitée à 40 m ?", "bonne": "La LDT", "fausses": ["La LDV 40", "La LDV 65", "La lance canon"], "expl": "Lance de premiers secours pour les petits feux."}, {"q": "Sur quel tuyau se branche la LDV 40 ?", "bonne": "Ø45", "fausses": ["Ø110", "Ø25", "Ø150"], "expl": ""}, {"q": "Que veut dire « En reconnaissance ! » ?", "bonne": "On s'équipe et on suit le chef", "fausses": ["On ouvre l'eau", "On range le matériel", "On rentre au centre"], "expl": "C'est l'ordre préparatoire."}, {"q": "Une lance établie et raccordée mais pas en eau est…", "bonne": "À sec", "fausses": ["En manœuvre", "En attente", "À disposition"], "expl": ""}, {"q": "Une lance en eau, prête à fonctionner, est…", "bonne": "En attente", "fausses": ["À sec", "En cours d'établissement", "À disposition"], "expl": ""}, {"q": "Avant d'ouvrir l'eau sur la division, on vérifie que…", "bonne": "Ses vannes sont fermées", "fausses": ["La lance est ouverte", "Le tuyau est plié", "Personne ne regarde"], "expl": ""}, {"q": "À quel ordre raccorde-t-on à la prise d'eau et ouvre-t-on ?", "bonne": "« Raccordez-Ouvrez ! »", "fausses": ["« En reconnaissance ! »", "« Fermez ! »", "« Sec ! »"], "expl": ""}, {"q": "En JSP2, la LDV 40 s'établit…", "bonne": "De plain-pied, à l'entraînement", "fausses": ["Dans les étages", "Sur un feu réel", "Sous ARI"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les établissements » (charte SDIS 34), partie 3 · RNF JSP/JMP v1.1 fiche JSP2 INC C6 · RDMI SDIS 34 v6 (avril 2026) § 5.1, 7.9, 9.2, 9.5 à 9.7, 9.9"}, "JSP3|Explosimétrie et la coupure des fluides": {"cycle": "JSP3", "bloc": "Sécuriser la zone d'intervention", "item": "Explosimétrie et la coupure des fluides", "objectif": "Expliquer quand un gaz devient explosif, placer le périmètre 50 m / 100 m sur un plan et montrer la position « fermé » d'un organe de coupure gaz, sans erreur, en 10 min.", "pointsCles": ["Gaz naturel (méthane) plus léger que l'air : il monte ; butane / propane (GPL) plus lourds : ils s'accumulent en bas (caves, sous-sols)", "Le gaz n'a pas d'odeur : on lui en ajoute une (« œuf pourri ») ; l'odeur peut disparaître et l'odorat se fatigue", "Un mélange gaz / air n'explose qu'entre la LIE et la LSE (méthane 5 à 15 %) ; une étincelle (interrupteur, sonnette, téléphone, moteur) suffit", "Dangers d'une fuite : explosion (souffle), incendie, asphyxie, intoxication (CO d'une chaudière mal réglée)", "Détecteur multigaz porté par le binôme de reconnaissance, mis en route à l'air libre : explosivité (% LIE), O2 (≈ 21 %), CO (alarmes 20 / 100 ppm), H2S (5 / 10 ppm)", "Procédure gaz classique (PGC, la plupart des cas) ou renforcée (PGR : fuite sous la rue sans sortie à l'air libre, fuite enflammée sur coffret de façade, ou sur demande) ; seul le COS requalifie", "Périmètre par défaut : zone d'exclusion 50 m (évacuation, minimum de pompiers et de temps), zone contrôlée 100 m ; pas de téléphone en zone d'exclusion", "Ogive de bouteille : rouge inflammable, jaune toxique / corrosif, bleu clair oxydant, vert inerte ; une bouteille chauffée peut éclater : on ne la déplace qu'en cas d'absolue nécessité", "Coupures toujours sur ordre du chef, signalées (quoi, où, quelle heure) ; jamais de remise en service soi-même (GRDF / ENEDIS)", "Gaz : quart de tour, poignée en travers du tuyau = fermé ; les pompiers ne touchent pas aux vannes du réseau sous la rue ; électricité : disjoncteur général (Linky : symbole circuit ouvert), coffret d'immeuble = technicien ENEDIS"], "materiel": "Détecteur multigaz de l'engin (démonstration), robinet / organe de coupure gaz de formation, photos de coffrets gaz de façade du secteur, disjoncteur de démonstration ou photo de tableau électrique et de compteur Linky, plan ou vue Géoportail du secteur, compas ou ficelle à l'échelle, feutres, photos d'ogives de bouteilles.", "activites": [{"titre": "Le détecteur multigaz", "duree": "10 min", "prep": "Détecteur de l'engin chargé ; lire avant les seuils d'alarme d'explosivité réglés par le SDIS.", "deroule": ["Mise en route à l'air libre, autotest, lecture de l'écran (LIE, O2, CO, H2S).", "Les JSP notent les seuils d'alarme affichés.", "Jeu : l'animateur annonce une valeur (« CO 120 ppm », « O2 17 % ») ; les binômes disent si c'est normal, alarme basse ou alarme haute et ce qu'on fait."], "phrase": "On ne devine pas : on mesure.", "securite": "Aucune exposition réelle à un gaz."}, {"titre": "Ouvert ou fermé ?", "duree": "10 min", "prep": "Organe de coupure de formation, photos de coffrets du secteur et de bouteilles (ogives de couleur).", "deroule": ["Chaque JSP manœuvre le robinet d'un quart de tour et annonce « ouvert » ou « fermé ».", "Il rend compte comme au chef : « Gaz coupé au coffret de façade, 14 h 32 ».", "Photos d'ogives : donner le danger (rouge, jaune, bleu clair, vert)."], "phrase": "En travers du tuyau = fermé.", "securite": "On ne manipule jamais une vraie installation de gaz."}, {"titre": "Le périmètre sur la carte", "duree": "15 min", "prep": "Plan du quartier du centre à l'échelle, ficelle / compas réglés sur 50 m et 100 m.", "deroule": ["Une fuite est placée sur le plan (coffret de façade).", "Les binômes tracent la zone d'exclusion (50 m) et la zone contrôlée (100 m).", "Ils listent les bâtiments à évacuer et les endroits où placer le balisage.", "Ils citent les 5 « je fais » et les 5 « je ne fais pas » d'une fuite de gaz."], "phrase": "On éloigne, on coupe sur ordre, on rend compte.", "securite": ""}, {"titre": "Chasse aux organes de coupure", "duree": "10 min", "prep": "Parcours autour du centre préparé à l'avance.", "deroule": ["Les binômes repèrent coffrets gaz, compteurs, disjoncteurs, robinets d'eau.", "Ils les photographient ou les notent sur un plan, sans y toucher."], "phrase": "Repérer avant d'en avoir besoin.", "securite": "Rester sur le trottoir, groupe encadré, on ne touche à rien."}], "questions": [{"q": "Pourquoi le gaz a-t-il une odeur ?", "r": "On lui en ajoute une pour pouvoir détecter une fuite."}, {"q": "Le butane monte ou descend ?", "r": "Il descend : il s'accumule dans les caves et sous-sols."}, {"q": "Que veut dire LIE ?", "r": "Limite inférieure d'explosivité : en dessous, pas assez de gaz pour exploser."}, {"q": "Entre quelles valeurs le gaz naturel est-il explosif ?", "r": "Entre 5 et 15 % dans l'air."}, {"q": "Que mesure le détecteur multigaz ?", "r": "L'explosivité, l'oxygène, le CO et l'H2S."}, {"q": "Quelles sont les zones par défaut autour d'une fuite de gaz ?", "r": "Exclusion 50 m, contrôlée 100 m."}, {"q": "Poignée de coupure en travers du tuyau, le gaz est… ?", "r": "Fermé."}, {"q": "Ça sent le gaz : que ne faut-il pas faire ?", "r": "Toucher un interrupteur ou une sonnette, faire une flamme, téléphoner dans la zone, démarrer un véhicule."}, {"q": "Qui remet le gaz ou l'électricité en service ?", "r": "L'exploitant (GRDF, ENEDIS) ou un professionnel, jamais les pompiers."}, {"q": "Couleur d'ogive d'une bouteille inflammable ?", "r": "Rouge."}], "quiz": [{"q": "Le gaz naturel (méthane) est…", "bonne": "Plus léger que l'air : il monte", "fausses": ["Plus lourd que l'air : il descend", "Coloré en jaune", "Sans danger"], "expl": "Le butane et le propane, eux, descendent."}, {"q": "Le gaz naturel est explosif entre…", "bonne": "5 et 15 %", "fausses": ["0 et 1 %", "30 et 50 %", "80 et 100 %"], "expl": "Entre la LIE et la LSE."}, {"q": "Ça sent le gaz : j'allume la lumière ?", "bonne": "Non, l'étincelle peut tout faire exploser", "fausses": ["Oui, pour mieux voir", "Oui si c'est une lampe LED", "Oui mais rapidement"], "expl": "Exemple de la rue de Trévise (Paris, 2019)."}, {"q": "Le détecteur multigaz se met en route…", "bonne": "À l'air libre, avant d'entrer", "fausses": ["Dans la pièce où ça sent", "Au retour à la caserne", "Jamais en exercice"], "expl": ""}, {"q": "Zone d'exclusion par défaut autour d'une fuite de gaz :", "bonne": "50 m", "fausses": ["5 m", "10 m", "500 m"], "expl": "Zone contrôlée : 100 m."}, {"q": "Une ogive de bouteille rouge signifie…", "bonne": "Inflammable", "fausses": ["Toxique", "Oxydant", "Inerte"], "expl": "Jaune toxique / corrosif, bleu clair oxydant, vert inerte."}, {"q": "Qui manœuvre les vannes du réseau sous la rue ?", "bonne": "GRDF", "fausses": ["Le JSP", "Le binôme d'attaque", "Les habitants"], "expl": "Les pompiers ne touchent pas au réseau de distribution."}, {"q": "Après une coupure, je…", "bonne": "Rends compte au chef : quoi, où, quelle heure", "fausses": ["Remets en service moi-même", "N'en parle à personne", "Rouvre pour vérifier"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « L'explosimétrie et la coupure des fluides » (charte SDIS 34) · Guide de doctrine « Interventions en présence de gaz » (DGSCGC), NIO du 11/04/2013, PIO 2020-07 ; RDEB SDIS 34 v2 annexes 5.3-5.5 et 5.8 ; RDMI SDIS 34 v6"}, "JSP4|Préservation des traces et indices": {"cycle": "JSP4", "bloc": "Sécuriser la zone d'intervention", "item": "Préservation des traces et indices", "objectif": "Sur une scène mise en place, atteindre la « victime » par un chemin unique, la secourir en premier, puis transmettre au chef d'agrès au moins 5 faits observés sans interprétation — 15 min.", "pointsCles": ["Règle d'or : les secours passent avant les indices (sauver, soigner, éteindre), même si on abîme des traces", "Enquête possible : incendie suspect, feu de forêt, accident de la route, décès inexpliqué, violences, accident du travail ; au départ on agit comme si une enquête allait suivre", "La gendarmerie ou la police dirigent l'enquête et sont seules à ramasser les preuves ; la RCCI recherche les causes des incendies", "La préservation des traces et indices fait partie des 11 critères de la marche générale des opérations (RDMI § 1.1)", "Laisser le moins de traces : le moins de monde possible, un seul chemin pour entrer et sortir, des gants, toucher le moins possible, ne rien emporter ni jeter (même un emballage de pansement)", "Sur incendie : juste quantité d'eau, point de départ signalé et protégé, déblai limité, pas de nettoyage ni de rangement", "Jamais sur les lieux : fumer, manger, boire, utiliser toilettes, évier ou téléphone de la maison, ramasser un objet « pour voir », faire des photos pour soi", "Discrétion : aucune photo, vidéo ni message sur les réseaux sociaux, même sans nom", "Observer en arrivant : portes, fenêtres, lumières, personnes, véhicules, départs de feu, fumées, odeurs, objets", "Transmettre des faits (« la porte était ouverte ») au chef d'agrès → COS → enquêteurs ; signaler aussi ce qu'on a déplacé pour secourir ; respecter le périmètre des forces de l'ordre"], "materiel": "Un local de la caserne mis en scène : chaise renversée, bidon vide, porte entrouverte, verre, lampe allumée, empreintes de pas à la farine ; mannequin « victime », gants, craie ou ruban, ardoises, tablette pour la photo de référence.", "activites": [{"titre": "La pièce mystère", "duree": "15 min", "prep": "Local mis en scène (chaise renversée, bidon vide, porte entrouverte, verre, lampe allumée, empreintes à la farine).", "deroule": ["Chaque binôme observe 1 minute depuis la porte, mains dans le dos.", "Il sort et liste tout ce qu'il a vu sur ardoise.", "Mise en commun : quels indices ? lesquels faudrait-il signaler au chef ?"], "phrase": "Je regarde avant d'entrer : après, tout aura changé.", "securite": ""}, {"titre": "Qu'est-ce qui a changé ?", "duree": "10 min", "prep": "Photo de la scène prise sur la tablette.", "deroule": ["Les JSP sortent ; l'animateur déplace 5 objets.", "Ils reviennent et retrouvent les changements.", "On compare avec la photo : pourquoi un objet déplacé peut tromper les enquêteurs ?"], "phrase": "", "securite": ""}, {"titre": "Le chemin unique", "duree": "10 min", "prep": "Empreintes et objets tracés au sol, mannequin au fond de la pièce, gants.", "deroule": ["Le binôme, gants mis, va jusqu'au mannequin sans marcher sur les traces.", "Il fait un geste de secours (la victime d'abord !).", "Il ressort par le même chemin sans rien toucher d'autre et dit ce qu'il a déplacé."], "phrase": "Les secours passent avant tout.", "securite": "Pas de vrai produit dans le bidon (vide et rincé)."}, {"titre": "Le témoin", "duree": "10 min", "prep": "L'animateur joue l'enquêteur.", "deroule": ["Chaque JSP raconte ce qu'il a vu en 30 secondes.", "L'animateur relève les interprétations (« il a voulu… ») et fait reformuler en faits.", "Le groupe vote : fait ou supposition ?"], "phrase": "Je dis ce que j'ai vu, pas ce que j'imagine.", "securite": ""}], "questions": [{"q": "Qu'est-ce qui passe en premier : les secours ou les indices ?", "r": "Les secours."}, {"q": "Qui dirige l'enquête ?", "r": "La gendarmerie ou la police."}, {"q": "Pourquoi un seul chemin pour entrer et sortir ?", "r": "Pour ne pas piétiner les traces partout."}, {"q": "J'ai déplacé un objet pour secourir : je fais quoi ?", "r": "Je retiens où il était et je le dis au chef."}, {"q": "Puis-je mettre une photo de l'intervention sur les réseaux ?", "r": "Jamais."}, {"q": "« Quelqu'un est entré » ou « la porte était ouverte » : lequel est un fait ?", "r": "« La porte était ouverte »."}, {"q": "Cite 3 interventions qui peuvent donner lieu à une enquête.", "r": "Incendie suspect, feu de forêt, accident de la route, décès inexpliqué, violences, accident du travail."}, {"q": "Pourquoi porter des gants ?", "r": "Ils protègent le secouriste et évitent de laisser ses empreintes."}], "quiz": [{"q": "Une victime est au milieu des indices :", "bonne": "Je la secours d'abord", "fausses": ["J'attends les enquêteurs", "Je contourne pour ne rien toucher", "Je prends des photos avant"], "expl": "Les secours passent avant les indices."}, {"q": "Qui ramasse les preuves ?", "bonne": "La gendarmerie ou la police", "fausses": ["Le premier pompier arrivé", "Le propriétaire", "Les JSP"], "expl": ""}, {"q": "Pour entrer et sortir, on utilise…", "bonne": "Un seul et même chemin", "fausses": ["Le plus de chemins possible", "N'importe quelle porte", "La fenêtre"], "expl": ""}, {"q": "Sur une scène, j'ai soif :", "bonne": "J'attends d'être sorti", "fausses": ["Je bois au robinet de la maison", "Je prends un verre dans la cuisine", "Je me sers dans le frigo"], "expl": "On ne mange pas, on ne boit pas, on n'utilise rien sur place."}, {"q": "Un emballage de pansement après les soins :", "bonne": "Je le garde et je le signale", "fausses": ["Je le jette dans la poubelle de la maison", "Je le laisse par terre sans rien dire", "Je le brûle"], "expl": ""}, {"q": "Lequel est un fait ?", "bonne": "« La fenêtre était cassée »", "fausses": ["« Un voleur est passé »", "« Il a voulu mettre le feu »", "« C'est sûrement le voisin »"], "expl": ""}, {"q": "Sur incendie, pour préserver les indices :", "bonne": "Juste la quantité d'eau nécessaire", "fausses": ["Un jet le plus fort possible", "On balaie pour faire propre", "On range les objets"], "expl": "Le point de départ du feu est précieux."}], "statut": "brouillon", "source": "Cours 2026 « Traces et indices – secourir sans effacer » (charte SDIS 34) · RNF INC A3 · RDMI v6 (avril 2026) § 1.1 · RDEB v2 § 2.18 · PEX ENSOSP « Interventions sensibles » (SDIS 73) — gestes de préservation : règles générales, à valider avec un officier RCCI"}, "JSP2|Les moyens de production de mousse": {"cycle": "JSP2", "bloc": "Eteindre un incendie", "item": "Les moyens de production de mousse", "objectif": "Citer les 3 éléments de la mousse, ses 3 effets et le matériel de l'engin, puis réaliser à blanc en binôme l'établissement d'une LDV 40 à mousse (ETB 5.3).", "pointsCles": ["Eau + émulseur = solution moussante ; solution moussante + air = mousse", "La mousse étouffe (couche qui empêche l'air d'arriver), isole (bloque les vapeurs inflammables) et refroidit (grâce à son eau)", "Pour les feux de liquides (classe B) surtout, aussi les solides (A)", "Foisonnement = combien de fois la mousse est plus volumineuse que la solution : bas (projetée loin), moyen et haut (remplir un volume)", "SDIS 34 : eau dopée 0,1 à 0,4 % · lance moussante 0,5 à 1 % · lance à mousse 1 % avec adaptateur mousse ; référence départementale 1 % maximum", "Sans injection fixe, l'engin-pompe a un injecteur proportionneur réglé et bloqué à 1 % et 4 bidons d'additif", "ETB 5.3 : la lance ne doit pas être à plus de 40 m de l'injecteur proportionneur ; le 2e binôme plonge la canne dans le bidon à l'ordre « Plongez ! » et surveille le niveau", "Le FPTGP a des adaptateurs mousse bas et moyen foisonnement (200 L d'additif) ; le FMOGP sert aux gros feux d'hydrocarbures et de sites industriels", "On recouvre la nappe en douceur (sur une paroi, en pluie) : on ne la frappe pas avec le jet"], "materiel": "FPTGP : injecteur proportionneur, adaptateur mousse, LDV 40, tuyaux Ø45 (O et Z), bidons d'additif (vides pour l'exercice) · FMOGP à montrer si disponible · seau, liquide vaisselle, fouet, verre doseur · plot « nappe en feu ».", "activites": [{"titre": "La mousse en cuisine", "duree": "10 min", "prep": "Seau d'eau, liquide vaisselle (le « émulseur »), fouet, verre doseur.", "deroule": ["Eau seule : on fouette, rien.", "Eau + un peu d'émulseur = solution moussante : on fouette, la mousse monte grâce à l'air.", "On compare le volume avant / après : c'est le foisonnement.", "Les JSP nomment les 3 ingrédients et les 3 effets (étouffe, isole, refroidit)."], "phrase": "Sans air, pas de mousse : c'est le rôle de l'adaptateur mousse.", "securite": ""}, {"titre": "Montre-moi le matériel", "duree": "10 min", "prep": "Matériel mousse du FPTGP posé au sol (injecteur proportionneur, adaptateur mousse, LDV 40, bidon vide).", "deroule": ["Chaque binôme reçoit une pièce et explique son rôle.", "Les binômes remettent la chaîne dans l'ordre : engin → injecteur proportionneur → tuyau (40 m max) → LDV 40 + adaptateur.", "Visite du FMOGP : à quoi sert-il ?"], "phrase": "Chaque pièce a sa place dans la chaîne.", "securite": "Matériel manipulé sans eau ni émulseur."}, {"titre": "ETB 5.3 à blanc", "duree": "20 min", "prep": "Tuyaux Ø45 en O et en Z, injecteur proportionneur, adaptateur mousse, LDV 40, bidons vides, plot « nappe en feu ».", "deroule": ["Démonstration par l'animateur.", "1er binôme : pose l'injecteur, établit, met l'adaptateur, ordonne « Plongez ! ».", "2e binôme : pose les bidons, plonge la canne, veille au niveau.", "Chaque binôme dit comment il appliquerait la mousse (en douceur, sur une paroi)."], "phrase": "On recouvre la nappe comme une couverture, on ne la frappe pas.", "securite": "À blanc, sans eau. Pas de manipulation d'émulseur réel par les JSP (irritant pour les yeux et la peau)."}], "questions": [{"q": "Quels sont les 3 éléments pour faire de la mousse ?", "r": "Eau, émulseur, air."}, {"q": "Comment appelle-t-on le mélange eau + émulseur ?", "r": "La solution moussante."}, {"q": "Cite les 3 effets de la mousse.", "r": "Elle étouffe, elle isole des vapeurs, elle refroidit."}, {"q": "Sur quels feux utilise-t-on surtout la mousse ?", "r": "Les feux de liquides (classe B)."}, {"q": "Qu'est-ce que le foisonnement ?", "r": "Combien de fois la mousse est plus volumineuse que la solution moussante."}, {"q": "Quelle est la concentration de référence au SDIS 34 ?", "r": "1 % maximum."}, {"q": "Distance maximale entre la lance et l'injecteur proportionneur ?", "r": "40 m."}, {"q": "Quel engin du CIS sert aux gros feux d'hydrocarbures ?", "r": "Le FMOGP (fourgon mousse grande puissance)."}], "quiz": [{"q": "Solution moussante + air = ?", "bonne": "Mousse", "fausses": ["Eau dopée", "Émulseur", "Poudre"], "expl": ""}, {"q": "La mousse agit surtout en…", "bonne": "Étouffant le feu", "fausses": ["Ajoutant de l'oxygène", "Chauffant le combustible", "Soufflant les flammes"], "expl": "Elle isole aussi les vapeurs et refroidit."}, {"q": "La mousse est surtout utilisée sur les feux de…", "bonne": "Liquides (classe B)", "fausses": ["Métaux (classe D)", "Huiles de cuisson (classe F)", "Gaz (classe C)"], "expl": ""}, {"q": "Concentration de référence du SDIS 34 pour la mousse ?", "bonne": "1 % maximum", "fausses": ["10 %", "50 %", "25 %"], "expl": ""}, {"q": "Le foisonnement, c'est…", "bonne": "Le volume de mousse par rapport à la solution", "fausses": ["La couleur de la mousse", "La pression de la lance", "La durée du feu"], "expl": ""}, {"q": "Distance max entre la lance et l'injecteur proportionneur ?", "bonne": "40 m", "fausses": ["5 m", "100 m", "200 m"], "expl": "ETB 5.3 du RDMI."}, {"q": "Quel engin du CIS est spécialisé dans les feux d'hydrocarbures ?", "bonne": "Le FMOGP", "fausses": ["Le VSAV", "Le CCFM", "Le VSRTU"], "expl": ""}, {"q": "Comment applique-t-on la mousse sur une nappe ?", "bonne": "En douceur, sur une paroi ou en pluie", "fausses": ["En frappant fort la nappe", "En jet droit au centre", "Avec les pieds"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les classes de feux et les agents extincteurs » (charte SDIS 34), diapo « La mousse » · RNF JSP/JMP v1.1 fiche JSP2 INC C4 · RDMI SDIS 34 v6 (avril 2026) § 5.4 et ETB 5.3"}, "JSP3|L'appareil respiratoire isolant": {"cycle": "JSP3", "bloc": "Sécuriser la zone d'intervention", "item": "L'appareil respiratoire isolant", "objectif": "S'équiper, réaliser le contrôle croisé RAPACE à voix haute, s'enregistrer puis suivre une ligne guide pré-installée à vue puis masque occulté, en binôme, sans erreur de procédure.", "pointsCles": ["On s'engage toujours en binôme : le chef d'équipe (sécurité, lance ou ligne guide) et l'équipier (caméra thermique) ; contact permanent par la main, la vue ou la voix", "Contrôle croisé RAPACE avant chaque engagement : Robinet, Armement (balise), Pression (≥ 270 bars), Ajustement, Code, Étanchéité ; un seul point qui ne va pas = on ne rentre pas", "Conditions pour s'engager : binôme contrôlé, ordre du chef d'agrès, enregistrement, autonomie calculée, radio et balise en marche, lien avec la sortie si pas de visibilité", "Enregistrement auprès du contrôleur : noms, pression, heure d'entrée, heure de sortie prévue, mission ; un binôme de sécurité est prêt à partir", "Autonomie = pression (réserve de 50 bars décomptée) × volume de la bouteille ÷ air consommé (ex. 250 × 7,2 ÷ 105 = 17 min) ; sifflet à 55 bars = sortie immédiate", "Air consommé : 10 L/min au repos, 50 à vue, 105 sur ligne de vie, 135 en sauvetage ; perdre son calme épuise l'air", "Sans visibilité : ligne de vie (tuyau ou ligne guide + liaison personnelle de 6 m), main gauche / main droite, se tenir bas, escalier dangereux descendu à reculons", "Ligne guide : attache de départ, attaches en route, attache de fin (un tour mort et deux demi-nœuds) ; demi-tour face à la ligne, le chef passe derrière", "Technique AIDES (Accéder, Isoler, Désenfumer, Explorer, Sauver) ; pièce fouillée marquée « R »", "Détresse : message radio, sans réponse 3 fois → appel de détresse puis balise ; jamais retirer son masque ; retour : « Je suis / Je vois / Je fais », récupération, pas de réengagement si suie au mouchage, malaise, cœur > 140, respiration > 25"], "materiel": "ARI d'exercice du FPTGP avec masques, balises de détresse, ligne guide et liaisons personnelles de 6 m, radio portative, caméra thermique, film / cagoule pour occulter les masques, tableau d'enregistrement (TGP) et chronomètre, bombe à craie ou craie, bouteilles d'eau et lingettes.", "activites": [{"titre": "RAPACE et enregistrement", "duree": "10 min", "prep": "ARI et masques prêts, tableau d'enregistrement dessiné.", "deroule": ["Chaque binôme s'équipe comme en vrai et réalise le contrôle croisé RAPACE à voix haute.", "L'animateur glisse une erreur (robinet pas ouvert à fond, balise non armée) : le binôme doit la trouver.", "Le binôme s'enregistre : noms, pression, heure d'entrée, heure de sortie calculée, mission."], "phrase": "Un seul point qui ne va pas : on ne rentre pas.", "securite": "Air sain uniquement, formateur présent."}, {"titre": "Calcul d'autonomie express", "duree": "5 min", "prep": "Cartes avec pressions (300, 280, 250 bars) et bouteilles 6 L / 7,2 L.", "deroule": ["Les binômes calculent l'heure de sortie avec 105 L/min (réserve de 50 bars décomptée).", "C'est le binôme qui a le moins d'air qui fixe l'heure de sortie."], "phrase": "Je connais mon air avant d'entrer.", "securite": ""}, {"titre": "Parcours sur ligne guide", "duree": "20 min", "prep": "Ligne guide pré-positionnée, parcours simple sans obstacle ; un formateur au contrôle, un sur le parcours.", "deroule": ["1er passage à vue : suivre la ligne, liaison personnelle accrochée.", "2e passage masque occulté, main gauche ou main droite, en se tenant bas.", "En bout de ligne : demi-tour face à la ligne, le chef d'équipe passe derrière.", "Une pièce à « fouiller » (AIDES) : marquer « R » à la craie sur la porte."], "phrase": "Toujours relié à la sortie, toujours en contact avec son binôme.", "securite": "Air sain, aucun obstacle ni hauteur, arrêt au moindre malaise ; les JSP n'évoluent sous ARI qu'en exercice."}, {"titre": "Compte rendu et récupération", "duree": "10 min", "prep": "Bouteilles d'eau, lingettes.", "deroule": ["À la sortie, chaque chef d'équipe fait son compte rendu « Je suis / Je vois / Je fais ».", "Désenregistrement auprès du contrôleur.", "Récupération : se découvrir, se rafraîchir, boire (cracher la 1re gorgée), lingettes.", "Jeu : l'animateur décrit un pompier (« il a de la suie au mouchage ») : repart / ne repart pas ?"], "phrase": "On ne repart que si on est en forme.", "securite": ""}], "questions": [{"q": "Que veut dire RAPACE ?", "r": "Robinet, Armement, Pression, Ajustement, Code, Étanchéité."}, {"q": "Quelle pression minimum pour s'engager ?", "r": "270 bars."}, {"q": "Que donne-t-on à l'enregistrement ?", "r": "Noms, pression, heure d'entrée, heure de sortie prévue, mission."}, {"q": "Qui porte la ligne guide ? Et la caméra thermique ?", "r": "Le chef d'équipe porte la ligne guide (ou la lance) ; l'équipier la caméra."}, {"q": "Le sifflet de l'ARI sonne : que fait le binôme ?", "r": "Il ressort immédiatement (55 bars)."}, {"q": "Combien d'air respire-t-on sur une ligne de vie ?", "r": "Environ 105 L/min, 15 min maximum."}, {"q": "Quel nœud pour attacher la ligne guide ?", "r": "Un tour mort et deux demi-nœuds."}, {"q": "Que veut dire le « R » sur une porte ?", "r": "La pièce a été reconnue (fouillée)."}, {"q": "Le message de détresse reste sans réponse 3 fois : que fais-tu ?", "r": "Je déclenche l'appel de détresse de la radio, puis la balise."}, {"q": "Les trois parties du compte rendu ?", "r": "Je suis, je vois, je fais."}], "quiz": [{"q": "Le P de RAPACE veut dire…", "bonne": "Pression : au moins 270 bars", "fausses": ["Prudence", "Porte fermée", "Poignée"], "expl": ""}, {"q": "Un point du RAPACE ne va pas :", "bonne": "On ne rentre pas", "fausses": ["On rentre quand même vite", "On le signale après", "On change de binôme et on rentre"], "expl": ""}, {"q": "Le sifflet de l'ARI sonne à…", "bonne": "55 bars", "fausses": ["10 bars", "150 bars", "270 bars"], "expl": "Le binôme ressort tout de suite."}, {"q": "Qui fixe l'heure de sortie du binôme ?", "bonne": "Celui qui a le moins d'air", "fausses": ["Celui qui a le plus d'air", "Le plus âgé", "Le conducteur"], "expl": ""}, {"q": "Sur une ligne de vie, on respire environ…", "bonne": "105 L/min", "fausses": ["10 L/min", "50 L/min", "300 L/min"], "expl": "Au repos : 10 ; à vue : 50 ; sauvetage : 135."}, {"q": "Dans la technique AIDES, le I veut dire…", "bonne": "Isoler : fermer la porte de la pièce", "fausses": ["Inspecter le toit", "Informer la famille", "Inonder la pièce"], "expl": "Accéder, Isoler, Désenfumer, Explorer, Sauver."}, {"q": "Plus d'air dans la fumée : je…", "bonne": "Garde mon masque et j'appelle", "fausses": ["Retire mon masque", "Cours vers la sortie seul", "Arrête de respirer"], "expl": "Ne jamais retirer son masque dans la fumée."}, {"q": "Suie au mouchage après le feu :", "bonne": "Pas de réengagement", "fausses": ["Je repars après avoir bu", "Je change de bouteille et je repars", "Ce n'est pas grave"], "expl": "Tableau d'aide à la décision du RDEB."}], "statut": "brouillon", "source": "Cours 2026 « L'engagement sous ARI » (charte SDIS 34) · RDEB SDIS 34 v2 (avril 2026) ch.2 et 3 (§2.9-2.16, 3.2-3.16) ; RDMI SDIS 34 v6 (binômes)"}, "JSP4|Rôle de l'équipier au sein du binôme de reconnaissance": {"cycle": "JSP4", "bloc": "Sécuriser la zone d'intervention", "item": "Rôle de l'équipier au sein du binôme de reconnaissance", "objectif": "En binôme, reconnaître une « maison » de 3-4 pièces (main gauche ou main droite, marquage R, portes refermées), signaler les dangers et faire un compte rendu complet au chef d'agrès — 15 min, aucune séparation du binôme admise.", "pointsCles": ["But de la reconnaissance (RDMI § 6.4) : sauver, comprendre le bâtiment, trouver le feu, couper énergies et fluides, ramener l'ascenseur au RDC porte calée ouverte, choisir le moyen d'extinction", "Binôme = chef d'équipe + équipier ; le chef d'équipe porte la lance ou la ligne guide et fait les amarrages, l'équipier porte la caméra thermique, observe et signale", "Missions du binôme : appliquer les ordres du chef d'agrès, rendre compte dès que ça change, contrôle croisé (RAPACE), rester dans l'engin sans ordre, entrer toujours à deux en zone dangereuse", "Ordre préparatoire : « 1er binôme, en reconnaissance ! » (EPI seuls) ou « … pour l'établissement d'une LDV 40, en reconnaissance ! » ; « À vos rangs ! » à l'arrière de l'engin", "Observer (RDEB § 2.23) : météo, bâtiment, fumées, flammes, chaleur, ouvrants, sons ; fumées : chaudes, opaques, mobiles, inflammables, toxiques", "Toujours relié à la sortie : tuyau en eau ou ligne guide + liaison personnelle de 6 m ; exploration linéaire, latérale ou circulaire", "Recherche : debout, accroupi ou à 4 pattes selon la chaleur ; escalier dangereux en marche arrière ; main gauche ou main droite choisie ensemble ; pièce par pièce ; immeuble : d'abord étage du feu + ascenseurs, puis étage au-dessus et dernier étage, puis le reste", "AIDES : Accéder, Isoler (fermer la porte), Désenfumer, Explorer, Sauver ; marquage « R » à la craie = reconnu, porte refermée", "Signaler tout de suite (victime, gaz, plancher qui cède, fumée qui change, sortie bloquée) ; compte rendu en sortant : accès, étages touchés, actions faites, propositions, évolution", "Sortir par le chemin de repli en priorité, sinon chemin de secours ou mise à l'abri ; « ÉVACUATION ×3 » ; imprévu : on fait le point au calme (blessés ? air ? lance ? ligne de vie ?)"], "materiel": "Local ou remise aménagé en « maison » (3-4 pièces avec portes), mannequin « victime », craie (marquage R), éléments dangers factices (bouteille de gaz vide, rallonge, produit étiqueté vide, sortie encombrée), commande ou liaison pour relier le binôme, bandeaux ou masques occultés, caméra thermique du FPTGP si disponible.", "activites": [{"titre": "Le mime des codes", "duree": "10 min", "prep": "Liste des codes RDEB § 2.10 : ça va, ça ne va pas, mi-bouteille, on monte, on descend, à droite, à gauche, en réserve, on fait retour, j'ai plus d'air.", "deroule": ["Un JSP fait le geste.", "L'équipe le nomme le plus vite possible.", "On change de mimeur à chaque code."], "phrase": "Sous le masque, on entend mal : les gestes doivent être connus par cœur.", "securite": ""}, {"titre": "Main droite", "duree": "10 min", "prep": "Zone dégagée, binôme relié par une commande, bandeaux ou masques occultés.", "deroule": ["Le binôme choisit ensemble main droite ou main gauche.", "Il progresse les yeux bandés le long du mur, en contact permanent.", "Il revient par le même chemin et dit ce qu'il a touché."], "phrase": "On choisit un côté ensemble et on le garde.", "securite": "Un animateur par binôme, zone sans obstacle dangereux, déplacement lent."}, {"titre": "La maison", "duree": "25 min", "prep": "3-4 pièces, un mannequin caché, dangers factices, craie. L'animateur joue le chef d'agrès.", "deroule": ["Ordre : « 1er binôme, en reconnaissance ! » — contrôle croisé avant d'entrer.", "Le binôme explore pièce par pièce, l'équipier « à la caméra » signale chaque danger.", "Il marque R chaque pièce vue et referme la porte ; il sort la « victime ».", "Retour d'engagement au chef d'agrès : accès, pièces vues, dangers, actions, propositions."], "phrase": "Le binôme ne se sépare jamais.", "securite": "Toujours en binôme, sans vraie fumée ni ARI en ambiance viciée, encadré par un animateur."}], "questions": [{"q": "Qui porte la caméra thermique dans le binôme ?", "r": "L'équipier."}, {"q": "Que veut dire un « R » sur une porte ?", "r": "Pièce reconnue (vérifiée)."}, {"q": "Dans un immeuble, où cherche-t-on d'abord ?", "r": "À l'étage du feu et dans les ascenseurs."}, {"q": "Que veut dire « main droite » ?", "r": "On longe le mur de droite, choisi ensemble et gardé."}, {"q": "Cite les 5 dangers des fumées.", "r": "Chaudes, opaques, mobiles, inflammables, toxiques."}, {"q": "Quel chemin prend-on en priorité pour sortir ?", "r": "Le chemin de repli : celui par lequel on est entré."}, {"q": "Que veut dire AIDES ?", "r": "Accéder, Isoler, Désenfumer, Explorer, Sauver."}, {"q": "Que contient le compte rendu en sortant ?", "r": "Les accès, les étages et pièces touchés, ce qu'on a fait, ce qu'on propose, l'évolution du feu."}], "quiz": [{"q": "Dans le binôme, la caméra thermique est portée par…", "bonne": "L'équipier", "fausses": ["Le chef d'équipe", "Le conducteur", "Le chef d'agrès resté dehors"], "expl": ""}, {"q": "Une porte marquée « R » :", "bonne": "Pièce reconnue", "fausses": ["Pièce à risque", "Pièce à refaire", "Rien à signaler, porte à laisser ouverte"], "expl": "Et on referme la porte."}, {"q": "Immeuble en feu, on cherche d'abord…", "bonne": "À l'étage du feu et dans les ascenseurs", "fausses": ["Au rez-de-chaussée", "Dans la cave", "Au hasard"], "expl": "Puis étage au-dessus et dernier étage."}, {"q": "Dans AIDES, le « I » veut dire…", "bonne": "Isoler (fermer la porte)", "fausses": ["Inonder", "Interroger", "Illuminer"], "expl": ""}, {"q": "La liaison personnelle mesure…", "bonne": "6 m", "fausses": ["1 m", "20 m", "60 m"], "expl": ""}, {"q": "Pour ressortir, on prend d'abord…", "bonne": "Le chemin de repli", "fausses": ["Le chemin le plus court inconnu", "La fenêtre la plus proche", "Un autre escalier au hasard"], "expl": "Celui par lequel on est entré."}, {"q": "Ordre « 1er binôme, en reconnaissance ! » sans matériel précisé :", "bonne": "On part avec les EPI seulement", "fausses": ["On prend toute la caisse à outils", "On attend un deuxième ordre", "On établit une lance"], "expl": ""}, {"q": "Un imprévu dans la reconnaissance :", "bonne": "On fait le point au calme", "fausses": ["On court vers la sortie", "On se sépare pour chercher", "On enlève son masque"], "expl": "Paniquer fait vider la bouteille plus vite."}], "statut": "brouillon", "source": "Cours 2026 « Le binôme de reconnaissance – le rôle de l'équipier » (charte SDIS 34) · RNF INC A1 · RDMI v6 (avril 2026) § 5.1-5.2, 6.4, 6.5, 6.9 · RDEB v2 (avril 2026) § 2.9-2.10, 2.23-2.24, 3.3-3.13 · RDSMES v2 § 4, 5.1"}, "JSP2|La toxicité des fumées d'incendies": {"cycle": "JSP2", "bloc": "Sécuriser la zone d'intervention", "item": "La toxicité des fumées d'incendies", "objectif": "Citer les 5 dangers des fumées et les 4 portes d'entrée des toxiques, puis retirer une veste « salie » à la farine avec des gants jetables sans s'en mettre sur la peau — 15 min, aucune trace sur le cou, les poignets ou les mains.", "pointsCles": ["Dans un incendie d'habitation, ce sont les fumées qui font le plus de victimes, souvent pendant le sommeil, avant les flammes", "Les 5 dangers des fumées (RDEB SDIS 34) : chaudes, opaques, mobiles, inflammables, toxiques", "Tout ce qui brûle produit des toxiques : bois et papier (beaucoup de CO et de suies), plastiques et mousses (canapés, matelas, isolants : gaz très toxiques), produits chimiques ; une maison moderne pleine de plastique brûle plus vite, avec des fumées plus toxiques", "CO (monoxyde de carbone) : invisible, sans odeur, il prend la place de l'oxygène dans le sang ; HCN (cyanure d'hydrogène) : vient des plastiques et des mousses ; gaz irritants : brûlent les yeux, la gorge, les poumons ; suies : collent à la peau et aux tenues, certaines donnent des cancers", "Quatre portes d'entrée dans le corps : la respiration, la peau (cou, visage, mains, poignets), la bouche (manger ou boire avec des mains sales), les yeux", "Après le feu, les toxiques continuent : ils se collent sur la tenue et le matériel, se libèrent peu à peu et voyagent (engin, voiture, maison) — une tenue qui sent la fumée n'est pas une tenue propre", "Personne intoxiquée : mal de tête (souvent le 1er signe), vertiges, nausées, toux, suies autour du nez et de la bouche, somnolence jusqu'à la perte de connaissance → je me protège, j'alerte le 18, je fais les gestes du PSC", "Pendant l'intervention, le sapeur-pompier porte l'ARI dès qu'il y a de la fumée et jusqu'à la fin du déblai, des EPI complets (cagoule, col fermé, gants), se place vent dans le dos et ne met rien à la bouche en zone enfumée", "Après l'intervention : nettoyage « je sais / je sens / je vois », demi-masque P3 et gants jetables pour se déshabiller, EPI très sales dans un sac rouge, douche obligatoire au retour au centre", "Chez soi : détecteur de fumée obligatoire dans chaque logement, porte fermée, rester bas, sortir puis appeler le 18 ou le 112"], "materiel": "Veste de feu propre + farine ou talc (suies), gants jetables, sac rouge du lot de décontamination (DECOPI) du FPTGP, demi-masque P3 et ARI pour montrer (non capelés), 6 à 8 photos ou descriptions d'interventions (je sais / je sens / je vois), feuilles et crayons, un détecteur de fumée pour montrer.", "activites": [{"titre": "Flammes ou fumées ?", "duree": "5 min", "prep": "Aucune.", "deroule": ["Vote à main levée : dans un incendie d'appartement, qu'est-ce qui fait le plus de victimes ?", "Réponse : les fumées, souvent pendant le sommeil, avant les flammes.", "On cite ensemble les 5 dangers : chaudes, opaques, mobiles, inflammables, toxiques."], "phrase": "Les fumées tuent avant les flammes.", "securite": ""}, {"titre": "Le défi de la farine", "duree": "15 min", "prep": "Veste de feu propre saupoudrée de farine aux épaules et aux manches, gants jetables, sac rouge.", "deroule": ["Le JSP met des gants jetables et retire la veste en la roulant, sans toucher la farine avec la peau.", "Il met la veste dans le sac rouge, puis retire ses gants en les retournant.", "Le groupe regarde où il reste de la « suie » : cou, poignets, mains.", "On fait tourner les binômes."], "phrase": "Ce qui reste sur la tenue finit sur la peau.", "securite": "Farine ou talc non toxique, pas de masque ; on ne secoue pas la veste, loin des yeux. Aucun produit réel, aucune fumée réelle."}, {"titre": "Je sais · je sens · je vois", "duree": "10 min", "prep": "6 à 8 photos ou descriptions d'interventions.", "deroule": ["Par binôme, classer chaque intervention : je sais (fumée courte à l'air libre), je sens (la tenue sent la fumée : déblai, reconnaissance, attaque), je vois (exposition longue, traces visibles).", "Pour chacune, dire le bon nettoyage : aérer les EPI / brosser à sec et aérer / EPI dans un sac et tenue propre au retour.", "Rappel : douche au retour au centre, avant de rentrer chez soi."], "phrase": "Une tenue qui sent la fumée n'est pas une tenue propre.", "securite": ""}, {"titre": "Mon plan maison", "duree": "10 min", "prep": "Feuilles et crayons, un détecteur de fumée.", "deroule": ["Chaque JSP dessine son logement et place le ou les détecteurs de fumée et son chemin de sortie.", "Il dit ce qu'il fait si la fumée bloque la sortie : rester dans une pièce, fermer la porte, calfeutrer avec des linges mouillés, se signaler à la fenêtre, appeler le 18."], "phrase": "Porte fermée, rester bas, sortir et appeler.", "securite": ""}], "questions": [{"q": "Cite les 5 dangers des fumées.", "r": "Chaudes, opaques, mobiles, inflammables, toxiques."}, {"q": "Pourquoi le CO est-il si dangereux ?", "r": "Invisible et sans odeur, il prend la place de l'oxygène dans le sang."}, {"q": "Quels matériaux donnent les fumées les plus toxiques ?", "r": "Les plastiques et les mousses (canapés, matelas, isolants)."}, {"q": "Par où les toxiques entrent-ils dans le corps ?", "r": "Respiration, peau, bouche, yeux."}, {"q": "Quel est souvent le premier signe d'une intoxication ?", "r": "Le mal de tête."}, {"q": "Jusqu'à quand le pompier garde-t-il l'ARI ?", "r": "Dès qu'il y a de la fumée et jusqu'à la fin du déblai."}, {"q": "Ma tenue sent la fumée : je suis à quel niveau ?", "r": "« Je sens » : brossage à sec et aération."}, {"q": "Que fait-on en rentrant au centre ?", "r": "On nettoie le matériel et on prend une douche."}, {"q": "Quel appareil protège la famille la nuit ?", "r": "Le détecteur de fumée."}], "quiz": [{"q": "Dans un incendie d'appartement, qu'est-ce qui fait le plus de victimes ?", "bonne": "Les fumées", "fausses": ["Les flammes", "L'eau des lances", "Le bruit"], "expl": "Souvent pendant le sommeil."}, {"q": "Les fumées sont chaudes, opaques, mobiles, inflammables et…", "bonne": "Toxiques", "fausses": ["Froides", "Propres", "Immobiles"], "expl": "Les 5 dangers des fumées."}, {"q": "Le monoxyde de carbone (CO) :", "bonne": "Invisible et sans odeur, il prend la place de l'oxygène dans le sang", "fausses": ["Il sent très fort", "Il est toujours noir", "Il n'existe que dans les usines"], "expl": ""}, {"q": "Quelles matières qui brûlent donnent des gaz très toxiques ?", "bonne": "Les plastiques et les mousses", "fausses": ["La pierre", "Le sable", "Le verre"], "expl": "Canapés, matelas, isolants."}, {"q": "Les 4 portes d'entrée des toxiques dans le corps :", "bonne": "Respiration, peau, bouche, yeux", "fausses": ["Respiration seulement", "Cheveux, ongles, oreilles, pieds", "Peau seulement"], "expl": ""}, {"q": "Ma tenue sent la fumée après un déblai : c'est le niveau…", "bonne": "« Je sens »", "fausses": ["« Je sais »", "« Je vois »", "Pas de nettoyage"], "expl": "Brossage à sec et aération des EPI."}, {"q": "En rentrant au centre après un feu :", "bonne": "Douche obligatoire avant de rentrer chez soi", "fausses": ["Je rentre chez moi en tenue", "Je range ma tenue sale dans la cabine", "Je mange avant de me laver les mains"], "expl": ""}, {"q": "La nuit, qu'est-ce qui réveille la famille si la fumée arrive ?", "bonne": "Le détecteur de fumée", "fausses": ["Le thermostat", "La box internet", "L'extincteur"], "expl": "Obligatoire dans chaque logement."}], "statut": "brouillon", "source": "Cours 2026 « La toxicité des fumées d'incendie » (charte SDIS 34) · RDEB SDIS 34 v2 (avril 2026) § 2.24 (danger des fumées), § 4.1 (exposition des intervenants), § 4.2 (nettoyage je sais / je sens / je vois), § 4.3 (lot DECOPI) ; GDO « prévention des risques liés à la toxicité des fumées » (2020) ; RNF JSP2 (détecteurs, dangers de la fumée) – à valider : item sans fiche RNF dédiée ; contenu sur les gaz toxiques (CO, HCN, gaz irritants, suies) issu de connaissances générales (chef de section)"}, "JSP2|Les contraintes physiologiques de l'ARI": {"cycle": "JSP2", "bloc": "Sécuriser la zone d'intervention", "item": "Les contraintes physiologiques de l'ARI", "objectif": "Citer les contraintes de l'ARI pour le porteur (poids, respiration, cœur, stress, perception) et calculer l'autonomie d'une bouteille avec la formule du cours, sans erreur.", "pointsCles": ["L'ARI-CO isole : le porteur ne respire que l'air de sa bouteille, jamais l'air ambiant", "Bouteille composite 7,2 L ou métallique 6 L, pleine à 300 bars ; de l'air comprimé, pas de l'oxygène", "Éléments : masque, soupape (SAD), manomètre (sifflet à 55 bars), détendeur (300 → 7 bars), robinet, harnais, cagoule d'évacuation", "Le poids : jusqu'à 18 kg sur le dos, l'équilibre change et on se fatigue plus vite", "La respiration : souffler dans le masque demande un effort, une partie de l'air expiré est respirée à nouveau", "Le cœur bat plus vite (effort, chaleur, stress) : on transpire, on se déshydrate, on s'épuise ; si on panique, la bouteille se vide plus vite", "On voit moins bien, on entend moins bien, on parle mal : gestes et radio", "Consommation : repos 10 L/min · effort intense 50 · effort continu 105 · sauvetage 135 L/min", "Autonomie = pression × volume ÷ consommation (ex. 250 × 7,2 ÷ 105 ≈ 17 min) ; réserve de 55 bars : au sifflet on sort tout de suite", "Pour tenir : bon entraînement physique, bien boire, bien manger, bien dormir"], "materiel": "FPTGP : ARI-CO (bouteilles de formation), masques, cagoules, casques · un masque seul par binôme · sac lesté ou bouteille pour sentir le poids · panneau à lire, calculatrice ou ardoises · lingettes de nettoyage des masques.", "activites": [{"titre": "Dans la peau du porteur", "duree": "15 min", "prep": "Masques seuls (sans ARI), un panneau de lettres, une consigne chuchotée.", "deroule": ["Un JSP coiffe un masque (sans ARI) : il lit un panneau, écoute une consigne chuchotée, cherche un objet au sol.", "Les autres observent ce qui est plus difficile.", "On liste ensemble : voir, entendre, parler."], "phrase": "Sous ARI, tout est plus difficile : il faut s'entraîner.", "securite": "Temps sous masque court, animateur à côté, retrait immédiat en cas de malaise ou de panique."}, {"titre": "Le poids de l'ARI", "duree": "10 min", "prep": "Un ARI-CO de formation, un animateur pour aider à le mettre sur le dos.", "deroule": ["Chaque JSP porte l'ARI sur le dos 1 minute (aidé par l'animateur), sans masque.", "Il marche, se baisse, passe sous une table.", "Il dit ce qu'il a ressenti (équilibre, fatigue)."], "phrase": "Jusqu'à 18 kg sur le dos : la condition physique, c'est ta sécurité.", "securite": "Pas d'évolution sous ARI en JSP2. Aide pour le capelage et le décapelage, sol dégagé."}, {"titre": "Combien de temps ça dure ?", "duree": "15 min", "prep": "Ardoises, tableau des consommations (10 / 50 / 105 / 135 L/min).", "deroule": ["Rappel de la formule : pression × volume ÷ consommation.", "Par binôme : calcul pour 7,2 L à 300 bars au repos, puis en sauvetage.", "Puis avec 250 bars et 105 L/min (≈ 17 min).", "Question : « Le sifflet sonne, que fais-tu ? »"], "phrase": "Plus tu travailles ou tu paniques, plus la bouteille se vide vite.", "securite": ""}], "questions": [{"q": "Que veut dire « isolant » dans ARI ?", "r": "Le porteur ne respire que l'air de sa bouteille, jamais l'air ambiant."}, {"q": "À quelle pression est une bouteille pleine ?", "r": "300 bars."}, {"q": "Que se passe-t-il à 55 bars ?", "r": "Le sifflet retentit : c'est la réserve, on sort tout de suite."}, {"q": "Combien pèse un ARI au maximum ?", "r": "Jusqu'à 18 kg."}, {"q": "Pourquoi le cœur bat-il plus vite sous ARI ?", "r": "À cause de l'effort, de la chaleur et du stress."}, {"q": "Pourquoi la panique est-elle dangereuse ?", "r": "On respire plus vite et la bouteille se vide plus vite."}, {"q": "Combien consomme-t-on en sauvetage ?", "r": "Environ 135 L/min."}, {"q": "Comment calcule-t-on l'autonomie ?", "r": "Pression × volume ÷ consommation."}, {"q": "Comment se préparer à porter l'ARI ?", "r": "Entraînement physique, bien boire, bien manger, bien dormir."}], "quiz": [{"q": "Une bouteille d'ARI contient…", "bonne": "De l'air comprimé", "fausses": ["De l'oxygène pur", "De l'azote pur", "Du CO2"], "expl": "78 % d'azote, 21 % d'oxygène."}, {"q": "Pression d'une bouteille pleine ?", "bonne": "300 bars", "fausses": ["55 bars", "7 bars", "1 000 bars"], "expl": ""}, {"q": "Le sifflet de l'ARI retentit à…", "bonne": "55 bars", "fausses": ["270 bars", "300 bars", "10 bars"], "expl": "C'est la réserve : on sort immédiatement."}, {"q": "Poids maximum d'un ARI sur le dos ?", "bonne": "18 kg", "fausses": ["2 kg", "40 kg", "5 kg"], "expl": ""}, {"q": "Quelle activité consomme le plus d'air ?", "bonne": "Le sauvetage d'une victime", "fausses": ["Le repos", "Attendre les secours", "Marcher doucement"], "expl": "Environ 135 L/min."}, {"q": "250 bars × 7,2 L ÷ 105 L/min ≈ ?", "bonne": "17 minutes", "fausses": ["3 heures", "2 minutes", "1 heure"], "expl": ""}, {"q": "Un porteur qui panique…", "bonne": "Vide sa bouteille plus vite", "fausses": ["Consomme moins d'air", "Voit mieux", "N'a plus besoin de son binôme"], "expl": ""}, {"q": "Sous ARI, pour communiquer on utilise…", "bonne": "Les gestes et la radio", "fausses": ["Le sifflet", "On crie très fort", "On enlève le masque"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « L'appareil respiratoire isolant » (charte SDIS 34), parties 1 et 2 · RNF JSP/JMP v1.1 fiche JSP2 INC A1 · RDEB SDIS 34 v2 (avril 2026) § 1.1, 1.4 à 1.8, 2.1 à 2.3, 2.11"}, "JSP3|Notions élémentaires d'hydraulique": {"cycle": "JSP3", "bloc": "Eteindre un incendie", "item": "Notions élémentaires d'hydraulique", "objectif": "Distinguer débit et pression et calculer, avec le tableau des pertes de charge, la pression à afficher à la pompe pour un établissement simple (2 situations justes sur 2, 10 min).", "pointsCles": ["Débit = quantité d'eau par minute (l/min) ; pression = force de l'eau (bar) ; une LDV : 250 ou 500 l/min", "Pressions : atmosphérique, statique (lance fermée), dynamique (lance ouverte) ; à l'ouverture, la pression baisse", "Pression de fonctionnement : LDV, lance canon, lance rideau 6 bars ; injecteur de mousse 10 bars", "Un binôme dans un feu doit pouvoir disposer de 500 l/min (débit de référence pour le conducteur)", "Perte de charge = pression perdue entre la pompe et la lance à cause des frottements de l'eau sur les parois et les raccords", "Les pertes augmentent avec la longueur, le débit, un plus petit diamètre, la rugosité du tuyau ; elles ne dépendent pas de la pression", "Débit × 2 = pertes × 4 : Ø45 de 20 m → 0,3 bar à 250 l/min, 1,2 bar à 500 l/min", "Dénivelé : +1 bar par 10 m de montée, −1 bar par 10 m de descente ; environ +1 bar par pièce (division, réduction…)", "Pression à la pompe = 6 bars à la lance + pertes des tuyaux + dénivelé + pièces (ex. 3 Ø45 à 500 l/min au 3e étage : 6 + 3,6 + 1 = 10,6 bars)", "Pas plus de 3 tuyaux de Ø45 après la prise d'eau ; pour aller loin, du Ø70 jusqu'à une division ; une citerne de 3 000 L se vide en 6 min à 500 l/min"], "materiel": "FPTGP avec le conducteur (manomètres de la pompe), LDV 40, tuyaux de Ø45 et Ø70, une division, tuyau d'arrosage et robinet, mètre ruban, pailles courtes / longues / fines / larges, cartes « situation » et tableau des pertes de charge du RDMI (copie), ardoises.", "activites": [{"titre": "Le couloir et les pailles", "duree": "10 min", "prep": "Couloir étroit et couloir large (plots), pailles de longueurs et diamètres différents, verres d'eau.", "deroule": ["Le groupe traverse en file un couloir étroit, puis plus nombreux, puis un couloir large : qu'est-ce qui ralentit ?", "Chacun aspire de l'eau avec une paille courte, longue, fine, large.", "On fait le lien : longueur, diamètre, débit = pertes de charge."], "phrase": "Plus c'est long, étroit et chargé, plus l'eau perd de la force.", "securite": ""}, {"titre": "Le tuyau d'arrosage et le manomètre", "duree": "10 min", "prep": "Tuyau d'arrosage sur un robinet, mètre ; FPT avec le conducteur.", "deroule": ["Mesurer la portée du jet avec 1, puis 3 tuyaux d'arrosage bout à bout.", "Au FPT : lire le manomètre, lance fermée (statique) puis ouverte (dynamique) : la pression baisse."], "phrase": "Quand on ouvre la lance, une partie de la force se perd en route.", "securite": "Lance tenue à deux mains, jamais dirigée vers quelqu'un ; pompe manœuvrée par le conducteur uniquement."}, {"titre": "Défi calcul par équipes", "duree": "20 min", "prep": "Cartes situation (nombre de tuyaux, débit, étage, division, cave), tableau des pertes de charge, ardoises.", "deroule": ["Exemple guidé : LDV à 250 l/min, 2 Ø45 au rez-de-chaussée → 6 + 0,6 = 6,6 bars.", "Chaque équipe tire une carte et calcule la pression à la pompe (lance + tuyaux + dénivelé + pièces).", "Le conducteur valide ou corrige ; bonus : comparer 60 m en Ø45 (3,6 bars) et en Ø70 (0,3 bar) à 500 l/min.", "Dernière carte : combien de temps dure une citerne de 3 000 L avec une lance à 500 l/min ?"], "phrase": "Pompe = 6 bars + tuyaux + 1 bar par 10 m de montée + 1 bar par pièce.", "securite": ""}], "questions": [{"q": "Différence entre débit et pression ?", "r": "Le débit est la quantité d'eau par minute (l/min), la pression la force de l'eau (bar)."}, {"q": "Pression de fonctionnement d'une LDV ?", "r": "6 bars."}, {"q": "Quel débit un binôme dans un feu doit-il pouvoir avoir ?", "r": "500 l/min."}, {"q": "Qu'est-ce qu'une perte de charge ?", "r": "La pression perdue entre la pompe et la lance à cause des frottements de l'eau."}, {"q": "Le débit double : que deviennent les pertes ?", "r": "Elles sont multipliées par 4."}, {"q": "Les pertes de charge dépendent-elles de la pression ?", "r": "Non, seulement du débit (et de la longueur, du diamètre, de l'état du tuyau)."}, {"q": "Combien de bar pour monter de 10 m ?", "r": "1 bar de plus."}, {"q": "Pertes d'un Ø45 de 20 m à 500 l/min ?", "r": "1,2 bar."}, {"q": "Combien de tuyaux de Ø45 au maximum après la prise d'eau ?", "r": "3, dans la mesure du possible."}, {"q": "Combien de temps dure une citerne de 3 000 L à 500 l/min ?", "r": "6 minutes."}], "quiz": [{"q": "Le débit se mesure en…", "bonne": "Litres par minute", "fausses": ["Bars", "Mètres", "Degrés"], "expl": "La pression, elle, se mesure en bars."}, {"q": "Pression de fonctionnement d'une LDV :", "bonne": "6 bars", "fausses": ["1 bar", "10 bars", "16 bars"], "expl": "L'injecteur de mousse : 10 bars."}, {"q": "La pression statique, c'est quand…", "bonne": "La lance est fermée", "fausses": ["La lance est ouverte", "La pompe est arrêtée et vide", "On aspire dans une rivière"], "expl": ""}, {"q": "Le débit double, les pertes de charge sont…", "bonne": "Multipliées par 4", "fausses": ["Multipliées par 2", "Divisées par 2", "Inchangées"], "expl": "Ø45/20 m : 0,3 bar à 250 l/min, 1,2 bar à 500 l/min."}, {"q": "Pour monter de 10 m, il faut…", "bonne": "1 bar de plus", "fausses": ["10 bars de plus", "0,1 bar de plus", "Rien de plus"], "expl": "Et on gagne 1 bar en descendant de 10 m."}, {"q": "Pertes d'un tuyau de Ø45 de 20 m à 500 l/min :", "bonne": "1,2 bar", "fausses": ["0,1 bar", "0,3 bar", "6 bars"], "expl": ""}, {"q": "Plus le diamètre du tuyau est gros…", "bonne": "Moins il y a de pertes", "fausses": ["Plus il y a de pertes", "Plus la pression monte", "Moins il y a de débit"], "expl": "D'où le Ø70 pour aller loin."}, {"q": "Au maximum, combien de tuyaux de Ø45 après la prise d'eau ?", "bonne": "3", "fausses": ["1", "6", "10"], "expl": "Au-delà, les pertes deviennent trop grandes."}], "statut": "brouillon", "source": "Cours 2026 « Les notions élémentaires d'hydraulique » (charte SDIS 34) · RDMI SDIS 34 v6 (avril 2026) ch.3 (pressions, lois et tableau d'aide aux pertes de charge, abaque hectométrique) ; GTO « Établissements et techniques d'extinction »"}, "JSP3|La mise en oeuvre des dispositifs d'alimentation": {"cycle": "JSP3", "bloc": "Eteindre un incendie", "item": "La mise en oeuvre des dispositifs d'alimentation", "objectif": "Reconnaître un PEI à sa couleur et à sa plaque, puis alimenter l'engin sur un poteau (purge, division, ouverture progressive et complète) et monter une ligne d'aspiration depuis le bord, en binôme, sans erreur de sécurité.", "pointsCles": ["La DECI = l'ensemble des points d'eau prévus pour l'incendie : poteaux et bouches sous pression, points d'eau naturels ou artificiels, autres dispositifs, autodéfense", "Couleurs : rouge = sous pression ; rouge cerclé de vert = eau non potable ; bleu = aspiration ; jaune = très forte pression (> 8 bars, prévenir le conducteur) ; vert = borne de puisage interdite aux pompiers", "Poteaux : Ø80 = 500 l/min ; Ø100 (le plus courant) = 1 000 l/min ; Ø150 = 2 000 l/min ; pression de 1 à 16 bars ; ouverture 13 ou 17 tours dans le sens inverse des aiguilles d'une montre", "Bouche d'incendie : au sol, repérée par sa plaque (type, diamètre / débit, distances) ; clé de barrage, coude (Ø110) ou retenue (Ø70) ; 17 tours ; gilet et balisage sur la chaussée", "Pendant le trajet, le binôme d'alimentation repère 2 points d'eau et les indique au conducteur", "Matériel : clé fédérale (poteau), clé de barrage (bouche), division Ø100/2×65, tuyau Ø110 de 20 m, tuyaux Ø70 en Z ou dévidoir mobile", "Alimenter : établir de l'engin vers le point d'eau, purger, installer division / coude / retenue, raccorder, ouvrir ; ramener la clé, vérifier, se mettre à disposition", "Ouvrir et fermer progressivement (coup de bélier) et en entier (un poteau à moitié ouvert fuit par le bas) ; moins de 20 m : Ø110 par le conducteur seul ; plus loin : Ø70 en Z (1 ligne sur 200 m ou 2 lignes sur 100 m)", "Aspiration : 6 m de haut au plus entre l'eau et la pompe, 8 m au plus entre l'engin et la crépine ; aspiraux rigides Ø110 de 2 m, crépine, flotteur (30 cm sous la surface, 50 cm au-dessus du fond), commande ; aucune entrée d'air", "Risque de noyade : jamais seul au bord de l'eau, jamais dans l'eau, toujours surveillé, gilet si prévu"], "materiel": "FPTGP avec le conducteur : clé fédérale, clé de barrage, division Ø100/2×65 et bouchons, tuyau Ø110/20 m, tuyaux Ø70/20 m en Z, dévidoir mobile, collecteur, 8 aspiraux semi-rigides Ø110/2 m, 2 crépines, 2 flotteurs et commandes, tricoises / polycoises. Poteau autorisé pour la formation, réserve ou bassin sécurisé, bouée / perche / gilets, plan de Cruzy ou Quarante, photos de poteaux de couleur et de plaques.", "activites": [{"titre": "Chasse aux PEI", "duree": "10 min", "prep": "Plan de Cruzy ou de Quarante, photos de poteaux et de plaques.", "deroule": ["Les binômes relèvent les PEI autour du centre : couleur, plaque, accessibilité, voiture gênante.", "Ils lisent une plaque : type, diamètre ou débit, distances.", "On compare avec la carte des PEI de l'engin."], "phrase": "Une couleur = une information.", "securite": "Rester sur le trottoir, groupe encadré."}, {"titre": "Brancher l'engin sur le poteau", "duree": "15 min", "prep": "Poteau autorisé, conducteur présent, matériel posé près de l'engin.", "deroule": ["Ordre donné par l'animateur : « Conducteur, alimentation de l'engin-pompe, PI à utiliser…, Établissez ! ».", "Le JSP établit le Ø110 depuis l'engin vers le poteau, purge, pose la division, raccorde.", "Il ouvre progressivement et en entier en comptant les tours, ramène la clé, vérifie et se met à disposition.", "Variante : point d'eau à plus de 20 m, le 2e binôme établit deux Ø70 en Z."], "phrase": "De l'engin vers le point d'eau, jamais l'inverse.", "securite": "Ouverture progressive (coup de bélier), raccords tenus à l'écart du visage."}, {"titre": "Monter une ligne d'aspiration", "duree": "15 min", "prep": "Réserve ou bassin sécurisé, zone interdite délimitée au bord, un formateur dédié à la surveillance, bouée et perche.", "deroule": ["Le 2e binôme pose et raccorde les aspiraux au sol.", "Il attache la commande à la crépine, puis crépine et flotteur au dernier aspiral.", "Il raccorde à l'aspiral de l'engin, immerge la ligne depuis le bord et amarre la commande.", "Le conducteur met en aspiration ; on cherche ensemble pourquoi un joint mal serré empêche d'aspirer (expérience de la paille trouée)."], "phrase": "Pas d'air dans la ligne, sinon pas d'eau.", "securite": "RISQUE DE NOYADE : jamais seul, jamais dans l'eau, toujours surveillé, gilet si prévu."}], "questions": [{"q": "Que veut dire un poteau bleu ?", "r": "Il n'a pas de pression : il faut aspirer."}, {"q": "Peut-on utiliser une borne verte ?", "r": "Non : borne de puisage, hors défense incendie."}, {"q": "Que signale un poteau jaune ?", "r": "Une très forte pression (plus de 8 bars) : on prévient le conducteur."}, {"q": "Débit d'un poteau de Ø100 ?", "r": "1 000 litres par minute."}, {"q": "Comment ouvre-t-on un poteau ?", "r": "Doucement et en entier, dans le sens inverse des aiguilles d'une montre."}, {"q": "Dans quel sens établit-on l'alimentation ?", "r": "De l'engin vers le point d'eau."}, {"q": "Que cherche le binôme d'alimentation pendant le trajet ?", "r": "Deux points d'eau proches du feu, qu'il indique au conducteur."}, {"q": "À quoi sert la crépine ?", "r": "À empêcher les cailloux et débris d'entrer dans la pompe."}, {"q": "Hauteur maximale entre l'eau et la pompe pour aspirer ?", "r": "6 m (et 8 m au plus entre l'engin et la crépine)."}, {"q": "Le grand danger de l'aspiration ?", "r": "La noyade : jamais seul, jamais dans l'eau."}], "quiz": [{"q": "Un poteau rouge signifie…", "bonne": "De l'eau sous pression", "fausses": ["Il faut aspirer", "Interdit aux pompiers", "Très forte pression"], "expl": ""}, {"q": "Un poteau bleu signifie…", "bonne": "Il faut aspirer", "fausses": ["Eau sous pression", "Eau potable", "Poteau hors service"], "expl": "Pas de pression permanente."}, {"q": "La borne verte (borne de puisage)…", "bonne": "N'est pas utilisable par les pompiers", "fausses": ["Donne 2 000 l/min", "Sert à la mousse", "Est réservée aux feux de forêt"], "expl": ""}, {"q": "Débit d'un poteau de Ø100 :", "bonne": "1 000 l/min", "fausses": ["100 l/min", "500 l/min", "5 000 l/min"], "expl": "Ø80 : 500 ; Ø150 : 2 000."}, {"q": "On ouvre un poteau…", "bonne": "Progressivement et en entier", "fausses": ["D'un coup sec", "À moitié seulement", "Avec le pied"], "expl": "Coup de bélier si trop vite ; fuite par le bas si à moitié ouvert."}, {"q": "Point d'eau à moins de 20 m : on alimente avec…", "bonne": "Un tuyau de Ø110", "fausses": ["Trois tuyaux de Ø45", "Une LDV", "Un aspiral"], "expl": "Le conducteur le fait seul."}, {"q": "Hauteur maximale d'aspiration entre l'eau et la pompe :", "bonne": "6 m", "fausses": ["1 m", "15 m", "30 m"], "expl": ""}, {"q": "Pour placer la crépine dans la rivière, le JSP…", "bonne": "Reste sur le bord et utilise la commande", "fausses": ["Entre dans l'eau", "Y va seul", "Plonge le flotteur à la main"], "expl": "Risque de noyade."}], "statut": "brouillon", "source": "Cours 2026 « Les points d'eau incendie » (charte SDIS 34) · RDMI SDIS 34 v6 (avril 2026) ch.2 (DECI, couleurs, signalisation, cartographie), ch.8.13-8.14, fiches ETB 4.1 à 4.5 ; FAT FPTGP ; GTO « Établissements et techniques d'extinction »"}, "JSP4|Notions de prévention appliquées à l'opération": {"cycle": "JSP4", "bloc": "Sécuriser la zone d'intervention", "item": "Notions de prévention appliquées à l'opération", "objectif": "Lors d'un rallye dans la caserne (ou un ERP avec accord), retrouver au moins 8 équipements de sécurité de la liste et dire pour chacun à quoi il sert aux sapeurs-pompiers en intervention — 20 min.", "pointsCles": ["La prévention, c'est avant le feu : des règles pour construire (accès, murs, portes, sorties, alarmes) ; pendant le feu, les pompiers utilisent tout ce qui a été prévu", "Desserte : la voie engins amène les camions jusqu'au bâtiment ; la voie échelles, au pied de la façade, permet de dresser la grande échelle ; une voiture garée dessus peut empêcher un sauvetage", "Quatre familles d'habitations (RDMI ch. 4) : 1re maison jusqu'à R+1 ; 2e petit immeuble jusqu'à R+3 ; 3e jusqu'à 28 m (≈ R+9) ; 4e jusqu'à 50 m (≈ R+17) ; au-delà : IGH", "Colonne sèche : un tuyau vide dans l'escalier, l'engin pompe en bas, une prise à chaque étage ; à privilégier quand elle existe (RDMI § 6.10)", "Ascenseur prioritaire : rappelé par les pompiers avec une clé spéciale, surtout pour monter le matériel (RDEB § 5.10)", "Cloisonnement : murs et portes qui résistent au feu ; la porte coupe-feu se referme seule et ne se cale jamais ouverte dans la vie de tous les jours", "Compartimentage (supermarché, entrepôt) : grand volume coupé en morceaux ; sectorisation (hôpital, maison de retraite, internat) : on évacue à plat d'un secteur à l'autre", "Désenfumage naturel (ouvertures en haut, air frais en bas) ou mécanique (ventilateurs) : garder couloirs et escaliers sans fumée", "Sorties : panneau vert allumé même sans courant, barre anti-panique, plan d'évacuation, point de rassemblement, dégagements toujours libres, espace d'attente sécurisé", "Alarmes : détecteur de fumée obligatoire dans chaque logement, déclencheur manuel « bris de glace », alarme générale, tableau d'alarme qui indique la zone du feu"], "materiel": "Fiche rallye à cocher (panneau sortie, bloc de secours, déclencheur manuel, extincteur, RIA, porte coupe-feu, plan d'évacuation, commande de désenfumage, colonne sèche, coupure gaz), plans d'évacuation imprimés, feutres, tablette avec photos d'équipements, plot pour figurer le FPTGP et la grande échelle.", "activites": [{"titre": "Le rallye des équipements", "duree": "20 min", "prep": "Fiche à cocher par binôme, parcours dans la caserne (ou un ERP avec l'accord de l'exploitant).", "deroule": ["Chaque binôme cherche les équipements de la liste.", "Il note où ils sont et à quoi ils servent.", "Débrief : lesquels aident les pompiers en intervention ? (plan, tableau d'alarme, colonne sèche, coupures…)"], "phrase": "On regarde, on note, on ne déclenche rien !", "securite": "Interdiction de toucher aux déclencheurs, extincteurs et commandes."}, {"titre": "Lis le plan", "duree": "10 min", "prep": "Plans d'évacuation imprimés (collège, caserne), feutres.", "deroule": ["Chaque binôme trouve « vous êtes ici ».", "Il trace le chemin vers la sortie la plus proche et le point de rassemblement.", "Variante : un couloir est enfumé, quel autre chemin ?"], "phrase": "Toujours savoir par où sortir.", "securite": ""}, {"titre": "Où placer la grande échelle ?", "duree": "10 min", "prep": "Photo ou schéma d'un immeuble avec voiries et véhicules garés.", "deroule": ["Les JSP repèrent la voie engins et la voie échelles.", "Ils disent ce qui gênerait (voiture garée, arbres, câbles).", "Ils donnent la famille d'habitation de l'immeuble."], "phrase": "Une voie échelles encombrée, c'est un sauvetage en moins.", "securite": ""}], "questions": [{"q": "Voie engins, voie échelles : à quoi servent-elles ?", "r": "Amener les engins jusqu'au bâtiment et dresser la grande échelle."}, {"q": "À quoi sert une colonne sèche ?", "r": "Monter l'eau dans les étages sans monter les tuyaux."}, {"q": "Une porte coupe-feu, on peut la caler ouverte ?", "r": "Non, jamais dans la vie de tous les jours."}, {"q": "Compartimenter, c'est quoi ?", "r": "Couper un grand bâtiment en morceaux qui retiennent le feu."}, {"q": "Pourquoi désenfumer ?", "r": "Garder couloirs et escaliers sans fumée pour sortir et intervenir."}, {"q": "Qui dit aux pompiers où est le feu ?", "r": "Le tableau de l'alarme incendie."}, {"q": "Une maison R+1, c'est quelle famille ?", "r": "La 1re famille."}, {"q": "Qu'est-ce que la sectorisation ?", "r": "Découper le bâtiment en secteurs protégés pour évacuer à plat, sans faire descendre (hôpital, maison de retraite)."}], "quiz": [{"q": "La voie échelles sert à…", "bonne": "Dresser la grande échelle au pied de la façade", "fausses": ["Garer les voitures des habitants", "Stocker les poubelles", "Faire demi-tour aux bus"], "expl": ""}, {"q": "Une colonne sèche, c'est…", "bonne": "Un tuyau vide qui monte l'eau dans les étages", "fausses": ["Un poteau d'incendie dans la rue", "Un extincteur géant", "Une gaine de désenfumage"], "expl": ""}, {"q": "La porte coupe-feu dans la vie de tous les jours :", "bonne": "Toujours fermée, jamais calée", "fausses": ["Calée ouverte pour aérer", "Fermée à clé", "Retirée l'été"], "expl": ""}, {"q": "Un immeuble jusqu'à 28 m (≈ R+9) est de la…", "bonne": "3e famille", "fausses": ["1re famille", "2e famille", "4e famille"], "expl": ""}, {"q": "Dans un hôpital, on évacue les patients…", "bonne": "À plat, d'un secteur à l'autre", "fausses": ["Par l'ascenseur", "Par les fenêtres", "On attend que le feu passe"], "expl": "C'est la sectorisation."}, {"q": "Le panneau de sortie de secours est…", "bonne": "Vert, allumé même sans courant", "fausses": ["Rouge clignotant", "Bleu", "Éteint en cas de coupure"], "expl": ""}, {"q": "Le tableau d'alarme indique aux pompiers…", "bonne": "La zone où le feu a été détecté", "fausses": ["Le nombre d'habitants", "La météo", "L'heure d'arrivée des secours"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La prévention au service de l'intervention » (charte SDIS 34) · RNF INC A4 · RDMI v6 (avril 2026) ch. 4, § 6.4, 6.10 · RDEB v2 § 3.11, 5.10 — voies engins/échelles, compartimentage, désenfumage, alarmes : réglementation générale, à valider avec un préventionniste"}, "JSP4|Phénomènes thermiques": {"cycle": "JSP4", "bloc": "Eteindre un incendie", "item": "Phénomènes thermiques", "objectif": "À partir de photos ou vidéos, nommer le phénomène thermique en préparation (EGE, explosion de fumées, FGI), citer 2 signes et la conduite à tenir, puis réaliser à froid l'ouverture de porte en binôme — 15 min, aucune erreur de sécurité admise.", "pointsCles": ["La fumée, c'est du combustible : si elle est assez chaude, ou rencontre de l'air et une flamme, elle s'enflamme", "Feu avec assez d'air : il grandit et peut tout embraser d'un coup ; feu sans assez d'air : il couve et remplit la pièce de gaz chauds, une entrée d'air peut tout faire exploser", "Embrasement généralisé éclair (EGE) : la chaleur des fumées fait brûler toute la pièce ; signes : chaleur qui oblige à se baisser, fumées épaisses qui descendent, petites flammes dans les fumées, objets qui fument à distance", "EGE : refroidir les fumées par petits coups de lance, prévenir le chef, se replier si la chaleur monte encore, jamais sans lance dans la pièce", "Explosion de fumées : feu sans air + ouverture = explosion ; signes : vitres noires et grasses, peu de flammes, fumées jaunâtres par saccades, sifflement, porte chaude, fumées aspirées sous la porte", "Explosion de fumées : on n'ouvre pas sans ordre du chef, jamais devant la porte (sur le côté, bas), lance en eau ; le chef peut attaquer de l'extérieur ou ventiler par le haut", "Fire Gas Ignition (FGI) : des fumées passées dans une pièce voisine, un faux plafond, une gaine s'enflamment d'un coup, souvent loin du foyer : chercher les fumées partout, refroidir, fermer les portes, caméra thermique au plafond", "Ouvrir une porte : sur le côté et accroupi, tester la chaleur (caméra ou un peu d'eau en haut de la porte), lance prête, ouvrir un peu, impulsions, refermer et observer, entrer bas", "Refroidir les fumées : jet diffusé vers le plafond, très courtes impulsions, juste assez d'eau pour garder la stratification", "Interdit de reproduire les expériences vues en formation (boîte à feu, inflammation de fumées) : brûlures, intoxication, incendie"], "materiel": "Tablette avec vidéos pédagogiques officielles (ENSOSP/SDIS) et photos (vitres noircies, flammes dans les fumées, fumées pulsées), cartes « signe », porte d'exercice de la caserne, établissement LDV 40 à sec depuis le FPTGP, EPI complets ; boîte à feu uniquement par un formateur qualifié.", "activites": [{"titre": "Stop vidéo : quels signes ?", "duree": "10 min", "prep": "Vidéos pédagogiques ENSOSP / SDIS, tablette.", "deroule": ["Tu lances la vidéo et l'arrêtes avant l'embrasement.", "Les binômes citent les signes vus.", "Ils nomment le phénomène qui arrive et ce qu'il faut faire."], "phrase": "Les fumées parlent : apprends à les écouter.", "securite": ""}, {"titre": "Quel phénomène ?", "duree": "10 min", "prep": "Cartes situation/photo : vitres noires et grasses, flammes qui courent au plafond, faux plafond enfumé dans la pièce voisine…", "deroule": ["Chaque binôme tire une carte.", "Il dit : EGE, explosion de fumées ou FGI ?", "Il donne la conduite à tenir (refroidir et se replier / ne pas ouvrir / chercher, refroidir, fermer)."], "phrase": "", "securite": ""}, {"titre": "La porte", "duree": "20 min", "prep": "Porte d'exercice, LDV 40 à sec, binôme en EPI. L'animateur annonce la « température » de la porte.", "deroule": ["Le binôme se place sur le côté, accroupi, hors de l'axe.", "Il teste la chaleur (geste mimé), lance prête.", "Il ouvre un peu, mime les impulsions vers le plafond, referme et observe.", "Il entre bas, puis referme derrière lui si possible."], "phrase": "Tant qu'elle est fermée, la porte retient le feu.", "securite": "À froid, sans feu réel ; boîte à feu seulement par le formateur, dehors, extincteur prêt, JSP à distance. Rappeler l'interdiction de reproduire."}], "questions": [{"q": "Où se trouvent les fumées chaudes dans une pièce ?", "r": "En haut : on se tient en bas."}, {"q": "Pourquoi la fumée peut-elle s'enflammer ?", "r": "C'est un combustible chaud."}, {"q": "Feu sans air + porte qu'on ouvre = ?", "r": "Risque d'explosion de fumées."}, {"q": "Petites flammes qui courent au plafond : signe de quoi ?", "r": "Embrasement généralisé éclair proche."}, {"q": "Où peut se produire un FGI ?", "r": "Dans une pièce voisine, un faux plafond, une gaine."}, {"q": "Comment refroidir les fumées ?", "r": "Jet diffusé, courtes impulsions vers le plafond."}, {"q": "Où se place-t-on pour ouvrir une porte ?", "r": "Sur le côté, accroupi, jamais face à la porte."}, {"q": "Peut-on refaire chez soi une expérience de boîte à feu ?", "r": "Non, c'est interdit et dangereux."}], "quiz": [{"q": "Vitres noires et grasses, peu de flammes, fumées par saccades :", "bonne": "Risque d'explosion de fumées", "fausses": ["Feu presque éteint", "Embrasement terminé", "Aucun danger"], "expl": "On n'ouvre pas sans ordre du chef."}, {"q": "La chaleur oblige à se baisser et les fumées descendent :", "bonne": "Embrasement généralisé éclair proche", "fausses": ["Le feu s'éteint", "FGI dans la cave", "Signe normal, on continue"], "expl": ""}, {"q": "Des fumées s'enflamment dans un faux plafond loin du foyer :", "bonne": "Fire Gas Ignition", "fausses": ["Explosion de fumées", "Feu de cheminée", "Coup de bélier"], "expl": ""}, {"q": "Pour ouvrir une porte suspecte, je me place…", "bonne": "Sur le côté, accroupi", "fausses": ["Face à la porte, debout", "Le plus loin possible sans lance", "Derrière la fenêtre"], "expl": ""}, {"q": "Refroidir les fumées, c'est…", "bonne": "Courtes impulsions en diffusé vers le plafond", "fausses": ["Jet droit continu au sol", "Ouvrir toutes les fenêtres", "Le plus d'eau possible"], "expl": "Juste assez d'eau pour garder la stratification."}, {"q": "Explosion de fumées : ce qui la déclenche…", "bonne": "Une entrée d'air", "fausses": ["La pluie", "Le jet diffusé", "La fermeture d'une porte"], "expl": ""}, {"q": "Contre le FGI, on…", "bonne": "Cherche les fumées, refroidit et ferme les portes", "fausses": ["Ouvre toutes les portes", "Attend dehors sans rien faire", "Coupe seulement l'électricité"], "expl": ""}, {"q": "Les expériences de boîte à feu :", "bonne": "Réservées aux formateurs", "fausses": ["À refaire à la maison", "Sans danger avec de petites quantités", "Autorisées entre copains"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les phénomènes thermiques et les techniques d'intervention » (charte SDIS 34) · RNF INC C1 · RDMI v6 (avril 2026) § 1.1, 6.6 · RDEB v2 § 2.23, 2.24, 3.10 — phénomènes et techniques : doctrine nationale (GDO incendies de structures, GTO), à valider avec le formateur"}, "JSP2|L'équipement en binôme (RAPACE)": {"cycle": "JSP2", "bloc": "Sécuriser la zone d'intervention", "item": "L'équipement en binôme (RAPACE)", "objectif": "En binôme, capeler l'ARI, coiffer le masque et réaliser à voix haute le contrôle croisé RAPACE complet, sans oubli, en moins de 5 min (sans évoluer sous ARI).", "pointsCles": ["En JSP2, on s'équipe UNIQUEMENT, en binôme : l'évolution sous ARI, c'est à partir du JSP3", "Vocabulaire : capeler (ARI sur le dos), coiffer (masque sur le visage), encliqueter (soupape sur le masque) ; binôme porteur d'ARI (masque prêt) / sous ARI (masque mis et branché)", "Capeler en 4 étapes : enfiler et ouvrir la bouteille jusqu'à la butée → clipser et serrer la ceinture → serrer les bretelles → brancher la soupape et tirer doucement", "Coiffer : cagoule, casque, jugulaire → retenir sa respiration, plaquer le masque → accrocher les griffes → serrer vers l'arrière", "RAPACE = Robinet (ouvert à la butée), Armement (balise activée), Pression (au moins 270 bars), Ajustement (tenue bien portée), Code (gestes et radio), Étanchéité (pas de fuite)", "Une seule anomalie = on ne s'engage pas", "Autour du binôme : le contrôleur (enregistre noms, pression, heures, mission) et le binôme de sécurité (prêt à porter secours)", "3 zones : exclusion (danger), contrôlée (contrôleur, binôme de sécurité), soutien (chefs, engins, réserve d'air)", "Au FPTGP, les 2 binômes capellent pendant le trajet ; tenue complète, aucun bijou, piercing ni montre", "Après l'exercice : nettoyer et désinfecter les masques, ranger chaque appareil prêt à repartir"], "materiel": "FPTGP : ARI-CO avec bouteilles de formation, masques à griffes (et à filet), cagoules, casques, balises (BSD/ICS), tableau de gestion des personnels · lingettes de nettoyage des masques · cartes R-A-P-A-C-E.", "activites": [{"titre": "Les lettres en désordre", "duree": "5 min", "prep": "6 cartes R-A-P-A-C-E mélangées, 6 cartes « mots ».", "deroule": ["Par équipe, remettre RAPACE dans l'ordre.", "Associer chaque lettre à son mot et à ce qu'on vérifie (ex. P = Pression, au moins 270 bars)."], "phrase": "Une seule anomalie, on ne s'engage pas.", "securite": ""}, {"titre": "Capeler et coiffer en binôme", "duree": "20 min", "prep": "1 ARI-CO de formation par binôme, 1 animateur pour 2 binômes.", "deroule": ["Démonstration par l'animateur des 4 étapes du capelage et du coiffage.", "Chaque JSP capelle avec l'aide de son binôme et de l'animateur.", "Il coiffe le masque : cagoule, casque, jugulaire, masque plaqué, griffes, serrage.", "Contrôle croisé RAPACE à voix haute, chacun son tour."], "phrase": "On s'équipe à deux, on se contrôle à deux.", "securite": "On s'équipe, on ne s'engage pas. Temps sous masque court, surveiller malaise ou panique. Aide pour le poids."}, {"titre": "Trouve l'erreur", "duree": "10 min", "prep": "Un animateur équipé avec 3 erreurs cachées (robinet pas à la butée, balise non activée, sangle desserrée…).", "deroule": ["Chaque binôme a 2 min pour faire RAPACE sur l'animateur.", "Il annonce les anomalies et dit : « Pas d'engagement ! »"], "phrase": "", "securite": ""}, {"titre": "Les codes gestuels et le contrôleur", "duree": "10 min", "prep": "Tableau de gestion des personnels.", "deroule": ["Un JSP fait un geste (ça va, ça ne va pas, on fait retour…), les autres le reconnaissent.", "Un JSP joue le contrôleur : il note noms, pression, heure d'entrée, heure de sortie prévue, mission.", "On nettoie et désinfecte les masques."], "phrase": "C'est le C de RAPACE : on se met d'accord avant d'entrer.", "securite": ""}], "questions": [{"q": "Que veut dire « capeler » ?", "r": "Mettre l'ARI sur son dos."}, {"q": "Que veut dire « coiffer » ?", "r": "Mettre le masque sur son visage."}, {"q": "Que veut dire RAPACE ?", "r": "Robinet, Armement, Pression, Ajustement, Code, Étanchéité."}, {"q": "Quelle pression minimum pour s'engager ?", "r": "270 bars."}, {"q": "Que fais-tu si tu trouves une anomalie au contrôle croisé ?", "r": "On ne s'engage pas, on le signale."}, {"q": "Quel est le rôle du contrôleur ?", "r": "Enregistrer les binômes (noms, pression, heures, mission) et calculer l'heure de sortie."}, {"q": "Qui va secourir un binôme en difficulté ?", "r": "Le binôme de sécurité, sur ordre du contrôleur."}, {"q": "Cite les 3 zones d'une intervention.", "r": "Exclusion, contrôlée, soutien."}, {"q": "En JSP2, peut-on évoluer sous ARI ?", "r": "Non : on s'équipe seulement, l'évolution c'est à partir du JSP3."}], "quiz": [{"q": "Dans RAPACE, que veut dire le premier A ?", "bonne": "Armement (balise activée)", "fausses": ["Air", "Alerte", "Attente"], "expl": ""}, {"q": "Pression minimum pour s'engager ?", "bonne": "270 bars", "fausses": ["55 bars", "100 bars", "150 bars"], "expl": ""}, {"q": "Le robinet de la bouteille s'ouvre…", "bonne": "Jusqu'à la butée", "fausses": ["D'un quart de tour", "À moitié", "Pas du tout avant d'entrer"], "expl": ""}, {"q": "Une anomalie au contrôle croisé : que fait-on ?", "bonne": "On ne s'engage pas", "fausses": ["On s'engage quand même", "On le dira en sortant", "On change de binôme"], "expl": ""}, {"q": "« Encliqueter », c'est…", "bonne": "Brancher la soupape sur le masque", "fausses": ["Mettre l'ARI sur le dos", "Fermer la bouteille", "Allumer la radio"], "expl": ""}, {"q": "Qui enregistre les binômes à l'entrée ?", "bonne": "Le contrôleur", "fausses": ["Le conducteur", "Le binôme de sécurité", "La victime"], "expl": ""}, {"q": "Dans quelle zone seuls les binômes équipés entrent-ils ?", "bonne": "La zone d'exclusion", "fausses": ["La zone de soutien", "La zone contrôlée", "Le parking"], "expl": ""}, {"q": "Le C de RAPACE veut dire…", "bonne": "Code (gestes et radio)", "fausses": ["Casque", "Cagoule", "Course"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « L'appareil respiratoire isolant » (charte SDIS 34), partie 3 · RNF JSP/JMP v1.1 fiche JSP2 INC A1 · RDEB SDIS 34 v2 (avril 2026) § 2.5 à 2.10, 2.12 à 2.21, 4.6"}, "JSP2|Le comportement et la réaction au feu des matériaux": {"cycle": "JSP2", "bloc": "Sécuriser la zone d'intervention", "item": "Le comportement et la réaction au feu des matériaux", "objectif": "Expliquer comment réagissent au feu le bois, l'acier, le béton, le verre et les plastiques, et lire une étiquette de résistance au feu (ex. EI 30) sans erreur.", "pointsCles": ["Le bois brûle, mais sa couche de charbon protège le cœur : une grosse poutre tient longtemps", "L'acier ne brûle pas mais se dilate et se ramollit (moitié de sa solidité vers 550 °C) : il peut céder d'un coup", "Le béton ne brûle pas mais peut éclater en surface ; le plâtre ne brûle pas et retarde le feu", "Le verre éclate avec la chaleur : l'air entre et relance le feu", "Les plastiques fondent, coulent en feu et dégagent des fumées très toxiques", "Réaction au feu = le matériau nourrit-il le feu ? Euroclasses A1 (ne brûle pas) à F (non classé) + fumées s1 à s3 + gouttes d0 à d2 (ancien classement M0 à M4)", "Résistance au feu = combien de temps l'élément joue son rôle : R (tient debout), E (bloque flammes et fumées), I (isole de la chaleur) + minutes", "Ex. porte EI 30 : bloque flammes, fumées et chaleur 30 min · mur REI 60 : 1 heure ; une porte coupe-feu ne se cale jamais ouverte", "Signes d'effondrement : fissures qui s'agrandissent, craquements, poutres déformées, plancher qui s'enfonce → je préviens mon chef et je m'éloigne avec mon binôme"], "materiel": "Allumettes et une bûchette du même bois, fil de fer fin avec un petit poids, pince, briquet long, plateau métallique, extincteur à eau · cartes matériaux et étiquettes (A1, D, EI 30, REI 60) · porte coupe-feu repérée dans la caserne.", "activites": [{"titre": "Expériences : fin ou épais ? / le fil de fer", "duree": "15 min", "prep": "Plateau métallique, extincteur à côté. Flammes manipulées par l'animateur uniquement.", "deroule": ["Les JSP parient : allumette ou bûchette, laquelle s'enflamme le plus vite ?", "L'animateur montre : l'épaisseur compte.", "Fil de fer fin tenant un petit poids, chauffé au briquet : il plie.", "Un JSP réexplique ce qu'on a vu (le bois tient, l'acier se ramollit)."], "phrase": "L'acier ne brûle pas… mais il peut céder d'un coup.", "securite": "Cheveux attachés, JSP à distance, animateur seul avec la flamme."}, {"titre": "Vrai ou faux ?", "duree": "10 min", "prep": "Une ligne au sol : VRAI à gauche, FAUX à droite. Affirmations du cours.", "deroule": ["L'animateur lit une affirmation (« On peut caler une porte coupe-feu ouverte pour aérer »…).", "Les JSP se placent du bon côté.", "Un JSP justifie la réponse."], "phrase": "", "securite": "Sol dégagé."}, {"titre": "La chasse aux étiquettes", "duree": "15 min", "prep": "Repérer à l'avance une porte coupe-feu étiquetée (étiquette sur la tranche) et des matériaux de la caserne.", "deroule": ["Par binôme, trouver l'étiquette de la porte coupe-feu et lire son classement.", "Dire ce que veulent dire les lettres et le chiffre.", "Classer 4 matériaux de la caserne du moins au plus dangereux (Euroclasses)."], "phrase": "Une porte coupe-feu fermée protège ; ouverte, elle ne protège plus rien.", "securite": "On reste dans les locaux autorisés, en binôme."}], "questions": [{"q": "Pourquoi l'acier est-il dangereux dans un feu ?", "r": "Il se dilate et se ramollit : il peut s'effondrer d'un coup."}, {"q": "Pourquoi une grosse poutre en bois tient-elle longtemps ?", "r": "La couche de charbon protège le cœur du bois."}, {"q": "Que fait le verre avec la chaleur ?", "r": "Il éclate, l'air entre et relance le feu."}, {"q": "Que font les plastiques dans un feu ?", "r": "Ils fondent, coulent en feu et dégagent des fumées très toxiques."}, {"q": "Quelle est la meilleure Euroclasse ?", "r": "A1 : le matériau ne brûle pas."}, {"q": "Que veut dire la lettre E ?", "r": "Étanchéité : bloque les flammes et les fumées."}, {"q": "Que veut dire « REI 60 » ?", "r": "Résistance, étanchéité et isolation pendant 60 minutes."}, {"q": "Cite un signe de risque d'effondrement.", "r": "Fissures, craquements, poutres déformées, plancher qui s'enfonce."}, {"q": "Que fais-tu si tu vois ces signes ?", "r": "Je préviens tout de suite mon chef et je m'éloigne avec mon binôme."}], "quiz": [{"q": "Quel matériau peut céder d'un coup sans brûler ?", "bonne": "L'acier", "fausses": ["Le plâtre", "La pierre", "La laine de verre"], "expl": "Il se ramollit avec la chaleur."}, {"q": "Que fait le verre avec la chaleur ?", "bonne": "Il éclate et laisse entrer l'air", "fausses": ["Il fond sans danger", "Il éteint le feu", "Il ne change pas"], "expl": ""}, {"q": "Quelle Euroclasse veut dire « ne brûle pas » ?", "bonne": "A1", "fausses": ["F", "D", "E"], "expl": ""}, {"q": "Dans « REI », que veut dire I ?", "bonne": "Isolation", "fausses": ["Incendie", "Intervention", "Interdiction"], "expl": "Il ne chauffe pas trop de l'autre côté."}, {"q": "Une porte EI 30 bloque flammes, fumées et chaleur pendant…", "bonne": "30 minutes", "fausses": ["30 secondes", "3 heures", "30 jours"], "expl": ""}, {"q": "Une porte coupe-feu doit rester…", "bonne": "Fermée", "fausses": ["Calée ouverte", "Démontée", "Ouverte la nuit"], "expl": "Ouverte, elle ne protège plus rien."}, {"q": "Les plastiques en feu dégagent…", "bonne": "Des fumées très toxiques", "fausses": ["De l'oxygène", "De la vapeur d'eau seulement", "Rien du tout"], "expl": ""}, {"q": "Un plancher devient mou sous tes pieds. Tu…", "bonne": "Préviens ton chef et t'éloignes avec ton binôme", "fausses": ["Sautes pour tester", "Continues seul", "Restes sans rien dire"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Comportement et réaction au feu des matériaux » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 INC C3 · Euroclasses (normes européennes) et critères R, E, I"}, "JSP3|Les manœuvres d'alimentation en binôme": {"cycle": "JSP3", "bloc": "Eteindre un incendie", "item": "Les manœuvres d'alimentation en binôme", "objectif": "Sur ordre complet du chef d'agrès, alimenter l'engin avec le dévidoir mobile puis prolonger un établissement d'un tuyau sans abandonner la lance, en binôme, sans erreur de procédure.", "pointsCles": ["Les ordres : « En reconnaissance ! » (s'équiper, prendre le matériel, suivre le chef), « Établissez ! » (le binôme réalise la manœuvre en entier), « Fermez ! » / « Ouvrez ! », « Raccordez – Ouvrez ! »", "L'ordre complet suit le SMES (Situation, Mission, Exécution, Sécurité) ; les restrictions (à sec, engagement sur ordre) sont dites avant « Établissez ! »", "L'engin est alimenté dès qu'une LDV est en service : la citerne se vide vite", "Moins de 20 m : le conducteur seul avec le Ø110 ; plus loin : le 2e binôme avec des Ø70 en Z (1 ligne sur 200 m ou 2 sur 100 m) ou le dévidoir mobile", "On établit toujours de l'engin vers le point d'eau ; en cas de doute, le chef d'équipe peut d'abord aller tester le PEI", "Dévidoir mobile : le conducteur place le collecteur ; le 2e binôme raccorde, déroule jusqu'au PEI, purge, installe division ou retenue, raccorde, ouvre, ramène la clé et remet le dévidoir près de l'engin", "Prolongement : l'équipier pose et établit le ou les tuyaux pendant que le chef continue l'attaque ; « Fermez ! », raccords, « Ouvrez ! », l'équipier vient doubler le porte-lance", "Remplacement d'un tuyau percé : même principe ; le tuyau abîmé est écarté et marqué d'un nœud près de son raccord", "Pas plus de 3 tuyaux de Ø45 après la prise d'eau ; l'eau est coupée le moins longtemps possible", "Le binôme reste en contact permanent ; une fois la mission finie, il vérifie et se met à disposition du chef d'agrès"], "materiel": "FPTGP avec le conducteur : dévidoir mobile (Ø70), collecteur d'alimentation Ø100/2×65, tuyaux Ø70/20 m et Ø45/20 m en Z, division, LDV 40, clé fédérale, division Ø100/2×65 de poteau, tricoises ; poteau autorisé pour la formation ; cartes « ordre du chef ».", "activites": [{"titre": "Les mots du chef", "duree": "10 min", "prep": "Cartes avec les ordres (En reconnaissance, Établissez, Fermez, Ouvrez, Raccordez – Ouvrez, Plongez) et cartes « ce que je fais ».", "deroule": ["Par binôme, associer chaque ordre à l'action.", "Un animateur donne un ordre complet (SMES) ; un JSP le reformule.", "Puis un JSP joue le chef d'agrès et donne l'ordre au binôme suivant."], "phrase": "À « Établissez ! », je fais toute la manœuvre.", "securite": ""}, {"titre": "Alimenter avec le dévidoir mobile", "duree": "15 min", "prep": "Engin, poteau autorisé, dévidoir, collecteur ; conducteur présent.", "deroule": ["Ordre : « Conducteur, 2e binôme, alimentation de l'engin-pompe avec le dévidoir mobile, PI à utiliser…, Établissez ! ».", "Le conducteur place le collecteur ; le 2e binôme raccorde, déroule jusqu'au poteau.", "Purge, division, raccord, ouverture progressive et complète.", "Retour de la clé, dévidoir près de l'engin, vérification, « à disposition »."], "phrase": "De l'engin vers le point d'eau.", "securite": "Dévidoir tiré à deux, pas de course ; ouverture progressive."}, {"titre": "Prolonger sans perdre la lance", "duree": "15 min", "prep": "Établissement d'une LDV 40 déjà en place (2 Ø45), 1 tuyau Ø45 en Z supplémentaire.", "deroule": ["Le chef d'équipe « attaque » (jet sur cible) ; l'équipier pose et établit le tuyau.", "« Fermez ! » : l'équipier fait fermer ; le chef purge et raccorde la lance, l'équipier raccorde les tuyaux.", "« Ouvrez ! » : l'eau revient, l'équipier vient doubler le porte-lance.", "Variante : remplacer un tuyau « percé » (marqué) et le repérer d'un nœud près du raccord."], "phrase": "Le chef garde la lance, l'équipier fait le travail.", "securite": "Lance tenue à deux mains, jamais dirigée vers quelqu'un."}], "questions": [{"q": "Que fait le binôme à l'ordre « Établissez ! » ?", "r": "Il réalise la manœuvre en entier, avec les indications données par le chef."}, {"q": "Que fait-on à l'ordre « En reconnaissance ! » ?", "r": "On s'équipe, on prend son matériel et on suit le chef."}, {"q": "Que veut dire SMES ?", "r": "Situation, Mission, Exécution, Sécurité."}, {"q": "Quand alimente-t-on l'engin ?", "r": "Dès qu'une LDV est en service."}, {"q": "Point d'eau à moins de 20 m : qui alimente et avec quoi ?", "r": "Le conducteur seul, avec un tuyau de Ø110."}, {"q": "Dans quel sens établit-on l'alimentation ?", "r": "De l'engin vers le point d'eau."}, {"q": "Avec le dévidoir, que place le conducteur ?", "r": "Le collecteur sur l'entrée de la pompe."}, {"q": "Pendant un prolongement, que fait le chef d'équipe ?", "r": "Il continue l'attaque, ordonne « Fermez ! » puis « Ouvrez ! » et garde la lance."}, {"q": "Que fait-on d'un tuyau percé ?", "r": "On l'écarte et on fait un nœud près de son raccord."}], "quiz": [{"q": "À l'ordre « Établissez ! », le binôme…", "bonne": "Réalise toute la manœuvre", "fausses": ["Attend un autre ordre", "Prépare seulement le matériel", "Ouvre l'eau tout de suite"], "expl": ""}, {"q": "On établit l'alimentation…", "bonne": "De l'engin vers le point d'eau", "fausses": ["Du point d'eau vers l'engin", "Du feu vers l'engin", "Dans n'importe quel sens"], "expl": "Pour éviter les problèmes d'ouverture de l'eau."}, {"q": "Point d'eau à 15 m de l'engin : on utilise…", "bonne": "Un tuyau de Ø110", "fausses": ["Le dévidoir de Ø45", "Des aspiraux", "Une lance canon"], "expl": ""}, {"q": "Avec des tuyaux de Ø70 en Z, une seule ligne permet d'aller jusqu'à…", "bonne": "200 m", "fausses": ["20 m", "50 m", "1 km"], "expl": "Ou 2 lignes sur 100 m."}, {"q": "Pendant un prolongement, qui garde la lance ?", "bonne": "Le chef d'équipe", "fausses": ["L'équipier", "Le conducteur", "Personne, on la pose"], "expl": ""}, {"q": "L'ordre « Raccordez – Ouvrez ! » veut dire…", "bonne": "Raccorder et ouvrir l'eau tout de suite", "fausses": ["Fermer l'eau", "Plonger la canne", "Partir en reconnaissance"], "expl": ""}, {"q": "Un tuyau percé est…", "bonne": "Écarté et marqué d'un nœud près du raccord", "fausses": ["Laissé en place", "Réparé avec du ruban", "Jeté dans l'engin"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les établissements » (JSP3, charte SDIS 34) · RDMI SDIS 34 v6 (avril 2026) ch.6.10-6.11 (ordres), fiches ETB 4.1 à 4.4, 6.1 et 6.2"}, "JSP3|Les différents binômes": {"cycle": "JSP3", "bloc": "Eteindre un incendie", "item": "Les différents binômes", "objectif": "Dire qui fait quoi (chef d'équipe, équipier, 1er et 2e binôme, conducteur) puis établir et amarrer une lance canon ou une lance rideau en binôme sur ordre, sans erreur de sécurité.", "pointsCles": ["Le binôme = un chef d'équipe + un équipier, indissociable en zone d'exclusion, toujours en contact (main, vue, voix) ; on prévient avant de rompre le contact", "Chef d'équipe : sécurité du binôme, porte la lance ou la ligne guide, choisit le chemin ; équipier : suit, porte la caméra thermique, observe et prévient", "Au FPT : le 1er binôme (attaque) et le 2e binôme (alimentation, prise d'eau, aide) ; les porteurs d'ARI sont désignés par le chef d'agrès ; le conducteur alimente et règle la pompe", "Autour des binômes engagés : le contrôleur (enregistrement, 5 binômes au plus) et le binôme de sécurité, prêt à partir", "Lance canon : jusqu'à 2 000 l/min, établissement de 100 m au plus, engin toujours alimenté ; amarrée avec la sangle (SIM) avant l'ouverture, tuyau droit sur 5 m", "Lance canon : le chef d'équipe pose un Ø70 et la lance, raccorde et amarre ; l'équipier établit jusqu'à l'engin et ouvre l'eau", "Lance rideau (queue de paon) : un mur d'eau de 26 m × 7 m contre la chaleur ou les gaz, alimentée en Ø45, 6 bars", "Lance à mousse : injecteur à 1 %, à 40 m au plus de la lance ; le 2e binôme pose les bidons et plonge la canne à l'ordre « Plongez ! » ; le porte-lance se place dans la boucle (O), l'équipier vient le doubler", "Chaque binôme termine en vérifiant et en se mettant à disposition du chef d'agrès"], "materiel": "FPTGP avec le conducteur : lance canon portable Ø65 et SIM, tuyaux Ø70/20 m en Z, lance rideau mobile Ø40, tuyaux Ø45/20 m en Z, LDV 40 avec adaptateur mousse, injecteur proportionneur, bidons (émulseur d'exercice ou eau seule) ; plots, chasubles « chef d'équipe / équipier / conducteur », cartes-missions.", "activites": [{"titre": "Qui fait quoi ?", "duree": "10 min", "prep": "Chasubles ou cartes de rôle, cartes-actions (porte la lance, porte la caméra, ouvre l'eau, plonge la canne, enregistre les binômes…).", "deroule": ["Chaque JSP reçoit un rôle (chef d'équipe, équipier, conducteur, contrôleur, binôme de sécurité).", "L'animateur lit une action : celui qui la fait lève la main et l'explique.", "Erreur = on échange les rôles."], "phrase": "Un binôme, un chef, un équipier, une mission.", "securite": ""}, {"titre": "Lance canon amarrée", "duree": "15 min", "prep": "Zone dégagée, engin alimenté, débit réduit en formation.", "deroule": ["Ordre : « 1er binôme, établissement d'une lance canon, En reconnaissance ! » puis « … Établissez ! ».", "Le chef d'équipe pose son Ø70 et la lance, l'équipier ses deux Ø70.", "Amarrage : tuyau droit sur 5 m, boucle devant la lance, sangle en tête d'alouette autour du tuyau, accrochée à la lance.", "L'équipier ouvre l'eau ; le chef règle le débit et le jet."], "phrase": "On amarre toujours la lance avant la mise en eau.", "securite": "Personne dans l'axe du jet ni devant la lance ; débit réduit."}, {"titre": "Rideau d'eau ou mousse", "duree": "15 min", "prep": "Lance rideau Ø40 et 3 Ø45, ou LDV mousse + injecteur + bidons d'exercice.", "deroule": ["Atelier A : le binôme établit la lance rideau et oriente le mur d'eau pour « protéger » une cible.", "Atelier B : le 1er binôme pose l'injecteur et le tuyau en O ; le 2e binôme pose les bidons ; « Plongez ! ».", "Les binômes tournent ; débrief : qui a fait quoi ?"], "phrase": "Chacun connaît son rôle : c'est ça, un binôme.", "securite": "Lance tenue à deux mains ; pas de rejet d'émulseur dans le milieu naturel."}], "questions": [{"q": "Qui compose un binôme ?", "r": "Un chef d'équipe et un équipier."}, {"q": "Qui est responsable de la sécurité du binôme ?", "r": "Le chef d'équipe."}, {"q": "Qui porte la caméra thermique ?", "r": "L'équipier."}, {"q": "Que fait habituellement le 2e binôme ?", "r": "L'alimentation ou la prise d'eau, et il aide le 1er binôme (bidons de mousse…)."}, {"q": "À quoi sert le binôme de sécurité ?", "r": "À aller aider un binôme engagé en difficulté."}, {"q": "Que fait-on avant d'ouvrir l'eau d'une lance canon ?", "r": "On l'amarre avec la sangle, tuyau droit sur 5 m."}, {"q": "À quoi sert la lance rideau ?", "r": "À faire un mur d'eau (26 m × 7 m) contre la chaleur ou les gaz."}, {"q": "Que veut dire « Plongez ! » ?", "r": "Mettre la canne de l'injecteur dans le bidon d'émulseur."}, {"q": "Où se place le porte-lance à mousse ?", "r": "À l'intérieur de la boucle du tuyau ; l'équipier vient le doubler."}], "quiz": [{"q": "Dans le binôme, la lance est portée par…", "bonne": "Le chef d'équipe", "fausses": ["L'équipier", "Le conducteur", "Le contrôleur"], "expl": ""}, {"q": "Dans la fumée, le binôme…", "bonne": "Ne se sépare jamais", "fausses": ["Se sépare pour aller plus vite", "Laisse l'équipier seul", "Change de chef"], "expl": "Contact par la main, la vue ou la voix."}, {"q": "La lance canon peut débiter jusqu'à…", "bonne": "2 000 l/min", "fausses": ["250 l/min", "500 l/min", "10 000 l/min"], "expl": "Établissement de 100 m au plus."}, {"q": "Avant d'ouvrir l'eau d'une lance canon, on…", "bonne": "L'amarre avec la sangle", "fausses": ["La tient à bout de bras", "La pose sans rien", "La dirige vers le ciel seulement"], "expl": "Elle recule fort."}, {"q": "La lance rideau sert à…", "bonne": "Protéger contre la chaleur ou les gaz", "fausses": ["Remplir la citerne", "Aspirer l'eau", "Éteindre un feu de friteuse"], "expl": "Mur d'eau de 26 m × 7 m."}, {"q": "L'injecteur de mousse est réglé à…", "bonne": "1 %", "fausses": ["10 %", "50 %", "100 %"], "expl": "À 40 m au plus de la lance."}, {"q": "À l'ordre « Plongez ! », le 2e binôme…", "bonne": "Met la canne dans le bidon d'émulseur", "fausses": ["Saute dans la rivière", "Plonge la crépine", "Plonge sous la fumée"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les établissements » (JSP3) et « L'engagement sous ARI » (partie binôme) (charte SDIS 34) · RDMI SDIS 34 v6 (avril 2026) ch.6.10-6.11, ch.8.17, fiches ETB 5.1 à 5.3 ; RDEB SDIS 34 v2 §2.9, 2.13, 3.3"}, "JSP4|Techniques d'intervention": {"cycle": "JSP4", "bloc": "Eteindre un incendie", "item": "Techniques d'intervention", "objectif": "En binôme, régler une LDV 40 (débit, jet, ouverture progressive), choisir le bon jet pour 4 situations annoncées et progresser derrière un diffusé de protection — 15 min, aucune erreur de sécurité admise.", "pointsCles": ["LDT : petits feux, 40 m maximum, jusqu'au 1er étage ; elle ne protège pas en volume ni contre un phénomène thermique", "LDV 40 : la lance d'attaque, débit de référence 500 l/min, 1 à 3 tuyaux de 45, jusqu'au 4e étage par l'escalier ; au-delà, ligne d'attaque obligatoire", "LDV 65 : gros recul, à tenir à deux ou trois ; lance canon : jusqu'à 2 000 l/min, au sol et attachée ; lance rideau : mur d'eau de 26 m × 7 m ; lance à mousse : petites flaques d'hydrocarbure", "États d'une lance : à disposition, en cours d'établissement, à sec, en attente (en eau, fermée, prête), en manœuvre", "Eau dopée (0,1 à 0,4 %), lance moussante (0,5 à 1 %), lance à mousse (1 % + embout) : le conducteur choisit sur ordre du chef", "Trois réglages : débit (bague), jet (tête de lance), ouverture (poignée) ; ouvrir et fermer doucement pour éviter le coup de bélier", "Jet droit : loin et pénétrant ; diffusé d'attaque : refroidir les fumées, éteindre ; diffusé de protection : écran contre la chaleur", "Tenir : bien ancré (debout, à genoux, couché), tuyau sous le bras, réserve derrière soi ; l'équipier double le porte-lance", "Sécurité (RDMI § 7.7) : pas dans l'axe d'une ouverture en feu, attention aux aplombs, jamais en zone dangereuse sans eau, balisage et tuyaux protégés sur la route", "Techniques : refroidir les fumées, attaque directe à la base des flammes, crayonnage des parois, protection, attaque indirecte, mousse ; économiser l'eau (≈ 2 000 L à 500 l/min = 4 min) ; « Raccordez – Ouvrez ! »"], "materiel": "FPTGP, LDV 40 avec 1-2 tuyaux de 45, LDT, plots, bidons vides ou cible basculante à 10-15 m, cartes situations, chronomètre, EPI complets (casque, gants).", "activites": [{"titre": "Le tir sur cible", "duree": "10 min", "prep": "Établissement LDV 40 en eau à débit réduit, plots ou bidons vides à 10-15 m.", "deroule": ["Chaque porte-lance règle le débit et le jet droit.", "Il ouvre doucement et fait tomber la cible.", "Il ferme doucement : on explique le coup de bélier."], "phrase": "On ouvre doucement, on ferme doucement.", "securite": "Casque, gants, jamais de jet vers une personne, débit réduit."}, {"titre": "Le bon jet", "duree": "10 min", "prep": "Cartes situations : feu en hauteur, chaleur forte, fumées au plafond, protéger un camarade, braises sur un toit.", "deroule": ["L'animateur annonce une situation.", "Le binôme règle le bon jet (droit, diffusé d'attaque, diffusé de protection) et justifie.", "Bonus : quelle lance prendre (LDT, LDV 40, LDV 65) ?"], "phrase": "", "securite": ""}, {"titre": "Le relais", "duree": "10 min", "prep": "Deux équipes, deux établissements préparés « à disposition ».", "deroule": ["Au signal, chaque équipe établit, annonce « Raccordez – Ouvrez ! », ouvre et éteint la cible.", "Le chrono ne compte que si les ordres et la sécurité sont respectés.", "Débrief : quels états de la lance a-t-on vus ?"], "phrase": "L'eau arrive quand on la demande.", "securite": "Pas de course dans les tuyaux, zone dégagée."}, {"titre": "Le mur d'eau", "duree": "10 min", "prep": "LDV 40 en eau à faible débit, cible à 15 m.", "deroule": ["Le binôme progresse lentement derrière un diffusé de protection.", "L'équipier double le porte-lance et gère la réserve de tuyau.", "Ils se parlent sans arrêt : avancer, stop, plus de tuyau."], "phrase": "La lance protège : on ne la lâche jamais.", "securite": "EPI complets, débit réduit, jamais de jet vers un camarade."}], "questions": [{"q": "Quelle lance prend-on dès que le feu est dans une pièce ?", "r": "La LDV 40 (la LDT ne protège pas assez)."}, {"q": "Une lance « en attente », c'est quoi ?", "r": "Établie, en eau, fermée, prête."}, {"q": "À quoi sert le jet diffusé d'attaque ?", "r": "Refroidir les fumées et éteindre."}, {"q": "Pourquoi ouvrir doucement la lance ?", "r": "Pour éviter le coup de bélier."}, {"q": "Combien de temps dure la citerne d'un FPTL à 500 l/min ?", "r": "Environ 4 minutes (≈ 2 000 L)."}, {"q": "Quel jet pour faire écran à la chaleur ?", "r": "Le diffusé de protection."}, {"q": "Quand la ligne d'attaque est-elle obligatoire ?", "r": "Au-delà du 4e étage par l'escalier."}, {"q": "Quel est l'ordre pour ouvrir l'eau à la prise d'eau ?", "r": "« Raccordez – Ouvrez ! »."}], "quiz": [{"q": "Dès que le feu est dans une pièce, on prend…", "bonne": "Une LDV 40", "fausses": ["La LDT", "Un seau", "La lance canon"], "expl": "La LDT ne protège pas contre un phénomène thermique."}, {"q": "Débit de référence d'une LDV 40 :", "bonne": "500 l/min", "fausses": ["50 l/min", "2 000 l/min", "5 000 l/min"], "expl": ""}, {"q": "Lance établie, en eau, fermée, prête :", "bonne": "En attente", "fausses": ["À sec", "À disposition", "En manœuvre"], "expl": ""}, {"q": "Ouvrir la lance d'un coup peut provoquer…", "bonne": "Un coup de bélier", "fausses": ["Un embrasement", "Une panne de pompe", "Rien du tout"], "expl": ""}, {"q": "Pour atteindre un feu en hauteur et loin :", "bonne": "Jet droit", "fausses": ["Diffusé de protection", "Lance fermée", "Mousse"], "expl": ""}, {"q": "Pour se protéger de la chaleur :", "bonne": "Diffusé de protection", "fausses": ["Jet droit", "Crayonnage", "Attaque indirecte"], "expl": ""}, {"q": "Une LDV 65 se tient…", "bonne": "À deux ou trois", "fausses": ["Seul d'une main", "Posée sans personne", "Par le conducteur depuis la cabine"], "expl": "Gros recul."}, {"q": "Quelle lance pour une petite flaque d'essence en feu ?", "bonne": "La lance à mousse", "fausses": ["La lance rideau", "Le jet droit à l'eau seule", "La LDT en jet droit"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les lances – choisir, régler, éteindre » (charte SDIS 34) · RNF INC C2 · RDMI v6 (avril 2026) § 3, 5.4, 6.14, 7.7-7.9, 9.14, ETB 1.1, 3.x, 3.10, 5.1-5.3 — jets et techniques d'extinction : doctrine nationale (GTO), à valider avec le formateur"}, "JSP4|Etablissements et établissements spécifiques": {"cycle": "JSP4", "bloc": "Eteindre un incendie", "item": "Etablissements et établissements spécifiques", "objectif": "En binôme, sur ordre du chef d'agrès, choisir l'établissement adapté à l'étage annoncé et réaliser à faible hauteur un hissage à la commande avec amarrage contrôlé à la mise en eau — 20 min, aucune erreur de sécurité admise.", "pointsCles": ["Ordres : préparatoire (« 1er binôme, établissement d'une LDV 40 avec la commande, en reconnaissance ! »), d'exécution (« point d'attaque ici…, Établissez ! »), ouverture de l'eau (« Raccordez – Ouvrez ! »)", "Par l'escalier (LDV 40 en rampant) : jusqu'au 4e étage ; au-delà, ligne d'attaque obligatoire", "Échelle à coulisse (ETB 3.3) : 2e étage avec la 2 plans, 4e avec la 3 plans ; le tuyau est amarré sur une partie solide, jamais sur l'échelle qui reste libre pour sortir", "À la commande (ETB 3.4) : jusqu'au 6e étage ; « Pour envoyer la commande ! », puis « Hissez ! » ; deux tuyaux à partir du 5e", "De haut en bas (ETB 3.5) : jusqu'au 8e étage (poids en eau), si un accès relie le point d'attaque à la prise d'eau ; guider avec la commande s'il y a du vent", "Colonne sèche (ETB 3.6) : toujours en priorité si elle existe ; le conducteur l'alimente, le binôme se branche à l'étage du dessous ; peu de débit = vérifier les vannes des autres étages", "Ligne d'attaque dans l'escalier (ETB 3.7) : le 2e binôme monte la division d'attaque et 4 tuyaux de 70 ; au-delà du 8e : 3 binômes ; le chef d'agrès emporte une lance de plus", "Amarrage (RDMI § 8.16) : deux tours morts autour du tuyau à sec et d'une partie solide, serrer, deux demi-nœuds, vérifier qu'il ne descend pas à la mise en eau ; un tuyau de 45 plein pèse plus de 30 kg", "Déblai : chercher le feu caché (caméra thermique, outils, lance à côté), ARI ou masque car fumée toxique ; limité si enquête possible", "Surveillance : lance en attente, rondes régulières (combles, faux plafonds, gaines, déchets) ; le COS lève la surveillance"], "materiel": "FPTGP, tuyaux de 45 (et de 70 pour la division), LDV 40, division d'attaque, commande, échelle à coulisse 2 plans, balcon ou passerelle sécurisée de la caserne (≈ 3 m), caméra thermique, chaufferettes ou bouillottes cachées dans des cartons, EPI complets.", "activites": [{"titre": "Combien d'étages ?", "duree": "10 min", "prep": "Cartes « étage » (1 à 10) et cartes « établissement ».", "deroule": ["Tu annonces un étage et une contrainte (escalier encombré, colonne sèche présente…).", "Les binômes choisissent l'établissement : escalier, échelle à coulisse, commande, haut en bas, colonne sèche, ligne d'attaque.", "Ils justifient avec la limite de hauteur."], "phrase": "Colonne sèche présente ? On l'utilise en priorité.", "securite": ""}, {"titre": "Le balcon : hisser à la commande", "duree": "20 min", "prep": "Balcon ou passerelle sécurisée (≈ 3 m), commande, tuyau de 45 en couronne, LDV 40.", "deroule": ["Ordre préparatoire puis « Établissez ! ».", "En haut : « Pour envoyer la commande ! », le JSP lance la commande.", "En bas : le 2e binôme attache le tuyau en couronne et crie « Hissez ! », guide la montée.", "En haut : amarrage (2 tours morts, 2 demi-nœuds), « Raccordez – Ouvrez ! », on vérifie que le tuyau ne descend pas.", "On inverse les rôles."], "phrase": "Un tuyau en eau pèse lourd : on amarre avant d'ouvrir.", "securite": "Hauteur ≈ 3 m maximum, garde-corps, personne sous la charge pendant le hissage, casque et gants."}, {"titre": "Les points chauds du déblai", "duree": "10 min", "prep": "Chaufferettes ou bouillottes cachées dans un tas de cartons, caméra thermique.", "deroule": ["Chaque binôme cherche les « points chauds » à la caméra thermique.", "Il les sort du tas et les « éteint » dehors.", "Débrief : où le feu peut-il couver ? Qui lève la surveillance ?"], "phrase": "Le feu caché peut repartir des heures après.", "securite": ""}], "questions": [{"q": "Jusqu'à quel étage la LDV 40 par l'escalier ?", "r": "Le 4e étage ; au-delà, ligne d'attaque."}, {"q": "Échelle à coulisse 3 plans : jusqu'où ?", "r": "Le 4e étage."}, {"q": "Que crie-t-on pour monter le tuyau ?", "r": "« Hissez ! »"}, {"q": "Pourquoi ne pas amarrer le tuyau à l'échelle ?", "r": "Elle doit rester libre pour sortir (chemin de repli)."}, {"q": "Que fait-on en priorité si le bâtiment a une colonne sèche ?", "r": "On l'utilise."}, {"q": "À quoi sert le déblai ?", "r": "Trouver et éteindre le feu caché."}, {"q": "Comment amarrer un tuyau ?", "r": "Deux tours morts autour du tuyau à sec et d'une partie solide, serrer, deux demi-nœuds."}, {"q": "Qui décide de la fin de la surveillance ?", "r": "Le commandant des opérations (COS)."}], "quiz": [{"q": "LDV 40 par l'escalier, limite :", "bonne": "4e étage", "fausses": ["2e étage", "8e étage", "Aucune limite"], "expl": "Au-delà : ligne d'attaque."}, {"q": "Établissement à la commande, limite :", "bonne": "6e étage", "fausses": ["1er étage", "4e étage", "10e étage"], "expl": "Longueur de la commande."}, {"q": "Établissement de haut en bas, limite :", "bonne": "8e étage", "fausses": ["2e étage", "4e étage", "12e étage"], "expl": "Poids du tuyau en eau."}, {"q": "Bâtiment avec colonne sèche :", "bonne": "On l'utilise en priorité", "fausses": ["On l'ignore", "On établit par l'échelle", "On attend la grande échelle"], "expl": ""}, {"q": "Pour monter le tuyau à la commande, on crie…", "bonne": "« Hissez ! »", "fausses": ["« Envoyez ! »", "« Contact ! »", "« Sec ! »"], "expl": ""}, {"q": "Le tuyau d'un établissement par l'échelle à coulisse est amarré…", "bonne": "Sur une partie solide, pas sur l'échelle", "fausses": ["Sur l'échelle", "Nulle part", "Au casque du porte-lance"], "expl": ""}, {"q": "Pendant le déblai, on porte…", "bonne": "ARI ou masque", "fausses": ["Rien de spécial, c'est éteint", "Uniquement des lunettes", "La tenue de sport"], "expl": "Le déblai fait de la fumée toxique."}, {"q": "Pendant la surveillance, la lance est…", "bonne": "En attente", "fausses": ["Rangée dans l'engin", "À disposition", "Démontée"], "expl": "Établie, en eau, prête."}], "statut": "brouillon", "source": "Cours 2026 « Les établissements spécifiques – monter l'eau dans les étages » (charte SDIS 34) · RNF INC C3 · RDMI v6 (avril 2026) § 1.1, 6.9-6.11, 7.7-7.8, 8.16, 9.10-9.17 (ETB 3.3 à 3.9) · RDEB v2 § 4.2"}, "JSP4|Établissement sur un moyen élévateur aérien": {"cycle": "JSP4", "bloc": "Eteindre un incendie", "item": "Établissement sur un moyen élévateur aérien", "objectif": "Citer les MEA (18, 24, 30 m) et leurs limites, puis, au sol et MEA non déployé, décrire dans l'ordre les rôles du chef d'agrès, de l'équipier et du conducteur pour l'ETB 3.11 (LDV 40 sur structure extensible) et réaliser l'amarrage d'un tuyau sur un échelon — 15 min, 1 erreur admise.", "pointsCles": ["Les MEA (grande échelle) de 18, 24 et 30 m permettent d'atteindre environ le 6e, le 8e et le 10e étage", "Placement (RDMI § 6.18) : contact avec le COS, façade où il y a des sauvetages, de préférence aux angles du bâtiment, laisser la place à un 2e MEA ; les autres engins ne gênent pas son accès", "Le sol doit être solide : interdit sur une bordure de trottoir ou une plaque d'égout ; attention aux balcons, câbles électriques, vent, foudre, brouillard (RDSMES § 3.6)", "Prise d'eau du MEA : vanne pied d'échelle de 65, tuyau de 70/1 m, division d'alimentation ; un établissement de manœuvre dédié au MEA seul", "ETB 3.11 : ordre « Conducteur et Équipier, établissement d'une LDV 40 sur structure extensible, en reconnaissance ! » ; chacun porte harnais et longe de maintien", "Le conducteur stabilise le MEA, met en place la prise d'eau, place la structure au point d'attaque et reste en tourelle", "Le chef d'agrès monte la lance et l'amarre à hauteur de poitrine ; l'équipier amarre le tuyau 10 échelons plus bas, puis une 2e fois entre ce point et le sol", "Amarrage sur MEA (RDMI § 8.21) : deux tours morts autour du tuyau à sec et d'un seul échelon, deux demi-nœuds, contrôle à la mise en eau", "L'équipier ouvre et ferme l'eau depuis la vanne pied d'échelle ; la lance reste si possible ouverte ; angle de dressage 60 ou 70° maximum selon le modèle", "Aucun mouvement du MEA avec du personnel ou du matériel sur la structure (sauf urgence par l'échelier) ; pour changer de point d'attaque, on retire d'abord le personnel et l'établissement"], "materiel": "Photos de MEA (18, 24, 30 m) sur la tablette, tuyau de 45, LDV 40, ligatures ou commande, harnais et longe de maintien, une échelle d'exercice posée au sol ou un MEA non déployé à l'arrêt, cartes « rôles » (chef d'agrès, équipier, conducteur).", "activites": [{"titre": "Bien placer le MEA", "duree": "10 min", "prep": "Photo ou plan d'une rue avec trottoirs, plaques d'égout, balcons, câbles, deux façades.", "deroule": ["Les binômes placent le MEA et justifient.", "Ils citent les sols interdits et les obstacles.", "Bonus : où mettre le FPTGP pour ne pas gêner ?"], "phrase": "Aux angles, on atteint deux façades.", "securite": ""}, {"titre": "Qui fait quoi ? (ETB 3.11)", "duree": "15 min", "prep": "Cartes actions mélangées : stabiliser, placer la structure, raccorder la lance, amarrer la lance à hauteur de poitrine, amarrer le tuyau 10 échelons plus bas, « Raccordez – Ouvrez ! », rester à la vanne pied d'échelle…", "deroule": ["Chaque binôme classe les cartes par rôle (conducteur, chef d'agrès, équipier).", "Puis il les remet dans l'ordre.", "Correction avec la fiche ETB 3.11 du RDMI."], "phrase": "", "securite": ""}, {"titre": "L'amarrage sur échelon", "duree": "15 min", "prep": "Échelle d'exercice posée au sol, tuyau de 45 à sec, ligature ou commande.", "deroule": ["Démonstration : deux tours morts autour du tuyau et d'un seul échelon, serrer, deux demi-nœuds.", "Chaque JSP réalise l'amarrage, le binôme contrôle.", "On simule la mise en eau : le tuyau ne doit pas glisser."], "phrase": "On amarre à sec, on contrôle en eau.", "securite": "Échelle au sol ou MEA non déployé : aucune montée en hauteur pour les JSP."}], "questions": [{"q": "Quels MEA existent et jusqu'à quel étage ?", "r": "18 m (≈ 6e), 24 m (≈ 8e), 30 m (≈ 10e)."}, {"q": "Où place-t-on de préférence le MEA ?", "r": "Sur la façade des sauvetages, aux angles du bâtiment."}, {"q": "Cite 2 sols interdits pour stabiliser.", "r": "Bordure de trottoir, plaque d'égout (dalle de moins de 15 t)."}, {"q": "Où le chef d'agrès amarre-t-il la lance ?", "r": "À hauteur de poitrine, pour absorber le recul."}, {"q": "Où l'équipier fait-il le premier amarrage ?", "r": "10 échelons sous celui du chef d'agrès."}, {"q": "Qui ouvre et ferme l'eau ?", "r": "L'équipier, à la vanne pied d'échelle."}, {"q": "Peut-on bouger le MEA avec quelqu'un sur la structure ?", "r": "Non, sauf manœuvre d'urgence par l'échelier en tourelle."}, {"q": "Quels obstacles vérifier avant de placer le MEA ?", "r": "Balcons, câbles électriques, vent, foudre, brouillard."}], "quiz": [{"q": "Un MEA de 24 m atteint environ…", "bonne": "Le 8e étage", "fausses": ["Le 2e étage", "Le 4e étage", "Le 15e étage"], "expl": ""}, {"q": "On peut stabiliser un MEA sur…", "bonne": "Un sol de chaussée solide", "fausses": ["Une plaque d'égout", "Une bordure de trottoir", "Une dalle fragile"], "expl": ""}, {"q": "Sur la structure, la lance est amarrée par…", "bonne": "Le chef d'agrès, à hauteur de poitrine", "fausses": ["Le conducteur, au sol", "Personne", "L'équipier, en haut du panier"], "expl": ""}, {"q": "L'eau sur MEA est ouverte et fermée…", "bonne": "À la vanne pied d'échelle par l'équipier", "fausses": ["Par le porte-lance seulement", "Par un passant", "Depuis la cabine de l'engin-pompe uniquement"], "expl": ""}, {"q": "Amarrage sur MEA : autour du tuyau et…", "bonne": "D'un seul échelon", "fausses": ["De trois échelons", "De la main courante", "Du panier"], "expl": "Deux tours morts, deux demi-nœuds."}, {"q": "Pendant que quelqu'un est sur la structure, le MEA…", "bonne": "Ne bouge pas", "fausses": ["Peut pivoter librement", "Se replie", "Avance doucement"], "expl": "Sauf urgence par l'échelier."}, {"q": "Le conducteur du MEA, pendant l'attaque :", "bonne": "Reste en tourelle", "fausses": ["Monte en haut", "Part chercher de l'eau", "Range le matériel"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les établissements spécifiques » (charte SDIS 34) · RDMI v6 (avril 2026) § 6.18, 8.21, 9.19-9.20 (ETB 3.11) · RDSMES v2 (avril 2026) § 3.5-3.6 · RDLSPCC v1 (longe de maintien) — le cours 2026 ne détaille pas l'ETB sur MEA : contenu repris du RDMI, à valider avec le formateur"}, "JSP1|Protection": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Protection", "objectif": "Avant d'approcher une victime, repérer et nommer à voix haute tous les dangers d'une scène, puis dire comment les supprimer ou s'en protéger, sans jamais s'exposer.", "pointsCles": ["Pas de sauveteur blessé : je ne deviens jamais une victime de plus", "Je regarde d'abord : y a-t-il un danger ? (circulation, feu, électricité, gaz…)", "Je supprime le danger si je peux le faire sans risque (couper le courant, couper le contact, baliser…)", "Je protège tout le monde : moi, la victime et les autres personnes présentes", "Sinon je m'écarte du danger et j'écarte les témoins", "Dégagement d'urgence : seulement si le danger est réel, vital, immédiat et impossible à supprimer", "Dégagement possible seulement si la victime est visible, facile à atteindre et le chemin dégagé : on l'emmène assez loin par le chemin le plus sûr", "Après la protection : j'alerte (15, 18, 112) et je fais les gestes de secours"], "materiel": "Gilets haute visibilité, triangle de signalisation, plots, mannequin, câble électrique factice, cartes « danger », diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Ton grand-père s'effondre", "duree": "10 min", "prep": "Diapo d'accroche du cours projetée ou lue.", "deroule": ["Chaque JSP dit sa première action en une phrase.", "L'animateur classe les réponses : se protéger, alerter, agir.", "On retient l'ordre : je regarde, je protège, j'alerte, j'agis."], "phrase": "Je m'arrête, je regarde, je protège.", "securite": ""}, {"titre": "Stop, je regarde !", "duree": "15 min", "prep": "Scène : mannequin au sol + 3 dangers factices (câble électrique, flaque « d'essence », voiture moteur allumé figurée).", "deroule": ["Un JSP arrive sur la scène et s'arrête à distance.", "Il nomme les dangers avant de s'approcher.", "Il dit comment il les supprime ou comment il s'en protège.", "Les autres complètent ce qui a été oublié."], "phrase": "Pas de sauveteur blessé.", "securite": "Dangers uniquement factices. Le mannequin sert de victime."}, {"titre": "Le balisage", "duree": "15 min", "prep": "Triangles, gilets, plots, portion de cour figurant une route.", "deroule": ["En binôme : gilet enfilé avant de sortir de la « voiture ».", "Baliser un « accident » de chaque côté avec triangle et plots.", "L'animateur vérifie gilets et balisage.", "Débrief : pourquoi baliser loin ?"], "phrase": "", "securite": "Jamais sur une vraie route : uniquement dans l'enceinte du centre, portail fermé."}], "questions": [{"q": "Que fais-tu avant de t'approcher d'une victime ?", "r": "Je regarde s'il y a un danger."}, {"q": "Cite 3 dangers possibles.", "r": "Circulation, feu, électricité, gaz…"}, {"q": "Si tu peux supprimer le danger sans risque ?", "r": "Je le supprime (couper le courant, le contact, baliser…)."}, {"q": "Qui dois-tu protéger ?", "r": "Moi, la victime et les autres personnes présentes."}, {"q": "Quand fait-on un dégagement d'urgence ?", "r": "Seulement si le danger est réel, immédiat et impossible à supprimer."}, {"q": "Pourquoi dit-on « pas de sauveteur blessé » ?", "r": "Parce qu'un sauveteur blessé devient une victime de plus et ne peut plus aider."}], "quiz": [{"q": "Premier réflexe devant un accident :", "bonne": "Regarder s'il y a un danger", "fausses": ["Courir vers la victime", "Filmer la scène", "Partir chercher un adulte sans rien regarder"], "expl": ""}, {"q": "Je peux couper le courant sans risque :", "bonne": "Je le coupe", "fausses": ["J'attends les pompiers", "Je laisse comme ça", "Je touche la victime d'abord"], "expl": ""}, {"q": "Le dégagement d'urgence se fait si le danger est…", "bonne": "Réel, immédiat et impossible à supprimer", "fausses": ["Faible", "Seulement possible", "Loin de la victime"], "expl": ""}, {"q": "Sur un accident de la route, je porte…", "bonne": "Un gilet haute visibilité", "fausses": ["Un casque de vélo", "Rien de spécial", "Un masque"], "expl": ""}, {"q": "Je protège…", "bonne": "Moi, la victime et les témoins", "fausses": ["Seulement la victime", "Seulement moi", "Seulement les témoins"], "expl": ""}, {"q": "« Pas de sauveteur blessé » veut dire :", "bonne": "Je ne prends pas de risque pour moi", "fausses": ["Je fonce sans réfléchir", "Je ne fais rien", "J'attends toujours les secours"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Alerte et protection des populations": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Alerte et protection des populations", "objectif": "Passer en jeu de rôle un message d'alerte complet au 18 ou au 112 (numéro, ce qui se passe, nombre de victimes, adresse précise, réponse aux questions) et dire quoi faire en entendant le signal national d'alerte.", "pointsCles": ["18 : sapeurs-pompiers · 15 : SAMU · 112 : numéro d'urgence européen · 114 : par SMS (personnes sourdes ou malentendantes)", "Le message : le numéro d'où j'appelle", "Ce qui se passe et combien de victimes", "L'adresse la plus précise possible", "Je réponds aux questions et je suis les consignes ; je ne raccroche que quand on me le dit", "Signal national d'alerte (sirène) : un son qui monte et descend, 3 fois 1 min 41 s séparées de 5 secondes → je me mets à l'abri et j'écoute la radio", "Fin d'alerte : un son continu de 30 secondes · essai le 1er mercredi du mois à midi (un seul cycle)", "FR-Alert : un message d'alerte s'affiche sur tous les téléphones de la zone"], "materiel": "Téléphones factices, fiches scénario, enregistrement officiel du signal national d'alerte (ministère de l'Intérieur), diaporama « Premiers secours citoyens » (lien cours « Les comportements qui sauvent »).", "activites": [{"titre": "Le bon numéro", "duree": "10 min", "prep": "Cartes situations (incendie, malaise, accident, personne sourde…) et cartes numéros 15/18/112/114.", "deroule": ["L'animateur lit une situation.", "Les JSP lèvent la carte du bon numéro.", "On justifie : pourquoi ce numéro ?"], "phrase": "", "securite": ""}, {"titre": "L'appel au 18", "duree": "20 min", "prep": "Deux téléphones factices, fiches scénario.", "deroule": ["En binôme : l'un appelle, l'autre joue l'opérateur.", "Le message : numéro, ce qui se passe, nombre de victimes, adresse précise.", "L'opérateur pose des questions et dit quand raccrocher.", "On inverse les rôles ; les autres notent ce qui manque."], "phrase": "Je ne raccroche que quand on me le dit.", "securite": "Jamais de vrai appel : téléphones factices ou éteints."}, {"titre": "La sirène", "duree": "10 min", "prep": "Enregistrement officiel du signal national d'alerte.", "deroule": ["On écoute le signal (son qui monte et descend).", "Que fait-on ? Se mettre à l'abri, écouter la radio.", "On écoute la fin d'alerte (son continu de 30 s).", "Y a-t-il une sirène à Cruzy ou à Quarante ?"], "phrase": "", "securite": ""}], "questions": [{"q": "Quel est le numéro des sapeurs-pompiers ?", "r": "Le 18."}, {"q": "Le numéro d'urgence valable dans toute l'Europe ?", "r": "Le 112."}, {"q": "Le 114, c'est pour qui ?", "r": "Pour les personnes sourdes ou malentendantes, par SMS."}, {"q": "Que dis-tu dans ton message ?", "r": "Mon numéro, ce qui se passe, le nombre de victimes, l'adresse précise ; je réponds aux questions."}, {"q": "Quand raccroches-tu ?", "r": "Quand l'opérateur me le dit."}, {"q": "Tu entends la sirène qui monte et descend : que fais-tu ?", "r": "Je me mets à l'abri et j'écoute la radio."}, {"q": "Comment sait-on que l'alerte est finie ?", "r": "Un son continu de 30 secondes."}, {"q": "C'est quoi FR-Alert ?", "r": "Un message d'alerte qui s'affiche sur les téléphones de la zone."}], "quiz": [{"q": "Le numéro d'urgence européen :", "bonne": "112", "fausses": ["17", "115", "119"], "expl": ""}, {"q": "Le 15, c'est :", "bonne": "Le SAMU", "fausses": ["Les pompiers", "La police", "Les urgences par SMS"], "expl": ""}, {"q": "Le 114 permet d'alerter :", "bonne": "Par SMS, pour les personnes sourdes ou malentendantes", "fausses": ["La police municipale", "La météo", "Le centre antipoison uniquement"], "expl": ""}, {"q": "Je raccroche…", "bonne": "Quand l'opérateur me le dit", "fausses": ["Dès que j'ai donné l'adresse", "Tout de suite", "Après 1 minute"], "expl": ""}, {"q": "Sirène qui monte et descend :", "bonne": "Je me mets à l'abri et j'écoute la radio", "fausses": ["Je sors voir ce qui se passe", "Je vais chercher mes frères à l'école", "J'appelle le 18 pour demander"], "expl": ""}, {"q": "La fin d'alerte, c'est :", "bonne": "Un son continu de 30 secondes", "fausses": ["Trois sons courts", "Un message à la télé seulement", "Le silence"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026) · cours 2026 « Les comportements qui sauvent » (signal national d'alerte)"}, "JSP1|Malaise": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Malaise", "objectif": "Face à une victime simulée qui ne se sent pas bien, l'installer au repos, lui poser les questions du cours et passer un appel simulé au 15, en moins de 5 minutes.", "pointsCles": ["Malaise : la victime se sent mal (douleur, sueurs, pâleur, gêne pour respirer ou parler…)", "Je l'installe au repos : allongée si possible", "Assise si elle respire mal, sinon dans la position où elle se sent le mieux", "Je desserre ses vêtements et je la rassure", "Je questionne : son âge, depuis quand ça dure, ses maladies, ses médicaments, hospitalisation ou chute récente, est-ce déjà arrivé ?", "J'appelle le 15 (SAMU) pour avoir l'avis d'un médecin et je suis ses consignes", "Sucre ou médicament habituel : seulement si la victime le demande ou si le médecin le dit"], "materiel": "Chaises, tapis, couverture, téléphone factice, fiches « victime » (signes et réponses aux questions), diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Les signes", "duree": "10 min", "prep": "Cartes avec des signes (pâleur, sueurs, douleur poitrine, fatigue, mal de tête…).", "deroule": ["Chaque JSP tire une carte et la mime.", "Les autres devinent le signe.", "On retient : on ne cherche pas la maladie, on agit."], "phrase": "", "securite": ""}, {"titre": "Installe et rassure", "duree": "10 min", "prep": "Tapis, chaises, couverture.", "deroule": ["Un JSP (volontaire) joue la victime qui ne se sent pas bien.", "Le sauveteur l'installe allongée, ou assise si elle respire mal.", "Il desserre (fictivement) le col, la couvre, lui parle calmement."], "phrase": "", "securite": "Victime volontaire, aucun geste douloureux, sur tapis."}, {"titre": "Le médecin au téléphone", "duree": "20 min", "prep": "Fiches victime avec réponses (âge, durée, maladies, médicaments, déjà arrivé ?), téléphone factice.", "deroule": ["Le sauveteur pose les questions à la victime.", "Il appelle le 15 (animateur = médecin régulateur).", "Il transmet les réponses et applique les consignes (ex. donner du sucre si le médecin le dit)."], "phrase": "Je questionne, j'appelle le 15, j'applique.", "securite": "Jamais de vrai appel. Aucun aliment ni médicament réellement donné."}], "questions": [{"q": "Comment installes-tu une personne qui fait un malaise ?", "r": "Allongée si possible, assise si elle respire mal, ou dans la position où elle se sent le mieux."}, {"q": "Que fais-tu de ses vêtements ?", "r": "Je les desserre."}, {"q": "Quelles questions lui poses-tu ?", "r": "Son âge, depuis quand, ses maladies, ses médicaments, si c'est déjà arrivé."}, {"q": "Quel numéro appelles-tu ?", "r": "Le 15, pour l'avis d'un médecin."}, {"q": "Peux-tu lui donner du sucre ?", "r": "Seulement si elle le demande ou si le médecin le dit."}, {"q": "Pourquoi la rassurer ?", "r": "Pour la calmer et qu'elle reste au repos."}], "quiz": [{"q": "Une personne fait un malaise et respire bien :", "bonne": "Je l'allonge", "fausses": ["Je la fais marcher", "Je lui donne à boire tout de suite", "Je la laisse debout"], "expl": ""}, {"q": "Elle respire mal :", "bonne": "Je l'installe assise", "fausses": ["Je l'allonge à plat ventre", "Je la fais courir", "Je la mets en PLS"], "expl": ""}, {"q": "Pour un malaise, j'appelle :", "bonne": "Le 15", "fausses": ["Le 17", "Le 114", "Personne"], "expl": ""}, {"q": "Le sucre, je le donne…", "bonne": "Si elle le demande ou si le médecin le dit", "fausses": ["Toujours", "Jamais", "Seulement le soir"], "expl": ""}, {"q": "Une bonne question à poser :", "bonne": "Est-ce déjà arrivé ?", "fausses": ["Quel est ton film préféré ?", "Tu as mangé quoi hier ?", "Où habite ta famille ?"], "expl": ""}, {"q": "Je desserre…", "bonne": "Ses vêtements", "fausses": ["Ses chaussures uniquement", "Rien du tout", "Sa ceinture de sécurité en roulant"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Obstruction aigue des voies aériennes": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Obstruction aigue des voies aériennes", "objectif": "Reconnaître une obstruction complète et enchaîner correctement, sur mannequin ou à blanc, 1 à 5 claques dans le dos puis 1 à 5 compressions (abdominales chez l'adulte et l'enfant, thoraciques chez le nourrisson).", "pointsCles": ["Obstruction complète : la personne ne peut plus parler, ni tousser, ni respirer (mains à la gorge)", "Obstruction partielle : elle tousse ou parle → je ne tape pas, je l'encourage à tousser, je l'installe comme elle se sent le mieux et j'alerte", "Adulte et enfant : 1 à 5 claques vigoureuses dans le dos, entre les omoplates, avec le talon de la main", "Si ça ne marche pas : 1 à 5 compressions abdominales, puis on recommence", "Nourrisson : tête vers le bas sur mon avant-bras, 1 à 5 claques dans le dos", "Puis 1 à 5 compressions sur la poitrine avec 2 doigts, au centre", "J'arrête dès qu'il tousse, pleure, respire ou rejette ce qui le bloquait", "S'il perd connaissance : c'est un arrêt cardiaque (alerte, massage, DAE)"], "materiel": "Mannequin adulte et mannequin nourrisson (ou gilet d'entraînement), tapis, diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Totale ou partielle ?", "duree": "10 min", "prep": "Cartes situation (« il tousse fort », « il ne peut plus parler », « il pleure »…).", "deroule": ["L'animateur lit ou mime une situation.", "Les JSP disent : je tape ou je ne tape pas ?", "On justifie avec les signes."], "phrase": "Il tousse : je l'encourage. Il ne tousse plus : j'agis.", "securite": ""}, {"titre": "Les gestes sur mannequin", "duree": "20 min", "prep": "Mannequin adulte ou gilet d'entraînement, mannequin nourrisson.", "deroule": ["L'animateur montre : penché en avant, 1 à 5 claques entre les omoplates.", "Puis 1 à 5 compressions abdominales (poing au creux de l'estomac, tirer vers soi et vers le haut).", "Nourrisson : tête en bas sur l'avant-bras, claques puis compressions à 2 doigts.", "Chaque JSP passe sur le mannequin."], "phrase": "", "securite": "Gestes de secours sur mannequin uniquement : jamais de compressions, de claques ou de compressions abdominales réelles sur un camarade."}, {"titre": "Et s'il tombe ?", "duree": "10 min", "prep": "Mannequin au sol.", "deroule": ["La « victime » perd connaissance.", "Le JSP dit : il ne répond plus, il ne respire plus → j'alerte, je masse.", "Lien avec la séance arrêt cardiaque."], "phrase": "", "securite": "Sur mannequin uniquement."}], "questions": [{"q": "Comment sais-tu que l'obstruction est complète ?", "r": "Il ne peut plus parler, ni tousser, ni respirer."}, {"q": "Il tousse fort : que fais-tu ?", "r": "Je ne tape pas, je l'encourage à tousser et j'alerte."}, {"q": "Premier geste chez l'adulte ?", "r": "1 à 5 claques dans le dos, entre les omoplates."}, {"q": "Et si ça ne marche pas ?", "r": "1 à 5 compressions abdominales, puis on recommence."}, {"q": "Chez le nourrisson ?", "r": "Tête vers le bas, claques dans le dos, puis compressions sur la poitrine avec 2 doigts."}, {"q": "Quand arrêtes-tu ?", "r": "Dès qu'il tousse, pleure, respire ou rejette ce qui bloquait."}, {"q": "Il perd connaissance : c'est quoi ?", "r": "Un arrêt cardiaque : j'alerte et je masse."}], "quiz": [{"q": "Il ne peut plus parler ni tousser :", "bonne": "Obstruction complète", "fausses": ["Obstruction partielle", "Simple hoquet", "Malaise sans gravité"], "expl": ""}, {"q": "Premier geste chez l'adulte :", "bonne": "1 à 5 claques dans le dos", "fausses": ["Le faire boire", "Le mettre en PLS", "Attendre que ça passe"], "expl": ""}, {"q": "Après les claques, si ça ne sort pas :", "bonne": "1 à 5 compressions abdominales", "fausses": ["Le faire courir", "Lui donner du pain", "Arrêter les gestes"], "expl": ""}, {"q": "Il tousse fort :", "bonne": "Je l'encourage à tousser", "fausses": ["Je tape dans son dos", "Je fais des compressions", "Je le fais boire"], "expl": ""}, {"q": "Chez le nourrisson, les compressions se font :", "bonne": "Sur la poitrine avec 2 doigts", "fausses": ["Sur le ventre avec le poing", "Dans le dos avec le pied", "On n'en fait jamais"], "expl": ""}, {"q": "Je m'entraîne aux claques et compressions :", "bonne": "Sur un mannequin", "fausses": ["Sur un camarade", "Sur mon petit frère", "Sur l'animateur"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Hémorragie": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Hémorragie", "objectif": "Arrêter un saignement abondant simulé en enchaînant, en moins d'une minute : compression directe main protégée, victime allongée, alerte, compression maintenue.", "pointsCles": ["Hémorragie externe : un saignement abondant qui ne s'arrête pas tout seul", "1. Je comprime : j'appuie fort sur l'endroit qui saigne, main protégée (gant, sac plastique)", "2. J'allonge la victime : elle ne doit pas tomber si elle fait un malaise", "3. J'alerte (15, 18, 112) ou je fais alerter par un témoin", "4. Je ne relâche pas : j'appuie jusqu'à l'arrivée des secours", "Un pansement compressif peut remplacer ma main seulement si la compression a déjà arrêté le saignement", "Garrot : seulement si appuyer ne suffit pas ou est impossible, sur un bras ou une jambe", "Garrot à 5-7 cm au-dessus de la plaie, jamais sur une articulation, laissé visible, jamais retiré sans avis médical"], "materiel": "Gants, sacs plastique, compresses, bandes, faux sang lavable, bras ou mannequin d'entraînement, garrot de formation, téléphone factice, diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Appuie fort !", "duree": "15 min", "prep": "Bras d'entraînement ou mannequin avec « plaie » au faux sang, gants, sac plastique.", "deroule": ["Le JSP met un gant (ou un sac plastique).", "Il appuie fort sur la plaie et allonge la victime.", "Il demande à un témoin d'alerter.", "Il ne relâche pas jusqu'au « stop » de l'animateur."], "phrase": "Je comprime, j'allonge, j'alerte, je ne relâche pas.", "securite": "Main toujours protégée ; faux sang lavable."}, {"titre": "Le message", "duree": "10 min", "prep": "Téléphone factice.", "deroule": ["Le témoin passe l'alerte : numéro, saignement abondant, adresse, victime allongée, compression en cours.", "Les autres vérifient que rien ne manque."], "phrase": "", "securite": "Jamais de vrai appel."}, {"titre": "Le garrot (démonstration)", "duree": "15 min", "prep": "Garrot de formation, mannequin ou bras d'entraînement.", "deroule": ["L'animateur explique quand on pose un garrot : compression inefficace ou impossible, sur un membre.", "Il montre la pose sur le mannequin : 5-7 cm au-dessus, pas sur une articulation, visible.", "Les JSP disent ce qu'on ne fait jamais : le retirer sans avis médical."], "phrase": "", "securite": "Garrot posé uniquement sur mannequin ou bras d'entraînement, jamais sur un camarade."}], "questions": [{"q": "Premier geste devant un saignement abondant ?", "r": "J'appuie fort sur l'endroit qui saigne, main protégée."}, {"q": "Avec quoi protèges-tu ta main ?", "r": "Un gant ou un sac plastique."}, {"q": "Pourquoi allonger la victime ?", "r": "Pour qu'elle ne tombe pas si elle fait un malaise."}, {"q": "Jusqu'à quand appuies-tu ?", "r": "Jusqu'à l'arrivée des secours."}, {"q": "Quand pose-t-on un garrot ?", "r": "Si appuyer ne suffit pas ou est impossible, sur un bras ou une jambe."}, {"q": "Où place-t-on le garrot ?", "r": "5 à 7 cm au-dessus de la plaie, jamais sur une articulation."}, {"q": "Peut-on retirer un garrot ?", "r": "Jamais sans avis médical."}], "quiz": [{"q": "Il saigne beaucoup, je…", "bonne": "Comprime fort l'endroit qui saigne", "fausses": ["Lui donne à boire", "Le fais marcher", "Attends que ça s'arrête"], "expl": ""}, {"q": "Pour appuyer, je protège ma main avec :", "bonne": "Un gant ou un sac plastique", "fausses": ["Rien du tout", "Du papier toilette", "Ma manche"], "expl": ""}, {"q": "La victime qui saigne, je l'installe :", "bonne": "Allongée", "fausses": ["Debout", "En train de marcher", "Assise sur une chaise haute"], "expl": ""}, {"q": "Le garrot se pose :", "bonne": "Si appuyer ne suffit pas ou est impossible", "fausses": ["Toujours en premier", "Sur le cou", "Sur un genou"], "expl": ""}, {"q": "Le garrot, on peut le retirer :", "bonne": "Jamais sans avis médical", "fausses": ["Au bout de 5 minutes", "Quand la victime le demande", "Dès qu'il fait mal"], "expl": ""}, {"q": "Je relâche la compression :", "bonne": "Jamais avant l'arrivée des secours", "fausses": ["Au bout de 30 secondes", "Pour regarder la plaie", "Quand je suis fatigué, sans relais"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Perte de connaissances": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Perte de connaissances", "objectif": "Reconnaître une victime qui ne répond pas mais respire, la mettre en position latérale de sécurité (PLS), alerter et surveiller sa respiration sans arrêt.", "pointsCles": ["Il ne répond pas : je lui parle, je lui prends la main, aucune réaction", "Je bascule doucement la tête en arrière et je vérifie la respiration : je regarde, j'écoute, je sens", "Il respire : je le mets sur le côté en PLS, stable, bouche ouverte vers le sol pour qu'il ne s'étouffe pas", "En le tournant, je limite les mouvements de la colonne (tête, cou, dos)", "J'alerte (15, 18, 112) et je surveille sa respiration sans arrêt", "S'il a pu chuter ou se blesser : je le laisse sur le dos, je ne fais pas de PLS", "Il ne respire plus : c'est un arrêt cardiaque → alerte, massage, DAE"], "materiel": "Tapis de sol, couvertures, mannequin, téléphone factice, diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Il répond ? Il respire ?", "duree": "10 min", "prep": "Mannequin ou JSP volontaire allongé sur tapis, cartes réponses de l'animateur.", "deroule": ["Le sauveteur parle à la victime, lui prend la main.", "Il bascule la tête en arrière et regarde, écoute, sent.", "L'animateur annonce « il respire » ou « il ne respire pas ».", "Le sauveteur dit ce qu'il fait."], "phrase": "Il ne répond pas mais il respire : PLS.", "securite": "Pas de bascule forcée de la tête sur un camarade : geste simulé doucement."}, {"titre": "La PLS", "duree": "20 min", "prep": "Tapis de sol.", "deroule": ["Démonstration lente par l'animateur.", "Par deux : l'un est la victime, l'autre le sauveteur (comme l'atelier du cours).", "On vérifie : stable, bouche vers le sol, tête qui ne bouge pas trop.", "On inverse les rôles."], "phrase": "Bouche vers le sol : il ne s'étouffe pas.", "securite": "Sur tapis, gestes lents ; un camarade qui ne souhaite pas être victime est remplacé par le mannequin."}, {"titre": "Je surveille", "duree": "10 min", "prep": "Victime en PLS, téléphone factice.", "deroule": ["Un témoin alerte.", "Le sauveteur surveille la respiration et la couvre.", "L'animateur annonce « il ne respire plus » : le JSP dit qu'il passe au massage."], "phrase": "", "securite": ""}], "questions": [{"q": "Comment vérifies-tu s'il répond ?", "r": "Je lui parle et je lui prends la main."}, {"q": "Comment vérifies-tu s'il respire ?", "r": "Tête basculée en arrière, je regarde, j'écoute, je sens."}, {"q": "Il ne répond pas mais respire : que fais-tu ?", "r": "Je le mets en PLS, j'alerte et je surveille."}, {"q": "Pourquoi la bouche vers le sol ?", "r": "Pour que les liquides s'écoulent et qu'il ne s'étouffe pas."}, {"q": "Il a fait une chute et ne répond pas mais respire ?", "r": "Je le laisse sur le dos, j'alerte et je surveille."}, {"q": "Il ne respire plus ?", "r": "C'est un arrêt cardiaque : j'alerte, je masse, je demande un DAE."}], "quiz": [{"q": "Il ne répond pas mais respire :", "bonne": "PLS", "fausses": ["Massage cardiaque", "Je le fais boire", "Je le laisse seul"], "expl": ""}, {"q": "En PLS, la bouche est…", "bonne": "Ouverte vers le sol", "fausses": ["Vers le ciel", "Fermée avec la main", "Contre le mur"], "expl": ""}, {"q": "Pour savoir s'il respire, je…", "bonne": "Regarde, écoute et sens", "fausses": ["Lui pince le nez", "Lui jette de l'eau", "Le secoue fort"], "expl": ""}, {"q": "Après la PLS, je…", "bonne": "Alerte et surveille sa respiration", "fausses": ["Pars chercher de l'aide sans revenir", "Le remets debout", "Lui donne à manger"], "expl": ""}, {"q": "Il ne respire plus :", "bonne": "C'est un arrêt cardiaque", "fausses": ["Il dort", "C'est un malaise simple", "Il faut attendre"], "expl": ""}, {"q": "Il ne répond pas après une chute :", "bonne": "Je le laisse sur le dos", "fausses": ["Je le mets debout", "Je le fais marcher", "Je le porte jusqu'au canapé"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Arrêt cardiaque": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Arrêt cardiaque", "objectif": "Sur mannequin, reconnaître un arrêt cardiaque, faire alerter, masser au bon rythme (100 à 120/min) et mettre en œuvre le DAE de formation en suivant ses consignes.", "pointsCles": ["Il ne répond pas et ne respire pas : c'est un arrêt cardiaque, chaque minute compte", "1. J'alerte (15, 18, 112) et je demande un défibrillateur (DAE)", "2. Je masse au centre de la poitrine, bras tendus, 100 à 120 fois par minute, en laissant la poitrine remonter", "Adulte : enfoncer d'environ 5 cm (pas plus de 6 cm)", "3. J'insuffle si je peux : 30 compressions, 2 insufflations ; sinon je masse sans m'arrêter", "4. J'allume le DAE et je suis ses consignes : électrodes sur peau nue et sèche", "On n'arrête le massage que pendant l'analyse et le choc, puis on reprend tout de suite", "On se relaie toutes les 2 minutes · tout le monde peut utiliser un DAE"], "materiel": "Mannequins de réanimation, DAE de formation, lingettes de désinfection, métronome (application) à 110/min, téléphone factice, diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Le rythme", "duree": "10 min", "prep": "Métronome à 110/min, mannequins.", "deroule": ["Les JSP tapent le rythme dans leurs mains avec le métronome.", "Puis sur le mannequin : bras tendus, au centre de la poitrine.", "On laisse la poitrine remonter à chaque fois."], "phrase": "100 à 120 par minute.", "securite": "Gestes de secours sur mannequin uniquement : jamais de compressions, de claques ou de compressions abdominales réelles sur un camarade."}, {"titre": "Les gestes qui sauvent", "duree": "20 min", "prep": "Mannequin, DAE de formation, téléphone factice ; groupes de 3.", "deroule": ["Le 1er JSP constate : il ne répond pas, il ne respire pas.", "Le 2e alerte et va chercher le DAE.", "Le 1er masse ; le 3e allume le DAE et pose les électrodes.", "On suit les consignes du DAE ; on reprend le massage après le choc."], "phrase": "J'alerte, je masse, je défibrille.", "securite": "DAE de formation uniquement (jamais un vrai DAE). Mannequin uniquement. Désinfecter le mannequin entre chaque JSP."}, {"titre": "Relais", "duree": "10 min", "prep": "Mannequin, chrono.", "deroule": ["Les JSP massent par équipes et se relaient toutes les 2 minutes sans arrêter le massage.", "Débrief : c'est fatigant, d'où l'intérêt de se relayer."], "phrase": "", "securite": "Arrêter si un JSP a mal aux poignets ; mannequin uniquement."}], "questions": [{"q": "Comment reconnais-tu un arrêt cardiaque ?", "r": "Il ne répond pas et ne respire pas."}, {"q": "Que demandes-tu en alertant ?", "r": "Un défibrillateur (DAE)."}, {"q": "Où places-tu tes mains ?", "r": "Au centre de la poitrine, bras tendus."}, {"q": "À quel rythme masses-tu ?", "r": "100 à 120 compressions par minute."}, {"q": "Combien de compressions et d'insufflations chez l'adulte ?", "r": "30 compressions, 2 insufflations, ou massage seul si je ne peux pas insuffler."}, {"q": "Qui peut utiliser un DAE ?", "r": "Tout le monde : il parle et dit quoi faire."}, {"q": "Quand arrêtes-tu le massage avec le DAE ?", "r": "Seulement pendant l'analyse et le choc, puis je reprends tout de suite."}, {"q": "Pourquoi se relayer ?", "r": "Le massage est fatigant : on change toutes les 2 minutes pour rester efficace."}], "quiz": [{"q": "Il ne répond pas et ne respire pas :", "bonne": "Arrêt cardiaque", "fausses": ["Malaise simple", "Il dort", "Obstruction partielle"], "expl": ""}, {"q": "Rythme du massage :", "bonne": "100 à 120 par minute", "fausses": ["30 par minute", "60 par minute", "200 par minute"], "expl": ""}, {"q": "Adulte, je fais :", "bonne": "30 compressions, 2 insufflations", "fausses": ["5 compressions, 5 insufflations", "15 insufflations seules", "2 compressions, 30 insufflations"], "expl": ""}, {"q": "Le DAE, je…", "bonne": "L'allume et suis ses consignes", "fausses": ["Le laisse dans sa boîte", "Attends un médecin pour l'ouvrir", "L'utilise seulement si je suis pompier"], "expl": ""}, {"q": "Les électrodes se posent :", "bonne": "Sur la peau nue et sèche", "fausses": ["Sur le tee-shirt", "Sur le bras", "Dans le dos seulement"], "expl": ""}, {"q": "Je m'entraîne au massage :", "bonne": "Sur un mannequin", "fausses": ["Sur un camarade", "Sur un coussin du canapé à la maison sans formateur", "Sur l'animateur"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Plaies": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Plaies", "objectif": "Dire si une plaie est simple ou grave et appliquer la bonne conduite : nettoyer et protéger une plaie simple, installer dans la bonne position d'attente et alerter pour une plaie grave.", "pointsCles": ["Plaie grave : je ne retire jamais un objet planté", "S'il saigne beaucoup : c'est d'abord une hémorragie (je comprime)", "Position d'attente : assis pour une plaie au thorax (laissée à l'air)", "Allongé jambes pliées pour une plaie au ventre", "Allongé, yeux fermés, tête immobile pour une plaie à l'œil ; allongé dans les autres cas", "Plaie grave : je protège, j'alerte, je surveille", "Plaie simple : je me lave les mains, je nettoie à l'eau courante ou en bouteille (savon si c'est sale), je sèche autour, je protège par un pansement", "Consulter si le vaccin antitétanique n'est pas à jour ou si la plaie s'infecte (rouge, chaude, gonflée)"], "materiel": "Compresses, pansements, savon, bouteille d'eau, couvertures, tapis, cartes « plaie » (photos ou dessins), crayon figurant un objet planté, diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Simple ou grave ?", "duree": "10 min", "prep": "Cartes « plaie » : écorchure du genou, coupure au doigt, objet planté dans la cuisse, plaie au ventre, à l'œil, au thorax…", "deroule": ["L'animateur montre une carte.", "Les JSP disent : simple ou grave ? Pourquoi ?", "On rappelle : objet planté = on ne le retire jamais."], "phrase": "", "securite": ""}, {"titre": "Les positions d'attente", "duree": "15 min", "prep": "Tapis, chaises, couvertures, cartes « plaie grave ».", "deroule": ["Un JSP volontaire tire une carte plaie grave.", "Le sauveteur l'installe : assis (thorax), allongé jambes pliées (ventre), allongé yeux fermés (œil).", "Il le couvre, alerte (téléphone factice) et le surveille."], "phrase": "Objet planté : je ne touche pas.", "securite": "Aucun objet réel planté : on fixe un crayon sur un vêtement pour simuler."}, {"titre": "Je soigne une plaie simple", "duree": "15 min", "prep": "Savon, eau, compresses, pansements, bras d'entraînement ou main avec « écorchure » dessinée.", "deroule": ["Se laver les mains.", "Nettoyer à l'eau, sécher autour, poser le pansement.", "Dire quand consulter : vaccin pas à jour, signes d'infection."], "phrase": "", "securite": "Hygiène : mains lavées, matériel à usage unique."}], "questions": [{"q": "Un objet est planté dans la jambe : que fais-tu ?", "r": "Je ne le retire jamais, j'installe la victime, j'alerte, je surveille."}, {"q": "Plaie au thorax : quelle position ?", "r": "Assis."}, {"q": "Plaie au ventre ?", "r": "Allongé, jambes pliées."}, {"q": "Plaie à l'œil ?", "r": "Allongé, yeux fermés, tête immobile."}, {"q": "Comment soignes-tu une plaie simple ?", "r": "Je me lave les mains, je nettoie à l'eau, je sèche autour, je mets un pansement."}, {"q": "Quand faut-il consulter un médecin pour une plaie simple ?", "r": "Si le vaccin n'est pas à jour ou si elle s'infecte."}], "quiz": [{"q": "Un objet est planté :", "bonne": "Je ne le retire jamais", "fausses": ["Je le retire doucement", "Je le tourne", "Je le pousse plus loin"], "expl": ""}, {"q": "Plaie au thorax, position :", "bonne": "Assis", "fausses": ["Allongé sur le ventre", "Debout", "PLS d'office"], "expl": ""}, {"q": "Plaie au ventre, position :", "bonne": "Allongé, jambes pliées", "fausses": ["Assis penché en avant", "Debout", "Allongé jambes tendues en l'air"], "expl": ""}, {"q": "Plaie à l'œil :", "bonne": "Allongé, yeux fermés, tête immobile", "fausses": ["Je rince fort", "Je frotte l'œil", "Je le fais lire"], "expl": ""}, {"q": "Plaie simple, d'abord :", "bonne": "Je me lave les mains", "fausses": ["Je souffle dessus", "Je mets du coton", "Je la laisse sale"], "expl": ""}, {"q": "Je nettoie une plaie simple avec :", "bonne": "De l'eau (et du savon si c'est sale)", "fausses": ["De la terre", "De la salive", "Du soda"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026)"}, "JSP1|Brûlures": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Brûlures", "objectif": "Refroidir immédiatement une brûlure simulée à l'eau courante tempérée (au moins 10 minutes, idéalement 20) et dire si la brûlure est grave ou simple et ce qu'on fait ensuite.", "pointsCles": ["Je refroidis tout de suite : eau courante tempérée, qui coule doucement (faible pression)", "Au moins 10 minutes, idéalement 20 minutes", "J'enlève les vêtements et les bijoux qui ne collent pas à la peau", "Brûlure grave : j'alerte dès que je commence à refroidir et je suis les consignes", "Après le refroidissement : position d'attente (allongé, ou assis s'il respire mal)", "Je ne mets aucun produit (ni crème, ni beurre, ni dentifrice) sans avis médical", "Je ne perce jamais les cloques", "Brûlure simple : refroidir jusqu'à ce que la douleur disparaisse, protéger (pansement stérile ou film plastique non adhésif) ; consulter si enfant ou nourrisson, vaccin pas à jour ou signes d'infection"], "materiel": "Robinet ou bassine d'eau tempérée avec broc, chrono, cartes brûlures, film plastique alimentaire, compresses, couverture, téléphone factice, diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Vrai ou faux ?", "duree": "10 min", "prep": "Cartes idées reçues (beurre, dentifrice, glaçon, percer la cloque, eau courante…).", "deroule": ["L'animateur lit une idée.", "Les JSP votent vrai ou faux.", "On corrige : seule l'eau courante tempérée est le bon réflexe."], "phrase": "", "securite": ""}, {"titre": "Le bon réflexe", "duree": "20 min", "prep": "Point d'eau, chrono.", "deroule": ["Un JSP a une « brûlure » à l'avant-bras (dessin au feutre lavable).", "Le sauveteur fait couler l'eau tempérée doucement dessus et lance le chrono.", "Il retire montre et bracelet, fait alerter si c'est grave.", "On fait la démonstration sur 2 minutes et on explique : en vrai, au moins 10 minutes, idéalement 20."], "phrase": "Je refroidis tout de suite, longtemps.", "securite": "Eau tempérée seulement (ni froide glacée, ni chaude) ; sol mouillé : attention aux glissades."}, {"titre": "Grave ou simple ?", "duree": "10 min", "prep": "Cartes brûlures (petite rougeur, grosse cloque, brûlure au visage, brûlure étendue…).", "deroule": ["Les JSP classent les cartes en simple ou grave.", "Pour chaque grave : j'alerte dès le début du refroidissement.", "Pour chaque simple : je refroidis, je protège, je surveille."], "phrase": "", "securite": ""}], "questions": [{"q": "Premier geste devant une brûlure ?", "r": "Refroidir tout de suite à l'eau courante tempérée."}, {"q": "Combien de temps ?", "r": "Au moins 10 minutes, idéalement 20."}, {"q": "Que retires-tu ?", "r": "Les vêtements et bijoux qui ne collent pas à la peau."}, {"q": "Peut-on mettre de la crème ou du beurre ?", "r": "Non, aucun produit sans avis médical."}, {"q": "Peut-on percer une cloque ?", "r": "Jamais."}, {"q": "Brûlure grave : quand alertes-tu ?", "r": "Dès que je commence à refroidir."}, {"q": "Comment protèges-tu une brûlure simple ?", "r": "Pansement stérile ou film plastique non adhésif."}], "quiz": [{"q": "Brûlure : je refroidis avec…", "bonne": "De l'eau courante tempérée", "fausses": ["Des glaçons", "Du beurre", "De l'eau très chaude"], "expl": ""}, {"q": "Combien de temps ?", "bonne": "Au moins 10 minutes, idéalement 20", "fausses": ["30 secondes", "1 minute", "Une heure obligatoire"], "expl": ""}, {"q": "Une cloque :", "bonne": "Je ne la perce jamais", "fausses": ["Je la perce avec une aiguille", "Je l'arrache", "Je la gratte"], "expl": ""}, {"q": "Sur la brûlure, je mets :", "bonne": "Rien (aucun produit sans avis médical)", "fausses": ["De la crème", "Du dentifrice", "Du beurre"], "expl": ""}, {"q": "Brûlure grave : j'alerte…", "bonne": "Dès que je commence à refroidir", "fausses": ["Après 20 minutes", "Le lendemain", "Jamais"], "expl": ""}, {"q": "Les bijoux près de la brûlure :", "bonne": "Je les retire s'ils ne collent pas", "fausses": ["Je les laisse", "Je les serre", "Je les retire même s'ils collent"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026) · fiche PSC 02PR07 Brûlures (07-2026)"}, "JSP1|Traumatismes": {"cycle": "JSP1", "bloc": "Porter secours", "item": "Traumatismes", "objectif": "Devant une victime simulée de chute ou de choc, ne pas la déplacer, lui demander de ne pas bouger, alerter, la couvrir et la surveiller jusqu'à l'arrivée des secours.", "pointsCles": ["Traumatisme : après un coup, une chute ou un choc (douleur, gonflement, déformation, impossible de bouger)", "Blessé : on ne bouge pas ! Je ne déplace pas la victime", "Je lui dis fermement de ne pas bouger la partie blessée", "Je ne remets jamais en place un membre déformé (fracture déplacée)", "Je la protège du chaud, du froid et de la pluie (couverture)", "J'alerte (15, 18, 112) et je suis les consignes", "Je surveille et je lui parle jusqu'à l'arrivée des secours", "S'il ne répond pas ou ne respire pas : la priorité reste l'urgence vitale (alerte, surveillance, réanimation)"], "materiel": "Tapis de sol, couvertures, téléphone factice, cartes « accident » (chute de vélo, chute dans l'escalier, choc au sport…), diaporama « Premiers secours citoyens ».", "activites": [{"titre": "Ne bouge pas !", "duree": "15 min", "prep": "Tapis, couverture ; un JSP volontaire joue le blessé (cheville, poignet…).", "deroule": ["Le sauveteur arrive, se présente et dit : « Ne bougez pas. »", "Il ne déplace pas la victime, il la couvre.", "Il fait alerter et lui parle pour la rassurer."], "phrase": "Blessé : on ne bouge pas.", "securite": "La victime reste allongée ou assise comme elle est tombée ; aucun geste de remise en place."}, {"titre": "Que s'est-il passé ?", "duree": "15 min", "prep": "Cartes accident, téléphone factice.", "deroule": ["Le JSP tire une carte et décrit les signes (douleur, gonflement, déformation).", "Il passe l'alerte au 18 ou au 15 : ce qui s'est passé, où, l'état de la victime.", "L'animateur joue l'opérateur."], "phrase": "", "securite": "Jamais de vrai appel."}, {"titre": "Le piège", "duree": "10 min", "prep": "Cartes « mauvaises idées » (le relever, lui faire bouger la jambe, remettre le bras droit, lui donner à boire…).", "deroule": ["Les JSP repèrent les mauvaises idées.", "Ils disent ce qu'il faut faire à la place."], "phrase": "", "securite": ""}], "questions": [{"q": "Qu'est-ce qu'un traumatisme ?", "r": "Une blessure après un coup, une chute ou un choc."}, {"q": "Quels signes peux-tu voir ?", "r": "Douleur, gonflement, déformation, impossible de bouger."}, {"q": "Déplaces-tu la victime ?", "r": "Non, je ne la déplace pas."}, {"q": "Que lui dis-tu ?", "r": "De ne pas bouger la partie blessée."}, {"q": "Remets-tu un bras tordu dans l'axe ?", "r": "Jamais."}, {"q": "Comment la protèges-tu ?", "r": "Je la couvre (froid, chaud, pluie), j'alerte, je la surveille et je lui parle."}], "quiz": [{"q": "Après une chute, la victime a mal au genou :", "bonne": "Je ne la déplace pas", "fausses": ["Je la relève", "Je la fais marcher", "Je lui tire la jambe"], "expl": ""}, {"q": "Je lui conseille…", "bonne": "De ne pas bouger", "fausses": ["De sauter sur place", "De se lever vite", "De masser fort"], "expl": ""}, {"q": "Une jambe déformée :", "bonne": "Je ne la remets jamais en place", "fausses": ["Je la redresse", "Je la secoue", "Je la plie"], "expl": ""}, {"q": "Pour la protéger du froid :", "bonne": "Je la couvre", "fausses": ["Je la déshabille", "Je l'arrose", "Je la laisse au vent"], "expl": ""}, {"q": "Ensuite :", "bonne": "J'alerte et je surveille", "fausses": ["Je rentre chez moi", "J'attends sans rien dire", "Je la mets debout"], "expl": ""}, {"q": "Le message clé :", "bonne": "Blessé : on ne bouge pas", "fausses": ["Blessé : on court", "Blessé : on soulève", "Blessé : on étire"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Premiers secours citoyens » (charte SDIS 34) · RNF JSP/JMP v1.1 (avril 2026) · recommandations PSC du ministère de l'Intérieur, fiches mises à jour 07-2026 (02PR06 Plaies, 02PR07 Brûlures, 02PR08 Traumatismes) · guide technique PSC (juin 2026) · fiche PSC 02PR08 Traumatismes (07-2026)"}, "JSP2|L'évolution au moyen du LSPCC": {"cycle": "JSP2", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "L'évolution au moyen du LSPCC", "objectif": "Nommer chaque élément du LSPCC, réaliser un amarrage en double et un nœud de 8 double contrôlés par l'animateur, et citer les règles contre les chutes (facteur de chute, connecteur automatique).", "pointsCles": ["LSPCC = lot de sauvetage et de protection contre les chutes : sauver, accéder à une victime, protéger un SP qui travaille en hauteur", "Lot « engin » : sac jaune, corde de 30 m, 1 harnais, 1 triangle · au CIS : FPTGP, CCFU et VSRTU ; lot « échelle » (sac bleu, 60 m) sur les grandes échelles", "Corde (≥ 3 000 kg), harnais, triangle (victime), descendeur en 8 (freine), sangles bleue 80 cm et rouge 1,5 m, connecteurs, poulie, cordelettes, protection cuir, antichute mobile", "Le connecteur automatique se place TOUJOURS entre la corde et la personne ; un connecteur travaille dans sa longueur et toujours fermé", "La chaîne : point d'ancrage solide → amarrage → frein (descendeur) → corde et charge ; un doute sur l'ancrage ? on en choisit un autre", "Amarrage = au minimum 1 sangle + 1 connecteur à vis ; sangle en double ; pas de tête d'alouette ; angle ≤ 90° entre deux sangles", "Nœud de 8 double à chaque bout (bout libre ≥ 10 cm, il enlève 30 % de résistance) ; nœud « Français » (3 tours) avec la cordelette", "Facteur de chute : 0,3 recherché (accroché au-dessus de soi), 1 à éviter, au-dessus de 1 interdit ; tirant d'air ≥ 1 m ; rester suspendu inerte est une urgence", "Ordres : « Laissez filer ! », « Du mou ! », « Sec ! », « Sécurisez le dispositif ! », « Contact ! », « Victime en sécurité ! »", "Après : regarder, toucher toute la corde, noter dans le cahier de suivi, laver à la main ≤ 30 °C, signaler ; textiles remplacés après 10 ans max"], "materiel": "LSPCC « engin » du FPTGP (ou CCFU / VSRTU) ou lot de formation, commande, casques, gants, mannequin de sauvetage, tapis de sol, cahier de suivi · point d'ancrage solide repéré (pilier, rambarde).", "activites": [{"titre": "Déballe le lot", "duree": "10 min", "prep": "Sac LSPCC vidé sur une bâche.", "deroule": ["Chaque binôme prend un élément, le nomme et dit à quoi il sert.", "Manipulation des connecteurs : visser / verrouiller, vérifier la fermeture.", "On remet tout dans l'ordre de reconditionnement (corde au fond, triangle en haut)."], "phrase": "Chaque élément a son rôle dans la chaîne.", "securite": ""}, {"titre": "Ateliers nœud de 8 et amarrage", "duree": "15 min", "prep": "Bouts de corde, sangles, connecteurs à vis, un pilier ou une rambarde au sol.", "deroule": ["Chaque JSP fait un nœud de 8 double, contrôlé par l'animateur (bout libre ≥ 10 cm).", "En binôme : amarrage en double sur le point d'ancrage, connecteur à vis fermé.", "Le binôme voisin contrôle : pas de tête d'alouette ?"], "phrase": "Une chaîne est aussi solide que son maillon le plus faible.", "securite": "Au sol uniquement."}, {"titre": "Harnais et ordres", "duree": "10 min", "prep": "Harnais, corde au sol, descendeur.", "deroule": ["Chaque JSP enfile le harnais (au sol, une jambe dans chaque boucle, demi-lune, serrage) ; contrôle croisé.", "L'animateur annonce un ordre (« Sec ! », « Du mou ! », « Laissez filer ! ») : les JSP miment avec la corde au sol."], "phrase": "", "securite": "Sans charge."}, {"titre": "Le contrôle et le cahier de suivi", "duree": "10 min", "prep": "Corde du lot, cahier de suivi.", "deroule": ["Toute la corde passe dans les mains : zone dure, molle ou écrasée ?", "On note l'utilisation dans le cahier de suivi.", "Sac reconditionné prêt à repartir."], "phrase": "", "securite": "Toute mise en situation en hauteur : 3 m max, ancrages installés et assurés par des animateurs qualifiés, double assurance, mannequin pour la victime."}], "questions": [{"q": "Que veut dire LSPCC ?", "r": "Lot de sauvetage et de protection contre les chutes."}, {"q": "Quelle longueur de corde dans le lot « engin » ?", "r": "30 m."}, {"q": "À quoi sert le descendeur ?", "r": "À freiner et contrôler la descente de la corde."}, {"q": "Où place-t-on le connecteur automatique ?", "r": "Entre la corde et la personne (obligatoire)."}, {"q": "Un amarrage, c'est au minimum… ?", "r": "1 sangle + 1 connecteur à vis."}, {"q": "Quel facteur de chute est interdit ?", "r": "Un facteur supérieur à 1 (point d'accroche sous soi)."}, {"q": "Que veut dire l'ordre « Sec ! » ?", "r": "Retenir fermement la corde, sans mou."}, {"q": "Que fais-tu si tu as un doute sur un point d'ancrage ?", "r": "J'en choisis un autre."}, {"q": "Après une manœuvre, que fait-on du LSPCC ?", "r": "On contrôle, on note dans le cahier de suivi, on lave si besoin et on signale tout doute."}], "quiz": [{"q": "Quel élément freine et contrôle la descente ?", "bonne": "Le descendeur en 8", "fausses": ["La poulie", "Le triangle", "La sangle bleue"], "expl": ""}, {"q": "Où se place le connecteur automatique ?", "bonne": "Entre la corde et la personne", "fausses": ["Sur le point d'ancrage", "Dans le sac", "Sur le casque"], "expl": "C'est obligatoire."}, {"q": "Un amarrage, c'est au minimum…", "bonne": "1 sangle + 1 connecteur à vis", "fausses": ["Une corde nouée au poignet", "2 descendeurs", "Un nœud sur le triangle"], "expl": ""}, {"q": "Quel facteur de chute recherche-t-on ?", "bonne": "0,3 (accroché au-dessus de soi)", "fausses": ["2", "1", "3"], "expl": ""}, {"q": "Quelle longueur de corde dans le lot « engin » ?", "bonne": "30 m", "fausses": ["60 m", "10 m", "100 m"], "expl": "Le lot « échelle » a 60 m."}, {"q": "La « tête d'alouette » sur une sangle est…", "bonne": "Interdite", "fausses": ["Obligatoire", "Conseillée", "Sans importance"], "expl": "Elle affaiblit la sangle."}, {"q": "Que veut dire « Du mou ! » ?", "bonne": "Donner un peu de corde", "fausses": ["Retenir fermement", "Lâcher la corde", "Ranger le sac"], "expl": ""}, {"q": "En formation, la victime est toujours…", "bonne": "Un mannequin", "fausses": ["Un JSP volontaire", "Un animateur", "Le plus léger du groupe"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Le lot de sauvetage et de protection contre les chutes » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 INC B1 · RDLSPCC SDIS 34 v1 (novembre 2025) § 1.1, 2.1 à 2.7, 2.12, 3.8, 5.1, 5.2, 5.7"}, "JSP2|Les règles d'emploi et de sécurité de l'échelle à coulisse": {"cycle": "JSP2", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "Les règles d'emploi et de sécurité de l'échelle à coulisse", "objectif": "En binôme, descendre de l'engin (avec le conducteur), porter, dresser, déployer et reployer l'échelle à coulisse 2 plans en respectant le piétage à 1/3 et les règles de sécurité, sans erreur.", "pointsCles": ["Elle sert à sauver, reconnaître et établir : coulisse 2 plans jusqu'au 2e étage, coulisse 3 plans jusqu'au 4e (le JSP2 ne travaille que la 2 plans)", "Au CIS : FPTGP (coulisse 2 plans grand modèle, 3 plans, crochets) · VSRTU (coulisse 2 plans grand modèle, crochets, télescopique) · CCFU (coulisse 3 plans, crochets)", "Éléments : plan supérieur, montants et échelons, parachutes (bloquent l'échelle dépliée), trait (corde pour déplier/replier), pieds", "Règles : 1 personne par plan (sauf sauvetage), sol stable, parachutes enclenchés, mains sur les montants pour déplier ou replier", "La manœuvre en binôme : descendre (avec le conducteur), porter (base devant, chef d'équipe côté sommet, équipier côté base, le plus bas possible), dresser, déployer, reployer", "Piétage ≈ 1/3 de la hauteur d'appui (angle 65 à 75°) ; test des bras : debout au pied, bras tendus, les mains tombent sur un échelon", "Appui sur une partie solide, les deux montants contre le mur ; en incendie de préférence sans dépassement", "Celui qui tient l'échelle se place devant, mains sur les montants, et ne la lâche jamais tant que quelqu'un est dessus ; trait attaché au milieu d'un échelon", "Monter avec 3 points de contact (2 mains + 1 pied ou 2 pieds + 1 main), mains sur les échelons", "Dangers : l'échelle n'isole pas (1 m à 5 m des câbles électriques), le vent, la chaleur (l'aluminium fond vers 660 °C) ; dos droit, jambes fléchies, un JSP ne monte jamais sur le toit de l'engin"], "materiel": "Échelle à coulisse 2 plans grand modèle du FPTGP ou du VSRTU (≈ 33 kg), un conducteur pour la descente de l'engin, casques jugulaire attachée, gants, plots, chrono · façade ou mur d'exercice dégagé de tout câble.", "activites": [{"titre": "Repère les éléments", "duree": "5 min", "prep": "Échelle posée au sol.", "deroule": ["Les JSP montrent : plan supérieur, montants, échelons, parachutes, trait, pieds.", "Ils disent à quoi sert chaque élément."], "phrase": "", "securite": "Doigts loin des plans qui coulissent."}, {"titre": "La manœuvre complète en binôme", "duree": "25 min", "prep": "Une échelle et un animateur par binôme ; le conducteur descend l'échelle avec le binôme.", "deroule": ["Descendre de l'engin avec le conducteur, réceptionner à deux.", "Porter base devant, le plus bas possible, jusqu'au point désigné.", "Dresser (équipier cale la base), déployer au trait, vérifier les DEUX parachutes, mettre en appui.", "Reployer, coucher, porter et remettre sur l'engin avec le conducteur. On inverse les rôles."], "phrase": "Toujours à deux, à l'ordre du chef.", "securite": "Un JSP ne monte jamais sur le toit de l'engin. Dos droit, jambes fléchies, mains sur les montants. Lever les yeux avant de dresser (câbles). Si c'est trop lourd, on le dit."}, {"titre": "Le bon piétage", "duree": "10 min", "prep": "Échelle dressée en appui par l'animateur, ruban ou mètre.", "deroule": ["Un JSP fait le test des bras au pied de l'échelle.", "Les autres vérifient avec le mètre : environ 1/3 de la hauteur ?", "On montre l'échelle trop droite (bascule) et trop penchée (glisse) : qu'est-ce qui se passe ?", "Chacun tient l'échelle à son tour : devant, mains sur les montants."], "phrase": "Trop droite, elle bascule ; trop penchée, elle glisse.", "securite": "Pas de montée sur l'échelle, sauf si l'animateur le décide : hauteur limitée, échelle tenue par un animateur, 3 points de contact."}, {"titre": "Défi chrono", "duree": "5 min", "prep": "Une fois les gestes acquis.", "deroule": ["Chaque binôme réalise dresser-déployer-reployer chronométré.", "Une erreur de sécurité = défi annulé."], "phrase": "", "securite": ""}], "questions": [{"q": "Jusqu'à quel étage va la coulisse 2 plans ?", "r": "Jusqu'au 2e étage."}, {"q": "À quoi servent les parachutes ?", "r": "À bloquer l'échelle une fois dépliée."}, {"q": "À quoi sert le trait ?", "r": "À déplier et replier l'échelle."}, {"q": "Où mettre ses mains pour déplier l'échelle ?", "r": "Sur les montants, jamais entre les échelons."}, {"q": "Comment porte-t-on l'échelle ?", "r": "À deux, base devant, le plus bas possible."}, {"q": "Quel piétage pour une échelle ?", "r": "Environ 1/3 de la hauteur d'appui."}, {"q": "Combien de points de contact pour monter ?", "r": "3 : deux mains et un pied, ou deux pieds et une main."}, {"q": "Combien de personnes par plan ?", "r": "Une seule, sauf pour un sauvetage."}, {"q": "Pourquoi rester loin des câbles électriques ?", "r": "L'échelle n'est pas isolante (1 à 5 m de distance)."}], "quiz": [{"q": "À quoi servent les parachutes ?", "bonne": "À bloquer l'échelle dépliée", "fausses": ["À freiner la chute du porteur", "À porter l'échelle", "À faire glisser le trait"], "expl": ""}, {"q": "Où place-t-on ses mains pour déployer l'échelle ?", "bonne": "Sur les montants", "fausses": ["Entre les échelons", "Sur les parachutes", "Dans les poches"], "expl": "Sinon, risque d'écrasement des doigts."}, {"q": "Le piétage, c'est environ…", "bonne": "1/3 de la hauteur d'appui", "fausses": ["La moitié de la hauteur", "Collé au mur", "Le double de la hauteur"], "expl": "Angle de 65 à 75°."}, {"q": "Combien de personnes par plan (hors sauvetage) ?", "bonne": "1", "fausses": ["2", "3", "Autant qu'on veut"], "expl": ""}, {"q": "Quand on porte l'échelle, on met devant…", "bonne": "La base (les pieds)", "fausses": ["Le sommet", "Le trait", "Le plan supérieur"], "expl": ""}, {"q": "Pour monter, on garde…", "bonne": "3 points de contact", "fausses": ["1 point de contact", "Les mains dans les poches", "Les deux pieds en l'air"], "expl": ""}, {"q": "Une échelle à coulisse en aluminium…", "bonne": "N'isole pas de l'électricité", "fausses": ["Isole de l'électricité", "Résiste à toutes les flammes", "Ne pèse rien"], "expl": ""}, {"q": "Celui qui tient l'échelle la lâche…", "bonne": "Jamais tant que quelqu'un est dessus", "fausses": ["Dès que l'autre est à mi-hauteur", "Pour se gratter", "Quand le chef regarde ailleurs"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les échelles à coulisse » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 INC B2 · RDEP SDIS 34 échelles portables (v1 juin 2023 – vérifier s'il existe une version plus récente) · GTO Sauvetages et mises en sécurité · RDMI v6 · FAT FPTGP, VSRTU, CCFU"}, "JSP2|Les matériels d'épuisement": {"cycle": "JSP2", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Les matériels d'épuisement", "objectif": "Faire la différence entre épuiser et assécher, citer la marche générale de l'intervention et mettre en œuvre en binôme le lot épuisement et le lot assèchement du VSRTU en sécurité (seul l'animateur branche).", "pointsCles": ["Épuiser = retirer la plus grande partie de l'eau (pompe électrique) ; assécher = retirer ce qui reste (aspirateur à eau, raclettes)", "Marche générale : reconnaître → sécuriser (couper l'électricité, baliser, s'équiper) → arrêter la cause → protéger les biens → épuiser puis assécher → rendre compte ; d'abord les personnes", "Lot épuisement (VSRTU) : pompe électrique de 15 ou 30 m³/h (15 m³/h = 250 L/min) + 2 tuyaux souples de 20 m ; la crépine empêche les cailloux d'entrer", "Lot assèchement : aspirateur électrique avec tuyau et balai, 2 raclettes ; lot bâchage (bâches 3 × 4 m) pour protéger les biens", "Calcul : volume = longueur × largeur × hauteur d'eau ; temps = volume ÷ débit ; 1 m³ = 1 000 litres (ex. 10 m³ avec 15 m³/h = 40 min)", "Mise en œuvre : couper l'électricité (décision du chef d'agrès), tuyau vers le caniveau, pompe au point bas portée par sa poignée (jamais par le câble), branchements hors de l'eau, personne dans l'eau pendant le pompage, arrêt dès qu'elle aspire de l'air", "Alimentation : groupe électrogène 3 kW du VSRTU ou prise protégée ; touret entièrement déroulé ; seul un adulte formé branche et débranche", "Dangers : électricité, obstacles invisibles sous l'eau, eau sale, plafonds abîmés, courant (30 cm d'eau qui coule font tomber), froid ; on sonde devant soi, jamais seul, pas de cuissardes", "EPI : casque, gants, bottes de sécurité ; après : se laver les mains, nettoyer le matériel, vérifier et ranger en caisse, conseiller l'habitant (électricien, assurance)"], "materiel": "VSRTU : lot épuisement électrique (pompe 15 ou 30 m³/h, 2 tuyaux souples de 20 m), lot assèchement (aspirateur à eau, tuyau, balai, 2 raclettes), lot bâchage, groupe électrogène 3 kW et touret · bac ou bâche relevée rempli d'eau, planche, seaux, mètre, chrono · casques, gants, bottes.", "activites": [{"titre": "Combien de seaux ?", "duree": "10 min", "prep": "Ardoises, mètre ; plan d'une cave de 4 m × 5 m avec 50 cm d'eau.", "deroule": ["Les JSP estiment : 100, 1 000 ou 10 000 seaux ?", "Calcul ensemble : 4 × 5 × 0,5 = 10 m³ = 10 000 L = 1 000 seaux de 10 L.", "Avec la pompe de 15 m³/h : 40 min ; avec 30 m³/h : 20 min.", "Par binôme : une buanderie 3 × 2 m avec 20 cm d'eau."], "phrase": "Sans pompe, on y serait encore demain !", "securite": ""}, {"titre": "Le chantier d'épuisement", "duree": "25 min", "prep": "Bac ou bâche relevée rempli d'eau, pompe du lot, tuyaux, groupe électrogène démarré et branché par l'animateur, aspirateur, raclettes.", "deroule": ["Reconnaître : où est l'eau, quels dangers ? On annonce « coupure de l'électricité » (simulée).", "Dérouler le tuyau de refoulement jusqu'au caniveau, sans plis.", "Placer la pompe au point bas, portée par la poignée ; l'animateur branche.", "Arrêt dès que la pompe aspire de l'air, puis assécher aux raclettes et à l'aspirateur. Chrono : qui vide le plus vite et le plus proprement ?"], "phrase": "D'abord la pompe, puis l'aspirateur et les raclettes.", "securite": "Seul l'animateur branche, débranche et démarre le groupe. Personne dans l'eau pendant le pompage. Mains sèches, gants, bottes."}, {"titre": "Reconditionner les lots", "duree": "10 min", "prep": "Le matériel de l'atelier.", "deroule": ["Rincer la pompe et nettoyer la crépine, vider et sécher les tuyaux, vider la cuve de l'aspirateur.", "Contrôler le câble (pas de coupure).", "Tout remettre complet en caisse et rendre compte à l'animateur."], "phrase": "Une caisse complète, c'est une intervention réussie la prochaine fois.", "securite": "Matériel débranché avant nettoyage."}], "questions": [{"q": "Quelle différence entre épuiser et assécher ?", "r": "Épuiser = retirer la plupart de l'eau (pompe) ; assécher = retirer ce qui reste (aspirateur, raclettes)."}, {"q": "Que fait-on avant d'entrer dans un local inondé ?", "r": "On coupe l'électricité (sur décision du chef d'agrès)."}, {"q": "Comment porte-t-on la pompe ?", "r": "Par sa poignée, jamais par le câble."}, {"q": "Où place-t-on la pompe ?", "r": "Au point le plus bas du local."}, {"q": "Combien de litres dans 1 m³ ?", "r": "1 000 litres."}, {"q": "Quand arrête-t-on la pompe ?", "r": "Dès qu'elle aspire de l'air : elle ne doit pas tourner à sec."}, {"q": "Pourquoi sonder devant soi dans l'eau ?", "r": "Pour repérer une trappe, une marche ou un regard ouvert invisibles."}, {"q": "Quel conseil donner à l'habitant ?", "r": "Ne pas remettre le courant avant la vérification d'un électricien, prévenir son assurance."}], "quiz": [{"q": "Retirer les dernières flaques, c'est…", "bonne": "Assécher", "fausses": ["Épuiser", "Bâcher", "Pomper à sec"], "expl": "Avec l'aspirateur à eau et les raclettes."}, {"q": "Première action avant d'entrer dans une cave inondée ?", "bonne": "Faire couper l'électricité", "fausses": ["Brancher la pompe", "Marcher dans l'eau pour voir", "Ouvrir le robinet"], "expl": ""}, {"q": "Où place-t-on la pompe électrique ?", "bonne": "Au point le plus bas", "fausses": ["Sur une table", "Dans l'escalier", "Dehors sur le trottoir"], "expl": ""}, {"q": "Comment porte-t-on la pompe ?", "bonne": "Par la poignée", "fausses": ["Par le câble", "Par le tuyau", "Avec les pieds"], "expl": ""}, {"q": "1 m³ d'eau, c'est…", "bonne": "1 000 litres", "fausses": ["100 litres", "10 litres", "10 000 litres"], "expl": ""}, {"q": "10 m³ avec une pompe de 15 m³/h, ça prend environ…", "bonne": "40 minutes", "fausses": ["4 minutes", "4 heures", "1 jour"], "expl": ""}, {"q": "Pendant le pompage, dans l'eau il y a…", "bonne": "Personne", "fausses": ["Le binôme", "L'habitant", "Le chef d'agrès"], "expl": ""}, {"q": "Pourquoi pas de cuissardes ?", "bonne": "Elles se remplissent d'eau en cas de chute", "fausses": ["Elles sont trop chaudes", "Elles sont trop chères", "Elles salissent la cave"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les matériels d'épuisement et d'assèchement » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 PPBE A1 · FAT VSRTU (lots conditionnés au CIS) · pas de référentiel départemental dédié : règles générales et notice de la pompe du centre (débit à vérifier)"}, "JSP3|Les agents extincteurs et les procédés d'extinction": {"cycle": "JSP3", "bloc": "Eteindre un incendie", "item": "Les agents extincteurs et les procédés d'extinction", "objectif": "Pour 4 situations de feu, donner la classe, l'agent extincteur adapté, le procédé d'extinction et ce qu'il ne faut surtout pas faire (4 justes sur 4, 10 min).", "pointsCles": ["5 classes de feux : A solides (braises), B liquides, C gaz, D métaux, F huiles de cuisson ; le feu électrique n'est plus une classe : on coupe le courant", "Huile en feu : JAMAIS d'eau (boule de feu) ; couper la plaque, couvrir (couvercle, couverture anti-feu) ou extincteur classe F", "L'eau agit par refroidissement : jet diffusé (refroidit et protège le binôme), jet droit (va loin), eau dopée avec additif (mouille mieux)", "Mousse = eau + émulseur (solution moussante) + air : elle étouffe, isole des vapeurs et refroidit ; surtout feux B, aussi A", "Poudre ABC (polyvalente), BC, D (métaux) : elle casse la réaction (inhibition) mais refroidit peu : le feu peut repartir", "CO2 : chasse l'oxygène (étouffe), ne salit pas, idéal sur appareils électriques et liquides ; très froid ; sable : étouffe les petits feux de liquides et de métaux (bien sec)", "Feu de gaz : on coupe le gaz, on n'éteint pas la flamme si la fuite continue", "Procédés : refroidissement (énergie, le plus utilisé : 1 L d'eau donne environ 1 700 L de vapeur), étouffement (comburant), coupure d'alimentation (combustible), soufflage (petits feux), dispersion (déblai), inhibition (poudre), faire la part du feu (stratégie)", "En vrai, on combine les procédés et on finit toujours par le déblai"], "materiel": "Extincteurs de démonstration (eau + additif, poudre ABC, CO2) pour lire les étiquettes et pictogrammes, seau de sable, couverture anti-feu ; bougies, bocal, pince, verre d'eau, plateau métallique, extincteur à proximité ; LDV 40 et adaptateur mousse du FPTGP pour montrer les jets ; cartes-situations.", "activites": [{"titre": "Lire les extincteurs", "duree": "10 min", "prep": "Extincteurs de démonstration posés sur une table.", "deroule": ["Chaque binôme lit l'étiquette d'un extincteur : agent, classes de feux (pictogrammes), utilisable sur appareil sous tension ?", "Il présente « son » extincteur au groupe : sur quels feux, et son défaut (la poudre refroidit peu, le CO2 est très froid)."], "phrase": "Un agent adapté à chaque feu.", "securite": "Extincteurs non percutés, on ne les déclenche pas."}, {"titre": "Quatre bougies, quatre procédés", "duree": "10 min", "prep": "4 bougies sur un plateau métallique, bocal, verre d'eau, pince, extincteur à côté.", "deroule": ["Les JSP prédisent ce qui va se passer et quel côté du triangle sera supprimé.", "L'animateur souffle (soufflage), pose le bocal (étouffement), verse un peu d'eau (refroidissement), pince la mèche (coupure).", "Après chaque bougie, un JSP réexplique."], "phrase": "Éteindre = casser le triangle.", "securite": "Expériences faites par l'animateur uniquement, cheveux attachés."}, {"titre": "Le bon agent sur le bon feu", "duree": "15 min", "prep": "Grand tableau classes × agents à remplir (OUI / NON), cartes-situations (poubelle de papiers, friteuse, ordinateur branché, bidon d'essence, tas de bois qui fume, fuite de gaz enflammée…).", "deroule": ["Par binôme, tirer une carte : donner la classe, l'agent, le procédé.", "Dire aussi ce qu'il ne faut surtout pas faire.", "Remplir ensemble le tableau du cours ; corriger les erreurs."], "phrase": "Pas d'eau sur l'huile ni sur l'électricité, et on coupe le gaz avant tout.", "securite": ""}, {"titre": "Les jets de la LDV", "duree": "10 min", "prep": "FPT avec le conducteur, LDV 40 en eau, zone dégagée.", "deroule": ["Chaque JSP, doublé par un animateur, passe du jet droit au jet diffusé.", "On observe : le jet diffusé fait un écran et refroidit, le jet droit va loin."], "phrase": "Le jet diffusé refroidit et protège.", "securite": "Lance tenue à deux mains, jamais dirigée vers quelqu'un."}], "questions": [{"q": "Cite les 5 classes de feux.", "r": "A solides, B liquides, C gaz, D métaux, F huiles de cuisson."}, {"q": "Pourquoi jamais d'eau sur une friteuse en feu ?", "r": "L'eau se vaporise d'un coup et projette l'huile en feu."}, {"q": "Feu sur un appareil électrique : premier réflexe ?", "r": "Couper le courant."}, {"q": "Comment agit l'eau ?", "r": "Par refroidissement."}, {"q": "Comment fabrique-t-on de la mousse ?", "r": "Eau + émulseur = solution moussante ; + air = mousse."}, {"q": "Quel est le défaut de la poudre ?", "r": "Elle refroidit peu : le feu peut repartir."}, {"q": "Feu de gaz : que fait-on d'abord ?", "r": "On coupe le gaz ; on n'éteint pas la flamme si la fuite continue."}, {"q": "Sur quel côté du triangle agit l'étouffement ?", "r": "Le comburant (l'oxygène)."}, {"q": "Pourquoi fait-on le déblai ?", "r": "Pour disperser et refroidir ce qui peut repartir."}, {"q": "Que veut dire « faire la part du feu » ?", "r": "Protéger ce qui peut être sauvé, en acceptant de perdre ce qui brûle déjà."}], "quiz": [{"q": "Un feu de classe F, c'est…", "bonne": "Un feu d'huile de cuisson", "fausses": ["Un feu de forêt", "Un feu électrique", "Un feu de métal"], "expl": "Friteuse, poêle d'huile."}, {"q": "Un feu de classe A, c'est…", "bonne": "Un feu de solides", "fausses": ["Un feu de liquides", "Un feu de gaz", "Un feu de métaux"], "expl": "Bois, papier, tissus : ils font des braises."}, {"q": "La friteuse s'enflamme :", "bonne": "Je coupe la plaque et je couvre", "fausses": ["J'arrose avec de l'eau", "Je souffle dessus", "Je la porte dehors"], "expl": "Jamais d'eau : boule de feu."}, {"q": "L'eau éteint surtout par…", "bonne": "Refroidissement", "fausses": ["Inhibition", "Soufflage", "Coupure d'alimentation"], "expl": ""}, {"q": "La poudre ABC éteint par…", "bonne": "Inhibition (elle casse la réaction)", "fausses": ["Refroidissement", "Soufflage", "Dispersion"], "expl": "Elle refroidit peu : surveiller la reprise."}, {"q": "Quel agent pour un ordinateur en feu, courant coupé ?", "bonne": "Le CO2", "fausses": ["L'eau en jet droit", "Le sable mouillé", "La mousse"], "expl": ""}, {"q": "Une fuite de gaz enflammée : on…", "bonne": "Coupe d'abord le gaz", "fausses": ["Éteint la flamme tout de suite", "Souffle dessus", "Met de l'eau sur le robinet"], "expl": "Sinon le gaz s'accumule et peut exploser."}, {"q": "Le déblai sert à…", "bonne": "Disperser et refroidir ce qui peut repartir", "fausses": ["Ranger les tuyaux", "Sauver les victimes", "Couper l'électricité"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les classes de feux et les agents extincteurs » et « Les procédés d'extinction » (JSP2, charte SDIS 34) · RNF JSP/JMP v1.1 fiches INC C4 et C5 ; RDMI SDIS 34 v6 (eau dopée, mousse)"}, "JSP3|Les phases de développement du feu": {"cycle": "JSP3", "bloc": "Eteindre un incendie", "item": "Les phases de développement du feu", "objectif": "Remettre dans l'ordre les phases de développement d'un feu dans une pièce et relier chaque situation (porte ouverte, fumées qui descendent, feu qui manque d'air) au bon danger, sans erreur, en 10 min.", "pointsCles": ["Un feu dans une pièce passe par : éclosion, croissance, embrasement généralisé éclair, feu pleinement développé, décroissance", "Assez d'air : le feu grandit, chauffe la pièce et peut tout embraser d'un coup ; pas assez d'air : il couve et remplit la pièce de gaz chauds", "Stratification : fumées chaudes en haut, air plus frais en bas, séparés par le plan neutre ; plus il descend, plus c'est grave", "Trop d'eau mal placée casse les couches : vapeur et fumées redescendent sur le binôme", "Une porte ouverte donne de l'air au feu (air frais en bas, fumées en haut) ; la fermer le ralentit ; le vent pousse feu et fumées vers nous", "Lire les fumées : quantité, vitesse (saccades = pression), épaisseur (épaisses et noires = brûleront facilement), couleur (jaunâtres qui « respirent » = manque d'air)", "La fumée est un combustible : embrasement généralisé éclair (la chaleur fait tout brûler), explosion de fumées (entrée d'air brutale), FGI (fumées accumulées ailleurs qui s'enflamment)", "Se protéger : rester bas, refroidir les fumées par courtes impulsions vers le plafond, ne pas ouvrir sans ordre, se tenir sur le côté de la porte, lance toujours prête", "Interdit de reproduire les démonstrations (boîte à feu, fumées) : brûlures, intoxication, incendie"], "materiel": "Tablette avec vidéos et photos de feux en volume (signes d'embrasement, fumées qui sortent par saccades), cartes des phases, schéma de la courbe du feu, ruban ou corde pour matérialiser le plan neutre, porte du centre pour l'exercice d'ouverture (sans feu), LDV 40 à sec, caméra thermique ; boîte à feu uniquement si un formateur qualifié la met en œuvre dehors, extincteur prêt.", "activites": [{"titre": "La courbe du feu", "duree": "10 min", "prep": "Cartes mélangées : éclosion, croissance, embrasement généralisé éclair, feu pleinement développé, décroissance ; cartes « ce qu'on voit ».", "deroule": ["Les binômes remettent les phases dans l'ordre sur une courbe dessinée au sol.", "Ils placent les cartes « ce qu'on voit » (un seul objet brûle, fumées au plafond, toute la pièce en flammes…).", "Question : que se passe-t-il si la pièce manque d'air ? (le feu couve, gaz chauds, danger à l'ouverture)."], "phrase": "Assez d'air, il grandit ; pas assez, il couve et attend.", "securite": ""}, {"titre": "Le plan neutre vivant", "duree": "10 min", "prep": "Une corde tenue à hauteur variable par deux animateurs = limite des fumées.", "deroule": ["Les JSP se déplacent sous la corde : debout, accroupis, à quatre pattes selon la hauteur.", "L'animateur baisse la corde : « La pièce chauffe dangereusement : on fait quoi ? » (prévenir le chef, refroidir, se replier).", "Variante : « trop d'eau » → la corde tombe d'un coup sur les JSP."], "phrase": "Le chaud en haut : on reste bas.", "securite": "Sol dégagé, pas de course."}, {"titre": "Quel phénomène ?", "duree": "10 min", "prep": "Photos / vidéos et situations lues.", "deroule": ["Pour chaque situation, les binômes nomment le phénomène (embrasement éclair, explosion de fumées, FGI) et l'action qui protège.", "Ex. : « vitres noires et grasses, fumées jaunâtres par saccades » → explosion de fumées : on n'ouvre pas sans ordre."], "phrase": "La fumée, c'est du combustible.", "securite": ""}, {"titre": "Ouvrir une porte en sécurité", "duree": "15 min", "prep": "Porte du centre, LDV 40 (à sec), caméra thermique ; aucun feu.", "deroule": ["Le binôme se place sur le côté, accroupi, jamais face à la porte.", "Il teste la chaleur (caméra ou geste simulé de l'eau sur le haut de la porte).", "Lance prête, il ouvre un peu, simule de courtes impulsions vers le plafond, referme et observe.", "Il entre bas et referme derrière lui si possible."], "phrase": "Tant qu'elle est fermée, la porte retient le feu.", "securite": "Exercice sans feu ; boîte à feu réservée au formateur, dehors, extincteur prêt ; interdit de reproduire chez soi."}], "questions": [{"q": "Cite les phases de développement d'un feu dans une pièce.", "r": "Éclosion, croissance, embrasement généralisé éclair, feu pleinement développé, décroissance."}, {"q": "Que fait un feu qui manque d'air ?", "r": "Il couve et remplit la pièce de gaz chauds."}, {"q": "Où se trouvent les fumées chaudes dans une pièce ?", "r": "En haut : on se tient en bas."}, {"q": "Qu'est-ce que le plan neutre ?", "r": "La limite entre les fumées et l'air ; plus il descend, plus c'est grave."}, {"q": "Pourquoi la fumée peut-elle s'enflammer ?", "r": "C'est un combustible chaud."}, {"q": "Feu sans air + porte qu'on ouvre = ?", "r": "Risque d'explosion de fumées."}, {"q": "Petites flammes qui courent au plafond : signe de quoi ?", "r": "Embrasement généralisé éclair proche."}, {"q": "Où peut se produire un FGI ?", "r": "Dans une pièce voisine, un faux plafond, une gaine."}, {"q": "Comment refroidir les fumées ?", "r": "Jet diffusé, courtes impulsions vers le plafond."}], "quiz": [{"q": "La première phase d'un feu est…", "bonne": "L'éclosion", "fausses": ["La décroissance", "L'embrasement généralisé", "Le déblai"], "expl": ""}, {"q": "Dans une pièce en feu, les fumées chaudes sont…", "bonne": "En haut", "fausses": ["En bas", "Au milieu", "Partout pareil"], "expl": "On reste bas."}, {"q": "Le plan neutre descend vite : c'est…", "bonne": "Un signe d'alerte", "fausses": ["Bon signe", "Sans importance", "La fin du feu"], "expl": "La pièce chauffe dangereusement."}, {"q": "Ouvrir une porte sur un feu…", "bonne": "Lui donne de l'air", "fausses": ["L'éteint", "Ne change rien", "Refroidit la pièce"], "expl": "Toute ouverture se décide avec la lance prête et l'accord du chef."}, {"q": "Vitres noires et grasses, fumées jaunâtres par saccades : risque de…", "bonne": "Explosion de fumées", "fausses": ["Feu de cheminée", "Fuite d'eau", "Feu de classe D"], "expl": "On n'ouvre pas sans ordre."}, {"q": "Le FGI se produit souvent…", "bonne": "Loin du foyer (faux plafond, pièce voisine)", "fausses": ["Uniquement dehors", "Dans l'engin", "Au début du feu, sur l'objet qui brûle"], "expl": ""}, {"q": "Pour refroidir les fumées, on utilise…", "bonne": "Le jet diffusé par courtes impulsions", "fausses": ["Le jet droit en continu sur le sol", "Un extincteur à poudre", "Le soufflage"], "expl": ""}, {"q": "Les démonstrations de la boîte à feu…", "bonne": "Sont réservées aux formateurs", "fausses": ["Peuvent se refaire chez soi", "Se font entre copains", "Sont sans danger"], "expl": "Brûlures, intoxication, incendie."}], "statut": "brouillon", "source": "Cours 2026 « Les phénomènes thermiques et les techniques d'intervention » (JSP4, partie « Le feu en volume », charte SDIS 34) · RDEB SDIS 34 v2 §2.23-2.24 ; RDMI SDIS 34 v6 §1.1 et §6.6 ; doctrine nationale (GDO incendies de structures, GTO établissements et techniques d'extinction) – cours JSP4 utilisé pour un item JSP3, à valider"}, "JSP3|Les sauvetages au moyen du LSPCC": {"cycle": "JSP3", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "Les sauvetages au moyen du LSPCC", "objectif": "Équiper un mannequin inconscient avec le triangle d'évacuation (connecteur automatique sur les attaches de poitrine) puis, en binôme, le descendre d'une fenêtre basse après vérification et test du dispositif, sous double assurance, sans erreur de sécurité.", "pointsCles": ["Rappels JSP2 : ancrage solide (un doute, on en change), connecteur automatique toujours entre la corde et la victime, le régulateur ne lâche jamais le garant, la commande est toujours emportée", "Ordres : « Laissez filer ! », « Du mou ! », « Sec ! », « Protégez / Sécurisez le dispositif ! », « À bras – Ferme ! », « Contact ! », « Victime en sécurité ! »", "Rôles : le chef d'équipe vérifie la faisabilité, choisit 1 ou 2 ancrages, installe l'amarrage ; le régulateur freine la descente ; le chef d'agrès contrôle ; dispositif vérifié et testé à deux", "4 techniques : sauvetage par l'extérieur, abordage d'une victime au harnais, sauvetage en excavation (puits, fosse), reconnaissance d'appartement ; ancrage douteux, corde trop courte ou victime trop blessée = équipe spécialisée (SMPM)", "Rassurer la victime : se présenter, expliquer simplement, ne jamais la laisser seule, être bienveillant", "Triangle sur victime consciente : bras dans les bretelles, bas sous les aisselles, attaches de poitrine reliées par le connecteur automatique, bretelles serrées ; inconsciente : sur le côté, puis sur le dos, puis fermer", "Passage au vide d'une victime inconsciente : sur le ventre, pieds vers la fenêtre, un sauveteur de chaque côté (bretelles et genoux), on la lève ensemble sans lâcher le garant", "Syndrome du harnais : rester suspendu sans bouger peut entraîner perte de connaissance puis arrêt cardiaque : faire vite, parler à la victime, la confier aux secours", "Excavation : mesurer l'air (ARI si besoin), protéger la corde au bord, remonter en rythme à « À bras – Ferme ! »", "Entraînement JSP : toujours un mannequin (aucun JSP suspendu), 3 m maximum, double assurance, EPI complets (casque jugulaire serrée, gants), contrôle par un formateur avant chaque mise au vide"], "materiel": "LSPCC du FPTGP (lot « engin ») ou lot de formation contrôlé : corde, descendeur, sangles, connecteurs automatiques, triangle d'évacuation, harnais, commande, cordelettes ; mannequin de sauvetage, 2e corde pour la double assurance, tapis de sol, EPI complets ; fenêtre du 1er étage du centre ou tour de manœuvre à hauteur limitée ; fosse ou dénivelé simulé.", "activites": [{"titre": "Le triangle d'évacuation", "duree": "10 min", "prep": "Triangles réglés, mannequin au sol.", "deroule": ["Équiper un JSP conscient (au sol) : bras dans les bretelles, connecteur automatique sur les attaches de poitrine, serrage.", "Équiper le mannequin « inconscient » : sur le côté, sur le dos, fermer.", "Un observateur vérifie avec la check-list."], "phrase": "Connecteur automatique entre la corde et la victime.", "securite": "Victime suspendue = mannequin uniquement."}, {"titre": "Rassurer une victime qui a peur", "duree": "5 min", "prep": "Un JSP joue la victime au sol, assis près d'une fenêtre fictive.", "deroule": ["Le sauveteur se présente, demande le prénom, explique chaque étape.", "La « victime » refuse d'abord : il faut la convaincre calmement.", "Débrief : quels mots ont rassuré ?"], "phrase": "Une personne rassurée bouge moins et aide les sauveteurs.", "securite": "Jeu de rôle au sol uniquement."}, {"titre": "Descente du mannequin par la fenêtre", "duree": "20 min", "prep": "Fenêtre basse (3 m maximum), ancrage choisi, double assurance tenue par un formateur.", "deroule": ["Le binôme prend le LSPCC et la commande ; le chef d'équipe choisit l'ancrage et installe l'amarrage.", "Corde attachée au triangle du mannequin, commande envoyée dehors.", "Vérification et test à deux, contrôle par le formateur, passage au vide.", "Le régulateur descend le mannequin aux ordres ; en bas, la commande écarte le mannequin du mur ; « Contact ! », « Victime en sécurité ! »."], "phrase": "Ancrage solide, dispositif vérifié et testé à deux, ordres clairs.", "securite": "Mannequin, 3 m maximum, double assurance, contrôle formateur : pas d'exception."}, {"titre": "Le puits « À bras – Ferme ! »", "duree": "10 min", "prep": "Fosse ou dénivelé simulé, mannequin équipé du triangle, cordelettes.", "deroule": ["Le binôme 2 remonte le mannequin aux cordelettes au rythme de l'ordre « À bras – Ferme ! ».", "On montre la protection de la corde sur le bord."], "phrase": "On tire tous ensemble, au rythme.", "securite": "Bord de fosse balisé, personne au fond, gants obligatoires."}], "questions": [{"q": "Où place-t-on le connecteur automatique ?", "r": "Entre la corde et la victime, sur les attaches de poitrine du triangle."}, {"q": "Que fait le régulateur ?", "r": "Il tient le garant et freine la descente : il ne le lâche jamais."}, {"q": "Qui choisit le point d'ancrage ?", "r": "Le chef d'équipe."}, {"q": "Que fait-on avant chaque descente ?", "r": "On vérifie et on teste tout le dispositif, à deux."}, {"q": "Victime inconsciente : première étape pour le triangle ?", "r": "La tourner sur le côté et poser le triangle sur son dos."}, {"q": "Comment rassurer une victime ?", "r": "Se présenter, expliquer simplement, rester avec elle, être bienveillant."}, {"q": "Qu'est-ce que le syndrome du harnais ?", "r": "Le danger de rester suspendu sans bouger : malaise, arrêt cardiaque."}, {"q": "Que dit-on pour tirer ensemble ?", "r": "« À bras – Ferme ! »"}, {"q": "Au fond d'un puits, quel danger en plus ?", "r": "L'air peut être dangereux : on mesure, ARI si besoin."}, {"q": "À l'entraînement, qui joue la victime suspendue ?", "r": "Toujours un mannequin."}], "quiz": [{"q": "Le connecteur automatique se place…", "bonne": "Entre la corde et la victime", "fausses": ["Sur le casque", "Dans le sac", "Au point d'ancrage seulement"], "expl": "Pour éviter une ouverture au passage au vide."}, {"q": "Le régulateur…", "bonne": "Ne lâche jamais le garant", "fausses": ["Tient la victime dans ses bras", "Choisit l'ancrage", "Descend avec la victime"], "expl": ""}, {"q": "Un ancrage paraît douteux :", "bonne": "On en choisit un autre", "fausses": ["On l'utilise quand même", "On le teste avec la victime", "On double la vitesse"], "expl": ""}, {"q": "Victime inconsciente : pour mettre le triangle, on commence par…", "bonne": "La tourner sur le côté", "fausses": ["La faire asseoir", "La passer au vide", "Lui mettre un casque"], "expl": ""}, {"q": "Le syndrome du harnais peut provoquer…", "bonne": "Une perte de connaissance puis un arrêt cardiaque", "fausses": ["Une simple fatigue", "Un coup de soleil", "Rien de grave"], "expl": "Il faut faire vite."}, {"q": "L'ordre pour tirer tous ensemble :", "bonne": "« À bras – Ferme ! »", "fausses": ["« Laissez filer ! »", "« Du mou ! »", "« Établissez ! »"], "expl": ""}, {"q": "À l'entraînement JSP, hauteur maximale :", "bonne": "Environ 3 m", "fausses": ["10 m", "Le 3e étage", "Aucune limite"], "expl": "Avec double assurance et mannequin."}, {"q": "Avant d'entrer dans un appartement par l'extérieur, le sauveteur…", "bonne": "Crie plusieurs fois « Sapeurs-pompiers ! »", "fausses": ["Entre sans bruit", "Casse toutes les vitres", "Attend que quelqu'un ouvre"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les sauvetages avec le LSPCC » (charte SDIS 34) · RDLSPCC SDIS 34 v1 (novembre 2025) ch.2 (2.1, 2.5, 2.7-2.12) et ch.3 (3.1, 3.3, 3.5-3.7) ; FAT FPTGP"}, "JSP4|Sauvetage, mise en sécurité, confinement, évacuation": {"cycle": "JSP4", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "Sauvetage, mise en sécurité, confinement, évacuation", "objectif": "Face à 4 situations, choisir entre sauvetage (à vue ou en exploration), évacuation et confinement, et réaliser sur mannequin un dégagement d'urgence et un porter — 15 min, aucune erreur de sécurité admise.", "pointsCles": ["Sauvetage (RDSMES § 1.1) : extraire une personne en danger vital et imminent qui ne peut pas s'en sortir seule ; il peut justifier plus de risques, c'est le chef qui décide", "Sauvetage à vue (victime visible de l'extérieur : échelles, MEA, LSPCC) ou en exploration (il faut entrer : eau + ligne de vie)", "Mise en sécurité (RDSMES § 1.2) : éloigner du danger des personnes non menacées immédiatement, par évacuation (on les déplace en les accompagnant) ou confinement (on les laisse à l'abri)", "On peut agir sur la source (couper le gaz, éteindre), le flux (désenfumer, ventiler, lance entre le feu et les gens) ou la cible (sauver, évacuer, confiner)", "Moyens : escaliers en priorité ; échelle à coulisse 2 plans → 2e étage, 3 plans → 4e ; MEA 18 m → 6e, 24 m → 8e, 30 m → 10e ; échelle à crochets et LSPCC quand les échelles ne passent pas", "Confinement : porte fermée, linge mouillé dessous, se montrer à la fenêtre, ni escalier enfumé ni ascenseur, les pompiers viennent vous chercher", "Dégagement d'urgence (PSE 03FT01) : seulement si danger réel, immédiat, impossible à supprimer, victime visible et accessible ; par les chevilles, les poignets ou les vêtements, dans l'axe du corps", "Porter sans matériel : accompagnement, à dos, dans les bras, porter pompier, en chaise à deux ; dos droit, jambes fléchies", "Victime consciente sur échelle : le sauveteur juste dessous, on anticipe la peur au passage au vide ; « regarde l'échelle, pas le vide »", "Rassurer : se présenter, expliquer chaque étape, garder le contact, ne jamais se moquer de la peur"], "materiel": "Mannequin, plots et rubalise pour une zone « en feu », plan de bâtiment dessiné, cartes situation, échelle à coulisse 2 plans dressée à faible hauteur (premiers barreaux), tapis de sol, EPI (casque, gants).", "activites": [{"titre": "Sauver, évacuer ou confiner ?", "duree": "10 min", "prep": "Cartes situation (escalier enfumé et logement intact, personne à la fenêtre au-dessus du feu, maison de retraite, appartement voisin d'un feu de cave…).", "deroule": ["Chaque binôme tire une carte.", "Il choisit : sauvetage (à vue / en exploration), évacuation ou confinement.", "Il dit quel moyen utiliser selon l'étage et ce qu'il dit aux occupants."], "phrase": "Sortir n'est pas toujours le plus sûr.", "securite": ""}, {"titre": "Dégagement d'urgence", "duree": "10 min", "prep": "Zone « en feu » matérialisée, mannequin au sol, sol propre et dégagé.", "deroule": ["Le binôme vérifie les 3 conditions (danger réel et immédiat, impossible à supprimer, victime accessible).", "Il tire le mannequin par les chevilles, puis par les poignets, dans l'axe du corps.", "Il l'amène en zone sûre et annonce « victime en sécurité »."], "phrase": "Le plus vite possible, jusqu'à un endroit sûr.", "securite": "Sur mannequin uniquement, sol sans obstacle."}, {"titre": "Les 5 porters", "duree": "15 min", "prep": "JSP de même gabarit, tapis.", "deroule": ["Démonstration de chaque porter (accompagnement, à dos, dans les bras, pompier, chaise à deux).", "Les binômes s'entraînent sur 10 m.", "Le porté décrit ce qu'il a ressenti : le porteur l'a-t-il rassuré ?"], "phrase": "On explique ce qu'on fait avant de le faire.", "securite": "Même gabarit, dos droit, jambes fléchies ; arrêt si douleur."}, {"titre": "L'échelle : accompagner un camarade", "duree": "10 min", "prep": "Échelle à coulisse 2 plans dressée et tenue, un formateur au pied.", "deroule": ["Le « sauveteur » se place juste sous la « victime » consciente.", "Il la guide barreau par barreau en lui parlant.", "On inverse."], "phrase": "Regarde l'échelle, pas le vide.", "securite": "Premiers barreaux seulement (≈ 3 m max), échelle piétée, formateur en parade."}], "questions": [{"q": "Sauvetage à vue ou en exploration : quelle différence ?", "r": "À vue : victime visible de l'extérieur ; exploration : il faut entrer."}, {"q": "Une échelle à coulisse 2 plans permet d'aller jusqu'où ?", "r": "Jusqu'au 2e étage."}, {"q": "Quand fait-on un dégagement d'urgence ?", "r": "Danger réel, immédiat, impossible à supprimer, victime accessible."}, {"q": "Confiner une personne, c'est quoi ?", "r": "La laisser à l'abri où elle est, porte fermée."}, {"q": "Quelle différence entre sauvetage et mise en sécurité ?", "r": "Sauvetage : danger vital et imminent ; mise en sécurité : personnes pas menacées immédiatement."}, {"q": "Cite 3 façons de porter une victime sans matériel.", "r": "Accompagnement, à dos, dans les bras, porter pompier, en chaise."}, {"q": "Que dit-on à une personne confinée ?", "r": "Porte fermée, linge mouillé dessous, se montrer à la fenêtre, ni escalier enfumé ni ascenseur."}, {"q": "Par où évacue-t-on en priorité ?", "r": "Par les escaliers et couloirs existants s'ils sont praticables."}], "quiz": [{"q": "Personne en danger vital, incapable de fuir seule :", "bonne": "Sauvetage", "fausses": ["Confinement", "Rien, on attend", "Simple information"], "expl": ""}, {"q": "Escalier enfumé, logement intact :", "bonne": "Confinement", "fausses": ["Évacuation par l'escalier", "Évacuation par l'ascenseur", "Sauter par la fenêtre"], "expl": ""}, {"q": "Échelle à coulisse 3 plans :", "bonne": "Jusqu'au 4e étage", "fausses": ["Jusqu'au 1er étage", "Jusqu'au 8e étage", "Jusqu'au 10e étage"], "expl": ""}, {"q": "Grande échelle de 30 m :", "bonne": "Jusqu'au 10e étage", "fausses": ["Jusqu'au 3e étage", "Jusqu'au 6e étage", "Jusqu'au 20e étage"], "expl": ""}, {"q": "Dégagement d'urgence : on tire la victime…", "bonne": "Dans l'axe du corps", "fausses": ["En la tordant", "Par la tête seulement", "En la soulevant par un bras"], "expl": ""}, {"q": "Désenfumer pour protéger les occupants, c'est agir sur…", "bonne": "Le flux", "fausses": ["La source", "La cible", "Rien"], "expl": "Source, flux, cible."}, {"q": "Une personne a peur du vide sur l'échelle :", "bonne": "On la rassure, on ne force pas brutalement", "fausses": ["On se moque gentiment", "On la pousse", "On la laisse seule"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Sauvetages et mises en sécurité – choisir la bonne technique » (charte SDIS 34) · RNF INC B1 · RDSMES v2 (avril 2026) § 1-4 · RDLSPCC v1 (novembre 2025) · PSE 03FT01 — consignes de confinement : consignes générales, à valider avec le formateur"}, "JSP4|Evolution sur une échelle aérienne": {"cycle": "JSP4", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "Evolution sur une échelle aérienne", "objectif": "Au sol (échelle d'exercice ou MEA non déployé), monter et descendre 3-4 échelons en gardant 3 points d'appui, se maintenir avec la longe de maintien et réaliser un croisement selon le RDSMES — 15 min, aucune erreur de sécurité admise.", "pointsCles": ["MEA 18 m → 6e étage, 24 m → 8e, 30 m → 10e ; il sert aux sauvetages, à l'attaque et peut servir d'itinéraire de secours", "Trois façons de sauver au MEA (RDSMES § 3.5) : isolé (dans le panier), multiples (les personnes valides descendent par l'échelle), par transfert (dépose à un étage plus bas ou un lieu sûr proche)", "Placement : sol solide, pas de bordure de trottoir ni plaque d'égout, pas de câbles électriques, balcons gênants, vent fort, foudre ou brouillard ; panier au plus près et face à la fenêtre", "Équipement des opérateurs MEA (RDLSPCC) : harnais, longe de maintien (1 m) pour se maintenir sur la structure ou dans le panier", "On ne monte que quand le chef d'agrès et le conducteur l'autorisent : aucun mouvement du MEA avec quelqu'un sur la structure (sauf urgence par l'échelier)", "Croisement (RDSMES) : celui qui monte s'arrête, se décale sur le côté en tenant un échelon, dos et pied contre la main courante, pour laisser passer", "Victime consciente : on anticipe sa peur au passage au vide, on l'accompagne ; victime inconsciente : garde-corps du panier au ras de la façade, l'opérateur reçoit la victime dans le panier", "Monter : toujours 3 points d'appui, regard vers le haut, gestes réguliers ; pour travailler, on se maintient avec la longe"], "materiel": "Échelle d'exercice posée à plat ou dressée sur les premiers échelons, ou MEA de visite non déployé à l'arrêt ; harnais et longe de maintien, photos de MEA et de sauvetages (tablette), parade par un encadrant.", "activites": [{"titre": "Isolé, multiples ou transfert ?", "duree": "10 min", "prep": "Photos ou dessins de façades avec victimes.", "deroule": ["Les binômes choisissent la technique de sauvetage au MEA.", "Ils disent où placer le panier et quels obstacles éviter.", "Correction avec les règles du RDSMES."], "phrase": "Le panier au plus près, face à la fenêtre.", "securite": ""}, {"titre": "Monter en sécurité", "duree": "15 min", "prep": "Échelle d'exercice sur les premiers échelons, parade par un encadrant, harnais.", "deroule": ["Démonstration : 3 points d'appui, regard en haut, gestes réguliers.", "Chaque JSP monte 3-4 échelons, se maintient avec la longe de maintien, redescend.", "Correction par le binôme puis l'encadrant."], "phrase": "Trois points d'appui, toujours.", "securite": "3-4 échelons maximum (≈ 3 m), harnais, parade, jamais sur un MEA déployé."}, {"titre": "Le croisement", "duree": "15 min", "prep": "Échelle d'exercice inclinée à faible hauteur, deux JSP.", "deroule": ["Un JSP descend, l'autre monte.", "Celui qui monte s'arrête, se décale en tenant un échelon, dos et pied contre la main courante.", "Celui qui descend passe ; on inverse."], "phrase": "Celui qui monte s'arrête et se décale.", "securite": "Faible hauteur, encadrant au pied, pas de précipitation."}], "questions": [{"q": "Quelles sont les 3 techniques de sauvetage au MEA ?", "r": "Isolé, multiples, par transfert."}, {"q": "Lors d'un croisement, qui s'arrête ?", "r": "Celui qui monte : il se décale sur le côté."}, {"q": "Le MEA peut-il bouger avec quelqu'un dessus ?", "r": "Non, sauf manœuvre d'urgence par l'échelier."}, {"q": "À quoi sert la longe de maintien ?", "r": "À se maintenir sur la structure ou dans le panier."}, {"q": "Cite 3 obstacles à vérifier avant de placer le MEA.", "r": "Balcons, câbles électriques, vent, foudre, brouillard."}, {"q": "Où place-t-on le panier pour une victime ?", "r": "Au plus près et face à la fenêtre."}, {"q": "Jusqu'où va un MEA de 18 m ?", "r": "Environ le 6e étage."}], "quiz": [{"q": "Au croisement sur l'échelle, celui qui monte…", "bonne": "S'arrête et se décale", "fausses": ["Accélère", "Redescend jusqu'en bas", "Saute un échelon"], "expl": ""}, {"q": "Des personnes valides descendent par l'échelle elle-même :", "bonne": "Sauvetage « multiples »", "fausses": ["Sauvetage « isolé »", "Par transfert", "Confinement"], "expl": ""}, {"q": "Pour se maintenir sur la structure, on utilise…", "bonne": "La longe de maintien", "fausses": ["Une main seulement", "Le tuyau", "Rien"], "expl": ""}, {"q": "En montant, on garde toujours…", "bonne": "3 points d'appui", "fausses": ["1 point d'appui", "Les deux mains dans les poches", "Le regard vers le sol"], "expl": ""}, {"q": "Le MEA est interdit sur…", "bonne": "Une plaque d'égout", "fausses": ["Une chaussée solide", "Un parking goudronné", "Une route"], "expl": ""}, {"q": "Victime inconsciente au MEA : le garde-corps du panier est placé…", "bonne": "Au ras de la façade", "fausses": ["Loin de la façade", "Sous la fenêtre à 5 m", "Au sol"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Sauvetages et mises en sécurité – choisir la bonne technique » (charte SDIS 34), partie MEA · RDSMES v2 (avril 2026) § 3.5-3.6, 4.2 · RDLSPCC v1 (EPI MEA, longe de maintien) · RDMI v6 § 6.18 — technique de progression sur l'échelle (3 points d'appui) : à valider avec le formateur"}, "JSP4|Sauvetage du sauveteur": {"cycle": "JSP4", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "Sauvetage du sauveteur", "objectif": "En jeu de rôle, faire le point rapide et passer un message « URGENT » complet (je suis, je vois, je fais, je demande), puis à deux, extraire un mannequin équipé par la poignée de l'ARI sur 10 m — 15 min, aucune erreur de sécurité admise.", "pointsCles": ["Sauvegarde opérationnelle (RDSMES § 1.3) : ne pas se mettre en danger, s'en sortir si ça tourne mal, se faire retrouver vite ; elle regroupe l'auto-sauvetage et le sauvetage de sauveteur", "Anticiper : chemin de repli libre, chemin de secours (échelle prête), binôme de sécurité équipé, parc matériel, contrôleur ; règle des minimums (personnes, temps, risque)", "Façades A, B, C, D : A = entrée principale (ou choisie par le premier chef), puis B, C, D dans le sens des aiguilles d'une montre", "« ÉVACUATION, ÉVACUATION, ÉVACUATION » : donné par n'importe quel intervenant, on sort tout de suite et on rejoint le point de regroupement où l'on compte les binômes", "Imprévu : faire le point (blessés ? air ? reliés ? perdus ? radio ?), message « URGENT ×3 » (je suis, je vois, je fais, je demande), S-P-A (Signalement, Positionnement, Air), attendre ou sortir", "Trois messages sans réponse → appel de détresse : bouton de la radio 3 secondes, « SOS » sur tous les postes ; jamais déclenché pour jouer", "Sauver un équipier : binôme dédié, en pleine forme, ≥ 270 bars, avec ses outils ; sa mission est exclusive (pas d'attaque en même temps) ; on demande des renforts", "Abordage : danger ? conscience et respiration ? bouteille ouverte (appui bref) ? compte rendu, air et extraction (serrer les bretelles, détacher de la ligne s'il est inconscient) ; d'abord ma sécurité", "Extraction par la poignée de l'ARI, à un ou deux, au ras du sol ; la SIM aide à mieux tenir et à monter un escalier ; dehors, déshabillage en ≈ 30 s pour commencer les soins", "Toxicité des fumées : elles entrent par la respiration, la bouche, la peau, les yeux ; nettoyage « je sais, je sens, je vois », lingettes, douche ; suie dans le nez ou malaise = pas de réengagement"], "materiel": "Mannequin lesté équipé d'un ARI réformé si disponible, SIM, radios éteintes ou canal d'exercice validé, sifflet, plan d'un bâtiment avec façades A-B-C-D, tenues pour le classement « je sais / je sens / je vois », lingettes, sol lisse.", "activites": [{"titre": "Le point rapide + « URGENT »", "duree": "10 min", "prep": "Cartes situation (équipier qui ne répond plus, sortie bloquée, perdu dans une pièce…), radios éteintes.", "deroule": ["Le binôme tire une carte : 30 s pour faire le point à voix haute.", "Il passe le message « URGENT, URGENT, URGENT » : je suis (façade, étage), je vois, je fais, je demande.", "Le groupe vérifie qu'il n'a rien oublié."], "phrase": "Rester calme : quand on panique, on vide sa bouteille.", "securite": "Radios éteintes : jamais de vraie détresse sur le réseau."}, {"titre": "Façades A-B-C-D", "duree": "5 min", "prep": "Plan d'un bâtiment, ou la caserne vue de la cour.", "deroule": ["Tu désignes la façade A.", "Les JSP nomment B, C, D dans le sens des aiguilles d'une montre.", "Chacun annonce sa position : « façade C, 1er étage »."], "phrase": "", "securite": ""}, {"titre": "La traction", "duree": "20 min", "prep": "Mannequin équipé, SIM, sol lisse, zone « fumée » balisée.", "deroule": ["Abordage : le binôme vérifie sa sécurité, conscience, respiration, bouteille.", "Il serre les bretelles et tire le mannequin par la poignée de l'ARI, à un puis à deux.", "Variante avec la SIM ; dehors, on simule le déshabillage (casque et masque ensemble, veste ouverte)."], "phrase": "Un sauveteur blessé ne sauve personne.", "securite": "Mannequin uniquement, JSP sans ARI (ou avec sur décision du formateur), dos droit."}, {"titre": "Je sais, je sens, je vois", "duree": "5 min", "prep": "Photos ou tenues plus ou moins « sales ».", "deroule": ["Les JSP classent chaque tenue dans le bon niveau de souillure.", "Ils disent ce qu'on fait : aérer, brosser, ou sac et tenue propre.", "Rappel : douche au retour à la caserne."], "phrase": "", "securite": ""}], "questions": [{"q": "La façade A, c'est laquelle ?", "r": "L'entrée principale (ou celle choisie par le premier chef)."}, {"q": "Le signal d'évacuation, c'est quoi ?", "r": "« ÉVACUATION » trois fois, et on sort tout de suite."}, {"q": "Par où les fumées entrent-elles dans le corps ?", "r": "Respiration, bouche, peau, yeux."}, {"q": "Suie dans le nez au mouchage : je repars ?", "r": "Non, on ne repart pas."}, {"q": "Quand déclenche-t-on l'appel de détresse ?", "r": "Après 3 messages de détresse sans réponse."}, {"q": "Le binôme qui va sauver un pompier fait-il aussi l'attaque ?", "r": "Non : sa mission est exclusive."}, {"q": "Que veut dire S-P-A ?", "r": "Signalement, Positionnement, Air."}, {"q": "Que contient un message « URGENT » ?", "r": "Je suis, je vois, je fais, je demande."}], "quiz": [{"q": "La façade A est…", "bonne": "L'entrée principale", "fausses": ["La façade arrière", "La plus haute", "Celle du côté du vent"], "expl": "Puis B, C, D dans le sens des aiguilles d'une montre."}, {"q": "Qui peut donner le signal « ÉVACUATION » ×3 ?", "bonne": "N'importe quel intervenant", "fausses": ["Seulement le COS", "Seulement le CODIS", "Seulement le conducteur"], "expl": ""}, {"q": "Message de détresse sans réponse 3 fois :", "bonne": "Appel de détresse (bouton de la radio)", "fausses": ["J'attends sans rien faire", "J'enlève mon masque", "Je me sépare de mon binôme"], "expl": ""}, {"q": "Le binôme qui va chercher un pompier en difficulté…", "bonne": "Ne fait que ça", "fausses": ["Attaque le feu en même temps", "Fait aussi la reconnaissance", "Part seul"], "expl": ""}, {"q": "Pour tirer un équipier équipé au sol, on utilise…", "bonne": "La poignée de sauvetage de l'ARI", "fausses": ["Son casque", "Son tuyau", "Ses bottes"], "expl": ""}, {"q": "Tenue avec des traces visibles après un long feu :", "bonne": "« Je vois » : sac et tenue propre", "fausses": ["« Je sais » : on l'aère", "Aucune souillure", "On la lave à la maison"], "expl": ""}, {"q": "Arrivé près de l'équipier, je vérifie d'abord…", "bonne": "Ma propre sécurité", "fausses": ["Son téléphone", "L'heure", "Sa tenue est-elle propre"], "expl": ""}, {"q": "Que veut dire le « A » de S-P-A ?", "bonne": "Air", "fausses": ["Alerte", "Attaque", "Ascenseur"], "expl": "Signalement, Positionnement, Air."}], "statut": "brouillon", "source": "Cours 2026 « La sauvegarde opérationnelle – se protéger, sauver un équipier » (charte SDIS 34) · RNF INC B2 · RDSMES v2 (avril 2026) § 1.3, 2.3-2.5, 4, 5, 6 · RDEB v2 (avril 2026) § 3.14-3.16, ch. 4"}, "JSP4|Matériel de calage temporaire et de protection des biens": {"cycle": "JSP4", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Matériel de calage temporaire et de protection des biens", "objectif": "En équipe, au sol, regrouper, caler et bâcher un « salon » puis bâcher une table inclinée avec deux bâches dans le bon ordre, sans que l'eau ne passe dessous au test d'arrosage — 20 min.", "pointsCles": ["On protège les biens lors de tempêtes, inondations, fuites, pendant et après un incendie, chute d'arbre, porte forcée", "Pendant un feu (sauvegarde) : regrouper les meubles au centre, surélever sur des cales, couvrir d'une bâche bien bordée, mettre à l'abri papiers et photos avec le propriétaire, évacuer l'eau", "On protège, on ne répare pas : mise hors d'eau d'urgence ; l'artisan répare, l'assurance indemnise, la mairie peut reloger ; avis de passage si personne n'est là", "Bienveillance : rassurer les sinistrés, expliquer, les faire participer, respecter leurs affaires et leur intimité", "Lot bâchage et protection du VSRTU : 4 bâches de 3 m × 4 m, clous de 100 mm, marteau de charpentier, fil de fer, tenaille ; une bâche 3 × 4 m aussi dans le FPTGP et le CCGC", "Autres lots du VSRTU : assèchement (aspirateur, 2 raclettes), épuisement électrique, éclairage, tronçonnage (réservé aux formés), jeu de cales (pour surélever, caler, stabiliser), balisage", "Bâcher un toit : la bâche passe par-dessus le faîtage, on pose du bas vers le haut (celle du haut recouvre celle du bas), bien tendue, bords enroulés sur une latte, sans trouer au milieu", "Étapes : reconnaître (charpente, électricité, vent), sécuriser (protection contre les chutes), préparer au sol, poser depuis le faîtage, fixer et vérifier", "Dangers : chute (toujours attaché), vent (une bâche de 12 m² peut emporter quelqu'un), électricité, chute d'objets (balisage au sol)", "Les JSP ne montent jamais sur un vrai toit : ils s'entraînent au sol"], "materiel": "Lot bâchage du VSRTU (bâches 3 × 4 m, clous, marteau, fil de fer, tenaille), jeu de cales du VSRTU, lattes de bois, chaises, cartons et coussins (le « salon »), table ou panneau incliné à 30°, arrosoir ou lance à faible débit, raclettes, rubalise et cônes, gants et casques.", "activites": [{"titre": "L'inventaire du VSRTU", "duree": "10 min", "prep": "Fiche inventaire du lot bâchage et du jeu de cales.", "deroule": ["Par binôme, retrouver chaque objet du lot dans le VSRTU.", "Dire à quoi il sert.", "Signaler ce qui manque ou est abîmé."], "phrase": "", "securite": "Engin à l'arrêt, clés retirées ; on sort le matériel, on ne monte pas sur l'engin sans autorisation."}, {"titre": "Sauve le salon", "duree": "15 min", "prep": "Chaises, cartons, coussins dispersés dans une pièce, jeu de cales, une bâche.", "deroule": ["Au chrono, l'équipe regroupe les « meubles » au centre, loin des murs et fenêtres.", "Elle les surélève sur des cales et les couvre jusqu'en bas sans que la bâche traîne au sol.", "Un « propriétaire » (animateur) choisit ce qu'on met à l'abri en premier."], "phrase": "Ce qu'on sauve, la famille n'aura pas à le racheter.", "securite": "Porter à deux les charges lourdes, dos droit."}, {"titre": "Le petit toit", "duree": "15 min", "prep": "Table ou panneau incliné à 30°, deux bâches, lattes, fil de fer, arrosoir.", "deroule": ["L'équipe pose la bâche du bas, puis celle du haut qui la recouvre.", "Elle tend et fixe les bords sur une latte (fil de fer), sans percer au milieu.", "Test à l'arrosoir : l'eau ne doit pas passer dessous."], "phrase": "L'eau doit glisser par-dessus.", "securite": "Au sol uniquement, gants et casque, marteau manié par l'animateur ou sous son contrôle."}], "questions": [{"q": "Les pompiers réparent-ils le toit ?", "r": "Non : ils mettent hors d'eau en urgence, l'artisan répare."}, {"q": "Combien de bâches dans le lot du VSRTU ?", "r": "4 bâches de 3 m × 4 m."}, {"q": "Pendant un feu, que fait-on des meubles ?", "r": "Regrouper, surélever, couvrir."}, {"q": "Par où commence la bâche sur un toit ?", "r": "De l'autre côté du faîtage, pour que l'eau glisse par-dessus."}, {"q": "Deux bâches : laquelle par-dessus ?", "r": "Celle du haut recouvre celle du bas."}, {"q": "Personne absente : que laisse-t-on ?", "r": "Un avis de passage."}, {"q": "À quoi sert le jeu de cales ?", "r": "À surélever, caler, stabiliser."}, {"q": "Pourquoi le vent est-il dangereux pendant un bâchage ?", "r": "Une grande bâche peut emporter quelqu'un : on travaille à plusieurs, bâche roulée."}], "quiz": [{"q": "Les bâches du lot VSRTU mesurent…", "bonne": "3 m × 4 m", "fausses": ["1 m × 1 m", "10 m × 10 m", "50 cm × 2 m"], "expl": ""}, {"q": "Pendant un feu, les meubles sont…", "bonne": "Regroupés, surélevés, couverts", "fausses": ["Jetés par la fenêtre", "Laissés contre les murs", "Arrosés pour les protéger"], "expl": ""}, {"q": "Sur un toit, deux bâches :", "bonne": "Celle du haut recouvre celle du bas", "fausses": ["Celle du bas recouvre celle du haut", "Côte à côte sans se toucher", "Une seule suffit toujours"], "expl": "Comme des tuiles."}, {"q": "Le toit est arraché, qui le répare ?", "bonne": "Un artisan", "fausses": ["Les pompiers", "Les JSP", "Le CODIS"], "expl": "Les pompiers mettent hors d'eau en urgence."}, {"q": "Le propriétaire est absent après notre passage :", "bonne": "On laisse un avis de passage", "fausses": ["On laisse la porte ouverte", "On emporte ses objets précieux", "On ne fait rien"], "expl": ""}, {"q": "Un JSP peut-il monter sur un toit pour bâcher ?", "bonne": "Non, entraînement au sol uniquement", "fausses": ["Oui, s'il fait beau", "Oui, avec des baskets", "Oui, s'il est seul"], "expl": ""}, {"q": "Pour fixer la bâche, on…", "bonne": "Enroule les bords sur une latte", "fausses": ["La perce au milieu", "La laisse libre au vent", "La colle au scotch"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La protection des biens – bâches et lots de protection » (charte SDIS 34) · RNF PPBE A1 · FAT VSRTU (04/2026), FAT FPTGP / CCGC · RDLSPCC v1 § 3.8 · RDEB v2 § 5.8 — le cours ne détaille pas le calage temporaire (étaiement) ; techniques de bâchage : pratique générale, à valider avec le formateur"}, "JSP1|L'engagement citoyen": {"cycle": "JSP1", "bloc": "S'impliquer dans son activité", "item": "L'engagement citoyen", "objectif": "Expliquer avec ses mots la différence entre citoyenneté et engagement, et classer par âge au moins 5 façons de s'engager (cadets, JSP, SPV, service civique, réserve).", "pointsCles": ["Citoyenneté : faire partie d'un pays, avec des droits et des devoirs (respecter la loi, voter à 18 ans, participer à la vie de tous)", "Engagement : choisir librement de donner de son temps et de son énergie pour les autres ou pour une cause", "Valeurs de l'engagement : altruisme, solidarité, responsabilité, respect, courage, fierté", "Chez les pompiers : cadets de la sécurité civile (au collège), JSP dès 13 ans dans notre section (4 ans jusqu'au brevet)", "Sapeur-pompier volontaire : dès 16 ans avec l'accord des parents (SDIS 34 : de 16 à 55 ans, engagement de 5 ans renouvelable)", "Ailleurs : service civique (16-25 ans, quelques mois, indemnisé), réserve opérationnelle (à partir de 17 ans), réserve citoyenne, bénévolat", "Les JSP dans la société : gestes qui sauvent, prévention auprès de la famille et des copains, cérémonies en tenue", "Le brevet de JSP valide une grande partie de la formation de SPV et facilite l'accès au métier de sapeur-pompier professionnel"], "materiel": "Cartes « dispositifs » (cadets, JSP, SPV, service civique, réserve opérationnelle, réserve citoyenne, bénévolat), feuilles et crayons, témoin : un ancien JSP devenu SPV (prévu à l'avance), diaporama « L'engagement citoyen ».", "activites": [{"titre": "Pourquoi je suis JSP ?", "duree": "10 min", "prep": "Tableau ou ardoises.", "deroule": ["Chacun donne sa raison d'être JSP.", "L'animateur regroupe : aider, devenir pompier, sport, copains…", "Message : en venant chaque dimanche, tu as déjà choisi de t'engager."], "phrase": "Être JSP, c'est déjà s'engager.", "securite": ""}, {"titre": "Classe-les", "duree": "10 min", "prep": "Cartes dispositifs.", "deroule": ["Par équipe, classer les cartes du plus jeune au plus vieux.", "Correction : cadets (collège) → JSP (13 ans) → SPV (16 ans) → service civique (16-25 ans) → réserve opérationnelle (17 ans).", "Pour chaque carte : qu'est-ce qu'on y fait ?"], "phrase": "", "securite": ""}, {"titre": "Raconte", "duree": "15 min", "prep": "Un ancien JSP du centre devenu SPV.", "deroule": ["Il raconte son parcours de JSP à SPV.", "Les JSP posent leurs questions préparées."], "phrase": "", "securite": ""}, {"titre": "Mon projet", "duree": "10 min", "prep": "Feuilles, enveloppe.", "deroule": ["Chacun écrit ce qu'il aimerait faire plus tard grâce à son engagement.", "Les feuilles sont gardées et relues en JSP4."], "phrase": "", "securite": ""}], "questions": [{"q": "C'est quoi la citoyenneté ?", "r": "Faire partie d'un pays avec des droits et des devoirs."}, {"q": "Un engagement, c'est obligatoire ?", "r": "Non, c'est un choix libre."}, {"q": "Cite 3 valeurs de l'engagement.", "r": "Altruisme, solidarité, responsabilité (respect, courage, fierté)."}, {"q": "À quel âge peut-on devenir sapeur-pompier volontaire ?", "r": "Dès 16 ans, avec l'accord des parents."}, {"q": "Le service civique, c'est pour qui ?", "r": "Les jeunes de 16 à 25 ans."}, {"q": "À quoi sert le brevet de JSP ?", "r": "À valider une grande partie de la formation de SPV."}, {"q": "Cite une action des JSP dans la société.", "r": "Gestes qui sauvent, prévention, cérémonies…"}], "quiz": [{"q": "S'engager, c'est :", "bonne": "Choisir librement d'aider les autres", "fausses": ["Être obligé par ses parents", "Signer un contrat de travail", "Gagner de l'argent"], "expl": ""}, {"q": "On peut devenir SPV dès :", "bonne": "16 ans, avec l'accord des parents", "fausses": ["10 ans", "13 ans", "25 ans seulement"], "expl": ""}, {"q": "Dans notre section, on devient JSP à partir de :", "bonne": "13 ans", "fausses": ["8 ans", "16 ans", "18 ans"], "expl": ""}, {"q": "Le service civique concerne les jeunes de :", "bonne": "16 à 25 ans", "fausses": ["6 à 10 ans", "30 à 40 ans", "Plus de 60 ans"], "expl": ""}, {"q": "Le brevet de JSP permet :", "bonne": "De valider une grande partie de la formation de SPV", "fausses": ["De conduire un camion", "De devenir officier directement", "De ne plus aller au collège"], "expl": ""}, {"q": "La citoyenneté, c'est :", "bonne": "Des droits et des devoirs", "fausses": ["Seulement des droits", "Seulement des devoirs", "Habiter en ville"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « L'engagement citoyen » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche SC A4 · SDIS 34, journée d'intégration SPV 2026 · conditions d'âge des dispositifs (service-public.fr, service-civique.gouv.fr) à revérifier chaque année"}, "JSP1|Valeurs et éthiques des sapeurs-pompiers, la charte du JSP": {"cycle": "JSP1", "bloc": "S'impliquer dans son activité", "item": "Valeurs et éthiques des sapeurs-pompiers, la charte du JSP", "objectif": "Citer les 4 valeurs et les 3 règles d'éthique des JSP et choisir, sur une situation concrète de la section, la conduite qui les respecte.", "pointsCles": ["4 valeurs des JSP : honnêteté, solidarité, respect de l'autre, respect des règles", "Honnêteté : dire la vérité, reconnaître ses erreurs, ne pas tricher", "Solidarité : s'entraider, personne ne reste seul en difficulté · respect de l'autre : camarades, animateurs, public", "3 règles d'éthique : altruisme (aider sans rien attendre), efficience (bien faire sans gaspiller), discrétion (ce qu'on voit chez les pompiers reste chez les pompiers)", "Sur Internet : jamais de photo d'un camarade sans son accord, de moquerie, de photo d'accident ou de victime, ni parler au nom de la section", "Le collectif : diversité et mixité sont une force, bienveillance, les anciens aident les nouveaux", "Règlement de la section : le dimanche de 9 h à 12 h, absence excusée par les parents, tenue complète, ni bijoux ni maquillage, cheveux attachés, ni tabac ni alcool", "Galons : JSP1 blanc, JSP2 jaune, JSP3 orange, JSP4 vert, puis le brevet national de JSP"], "materiel": "Règlement intérieur de la section (affiché dans l'appli Carnet JSP), cartes valeurs, cartes « Que ferais-tu ? », galons de poitrine, diaporama « Les valeurs et l'éthique des JSP ».", "activites": [{"titre": "Qu'attend-on de toi ?", "duree": "10 min", "prep": "Tableau, 4 colonnes au nom des valeurs.", "deroule": ["Chacun donne une idée (être à l'heure, aider, ne pas tricher…).", "On range chaque idée sous une des 4 valeurs.", "Chacun cite un exemple vécu en séance, au sport ou en manœuvre."], "phrase": "", "securite": ""}, {"titre": "Que ferais-tu ?", "duree": "20 min", "prep": "4 cartes cas : moquerie d'un nouveau, raccord cassé que personne n'a vu, vidéo d'un camarade qui tombe, autre équipe en difficulté.", "deroule": ["Petits groupes : 5 minutes de discussion par cas.", "Chaque groupe présente sa réponse et la valeur en jeu.", "Pas de mauvaise réponse sanctionnée : on cherche ensemble la conduite juste."], "phrase": "", "securite": ""}, {"titre": "Le règlement de la section", "duree": "15 min", "prep": "Règlement intérieur (appli Carnet JSP).", "deroule": ["Lecture commentée des points clés : horaires, absences, tenue, bijoux, tabac et alcool, manifestations.", "Quiz express : « Je suis absent, qui prévient ? » « Ma tenue au collège ? »"], "phrase": "", "securite": ""}], "questions": [{"q": "Cite les 4 valeurs des JSP.", "r": "Honnêteté, solidarité, respect de l'autre, respect des règles."}, {"q": "C'est quoi l'altruisme ?", "r": "Penser aux autres, aider sans rien attendre en retour."}, {"q": "C'est quoi l'efficience ?", "r": "Bien faire sans gaspiller son temps, son énergie, le matériel."}, {"q": "La discrétion, c'est ?", "r": "Ne pas raconter ni diffuser ce qu'on voit chez les pompiers."}, {"q": "Peux-tu publier la photo d'un camarade ?", "r": "Pas sans son accord, et jamais pour se moquer."}, {"q": "Je porte ma tenue de JSP au collège ?", "r": "Non, seulement aux activités de la section."}, {"q": "Je suis absent dimanche : qui prévient ?", "r": "Mes parents."}, {"q": "Quel galon en JSP1 ?", "r": "Le galon blanc."}], "quiz": [{"q": "Les valeurs des JSP :", "bonne": "Honnêteté, solidarité, respect de l'autre, respect des règles", "fausses": ["Force, vitesse, compétition, victoire", "Silence, obéissance, solitude, rigueur", "Célébrité, réussite, argent, pouvoir"], "expl": ""}, {"q": "Les 3 règles d'éthique :", "bonne": "Altruisme, efficience, discrétion", "fausses": ["Rapidité, force, audace", "Célébrité, humour, ruse", "Compétition, indépendance, vitesse"], "expl": ""}, {"q": "J'ai cassé un raccord, personne n'a vu :", "bonne": "Je le dis à l'animateur", "fausses": ["Je le cache", "J'accuse un autre", "Je le remets en place sans rien dire"], "expl": ""}, {"q": "Un JSP veut poster une vidéo d'un camarade qui tombe :", "bonne": "Je lui dis que c'est interdit", "fausses": ["Je partage", "Je like", "Je filme aussi"], "expl": ""}, {"q": "Galon du JSP1 :", "bonne": "Blanc", "fausses": ["Vert", "Orange", "Rouge"], "expl": ""}, {"q": "Mon absence le dimanche est excusée par :", "bonne": "Mes parents", "fausses": ["Mon meilleur ami", "Personne", "Moi-même par SMS à un copain"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les valeurs et l'éthique des JSP » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche SC A1 · règlement intérieur de la section JSP Cruzy-Quarante (1er janvier 2025)"}, "JSP1|L'information préventive aux comportements qui sauvent": {"cycle": "JSP1", "bloc": "Diffuser la culture du service public", "item": "L'information préventive aux comportements qui sauvent", "objectif": "Choisir le bon comportement selon le signal entendu (alarme incendie : j'évacue ; sirène : je me mets à l'abri) et réussir un exercice d'évacuation du centre jusqu'au point de rassemblement.", "pointsCles": ["Danger à l'intérieur (incendie) : j'évacue · danger dehors (nuage toxique, tempête, intrusion) : je me mets à l'abri, portes et fenêtres fermées", "Évacuer : j'arrête tout, je laisse mes affaires, je suis les panneaux verts, jamais l'ascenseur", "Fumée : je me baisse ; je ferme les portes derrière moi ; au point de rassemblement, je ne retourne jamais à l'intérieur", "Bloqué par la fumée : je reste dans une pièce, je ferme la porte, je bouche le bas avec un linge mouillé, je me montre à la fenêtre et j'appelle le 18 (ou le 112)", "Autoprotection : j'observe, je ne m'expose pas, je m'éloigne, j'écoute les consignes", "Signal national d'alerte : son qui monte et descend (3 × 1 min 41 s) → abri + radio ; fin d'alerte : son continu de 30 s ; essai le 1er mercredi du mois à midi · FR-Alert sur les téléphones", "Feu à la maison : tout le monde dehors, je ferme la porte de la pièce en feu, j'appelle le 18 une fois dehors ; le détecteur de fumée réveille, on vérifie qu'il marche", "Numéros : 18, 15, 17, 112, 114 (SMS) · les ASSEC sont des élèves formés pour aider pendant les exercices au collège"], "materiel": "Enregistrement officiel du signal national d'alerte et sonnerie d'alarme incendie, téléphones factices, détecteur de fumée (bouton test), serviettes, plan d'évacuation du centre, diaporama « Les comportements qui sauvent ».", "activites": [{"titre": "Quel signal ?", "duree": "10 min", "prep": "Enregistrements : sirène SNA, alarme incendie.", "deroule": ["On écoute un son.", "Les JSP se placent côté « J'évacue » ou côté « Je m'abrite ».", "On explique pourquoi (danger dedans ou dehors)."], "phrase": "Danger dedans : j'évacue. Danger dehors : je m'abrite.", "securite": ""}, {"titre": "Exercice d'évacuation", "duree": "15 min", "prep": "Plan d'évacuation du centre, point de rassemblement repéré ; chef de centre prévenu.", "deroule": ["Au signal, les JSP arrêtent tout et laissent leurs affaires.", "Ils suivent le balisage vert jusqu'au point de rassemblement.", "Appel nominatif ; débrief : temps, portes fermées, personne n'est revenu en arrière."], "phrase": "Je ne retourne jamais à l'intérieur.", "securite": "Pas de vraie fumée ; marcher sans courir ; prévenir le chef de centre avant l'exercice."}, {"titre": "Bloqué dans la chambre", "duree": "10 min", "prep": "Salle figurant une chambre, serviettes, téléphone factice.", "deroule": ["Scénario : fumée dans l'escalier.", "Le JSP ferme la porte, bouche le bas avec une serviette, se montre à la fenêtre.", "Il passe l'alerte (l'animateur joue l'opérateur)."], "phrase": "", "securite": "Jamais de vrai appel ; ne pas se pencher à une fenêtre ouverte en étage."}, {"titre": "Le bon appel", "duree": "10 min", "prep": "Téléphones factices.", "deroule": ["En binôme : l'un appelle le 18, l'autre joue l'opérateur.", "Message : qui je suis, numéro, où, ce qui se passe, nombre de victimes.", "Défi restitution : préparer une affiche des bons réflexes pour sa classe ou sa famille."], "phrase": "", "securite": "Jamais composer un vrai numéro d'urgence."}], "questions": [{"q": "L'alarme incendie sonne au collège : que fais-tu ?", "r": "J'évacue calmement par le chemin prévu jusqu'au point de rassemblement."}, {"q": "Sirène qui monte et descend ?", "r": "Je me mets à l'abri et j'écoute la radio."}, {"q": "Pourquoi se baisser dans la fumée ?", "r": "L'air est plus respirable près du sol."}, {"q": "Pourquoi fermer les portes ?", "r": "Une porte fermée ralentit le feu et la fumée."}, {"q": "De la fumée dans l'escalier ?", "r": "Je reste dans une pièce fermée, je bouche le bas, je me montre et j'appelle le 18."}, {"q": "Je retourne chercher mon sac ?", "r": "Jamais."}, {"q": "Quand teste-t-on la sirène ?", "r": "Le 1er mercredi de chaque mois à midi."}, {"q": "Un ASSEC, c'est quoi ?", "r": "Un élève formé pour aider pendant les exercices et les alertes au collège."}], "quiz": [{"q": "Incendie dans le bâtiment :", "bonne": "J'évacue", "fausses": ["Je me cache sous la table", "Je prends l'ascenseur", "Je retourne chercher mes affaires"], "expl": ""}, {"q": "Nuage toxique dehors :", "bonne": "Je me mets à l'abri, fenêtres fermées", "fausses": ["Je sors voir", "J'ouvre les fenêtres", "Je pars à vélo"], "expl": ""}, {"q": "Pendant l'évacuation, l'ascenseur :", "bonne": "Jamais", "fausses": ["Toujours", "Seulement s'il est libre", "Seulement au 1er étage"], "expl": ""}, {"q": "Fin d'alerte de la sirène :", "bonne": "Son continu de 30 secondes", "fausses": ["3 sons courts", "Un message à la télévision seulement", "Une cloche"], "expl": ""}, {"q": "Feu à la maison, j'appelle le 18…", "bonne": "Une fois dehors, en sécurité", "fausses": ["Avant de sortir, en restant dans la pièce en feu", "Le lendemain", "Jamais"], "expl": ""}, {"q": "Le détecteur de fumée sert à :", "bonne": "Réveiller quand il y a de la fumée", "fausses": ["Éteindre le feu", "Appeler les pompiers tout seul", "Chauffer la maison"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les comportements qui sauvent » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche SC B1 (IPCS) · scénario pédagogique ASSEC de l'IPCS · consignes générales Géorisques / ministère de l'Intérieur"}, "JSP1|Protocole et cérémonie": {"cycle": "JSP1", "bloc": "Diffuser la culture du service public", "item": "Protocole et cérémonie", "objectif": "Tenir le garde-à-vous et le repos, exécuter les commandements de base (à vos rangs, alignement, en avant marche, halte) et citer les grandes dates de cérémonie avec leur origine.", "pointsCles": ["Grandes dates : 8 mai (victoire de 1945), 14 juillet (fête nationale), 11 novembre (armistice de 1918, hommage aux morts pour la France), 4 décembre (Sainte-Barbe, patronne des sapeurs-pompiers)", "Pourquoi : se souvenir, représenter tous les pompiers, être ensemble, récompenser (grades, médailles)", "Déroulement : mise en place, arrivée des autorités (garde-à-vous), revue des troupes, temps forts, fin et défilé", "Temps forts : honneur au drapeau, dépôt de gerbe, minute de silence, Marseillaise : on reste au garde-à-vous", "Garde-à-vous : talons joints, pointes écartées, jambes tendues, bras le long du corps, mains ouvertes doigts serrés, tête droite, immobile", "Repos : pied gauche écarté (largeur d'épaules), mains dans le dos, silencieux, à sa place", "Commandements : « À vos rangs ! », « Alignement ! » puis « Fixe ! », « En avant… marche ! » (départ pied gauche), « Halte ! »", "Comportement : tenue impeccable, pas de téléphone ni chewing-gum ni mains dans les poches, silence, immobile, aligné, fier ; un malaise se signale discrètement"], "materiel": "Cour du centre, tenues de JSP complètes, gerbe d'entraînement, enregistrement de la Marseillaise et de la sonnerie aux morts, calendrier des cérémonies de la section, diaporama « Les protocoles et cérémonies ».", "activites": [{"titre": "Les dates", "duree": "10 min", "prep": "Cartes dates (8 mai, 14 juillet, 11 novembre, 4 décembre) et cartes événements.", "deroule": ["Les JSP associent chaque date à son origine.", "On repère la prochaine cérémonie de la section."], "phrase": "", "securite": ""}, {"titre": "Les positions", "duree": "15 min", "prep": "Cour, JSP en ligne, en tenue.", "deroule": ["Garde-à-vous, repos, alignement, fixe : répéter jusqu'à être parfaitement ensemble.", "Un JSP joue « l'autorité » et passe la revue : personne ne bouge."], "phrase": "Immobile, aligné, fier.", "securite": "Hydratation ; un JSP qui se sent mal le signale et s'assoit."}, {"titre": "Marcher au pas", "duree": "10 min", "prep": "Cour dégagée, petite colonne.", "deroule": ["« En avant… marche ! » départ pied gauche.", "« Halte ! » en deux temps, talons joints.", "Variante : demi-tour."], "phrase": "", "securite": "Terrain plat et dégagé."}, {"titre": "Le dépôt de gerbe", "duree": "10 min", "prep": "Gerbe d'entraînement, monument figuré.", "deroule": ["Deux JSP portent la gerbe à hauteur de poitrine et marchent au pas.", "Ils la déposent, font un pas en arrière, marquent un temps d'arrêt au garde-à-vous, puis reviennent.", "Pendant ce temps les autres écoutent la sonnerie aux morts au garde-à-vous."], "phrase": "", "securite": ""}], "questions": [{"q": "Que fête-t-on le 11 novembre ?", "r": "L'armistice de 1918 et l'hommage à tous les morts pour la France."}, {"q": "Qui est sainte Barbe ?", "r": "La patronne des sapeurs-pompiers, fêtée le 4 décembre."}, {"q": "Pourquoi les pompiers participent aux cérémonies ?", "r": "Se souvenir, représenter les pompiers, être ensemble, récompenser."}, {"q": "Au garde-à-vous, mes mains ?", "r": "Le long du corps, ouvertes, doigts serrés."}, {"q": "Au repos ?", "r": "Pied gauche écarté, mains dans le dos, silencieux."}, {"q": "Je pars au pas avec quel pied ?", "r": "Le pied gauche."}, {"q": "Pendant la Marseillaise ?", "r": "Je reste au garde-à-vous, immobile."}, {"q": "Mon téléphone pendant la cérémonie ?", "r": "Rangé, jamais sorti."}], "quiz": [{"q": "Le 11 novembre, on commémore :", "bonne": "L'armistice de 1918", "fausses": ["La prise de la Bastille", "La victoire de 1945", "La Sainte-Barbe"], "expl": ""}, {"q": "Sainte-Barbe est fêtée le :", "bonne": "4 décembre", "fausses": ["14 juillet", "8 mai", "1er janvier"], "expl": ""}, {"q": "On part au pas du pied :", "bonne": "Gauche", "fausses": ["Droit", "Les deux pieds joints", "Au choix"], "expl": ""}, {"q": "Pendant la Marseillaise :", "bonne": "Garde-à-vous, immobile", "fausses": ["On chante en bougeant", "On se met au repos", "On applaudit"], "expl": ""}, {"q": "Au repos, mes mains sont :", "bonne": "Dans le dos", "fausses": ["Dans les poches", "Sur la tête", "Croisées devant"], "expl": ""}, {"q": "Le 8 mai rappelle :", "bonne": "La victoire de 1945", "fausses": ["L'armistice de 1918", "La fête nationale", "La fête des pompiers"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les protocoles et cérémonies » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche SC A5 · règlement de la section (§ VII) · usages du cérémonial et de l'ordre serré décrits de façon générale (pas de référentiel SDIS 34) – à valider"}, "JSP1|Le réseau associatif, son rôle et ses valeurs": {"cycle": "JSP1", "bloc": "Diffuser la culture du service public", "item": "Le réseau associatif, son rôle et ses valeurs", "objectif": "Distinguer le SDIS (service public) des associations et placer dans l'ordre les niveaux du réseau associatif, de l'amicale du centre jusqu'à la FNSPF, en citant les 4 valeurs du réseau.", "pointsCles": ["Le SDIS est un service public : il organise les secours, forme et équipe les pompiers", "Les associations (loi 1901) rassemblent les pompiers et leurs familles : entraide, sport, fêtes ; la section JSP est elle-même une association", "Le réseau : amicales et sections de JSP (au centre) → unions départementales (UDSP, l'Hérault) → unions régionales (Occitanie) → Fédération nationale (FNSPF)", "Amicale : fêtes, sorties, entraide · UDSP : congrès, sport, formation, social · FNSPF : représente tous les pompiers auprès de l'État", "L'Œuvre des pupilles (ODP) aide les orphelins et les familles de sapeurs-pompiers (100 ans en 2026)", "La FNSPF : créée en 1881, environ 285 000 adhérents, 7 000 amicales, 97 unions départementales, 14 unions régionales (chiffres 2024, à revérifier)", "4 valeurs du réseau : lien social, cohésion, solidarité, représentativité", "Les JSP participent : cérémonies, cross et rassemblements, congrès départemental, loto, bal du 13 juillet, portes ouvertes"], "materiel": "Cartes ou étiquettes des niveaux (amicale du CIS, association départementale des JSP de l'Hérault, UDSP 34, union régionale, FNSPF, ODP) – noms exacts à compléter par le chef de section, agenda de l'année, diaporama « Le réseau associatif des sapeurs-pompiers ».", "activites": [{"titre": "SDIS ou association ?", "duree": "10 min", "prep": "Cartes actions (loto, intervention, bal du 13 juillet, achat des camions, cross, aide à un orphelin…).", "deroule": ["Les JSP classent chaque carte : SDIS ou association ?", "Correction et explication : service public / associations."], "phrase": "", "securite": ""}, {"titre": "Complète la pyramide", "duree": "15 min", "prep": "Pyramide dessinée au sol ou au tableau, étiquettes.", "deroule": ["Par équipe, placer chaque association du centre jusqu'à la fédération.", "Pour chaque niveau, dire ce qu'il fait.", "Ajouter l'ODP et son rôle."], "phrase": "", "securite": ""}, {"titre": "L'agenda et l'idée solidaire", "duree": "15 min", "prep": "Calendrier de la section, feuilles.", "deroule": ["Lister les manifestations de l'année où la section sera présente.", "Chaque équipe imagine une action des JSP pour aider ou rassembler (à valider par le chef de section).", "Associer l'action à une valeur : lien social, cohésion, solidarité, représentativité."], "phrase": "", "securite": ""}], "questions": [{"q": "Le SDIS est-il une association ?", "r": "Non, c'est un service public."}, {"q": "Que veut dire FNSPF ?", "r": "Fédération nationale des sapeurs-pompiers de France."}, {"q": "L'UDSP, c'est quel niveau ?", "r": "Le département."}, {"q": "Qui organise les fêtes du centre ?", "r": "L'amicale."}, {"q": "À quoi sert l'Œuvre des pupilles ?", "r": "À aider les orphelins et les familles de pompiers."}, {"q": "Cite deux valeurs du réseau.", "r": "Lien social, cohésion, solidarité, représentativité."}, {"q": "Cite une manifestation où les JSP participent.", "r": "Cérémonies, cross, congrès départemental, loto, bal du 13 juillet…"}], "quiz": [{"q": "Le SDIS est :", "bonne": "Un service public", "fausses": ["Une association", "Une entreprise privée", "Un club de sport"], "expl": ""}, {"q": "L'association des pompiers au niveau du département :", "bonne": "L'UDSP", "fausses": ["La FNSPF", "L'amicale", "Le CTA"], "expl": ""}, {"q": "FNSPF : le N veut dire…", "bonne": "Nationale", "fausses": ["Nouvelle", "Normale", "Navale"], "expl": ""}, {"q": "L'ODP aide :", "bonne": "Les orphelins et familles de pompiers", "fausses": ["Les animaux perdus", "Les touristes", "Les élus"], "expl": ""}, {"q": "Le bal du 13 juillet est organisé par :", "bonne": "L'amicale", "fausses": ["Le préfet", "Le SAMU", "La gendarmerie"], "expl": ""}, {"q": "Une valeur du réseau associatif :", "bonne": "La solidarité", "fausses": ["La compétition", "La richesse", "La solitude"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Le réseau associatif des sapeurs-pompiers » (charte SDIS 34) · RNF JSP/JMP v1.1, fiches SC A2 et SC A3 · FNSPF, rapport d'activité 2024 (pompiers.fr) · règlement de la section (§ II et VII)"}, "JSP1|La combustion et les modes de propagation": {"cycle": "JSP1", "bloc": "Eteindre un incendie", "item": "La combustion et les modes de propagation", "objectif": "Citer les 3 éléments du triangle du feu et les 4 modes de propagation, puis reconnaître sur des exemples quel côté du triangle est supprimé et par quel mode le feu voyage.", "pointsCles": ["Combustion : réaction chimique entre un combustible et un comburant (l'oxygène de l'air), déclenchée par une énergie d'activation ; elle dégage chaleur, lumière et fumées toxiques", "Triangle du feu : combustible + comburant + énergie d'activation · pas de triangle, pas de feu", "L'air : 78 % d'azote, 21 % d'oxygène · plus d'air = plus de feu", "Éteindre = casser le triangle : enlever le combustible (couper le gaz), le comburant (couvercle), l'énergie (refroidir à l'eau, action principale des pompiers)", "Jamais d'eau sur de l'huile en feu : on coupe la plaque et on couvre la poêle", "Ce n'est pas le bois qui brûle, ce sont les gaz qu'il dégage en chauffant (gaz de pyrolyse)", "4 modes de propagation : conduction (à travers la matière), convection (gaz chauds et fumées qui montent), rayonnement (à distance, comme le soleil), déplacement de matières enflammées (braises, gouttes, liquide qui coule)", "Limiter la propagation : fermer les portes, refroidir, débroussailler, surveiller autour du feu"], "materiel": "Corde pour le triangle vivant, bougies, bocal en verre, verre d'eau, pince, briquet long, spirale de papier, cuillères métal et bois, bol d'eau chaude, beurre, plateau métallique, extincteur à eau, diaporamas « La combustion » et « Les modes de propagation du feu ».", "activites": [{"titre": "Le triangle vivant", "duree": "10 min", "prep": "Corde nouée en triangle, 3 étiquettes (combustible, comburant, énergie).", "deroule": ["3 JSP tiennent les sommets, chacun est un élément.", "L'animateur cite une action (couvercle, lance, couper le gaz, débroussailler).", "Le JSP concerné lâche la corde : le feu « s'éteint »."], "phrase": "Pas de triangle, pas de feu.", "securite": ""}, {"titre": "Casser le triangle (démonstration)", "duree": "15 min", "prep": "Bougies, bocal, eau, pince, plateau métallique, extincteur à côté.", "deroule": ["Avant chaque expérience, les JSP devinent ce qui va se passer.", "Bocal sur la bougie (sans comburant), eau sur la mèche (sans énergie), mèche pincée (sans combustible).", "Un JSP réexplique avec ses mots."], "phrase": "", "securite": "Expériences faites par l'animateur uniquement, sur plateau, extincteur à côté, cheveux attachés, JSP à distance."}, {"titre": "Comment le feu voyage", "duree": "15 min", "prep": "Cuillères métal et bois dans l'eau chaude avec du beurre, spirale de papier au-dessus d'une bougie, cartes situations.", "deroule": ["Démonstrations : cuillères (conduction), spirale qui tourne (convection), main approchée sur le côté sans toucher (rayonnement).", "En binôme : cartes situations (poutre en métal, fumée à l'étage, maison d'en face, braises emportées par le vent).", "Pour chaque carte : quel mode et comment le bloquer ?"], "phrase": "", "securite": "On ne touche jamais la flamme ; démonstrations menées par l'animateur."}], "questions": [{"q": "Qu'est-ce que la combustion ?", "r": "Une réaction chimique qui dégage de la chaleur entre un combustible et un comburant, déclenchée par une énergie d'activation."}, {"q": "Les 3 éléments du triangle du feu ?", "r": "Combustible, comburant, énergie d'activation."}, {"q": "Le comburant le plus courant ?", "r": "L'oxygène de l'air (21 %)."}, {"q": "Qu'est-ce qui brûle vraiment dans un feu de bois ?", "r": "Les gaz de pyrolyse dégagés par le bois chauffé."}, {"q": "Pourquoi jamais d'eau sur l'huile en feu ?", "r": "Risque de boule de feu : on coupe la plaque et on couvre."}, {"q": "Cite les 4 modes de propagation.", "r": "Conduction, convection, rayonnement, déplacement de matières enflammées."}, {"q": "Pourquoi ferme-t-on les portes derrière soi ?", "r": "Pour bloquer les fumées et gaz chauds (convection)."}, {"q": "Qu'est-ce qu'une saute de feu ?", "r": "Des braises emportées par le vent qui allument un feu plus loin."}], "quiz": [{"q": "Les 3 éléments du triangle du feu :", "bonne": "Combustible, comburant, énergie d'activation", "fausses": ["Eau, terre, air", "Bois, papier, carton", "Chaleur, fumée, flamme"], "expl": ""}, {"q": "Je pose un couvercle sur la poêle en feu, j'enlève :", "bonne": "Le comburant", "fausses": ["Le combustible", "L'énergie", "Rien"], "expl": ""}, {"q": "Les pompiers arrosent le feu, ils enlèvent surtout :", "bonne": "L'énergie (ils refroidissent)", "fausses": ["Le comburant", "Le combustible", "L'azote"], "expl": ""}, {"q": "La fumée chaude envahit l'étage du dessus :", "bonne": "Convection", "fausses": ["Conduction", "Rayonnement", "Déplacement de matières"], "expl": ""}, {"q": "La maison d'en face prend feu sans être touchée par les flammes :", "bonne": "Rayonnement", "fausses": ["Conduction", "Convection", "Projection d'eau"], "expl": ""}, {"q": "Le feu passe par une poutre en métal :", "bonne": "Conduction", "fausses": ["Convection", "Rayonnement", "Saute de feu"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La combustion » et « Les modes de propagation du feu » (charte SDIS 34, supports JSP2 utilisés pour cet item JSP1) · RNF JSP/JMP v1.1, fiches INC C1 et C2 · GDO incendies de structure"}, "JSP1|Les phases de la MGO de lutte contre les incendies": {"cycle": "JSP1", "bloc": "Eteindre un incendie", "item": "Les phases de la MGO de lutte contre les incendies", "objectif": "Citer les 11 actions de la marche générale des opérations (MGO) et les retrouver dans le récit d'un feu de cuisine, en repérant celles qui se font en même temps.", "pointsCles": ["MGO = marche générale des opérations : 11 actions qui aident le COS (commandant des opérations de secours) à organiser l'intervention", "Pas d'ordre imposé : plusieurs actions se font en même temps (ex. sauvetage et établissement) ; le cours les présente dans un ordre logique", "Arriver : reconnaissance (où est le feu, y a-t-il des personnes, quels dangers, couper gaz et électricité), placement des engins, sauvetages et mises en sécurité", "Placement : engins en sécurité, l'engin d'attaque dépasse l'adresse pour laisser la place à la grande échelle, près d'un point d'eau", "Sauvetage = danger immédiat pour la vie ; mise en sécurité = mettre à l'abri des personnes qui pourraient être menacées · les sauvetages sont prioritaires", "Éteindre : établissements (tuyaux du point d'eau à la lance, sur ordre du chef d'agrès), attaque (le plus vite possible, avec le moins d'eau possible), ventilation (sortir fumée et chaleur), protection (empêcher le feu de s'étendre, protéger les biens)", "Terminer : déblai (chercher les points chauds), préservation des traces et indices (toucher le moins possible), surveillance (éviter une reprise)", "Remise en condition des intervenants (boire, se reposer, se laver) et reconditionnement des matériels (engin prêt pour le départ suivant)"], "materiel": "11 cartes « actions » de la MGO par équipe, scénario « feu de cuisine » (notes du cours), tableau, FPTGP pour illustrer le placement, diaporama « La marche générale des opérations ».", "activites": [{"titre": "Que font-ils en premier ?", "duree": "10 min", "prep": "Tableau.", "deroule": ["Chaque JSP propose une action des pompiers sur un feu de cuisine au 1er étage.", "On les classe ensemble : avant d'éteindre, on regarde et on sauve.", "On complètera la liste à la fin."], "phrase": "", "securite": ""}, {"titre": "Remets l'intervention dans l'ordre", "duree": "20 min", "prep": "11 cartes par équipe, récit du feu de cuisine (FPT rue de l'église, mamie au 1er étage…).", "deroule": ["L'animateur raconte l'intervention étape par étape.", "Les équipes posent la carte correspondant à chaque étape.", "On repère les cartes qui se font en même temps (sauvetage et établissement)."], "phrase": "Regarder, sauver, éteindre, terminer.", "securite": ""}, {"titre": "Le placement des engins", "duree": "10 min", "prep": "Cour, plots figurant une maison, une borne, des engins.", "deroule": ["Les JSP placent l'engin d'attaque : dépasser l'adresse, en sécurité, près du point d'eau.", "Ils expliquent pourquoi on laisse la place à la grande échelle."], "phrase": "", "securite": "Engins à l'arrêt, aucun déplacement de véhicule ; plots seulement."}], "questions": [{"q": "Que veut dire MGO ?", "r": "Marche générale des opérations."}, {"q": "Combien d'actions dans la MGO ?", "r": "11."}, {"q": "Les actions se font-elles toujours dans le même ordre ?", "r": "Non, il n'y a pas d'ordre imposé, plusieurs se font en même temps."}, {"q": "À quoi sert la reconnaissance ?", "r": "À comprendre la situation et trouver les victimes."}, {"q": "Sauvetage ou mise en sécurité : le plus urgent ?", "r": "Le sauvetage : danger immédiat."}, {"q": "Pourquoi le 1er engin dépasse-t-il l'adresse ?", "r": "Pour laisser la place à la grande échelle."}, {"q": "Pourquoi faire le déblai ?", "r": "Chercher les points chauds pour éviter une reprise."}, {"q": "Pourquoi préserver les traces et indices ?", "r": "Pour aider à trouver la cause du feu."}], "quiz": [{"q": "La MGO compte :", "bonne": "11 actions", "fausses": ["3 actions", "5 actions", "20 actions"], "expl": ""}, {"q": "Les actions de la MGO se font :", "bonne": "Selon la situation, souvent en même temps", "fausses": ["Toujours dans le même ordre", "Une seule à la fois", "Au hasard"], "expl": ""}, {"q": "La personne est en danger immédiat :", "bonne": "Sauvetage", "fausses": ["Mise en sécurité", "Déblai", "Surveillance"], "expl": ""}, {"q": "Chercher les points chauds après l'extinction :", "bonne": "Le déblai", "fausses": ["La ventilation", "La reconnaissance", "Le placement"], "expl": ""}, {"q": "Faire sortir fumée et chaleur :", "bonne": "La ventilation", "fausses": ["La protection", "L'attaque", "Le déblai"], "expl": ""}, {"q": "Le 1er engin dépasse l'adresse pour :", "bonne": "Laisser la place à la grande échelle", "fausses": ["Se garer à l'ombre", "Aller plus vite au centre", "Cacher le camion"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La marche générale des opérations » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC C3 · RDMI v6 (avril 2026) § 1.1, 6.4, 6.15, 6.17 · RDSMES v2 · RDEB v2 § 4"}, "JSP1|La composition et le fonctionnement de l'ARI": {"cycle": "JSP1", "bloc": "Eteindre un incendie", "item": "La composition et le fonctionnement de l'ARI", "objectif": "Expliquer pourquoi les fumées sont dangereuses, nommer sur un ARI réel au moins 6 éléments et décrire le trajet de l'air de la bouteille au masque, sans capelage.", "pointsCles": ["Les fumées sont Chaudes, Opaques, Mobiles, Inflammables, toXiques (COMIX) ; le feu consomme aussi l'oxygène", "La plupart des victimes d'incendie meurent intoxiquées par les fumées (monoxyde de carbone incolore et inodore), pas brûlées", "Deux façons de se protéger : filtrer l'air (appareil filtrant, jamais dans les fumées) ou emporter son air (ARI = appareil respiratoire isolant, seule solution dans les fumées)", "3 appareils : ARI à circuit ouvert (ARI-CO, le plus utilisé au feu), ARI à circuit fermé (longue durée, spécialistes), appareil filtrant (masque + filtre)", "ARI-CO : masque, soupape à la demande, manomètre, harnais, bouteille d'air comprimé (pas d'oxygène pur), robinet, détendeur, cagoule d'évacuation", "Trajet de l'air : bouteille (forte pression, 300 bars) → détendeur (baisse la pression) → soupape (donne l'air quand j'inspire) → masque ; l'air soufflé part dehors", "Le sifflet (avertisseur) sonne quand l'air commence à manquer (55 bars) : le binôme sort immédiatement", "Porter un ARI : jusqu'à 18 kg, on voit et on entend moins bien, durée limitée · règles d'or : toujours en binôme, contrôle croisé, toujours relié (ligne de vie, balise de détresse activée)"], "materiel": "ARI complet de formation, balise de sécurité et de détresse, ligne guide, cagoule d'évacuation, lingettes de désinfection des masques, étiquettes des éléments, chrono, diaporama « La protection respiratoire ».", "activites": [{"titre": "Retiens ta respiration", "duree": "5 min", "prep": "Chrono.", "deroule": ["Assis, chacun retient sa respiration sans forcer.", "On compare : 20 à 60 secondes.", "Message : dans la fumée, il faut emporter son air avec soi."], "phrase": "", "securite": "Assis, sans forcer, on s'arrête dès que c'est désagréable."}, {"titre": "Touche et nomme", "duree": "15 min", "prep": "ARI posé sur une table, étiquettes.", "deroule": ["L'ARI passe de main en main.", "Chaque JSP nomme une pièce et colle son étiquette.", "On reconstitue le trajet de l'air : bouteille, détendeur, soupape, masque."], "phrase": "L'air de la bouteille, ce n'est pas de l'oxygène pur.", "securite": "Pas de capelage ni d'ouverture de bouteille par les JSP1 : l'animateur manipule le robinet."}, {"titre": "Essaie le masque", "duree": "10 min", "prep": "Masques, lingettes.", "deroule": ["Chaque JSP plaque le masque sur son visage, main devant l'embout : il doit coller (test d'étanchéité).", "Il décrit ce qu'il ressent : champ de vision réduit, voix étouffée."], "phrase": "", "securite": "Désinfecter le masque entre chaque JSP ; masque non raccordé à l'appareil."}, {"titre": "Écoute", "duree": "10 min", "prep": "ARI, balise.", "deroule": ["L'animateur fait siffler l'avertisseur : que fait le binôme ? Il sort immédiatement.", "Il active la balise : pourquoi sonne-t-elle ? Le porteur ne bouge plus ou est en détresse.", "Présentation de la ligne guide et de la cagoule d'évacuation."], "phrase": "Le sifflet = on sort.", "securite": "Démonstration de l'avertisseur et de la balise par l'animateur uniquement."}], "questions": [{"q": "Pourquoi les fumées sont-elles dangereuses ?", "r": "Chaudes, opaques, mobiles, inflammables, toxiques."}, {"q": "Que veut dire ARI ?", "r": "Appareil respiratoire isolant."}, {"q": "La bouteille contient-elle de l'oxygène pur ?", "r": "Non, de l'air comprimé."}, {"q": "Peut-on utiliser un masque filtrant dans les fumées ?", "r": "Jamais : seul l'ARI protège dans les fumées."}, {"q": "À quoi sert le détendeur ?", "r": "À faire baisser la pression de l'air."}, {"q": "Le sifflet de l'ARI sonne : que fait-on ?", "r": "Le binôme sort immédiatement."}, {"q": "À quoi sert la balise ?", "r": "À alerter si le porteur ne bouge plus ou est en détresse."}, {"q": "Peut-on s'engager seul sous ARI ?", "r": "Jamais : toujours en binôme."}], "quiz": [{"q": "ARI veut dire :", "bonne": "Appareil respiratoire isolant", "fausses": ["Appareil de respiration individuelle", "Air respirable intérieur", "Alarme respiratoire incendie"], "expl": ""}, {"q": "La bouteille de l'ARI contient :", "bonne": "De l'air comprimé", "fausses": ["De l'oxygène pur", "De l'azote seul", "Du gaz carbonique"], "expl": ""}, {"q": "Le sifflet de l'ARI sonne :", "bonne": "Le binôme sort immédiatement", "fausses": ["On continue encore 10 minutes", "On enlève le masque", "On appelle sa famille"], "expl": ""}, {"q": "Dans les fumées d'incendie, on utilise :", "bonne": "Un ARI", "fausses": ["Un masque filtrant", "Un foulard mouillé", "Un masque de piscine"], "expl": ""}, {"q": "L'élément qui donne l'air quand j'inspire :", "bonne": "La soupape à la demande", "fausses": ["Le harnais", "Le manomètre", "La balise"], "expl": ""}, {"q": "Sous ARI, on s'engage :", "bonne": "Toujours en binôme", "fausses": ["Seul", "À quatre obligatoirement", "Sans ligne de vie"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La protection respiratoire » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC A2 · RDEB v2 (avril 2026) chap. 1 (nomenclature ARI-CO, contraintes, ligne de vie), § 2.10 (balise), § 2.11 (avertisseur)"}, "JSP1|Les matériels de lutte contre l'incendie": {"cycle": "JSP1", "bloc": "Eteindre un incendie", "item": "Les matériels de lutte contre l'incendie", "objectif": "Au pied du FPTGP, reconnaître et nommer les tuyaux (25, 45, 70, 110), les pièces de jonction, les accessoires et les lances, puis reconstituer au sol le trajet de l'eau du point d'eau à la lance.", "pointsCles": ["Trajet de l'eau : point d'eau (poteau, bouche ou citerne) → engin-pompe (donne la pression) → division (partage l'eau) → lance", "Tuyaux (diamètre intérieur en mm) : Ø25 semi-rigide sur dévidoir tournant (LDT, petits feux) · Ø45 de 20 m (attaque, LDV 40) · Ø70 (alimentation et attaque) · Ø110 (alimenter l'engin-pompe)", "Rangement : en Z (accordéon), en O (Ø45, pratique dans les escaliers), en couronne (Ø110 de 20 m), sur dévidoir · tuyau bien plié, raccords protégés = du temps gagné", "Dévidoirs : tournant (Ø25 sur l'engin), de 45 (dévidoir auxiliaire pour une LDV 40), mobile (chariot avec 40 m de Ø70)", "Pièces de jonction : demi-raccords symétriques (verrouillés par un quart de tour), réductions (ex. 65 vers 40), pièces intermédiaires (65/65), bouchons", "Accessoires : divisions, clé fédérale (poteau d'incendie), clé de barrage (bouche d'incendie), coude et retenue, crépine (aspiration), injecteur (mousse)", "Lances : LDT (petits feux), LDV 40 (attaque des binômes, la plus utilisée), LDV 65 (plus d'eau, plus de recul), lance canon, lance rideau, lance à mousse · LDV = lance à débit variable", "Mousse : émulseur + injecteur + lance → la mousse recouvre le liquide en feu · extincteurs : eau + additif (solides), poudre ABC (polyvalent), CO2 (électrique, liquides) ; on vise la base des flammes en balayant, sortie dans le dos"], "materiel": "FPTGP coffres ouverts (et CCFU si disponible) : tuyaux Ø25, 45, 70, 110, dévidoirs, demi-raccords, réduction, divisions, clé fédérale, clé de barrage, crépine, injecteur, bidon d'émulseur, LDV 40, LDV 65, lance à mousse, extincteurs d'exercice, bâche, diaporama « Les matériels de lutte contre l'incendie ».", "activites": [{"titre": "Par où passe l'eau ?", "duree": "5 min", "prep": "Tableau.", "deroule": ["Chacun cite un matériel entre la bouche d'incendie et le feu.", "On les place dans l'ordre du trajet de l'eau."], "phrase": "", "securite": ""}, {"titre": "Trouve-le !", "duree": "15 min", "prep": "Au pied du FPTGP, coffres ouverts, matériel connu des animateurs.", "deroule": ["L'animateur nomme un matériel.", "Le premier JSP qui le rapporte (en marchant) marque un point et dit à quoi il sert.", "Chaque matériel est remis à sa place dans l'engin."], "phrase": "Chaque matériel a sa place dans l'engin.", "securite": "Engin à l'arrêt, moteur coupé, clés retirées ; on marche autour de l'engin ; tuyaux de 110 et dévidoir mobile portés à deux, dos droit."}, {"titre": "Quel diamètre ?", "duree": "10 min", "prep": "Tuyaux Ø25, 45, 70, 110 posés au sol, demi-raccords.", "deroule": ["Classer les tuyaux du plus petit au plus gros.", "Associer chaque tuyau à son usage (petits feux, attaque, alimentation).", "Accoupler deux demi-raccords (quart de tour) et vérifier le joint."], "phrase": "", "securite": "Attention aux doigts lors de l'accouplement."}, {"titre": "Le trajet de l'eau", "duree": "15 min", "prep": "Bâche, matériel posé au sol.", "deroule": ["Par équipe : relier au sol, dans l'ordre, point d'eau → tuyau → division → tuyaux → lance.", "Chaque équipe explique son montage ; l'animateur vérifie et fait tout ranger."], "phrase": "", "securite": "Pas de mise en eau en JSP1."}], "questions": [{"q": "Le tuyau de 45 sert à quoi ?", "r": "À alimenter une lance d'attaque (LDV 40)."}, {"q": "Plié en Z, c'est quoi ?", "r": "Plié en accordéon pour se dérouler vite en marchant."}, {"q": "À quoi sert une division ?", "r": "À partager l'eau d'un gros tuyau vers deux tuyaux plus petits."}, {"q": "Avec quoi ouvre-t-on un poteau d'incendie ?", "r": "La clé fédérale."}, {"q": "Et une bouche d'incendie ?", "r": "La clé de barrage."}, {"q": "Que veut dire LDV ?", "r": "Lance à débit variable."}, {"q": "Comment fait-on de la mousse ?", "r": "Émulseur + injecteur + lance."}, {"q": "Un extincteur, je vise où ?", "r": "La base des flammes, en balayant."}], "quiz": [{"q": "Le tuyau sur le dévidoir tournant fait :", "bonne": "25 mm", "fausses": ["110 mm", "70 mm", "200 mm"], "expl": ""}, {"q": "La lance la plus utilisée par les binômes :", "bonne": "La LDV 40", "fausses": ["La lance canon", "La lance rideau", "La LDV 65"], "expl": ""}, {"q": "Pour ouvrir un poteau d'incendie :", "bonne": "La clé fédérale", "fausses": ["La clé de barrage", "Un tournevis", "La crépine"], "expl": ""}, {"q": "La division sert à :", "bonne": "Partager l'eau vers deux tuyaux", "fausses": ["Chauffer l'eau", "Arrêter la pompe", "Aspirer l'émulseur"], "expl": ""}, {"q": "La crépine se met :", "bonne": "Au bout du tuyau d'aspiration", "fausses": ["Sur la lance", "Sur le casque", "Dans la cabine"], "expl": ""}, {"q": "Avec un extincteur, je vise :", "bonne": "La base des flammes", "fausses": ["Le haut des flammes", "La fumée", "Le plafond"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les matériels de lutte contre l'incendie » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC C1 · RDMI v6 (avril 2026) § 7.1-7.2 (tuyaux), § 8.11-8.14, § 9 (fiches ETB) · FAT du FPTGP"}, "JSP1|La DECI, les réseaux d'eaux et les réserves incendies": {"cycle": "JSP1", "bloc": "Eteindre un incendie", "item": "La DECI, les réseaux d'eaux et les réserves incendies", "objectif": "Lors d'une sortie encadrée autour du centre, repérer au moins 2 points d'eau incendie, dire ce que signifie leur couleur et lire une plaque de signalisation.", "pointsCles": ["DECI = défense extérieure contre l'incendie : des points d'eau installés à l'avance pour que les pompiers trouvent de l'eau près de chaque bâtiment", "Le maire est responsable des points d'eau de sa commune ; le règlement départemental fixe les règles ; les pompiers conseillent, repèrent et utilisent", "La citerne d'un FPT (≈ 2 000 L) ne dure qu'environ 4 minutes avec une lance à 500 L/min", "Besoins en eau : risque faible 30 m³ (maison isolée), ordinaire 60 m³ (lotissement), important 120 m³ (centre ancien) ; risque particulier étudié à part", "Points d'eau : poteaux et bouches (réseau, sous pression), points d'eau naturels (rivière, canal, étang : il faut aspirer), artificiels (citerne, réserve, bassin), autodéfense des entreprises", "Couleurs : rouge = sous pression · rouge cerclé de vert = sous pression, eau non potable · bleu = pas de pression, il faut aspirer · jaune = très forte pression (plus de 8 bars) · vert = borne de puisage, interdite aux pompiers", "Poteaux : Ø80 = 500 L/min · Ø100 (le plus courant) = 1 000 L/min · Ø150 = 2 000 L/min ; pression de 1 à 16 bars ; ouverture dans le sens inverse des aiguilles d'une montre · plaque : type de point d'eau en haut, diamètre ou débit dans le rond, distance en bas", "Réseau ramifié : une seule arrivée, comme les branches d'un arbre · réseau maillé : tuyaux reliés comme un filet, l'eau arrive par plusieurs chemins (plus sûr)"], "materiel": "Gilets haute visibilité, carte opérationnelle du secteur (symboles PI, PR, BI, PA, BA, CI-RI), photos de points d'eau du secteur (canal du Midi, réserves), fiches relevé, dessins réseau ramifié/maillé, diaporama « La défense extérieure contre l'incendie (DECI) ».", "activites": [{"titre": "4 minutes ?", "duree": "5 min", "prep": "Question d'accroche du cours.", "deroule": ["La citerne est pleine : combien de temps peut-on arroser ? 4 min, 20 min ou 1 heure ?", "Réponse : environ 4 minutes (2 000 L / 500 L par minute).", "Conclusion : il faut des points d'eau prévus à l'avance."], "phrase": "", "securite": ""}, {"titre": "Chasse aux points d'eau", "duree": "20 min", "prep": "Fiches relevé, crayons, gilets, itinéraire repéré autour du CIS.", "deroule": ["Par équipe, trouver poteaux, bouches et plaques autour du centre.", "Noter : couleur, sorties, chiffres de la plaque.", "Dire ce que la couleur signifie."], "phrase": "Une couleur = une information.", "securite": "Sortie à pied encadrée, gilets haute visibilité, règles de sécurité routière, trottoir uniquement ; aucun point d'eau n'est ouvert en JSP1."}, {"titre": "Sur la carte", "duree": "10 min", "prep": "Carte opérationnelle du secteur.", "deroule": ["Retrouver sur la carte chaque point d'eau relevé.", "Repérer les points d'eau naturels du secteur (canal du Midi) et les réserves."], "phrase": "", "securite": ""}, {"titre": "Quelle eau choisir ?", "duree": "10 min", "prep": "Tableau à 4 colonnes (citerne, poteau/bouche, point naturel, réserve).", "deroule": ["Les JSP remplissent avantages et inconvénients de chaque source.", "Dessin : réseau ramifié ou maillé, lequel est le plus sûr ?"], "phrase": "", "securite": ""}], "questions": [{"q": "Que veut dire DECI ?", "r": "Défense extérieure contre l'incendie."}, {"q": "Qui est responsable des points d'eau de la commune ?", "r": "Le maire."}, {"q": "Poteau rouge : qu'est-ce que ça veut dire ?", "r": "De l'eau sous pression."}, {"q": "Poteau bleu ?", "r": "Pas de pression : il faut aspirer."}, {"q": "Borne verte : on peut l'utiliser ?", "r": "Non, elle est interdite aux pompiers."}, {"q": "Un poteau de 100 donne combien ?", "r": "1 000 litres par minute."}, {"q": "Réseau maillé ou ramifié : le plus sûr ?", "r": "Maillé : l'eau arrive par plusieurs chemins."}, {"q": "Combien de temps dure la citerne d'un FPT avec une lance ?", "r": "Environ 4 minutes."}], "quiz": [{"q": "DECI veut dire :", "bonne": "Défense extérieure contre l'incendie", "fausses": ["Direction des eaux contre l'incendie", "Dépôt d'eau communal incendie", "Défense électrique contre l'incendie"], "expl": ""}, {"q": "Le responsable des points d'eau de la commune :", "bonne": "Le maire", "fausses": ["Le chef de centre", "Le préfet seul", "Les habitants"], "expl": ""}, {"q": "Un poteau bleu :", "bonne": "Pas de pression, il faut aspirer", "fausses": ["Eau potable sous pression", "Très forte pression", "Interdit aux pompiers"], "expl": ""}, {"q": "Une borne verte :", "bonne": "Interdite aux pompiers", "fausses": ["Réservée aux pompiers", "La plus puissante", "Eau très chaude"], "expl": ""}, {"q": "Le poteau le plus courant (Ø100) donne :", "bonne": "1 000 L/min", "fausses": ["100 L/min", "50 L/min", "10 000 L/min"], "expl": ""}, {"q": "Le réseau le plus sûr :", "bonne": "Maillé", "fausses": ["Ramifié", "Un seul tuyau", "Aucun"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La défense extérieure contre l'incendie (DECI) » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC C2 · RDMI v6 (avril 2026) chap. 2 (§ 2.1 à 2.9), § 6.2, § 6.14 · règlement départemental de DECI de l'Hérault"}, "JSP1|La description du lot de sauvetage et de protection contre les chutes": {"cycle": "JSP1", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "La description du lot de sauvetage et de protection contre les chutes", "objectif": "Nommer chaque élément du LSPCC « engin », dire à quoi il sert et le replacer au bon endroit dans le sac (triangle en haut, porte-outils au milieu, corde lovée en bas).", "pointsCles": ["LSPCC = lot de sauvetage et de protection contre les chutes : sauver une personne, rejoindre une victime, protéger un pompier qui travaille en hauteur", "Lot « engin » : sac jaune, corde de 30 m (dans le FPTGP, le CCFU et le VSRTU du centre) · lot « échelle » : sac bleu, corde de 60 m (grandes échelles)", "Missions : sauver par l'extérieur (descente), rejoindre une victime (toit, falaise), puits et excavations, se protéger des chutes", "Corde : statique, Ø 12 à 13 mm, résiste à au moins 3 000 kg, nœud de 8 double à chaque bout", "Harnais (sécurise le sapeur-pompier) · triangle d'évacuation (se met sur la victime) · descendeur en 8 (freine et contrôle la descente)", "Petit matériel : sangles bleue (80 cm) et rouge (1,5 m), connecteurs à vis ou automatiques, poulie, cordelettes, protection en cuir (angles coupants), antichute mobile (échelle)", "Rangement : haut du sac = triangle + connecteur automatique · milieu = porte-outils (sangles, connecteurs, poulie, descendeur, cordelettes) · bas = corde lovée + protection · rabats = un bout de corde, antichute, fiche de suivi", "Le LSPCC est un équipement de protection vitale (EPI de catégorie III) : on le respecte"], "materiel": "LSPCC « engin » de formation (sinon celui du FPTGP, contrôlé par l'animateur après l'atelier), bâche, étiquettes, chrono, diaporama « Le lot de sauvetage et de protection contre les chutes ».", "activites": [{"titre": "Une corde pour une voiture ?", "duree": "5 min", "prep": "Question d'accroche.", "deroule": ["Vote : une corde de 12 mm peut-elle retenir une voiture ?", "Réponse : oui, au moins 3 000 kg.", "Mais un nœud, une arête vive ou une corde abîmée la rendent beaucoup moins solide."], "phrase": "", "securite": ""}, {"titre": "Je vide et je nomme", "duree": "15 min", "prep": "LSPCC, bâche, étiquettes.", "deroule": ["On sort le matériel dans l'ordre et on le pose sur la bâche.", "Chaque JSP nomme une pièce, dit à quoi elle sert et pose l'étiquette."], "phrase": "Chaque élément a un rôle précis.", "securite": "Aucune manœuvre en hauteur en JSP1 ; matériel posé au sol."}, {"titre": "Qui suis-je ?", "duree": "10 min", "prep": "Cartes devinettes (« Je freine la descente », « Je protège la corde des angles »…).", "deroule": ["L'animateur lit une devinette.", "Les JSP montrent le bon élément sur la bâche."], "phrase": "", "securite": ""}, {"titre": "Je range (chrono)", "duree": "15 min", "prep": "LSPCC vidé, chrono.", "deroule": ["Par équipe : remettre tout en place, corde lovée en bas, porte-outils au milieu, triangle en haut.", "L'animateur vérifie l'exactitude avant le temps.", "Il contrôle le lot et renseigne le cahier de suivi."], "phrase": "Un sac bien rangé = un sauvetage rapide.", "securite": "Si le lot opérationnel est utilisé, l'animateur le contrôle et le remet dans l'engin."}], "questions": [{"q": "Que veut dire LSPCC ?", "r": "Lot de sauvetage et de protection contre les chutes."}, {"q": "Sac jaune ou sac bleu dans nos engins ?", "r": "Jaune : le lot « engin », corde de 30 m."}, {"q": "Quels engins du centre ont un LSPCC ?", "r": "Le FPTGP, le CCFU et le VSRTU."}, {"q": "À quoi sert le triangle ?", "r": "À descendre ou remonter une victime."}, {"q": "À quoi sert le descendeur ?", "r": "À freiner et contrôler la descente."}, {"q": "Où est rangée la corde ?", "r": "En bas du sac, lovée."}, {"q": "À quoi sert la protection en cuir ?", "r": "À protéger la corde des angles coupants."}], "quiz": [{"q": "LSPCC veut dire :", "bonne": "Lot de sauvetage et de protection contre les chutes", "fausses": ["Lance de secours pour circuit court", "Lot de soins pour chutes et coupures", "Liste des sauveteurs du centre"], "expl": ""}, {"q": "Le sac du lot « engin » est :", "bonne": "Jaune, corde de 30 m", "fausses": ["Bleu, corde de 60 m", "Rouge, corde de 10 m", "Vert, corde de 100 m"], "expl": ""}, {"q": "La corde résiste à au moins :", "bonne": "3 000 kg", "fausses": ["30 kg", "300 kg", "100 kg"], "expl": ""}, {"q": "Le triangle sert à :", "bonne": "Descendre ou remonter une victime", "fausses": ["Freiner la corde", "Protéger les angles", "Ranger les sangles"], "expl": ""}, {"q": "Le descendeur a la forme :", "bonne": "D'un 8", "fausses": ["D'un carré", "D'un triangle", "D'une étoile"], "expl": ""}, {"q": "La corde est rangée :", "bonne": "En bas du sac, lovée", "fausses": ["En haut, nouée", "Enroulée autour du sac", "Dans la cabine"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Le lot de sauvetage et de protection contre les chutes » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC B1 · RDLSPCC v1 (novembre 2025) § 1.1 nomenclature, § 1.3 conditionnement, § 2.2 champ missionnel, § 5.7 entretien et réforme"}, "JSP1|L'entretien et le contrôle du lot de sauvetage et de protection contre les chutes": {"cycle": "JSP1", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "L'entretien et le contrôle du lot de sauvetage et de protection contre les chutes", "objectif": "Contrôler un LSPCC en regardant et en touchant chaque élément, repérer un défaut volontairement placé et dire la conduite à tenir (mettre de côté, signaler, cahier de suivi).", "pointsCles": ["Je regarde : fils tirés, coupures, brûlures, taches, partie décolorée ou fondue, métal tordu, choqué ou fissuré, marquage illisible", "Je touche : toute la corde passe dans mes mains (zone dure, molle, écrasée ? longueur ou souplesse changées ?)", "Le connecteur est toujours fermé : à vis, je visse la bague jusqu'au bout ; automatique, je vérifie qu'il est verrouillé · très solide dans la longueur, beaucoup moins en travers", "Je note : chaque utilisation (formation comprise) est inscrite dans le cahier de suivi", "Je lave les textiles à la main à l'eau tiède (30 °C maximum), séchage à plat, à l'ombre, dans un local aéré · jamais de nettoyeur haute pression", "Le métal se lave à l'eau seule (40 °C maximum), séchage naturel, puis on contrôle le mécanisme de fermeture", "Un doute, une chute, un produit chimique ? Le matériel est mis de côté et signalé (demande KIMOCE au service maintenance)", "Le matériel textile est remplacé au plus tard 10 ans après sa mise en service · vérification annuelle par le GTL"], "materiel": "LSPCC de formation, éléments réformés ou volontairement « défectueux » (sangle marquée, connecteur sale ou mal vissé, corde tachée), connecteurs à vis et automatiques, cahier de suivi, diaporama « Le lot de sauvetage et de protection contre les chutes ».", "activites": [{"titre": "Les mains qui contrôlent", "duree": "15 min", "prep": "Corde du lot de formation dépliée au sol.", "deroule": ["Démonstration : la corde passe dans les mains, centimètre par centimètre.", "Chaque JSP contrôle une portion et dit ce qu'il sent et ce qu'il voit.", "On note le contrôle dans le cahier de suivi."], "phrase": "Je regarde, je touche, je note, je lave, je signale.", "securite": ""}, {"titre": "Trouve le défaut", "duree": "15 min", "prep": "Éléments défectueux mélangés à des éléments en bon état.", "deroule": ["Par équipe, trouver les éléments défectueux.", "Pour chacun : quel défaut ? Que fait-on ? (mis de côté, signalé).", "Rappel : au moindre doute, on ne l'utilise pas."], "phrase": "Un doute ? Je mets de côté et je signale.", "securite": "Les éléments défectueux sont marqués et ne retournent jamais dans un lot opérationnel."}, {"titre": "Toujours fermé", "duree": "10 min", "prep": "Connecteurs à vis et automatiques.", "deroule": ["Chaque JSP ouvre et ferme les deux types de connecteurs.", "Il vérifie le verrouillage (bague vissée, doigt qui revient seul).", "Le binôme contrôle."], "phrase": "", "securite": "Attention aux doigts dans le doigt du connecteur."}], "questions": [{"q": "Comment contrôles-tu une corde ?", "r": "Je la regarde et je la fais passer dans mes mains sur toute sa longueur."}, {"q": "Que cherches-tu en touchant la corde ?", "r": "Une zone dure, molle ou écrasée."}, {"q": "Quand remplit-on le cahier de suivi ?", "r": "Après chaque utilisation, formation comprise."}, {"q": "Comment lave-t-on une corde ?", "r": "À la main, à l'eau tiède, séchée à plat à l'ombre."}, {"q": "Peut-on utiliser un nettoyeur haute pression ?", "r": "Jamais."}, {"q": "Un connecteur mal fermé ?", "r": "Il ne protège plus : je le ferme et je vérifie."}, {"q": "Tu as un doute sur un élément ?", "r": "Je le mets de côté et je le signale."}, {"q": "Combien de temps peut-on garder le matériel textile ?", "r": "10 ans maximum."}], "quiz": [{"q": "Pour contrôler la corde, je :", "bonne": "La regarde et la touche sur toute sa longueur", "fausses": ["La sens", "La pèse", "La tire avec la voiture"], "expl": ""}, {"q": "Le cahier de suivi se remplit :", "bonne": "Après chaque utilisation", "fausses": ["Une fois par an", "Jamais", "Seulement en intervention"], "expl": ""}, {"q": "Une corde se lave :", "bonne": "À la main, à l'eau tiède", "fausses": ["Au nettoyeur haute pression", "À la machine avec de l'eau de javel", "À l'essence"], "expl": ""}, {"q": "Elle sèche :", "bonne": "À plat, à l'ombre, dans un local aéré", "fausses": ["Sur un radiateur", "En plein soleil", "Dans un sac fermé"], "expl": ""}, {"q": "Un connecteur est solide surtout :", "bonne": "Dans sa longueur", "fausses": ["En travers", "Ouvert", "Quand il est mal vissé"], "expl": ""}, {"q": "Le textile du LSPCC est changé au plus tard après :", "bonne": "10 ans", "fausses": ["1 an", "50 ans", "Jamais"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Le lot de sauvetage et de protection contre les chutes » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC B1 · RDLSPCC v1 (novembre 2025) § 1.1 nomenclature, § 1.3 conditionnement, § 2.2 champ missionnel, § 5.7 entretien et réforme"}, "JSP1|La description des échelles à mains": {"cycle": "JSP1", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "La description des échelles à mains", "objectif": "Sur les échelles posées au sol, nommer les éléments de l'échelle à coulisse et de l'échelle à crochets, et choisir la bonne échelle selon une situation donnée.", "pointsCles": ["Les échelles servent à sauver, reconnaître, établir (monter un tuyau) ou faire un itinéraire de secours quand le chemin est coupé", "Au centre : FPTGP (coulisse 2 plans grand modèle, coulisse 3 plans, échelle à crochets) · VSRTU (coulisse 2 plans, crochets, télescopique) · CCFU (coulisse 3 plans, crochets)", "Coulisse 2 plans : jusqu'au 2e étage, la plus utilisée · coulisse 3 plans : jusqu'au 4e étage, avec arcs-boutants", "Coulisse : plan supérieur qui coulisse, montants et échelons, parachutes (bloquent l'échelle dépliée), trait (corde pour déplier et replier), pieds", "Règles de la coulisse : 1 personne par plan (sauf sauvetage), pied à environ 1/3 de la hauteur du mur, sol stable, parachutes enclenchés, mains sur les montants (jamais entre les échelons), quelqu'un tient toujours l'échelle", "Échelle à crochets (2 plans) : crochets, pointes, montants, échelons, entretoise, dispositif d'écartement ; environ 4,20 m dépliée, 15 kg maximum, 14 échelons, 300 kg ; elle pend à la verticale, aucune résistance sur le côté", "Avant de monter sur l'échelle à crochets : bien accrochée, testée (un pompier se suspend dessus), plaquée ou tenue en bas ; en formation, le JSP qui monte est assuré", "Pour toutes : 3 points de contact, casque jugulaire attachée et gants, loin des câbles électriques, jamais devant les flammes (l'aluminium fond vers 660 °C), attention au vent et aux gens autour"], "materiel": "Échelles du FPTGP posées au sol (coulisse 2 plans, coulisse 3 plans, échelle à crochets), casques et gants, étiquettes des éléments, cartes situations, diaporama « Les échelles à main ».", "activites": [{"titre": "Le feu bloque l'escalier", "duree": "5 min", "prep": "Question d'accroche.", "deroule": ["Comment rejoindre quelqu'un au 2e étage ?", "Laquelle ? Elle est où ? Elle monte jusqu'où ?"], "phrase": "", "securite": ""}, {"titre": "Trouve les éléments", "duree": "15 min", "prep": "Échelles au sol, étiquettes.", "deroule": ["Par équipe, coller les étiquettes : montants, échelons, trait, parachutes, pieds, crochets, pointes…", "Chaque équipe explique le rôle de 2 éléments."], "phrase": "", "securite": "Échelles posées au sol uniquement ; casque et gants."}, {"titre": "Soulève", "duree": "10 min", "prep": "Coulisse 2 plans au sol.", "deroule": ["À deux, soulever l'échelle à coulisse de quelques centimètres puis la reposer : elle est lourde !", "Soulever seul l'échelle à crochets : légère (15 kg max).", "Rappel : on porte bas, on prévient les autres."], "phrase": "", "securite": "Pas de dressage ni de montée en JSP1 ; dos droit, jambes fléchies ; gants."}, {"titre": "Laquelle choisir ?", "duree": "15 min", "prep": "Cartes situations : fenêtre au 1er étage, balcon au 4e, ruelle trop étroite, coulisse trop courte.", "deroule": ["L'animateur lit une situation.", "Les équipes choisissent l'échelle et justifient.", "Bonus : citer une règle de sécurité pour cette échelle."], "phrase": "", "securite": ""}], "questions": [{"q": "À quoi servent les échelles à main ?", "r": "Sauver, reconnaître, établir, itinéraire de secours."}, {"q": "La coulisse 2 plans monte jusqu'où ?", "r": "Jusqu'au 2e étage."}, {"q": "Et la coulisse 3 plans ?", "r": "Jusqu'au 4e étage."}, {"q": "Combien de personnes par plan ?", "r": "Une seule, sauf pour un sauvetage."}, {"q": "Le trait, c'est quoi ?", "r": "La corde qui sert à déplier et replier l'échelle."}, {"q": "À quoi servent les parachutes ?", "r": "À bloquer l'échelle une fois dépliée."}, {"q": "Que fait-on avant de monter sur l'échelle à crochets ?", "r": "On la teste en se suspendant dessus."}, {"q": "Combien de points de contact ?", "r": "Toujours 3."}], "quiz": [{"q": "La coulisse 2 plans atteint :", "bonne": "Le 2e étage", "fausses": ["Le 10e étage", "Le toit d'un immeuble", "Le 6e étage"], "expl": ""}, {"q": "Sur une coulisse, sauf sauvetage :", "bonne": "1 personne par plan", "fausses": ["3 personnes par plan", "Autant qu'on veut", "Personne"], "expl": ""}, {"q": "Le trait sert à :", "bonne": "Déplier et replier l'échelle", "fausses": ["Accrocher l'échelle", "Freiner la descente", "Décorer l'échelle"], "expl": ""}, {"q": "Quand on déplie la coulisse, les mains sont :", "bonne": "Sur les montants", "fausses": ["Entre les échelons", "Dans les poches", "Sur le trait seulement"], "expl": ""}, {"q": "L'échelle à crochets s'accroche :", "bonne": "À une fenêtre ou un balcon", "fausses": ["À un arbre", "À un camion", "Au sol"], "expl": ""}, {"q": "Sur une échelle, je garde :", "bonne": "3 points de contact", "fausses": ["1 point de contact", "Les mains libres", "Les yeux fermés"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les échelles à main » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC B2 · GTO sauvetages et mises en sécurité · RDEP SDIS 34 (échelles portables, via diaporama départemental) · RDSMES v2 · RDLSPCC v1 · FAT des engins du CIS"}, "JSP1|Les objectifs de l'activité physique": {"cycle": "JSP1", "bloc": "S'impliquer dans son activité", "item": "Les objectifs de l'activité physique", "objectif": "Expliquer avec 3 exemples d'interventions pourquoi un sapeur-pompier doit être en forme toute sa vie, et réaliser un atelier « comme en intervention » adapté à son âge.", "pointsCles": ["Des missions physiques : feu d'appartement (tenue, ARI, escaliers, tuyaux), accident de la route (outils lourds), déblai, porter une victime, feu de forêt, interventions qui durent toute une nuit", "Sous l'ARI tout est plus dur : jusqu'à 18 kg sur le dos, chaleur et déshydratation, essoufflement (l'air de la bouteille part plus vite), on voit et on entend moins bien", "Un pompier bien entraîné consomme moins d'air pour le même effort et reste efficace plus longtemps", "Ma sécurité : un corps entraîné se blesse moins, fatigue moins et fait moins d'erreurs ; je connais mes limites", "Celle de mon binôme : je dois pouvoir l'aider, le tirer, le porter, le ramener", "Le sport aide aussi la tête : moins de stress, meilleur sommeil, esprit d'équipe, confiance en soi", "Toute la carrière : visite médicale (aptitude), tests physiques chaque année (ICP), sport en service et à la maison", "Dès maintenant : bouger chaque jour, un sport en club, bien boire et bien manger, bien dormir (moins d'écrans le soir)"], "materiel": "Tuyaux Ø45 vides, plots, sac à dos léger (quelques kilos adaptés à l'âge), tapis de glisse ou tapis de sol, chrono, bouteilles d'eau, diaporama « Pourquoi les pompiers font du sport ».", "activites": [{"titre": "4 étages avec 18 kg ?", "duree": "10 min", "prep": "Sac à dos lesté légèrement (adapté à 12-13 ans).", "deroule": ["Vote : qui pense tenir 4 étages en tenue avec 18 kg ?", "Chacun porte le sac léger le temps de monter un étage, à son rythme.", "Témoignage (si possible) d'un sapeur-pompier du centre sur une intervention physique."], "phrase": "", "securite": "Charge légère uniquement ; escalier avec rampe ; pas de course."}, {"titre": "Le relais tuyaux", "duree": "10 min", "prep": "Tuyaux Ø45 vides, plots ; échauffement fait avant.", "deroule": ["Par équipe, transporter des tuyaux d'un plot à un autre en relais.", "On porte à deux si besoin, dos droit."], "phrase": "Une équipe vaut ce que vaut chacun.", "securite": "Échauffement obligatoire ; gestes et postures (dos droit, jambes fléchies) ; hydratation ; douleur = arrêt."}, {"titre": "Le binôme", "duree": "10 min", "prep": "Tapis de glisse ou tapis de sol sur surface lisse.", "deroule": ["À deux, tirer un camarade assis sur un tapis sur quelques mètres.", "On inverse les rôles.", "Lien : sauver son binôme demande de la force."], "phrase": "", "securite": "Surface lisse et dégagée, distance courte, camarades de gabarit proche."}, {"titre": "Débrief et bonnes habitudes", "duree": "10 min", "prep": "Tableau.", "deroule": ["Qu'est-ce qui était le plus dur ? Imaginez avec 18 kg, dans la chaleur et la fumée.", "Chacun choisit une bonne habitude à tenir cette semaine (bouger, dormir, boire de l'eau…)."], "phrase": "Les JSP en forme d'aujourd'hui sont les pompiers en forme de demain.", "securite": ""}], "questions": [{"q": "Pourquoi les pompiers font-ils du sport ?", "r": "Pour réussir leurs missions sans se blesser."}, {"q": "Combien peut peser un ARI ?", "r": "Jusqu'à 18 kg."}, {"q": "Cite une intervention très physique.", "r": "Feu, désincarcération, déblai, porter une victime, feu de forêt…"}, {"q": "Pourquoi un pompier entraîné reste plus longtemps sous ARI ?", "r": "Il consomme moins d'air pour le même effort."}, {"q": "En quoi le sport protège ton binôme ?", "r": "Je peux l'aider, le tirer, le porter si besoin."}, {"q": "Le sport aide aussi la tête ?", "r": "Oui : moins de stress, meilleur sommeil, confiance."}, {"q": "Les pompiers sont-ils testés chaque année ?", "r": "Oui : les ICP et une visite médicale."}, {"q": "Je commence quand ?", "r": "Maintenant : bouger chaque jour."}], "quiz": [{"q": "Un ARI peut peser jusqu'à :", "bonne": "18 kg", "fausses": ["2 kg", "50 kg", "100 kg"], "expl": ""}, {"q": "Un corps entraîné…", "bonne": "Se blesse moins", "fausses": ["Se blesse plus", "N'a jamais besoin de repos", "N'a pas besoin de boire"], "expl": ""}, {"q": "Le sport aide aussi à :", "bonne": "Moins stresser et mieux dormir", "fausses": ["Ne plus jamais dormir", "Être plus stressé", "Ne plus manger"], "expl": ""}, {"q": "Chaque année, les pompiers passent :", "bonne": "Des tests physiques (ICP) et une visite médicale", "fausses": ["Un examen de cuisine", "Rien du tout", "Un permis bateau"], "expl": ""}, {"q": "Une bonne habitude pour un JSP :", "bonne": "Bouger chaque jour", "fausses": ["Écrans tard le soir", "Sauter le petit-déjeuner", "Boire des sodas pendant le sport"], "expl": ""}, {"q": "Pendant le sport, une douleur :", "bonne": "J'arrête et je le dis à l'animateur", "fausses": ["Je force encore plus", "Je le cache", "Je change d'exercice sans rien dire"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Pourquoi les pompiers font du sport » (JSP1 – Les objectifs de l'activité physique, charte SDIS 34) · RNF JSP/JMP v1.1, fiche APS A2 · RDEB v2 (avril 2026) § 1.4 à 1.8 (contraintes ARI), § 2.1 à 2.3 · barèmes ICP officiels non présentés aux JSP1"}, "JSP1|La connaissance théorique des EPI": {"cycle": "JSP1", "bloc": "Eteindre un incendie", "item": "La connaissance théorique des EPI", "objectif": "Nommer les EPI du sapeur-pompier au feu et leur rôle, régler son casque, et repérer un EPI abîmé en disant quoi faire (ne pas le porter, le signaler).", "pointsCles": ["EPI = équipement de protection individuelle : porté sur soi pour se protéger (chaleur et flammes, chocs, coupures, fumée et suies, eau et froid, être vu la nuit)", "Tenues des sapeurs-pompiers : cérémonie, service et intervention (TSI), protection incendie, feux de forêts, tenues spéciales, sport", "Tenue de JSP (manœuvre) : polo, veste et pantalon TSI, ceinture et galon, rangers, casque et gants · complète à chaque séance, jamais en dehors des activités JSP, propre ; elle appartient à la section", "Au feu, de la tête aux pieds : casque avec visière, cagoule, veste et surpantalon, gants, bottes ; ni bijoux, ni piercing, ni montre", "Casque type B (F1, couvrant, feu de bâtiment) ou type A (F2, plus léger : feux de forêts, secours routier) · jugulaire toujours attachée", "Gants de protection (manœuvres, coupures) · gants d'attaque obligatoires dans la chaleur", "Bien régler : tour de tête (molette), jugulaire sous le menton, visière baissée, la bonne taille · limites : l'EPI retarde la brûlure, il ne protège ni de l'électricité ni des produits chimiques", "Contrôler avant (casque, veste et pantalon, gants, bottes) ; abîmé = je ne le porte pas et je le signale · après le feu : nettoyage selon la saleté (« je sais, je sens, je vois »), on ne ramène pas les suies chez soi"], "materiel": "Tenue de protection incendie complète par binôme (casques F1 et F2, cagoule, veste, surpantalon, gants de protection et d'attaque, bottes), tenues de JSP, EPI réformés ou défectueux, mannequin ou animateur volontaire, diaporama « Les équipements de protection individuelle (EPI) ».", "activites": [{"titre": "Pourquoi autant d'habits ?", "duree": "5 min", "prep": "Une tenue complète présentée sur une table ou portée par un animateur.", "deroule": ["En plein été, pourquoi le pompier s'habille-t-il autant pour aller au feu ?", "Les JSP citent les dangers : chaleur, flammes, chocs, coupures, fumée, être vu."], "phrase": "", "securite": ""}, {"titre": "Trouve l'erreur", "duree": "10 min", "prep": "EPI réformés ou défectueux (gant troué, jugulaire cassée, bande réfléchissante décollée, fermeture HS) mélangés à des EPI en bon état.", "deroule": ["Par équipe, repérer les EPI abîmés.", "Pour chacun : quel défaut ? Que fait-on ? (ne pas le porter, le signaler)."], "phrase": "Un EPI abîmé ? Je ne le porte pas et je le signale.", "securite": "EPI défectueux marqués, jamais remis en service."}, {"titre": "Règle ton casque", "duree": "10 min", "prep": "Casques F1 et F2.", "deroule": ["Chaque JSP règle le tour de tête et la jugulaire.", "Il baisse la visière.", "Son binôme vérifie : le casque ne tombe pas quand on se penche."], "phrase": "Jugulaire toujours attachée.", "securite": "Désinfecter l'intérieur des casques et cagoules entre chaque JSP."}, {"titre": "Habille le mannequin", "duree": "15 min", "prep": "Une tenue complète par équipe, mannequin ou animateur volontaire.", "deroule": ["Course d'habillage par équipe.", "On note la rapidité ET l'exactitude : aucune peau visible, jugulaire attachée, gants enfilés poignets recouverts.", "Les JSP essaient casque, cagoule et gants."], "phrase": "", "securite": "Pas de course en courant : on marche ; tenue de feu non portée en manœuvre par les JSP1."}], "questions": [{"q": "Que veut dire EPI ?", "r": "Équipement de protection individuelle."}, {"q": "Cite 4 EPI du pompier au feu.", "r": "Casque, cagoule, veste et surpantalon, gants, bottes."}, {"q": "Quand portes-tu ta tenue de JSP ?", "r": "Aux séances et manifestations officielles, jamais en dehors."}, {"q": "Quels gants dans la chaleur ?", "r": "Les gants d'attaque."}, {"q": "Ta jugulaire, tu la mets quand ?", "r": "Toujours, dès que je porte le casque."}, {"q": "Pourquoi pas de bijoux ?", "r": "Ils chauffent et accrochent."}, {"q": "Ton gant est troué : que fais-tu ?", "r": "Je ne le porte pas et je le signale."}, {"q": "Ton EPI te protège-t-il de l'électricité ?", "r": "Non, on reste loin des câbles électriques."}], "quiz": [{"q": "EPI veut dire :", "bonne": "Équipement de protection individuelle", "fausses": ["Équipe de pompiers d'intervention", "Engin de protection incendie", "Échelle pour intervention"], "expl": ""}, {"q": "Dans la chaleur, je mets :", "bonne": "Des gants d'attaque", "fausses": ["Des gants de jardin", "Pas de gants", "Des gants en laine"], "expl": ""}, {"q": "La jugulaire du casque :", "bonne": "Toujours attachée", "fausses": ["Jamais attachée", "Seulement s'il pleut", "Dans la poche"], "expl": ""}, {"q": "Ma tenue de JSP, je la porte :", "bonne": "Seulement aux activités de la section", "fausses": ["Au collège", "Pour sortir le samedi", "Pour faire du vélo"], "expl": ""}, {"q": "Un EPI troué :", "bonne": "Je ne le porte pas et je le signale", "fausses": ["Je le porte quand même", "Je le jette sans rien dire", "Je le répare avec du scotch"], "expl": ""}, {"q": "Pendant les activités, les bijoux :", "bonne": "Interdits", "fausses": ["Obligatoires", "Autorisés s'ils sont petits", "Seulement les montres"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les équipements de protection individuelle (EPI) » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche INC A1 · RDEB v2 (avril 2026) § 2.5, § 4, § 5.8 · RDLSPCC v1 § 2.6 · arrêté du 8 avril 2015 modifié · règlement de la section (§ IV)"}, "JSP1|L'organisation nationale de la sécurité civile": {"cycle": "JSP1", "bloc": "Diffuser la culture du service public", "item": "L'organisation nationale de la sécurité civile", "objectif": "Pour 3 situations (feu de poubelle, grand feu de forêt sur plusieurs communes, inondation de plusieurs villages), placer les bons acteurs et désigner le DOS et le COS en expliquant son choix — 20 min, au moins 2 situations justes sur 3.", "pointsCles": ["La sécurité civile protège la population contre tous les risques : prévenir, informer et alerter, protéger (personnes, animaux, biens, environnement), secourir", "Le premier maillon, c'est le citoyen : je vois (je me protège), j'alerte (18 ou 112), j'agis (gestes de premiers secours), j'aide (j'accueille les secours) — « toute personne concourt par son comportement à la sécurité civile »", "Plus la crise est grande, plus on monte : le maire (sa commune), le préfet du département (tout l'Hérault), le préfet de zone (zone Sud, état-major à Marseille), l'État (ministre de l'Intérieur, DGSCGC)", "Le DOS (directeur des opérations de secours) est le maire, ou le préfet si c'est plus grave : il prend les grandes décisions (évacuer, fermer une route, héberger) et il est responsable de la population", "Le COS (commandant des opérations de secours) est un sapeur-pompier (le chef d'agrès, puis un officier) : il commande sur le terrain, conseille le DOS et lui rend compte — on ne dit pas « le maire commande les pompiers »", "Des plans pour ne pas improviser : ORSEC (plan du préfet), PCS (plan communal de sauvegarde du maire), PFMS (plan familial et kit d'urgence) ; le DICRIM explique les risques de la commune", "Une grande équipe : un SDIS par département (chez nous le SDIS 34), pompiers militaires (BSPP à Paris, BMPM à Marseille, unités de la sécurité civile), SAMU (15), gendarmes et policiers, associations (Croix-Rouge, Protection civile…), bénévoles et réserves communales", "Les renforts de l'État : avions bombardiers d'eau basés à Nîmes-Garons, hélicoptères Dragon, militaires des UIISC, colonnes de renfort d'autres départements", "En France (DGSCGC, 2024) : 256 400 sapeurs-pompiers dont 78 % de volontaires ; 4,7 millions d'interventions par an, 8 sur 10 pour du secours aux personnes", "Numéros d'urgence : 18 pompiers, 112 urgence en Europe, 15 SAMU, 17 police-gendarmerie, 114 par SMS, 196 urgence en mer — jamais de faux appel"], "materiel": "Tableau ou paperboard (accroche « orage sur Cruzy »), 4 à 6 cartes situations (feu de poubelle, feu de forêt sur plusieurs communes, inondation de plusieurs villages, accident de car…), une vingtaine de cartes acteurs (citoyen témoin, maire, préfet, préfet de zone, SDIS 34, colonne de renfort, avions, hélicoptère Dragon, SAMU, gendarmerie, Croix-Rouge, Protection civile, réserve communale…), étiquettes « DOS » et « COS », DICRIM de Cruzy ou de Quarante, diaporama du cours.", "activites": [{"titre": "Orage sur Cruzy", "duree": "10 min", "prep": "Tableau ; situation d'accroche du cours.", "deroule": ["L'animateur lit : « Un gros orage inonde Cruzy et les villages voisins. Qui décide ? Qui vient aider ? »", "Les JSP listent tous ceux qui vont agir ; on note au tableau (pompiers, maire, gendarmes, SAMU, voisins, Croix-Rouge, avions…).", "On y reviendra à la fin : chacun a sa place dans la sécurité civile, à commencer par le citoyen."], "phrase": "Le premier maillon de la sécurité civile, c'est toi.", "securite": ""}, {"titre": "L'escalier des décideurs", "duree": "10 min", "prep": "4 grandes cartes : maire, préfet du département, préfet de zone, ministre de l'Intérieur.", "deroule": ["Les JSP rangent les cartes de la commune à l'État : Cruzy → Hérault → zone Sud → France.", "L'animateur annonce des événements de plus en plus gros ; les JSP disent qui prend la direction.", "On pose les étiquettes : le maire ou le préfet dirige (DOS), le pompier commande sur le terrain (COS)."], "phrase": "Le maire dirige, le pompier commande sur le terrain.", "securite": ""}, {"titre": "Atelier : qui fait quoi ?", "duree": "20 min", "prep": "Cartes situations et cartes acteurs du cours, étiquettes DOS / COS.", "deroule": ["Chaque équipe tire une carte situation et place autour tous les acteurs qui vont agir.", "Elle désigne le DOS et le COS, puis explique son choix au groupe.", "Correction : petit feu de poubelle → citoyen + SDIS, DOS = maire ; grand feu de forêt sur plusieurs communes → DOS = préfet, avions et colonnes de renfort ; inondation de plusieurs villages → plan ORSEC, PCS des communes, associations pour l'hébergement."], "phrase": "Plus la crise est grande, plus on monte.", "securite": ""}, {"titre": "Les numéros", "duree": "5 min", "prep": "Cartes 18, 112, 15, 17, 114, 196.", "deroule": ["L'animateur montre un numéro, les JSP disent qui répond.", "Rappel : un faux appel est un délit et bloque une ligne pour une vraie urgence."], "phrase": "", "securite": ""}], "questions": [{"q": "Qui est le premier acteur de la sécurité civile ?", "r": "Le citoyen : toi !"}, {"q": "Qui dirige les secours dans une commune ?", "r": "Le maire (DOS)."}, {"q": "Et si l'événement dépasse la commune ?", "r": "Le préfet du département prend la direction."}, {"q": "Qui commande les secours sur le terrain ?", "r": "Un sapeur-pompier (le COS)."}, {"q": "Comment s'appelle le plan du préfet ?", "r": "Le plan ORSEC."}, {"q": "Combien de SDIS par département ?", "r": "Un seul : chez nous, le SDIS 34."}, {"q": "Que font les sapeurs-pompiers le plus souvent ?", "r": "Du secours aux personnes (8 interventions sur 10)."}, {"q": "Cite 2 renforts de l'État.", "r": "Avions bombardiers d'eau (Nîmes-Garons), hélicoptères Dragon, militaires des UIISC, colonnes de renfort."}, {"q": "Quels pompiers sont militaires ?", "r": "La BSPP (Paris), le BMPM (Marseille) et les unités de la sécurité civile."}], "quiz": [{"q": "Qui est le premier maillon de la sécurité civile ?", "bonne": "Le citoyen", "fausses": ["Le ministre de l'Intérieur", "Le préfet", "Le SAMU"], "expl": "« Toute personne concourt par son comportement à la sécurité civile. »"}, {"q": "Dans une commune, qui dirige les opérations de secours (DOS) ?", "bonne": "Le maire", "fausses": ["Le chef de centre", "Le gendarme", "Le directeur d'école"], "expl": "Le préfet prend le relais si c'est plus grave."}, {"q": "Le COS, qui commande les secours sur le terrain, c'est :", "bonne": "Un sapeur-pompier", "fausses": ["Le maire", "Le préfet", "Un médecin du SAMU"], "expl": "Il conseille le DOS et lui rend compte."}, {"q": "Le plan du préfet qui organise tous les secours du département :", "bonne": "Le plan ORSEC", "fausses": ["Le PCS", "Le DICRIM", "Le PFMS"], "expl": "PCS = plan du maire ; PFMS = plan de la famille."}, {"q": "L'Hérault dépend de la zone de défense :", "bonne": "Sud", "fausses": ["Sud-Ouest", "Est", "Paris"], "expl": "État-major de zone à Marseille."}, {"q": "Les sapeurs-pompiers interviennent le plus souvent pour :", "bonne": "Du secours aux personnes", "fausses": ["Des feux de forêt", "Des inondations", "Des nids de guêpes"], "expl": "8 interventions sur 10."}, {"q": "Les avions bombardiers d'eau de la sécurité civile sont basés à :", "bonne": "Nîmes-Garons", "fausses": ["Montpellier", "Paris", "Lyon"], "expl": ""}, {"q": "Le 114, c'est :", "bonne": "Le numéro d'urgence par SMS", "fausses": ["Les pompiers en Europe", "Le SAMU", "Les urgences en mer"], "expl": "Pour les sourds, les malentendants ou si on ne peut pas parler."}], "statut": "brouillon", "source": "Cours 2026 « L'organisation nationale de la sécurité civile » (charte SDIS 34) · Code de la sécurité intérieure art. L112-1, L721-1, L731-3 (PCS), L741-1 (ORSEC) ; CGCT art. L1424-4 (DOS / COS) ; cours JSP3 « L'organisation et les missions du SDIS » et RNF JSP3 SC B1 ; statistiques DGSCGC 2024 – à valider : item sans fiche RNF JSP1 dédiée (chef de section), chiffres DGSCGC à mettre à jour chaque année, DICRIM de Cruzy / Quarante à récupérer, hélicoptère Dragon basé à Montpellier à vérifier"}, "JSP1|Les grades des sapeurs-pompiers civils et militaires": {"cycle": "JSP1", "bloc": "S'impliquer dans son activité", "item": "Les grades des sapeurs-pompiers civils et militaires", "objectif": "Reconnaître sur de vrais galons de poitrine les grades des sapeurs-pompiers civils (du sapeur au colonel), dire à quoi servent les grades et citer les galons de couleur des JSP.", "pointsCles": ["Les grades servent à savoir qui commande, reconnaître l'expérience, organiser l'équipe ; respect mutuel", "3 familles : hommes du rang (équipiers), sous-officiers (chefs d'équipe et d'agrès), officiers (chefs de groupe, de colonne, de centre…) ; SPP et SPV ont les mêmes grades", "Hommes du rang, galons rouges : sapeur 2e classe (sans galon), sapeur 1re classe (1), caporal (2), caporal-chef (3)", "Sous-officiers, galons argent : sergent (2), sergent-chef (3), adjudant (1 argent à liseré rouge), adjudant-chef (1 or à liseré rouge)", "Officiers : lieutenant (1 galon argent), capitaine (3), commandant (4), lieutenant-colonel (5, alternés argent et or), colonel (5 argent), contrôleur général (feuilles de chêne)", "Pompiers militaires : BSPP à Paris (armée de Terre : soldat, caporal, sergent, adjudant, lieutenant, capitaine, colonel, général) · BMPM à Marseille (Marine : matelot, quartier-maître, second-maître, maître, enseigne, lieutenant de vaisseau…)", "JSP : galon blanc (JSP1), jaune (JSP2), orange (JSP3), vert (JSP4), en velcro sur la poitrine ; il change chaque année réussie", "S'adresser à un gradé : « Caporal », « Sergent » ; « Mon lieutenant », « Mon capitaine » pour un officier ; toujours bonjour et politesse (usages à adapter au centre)"], "materiel": "Vrais galons de poitrine en velcro (à vérifier avant la séance), cartes mémory galon/nom, galons JSP de couleur, diaporama « Les grades ».", "activites": [{"titre": "Qui est le chef ?", "duree": "5 min", "prep": "Animateurs et sapeurs-pompiers présents en tenue.", "deroule": ["Les JSP observent les galons autour d'eux.", "Rouge, argent, combien de barres ? Ils devinent les grades."], "phrase": "Le grade se lit sur la poitrine.", "securite": ""}, {"titre": "Qui est-ce ?", "duree": "10 min", "prep": "Galons en velcro.", "deroule": ["L'animateur montre un galon.", "Le premier qui donne le bon grade gagne un point."], "phrase": "", "securite": ""}, {"titre": "Remets dans l'ordre", "duree": "15 min", "prep": "Galons ou cartes, du sapeur au colonel, mélangés.", "deroule": ["Par équipe, classer du sapeur 2e classe au colonel.", "Séparer les 3 familles : hommes du rang, sous-officiers, officiers.", "Ajouter les galons JSP : blanc, jaune, orange, vert."], "phrase": "", "securite": ""}, {"titre": "Mémory", "duree": "15 min", "prep": "Cartes par paires : un galon + son nom (dont BSPP/BMPM pour les plus rapides).", "deroule": ["Retourner deux cartes : si galon et nom vont ensemble, on garde la paire.", "Prolongement : à chaque séance, demander le grade des pompiers présents."], "phrase": "", "securite": ""}], "questions": [{"q": "À quoi servent les grades ?", "r": "À savoir qui commande et à reconnaître l'expérience."}, {"q": "Cite les 3 familles de grades.", "r": "Hommes du rang, sous-officiers, officiers."}, {"q": "Combien de galons rouges pour un caporal ?", "r": "Deux."}, {"q": "Le sergent a des galons de quelle couleur ?", "r": "Argent."}, {"q": "Combien de galons pour un capitaine ?", "r": "Trois."}, {"q": "Les pompiers de Paris sont… ?", "r": "Des militaires de l'armée de Terre (BSPP)."}, {"q": "Et ceux de Marseille ?", "r": "Des marins-pompiers de la Marine nationale (BMPM)."}, {"q": "Quel galon en JSP3 ?", "r": "Le galon orange."}], "quiz": [{"q": "Le caporal a :", "bonne": "2 galons rouges", "fausses": ["1 galon argent", "3 galons argent", "Aucun galon"], "expl": ""}, {"q": "Les galons des sous-officiers sont :", "bonne": "Argent", "fausses": ["Rouges", "Verts", "Bleus"], "expl": ""}, {"q": "Le capitaine a :", "bonne": "3 galons", "fausses": ["1 galon", "5 galons", "Des feuilles de chêne"], "expl": ""}, {"q": "Les pompiers de Paris (BSPP) sont :", "bonne": "Des militaires de l'armée de Terre", "fausses": ["Des marins", "Des civils volontaires", "Des policiers"], "expl": ""}, {"q": "Le galon des JSP2 est :", "bonne": "Jaune", "fausses": ["Blanc", "Vert", "Orange"], "expl": ""}, {"q": "Le sapeur 2e classe porte :", "bonne": "Aucun galon", "fausses": ["1 galon rouge", "2 galons argent", "Un galon vert"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les grades » (charte SDIS 34) · RNF JSP/JMP v1.1, fiche SC C1 · arrêté du 8 avril 2015 modifié (insignes de grade, à vérifier sur les vrais galons) · règlement de la section (§ III, galons JSP)"}, "JSP2|Les matériels électriques portatifs": {"cycle": "JSP2", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Les matériels électriques portatifs", "objectif": "Installer en binôme un éclairage sur trépied alimenté par le groupe électrogène du VSRTU (groupe démarré par l'animateur) et citer les dangers du courant et du moteur thermique, sans erreur de sécurité.", "pointsCles": ["Le groupe électrogène produit l'électricité quand il n'y en a pas : éclairer, pomper, outiller ; au CIS, groupe de 3 kW dans le VSRTU avec son bidon et un touret de 25 m", "Fonctionnement : carburant → moteur → alternateur → prises ; le moteur rejette du monoxyde de carbone (CO) et chauffe beaucoup", "TOUJOURS dehors, loin des portes et fenêtres, sur un sol plat et stable : jamais dans une maison, un garage ou une cave, même porte ouverte", "La somme des puissances branchées ne dépasse pas celle du groupe (3 kW = 3 000 W) : on lit l'étiquette de chaque appareil", "Méthode : placer dehors → vérifier (carburant, huile, câbles) → dérouler entièrement le touret (un câble enroulé chauffe) → démarrer puis brancher un par un → surveiller → débrancher puis couper le moteur", "Le plein : moteur arrêté et refroidi, sans flamme ni étincelle, avec le bon bidon", "Éclairages : projecteurs portatifs sur batterie (7 au FPTGP, 1 au VSRTU), 2 projecteurs 24 V du FPTGP, lot éclairage du VSRTU (projecteur, lumaphore, 2 trépieds) ; on éclaire le travail, pas les yeux", "Le courant brûle, bloque les muscles et peut arrêter le cœur : branchements au sec, mains sèches, câble abîmé = on ne l'utilise pas, on ne débranche jamais en tirant sur le câble", "Victime électrisée : je ne la touche pas → je fais couper le courant → j'alerte (18 ou 112) → je porte secours une fois le courant coupé ; câble au sol : on recule et on alerte", "Après usage : projecteurs remis en charge, contrôle du groupe (niveau de gasoil, compteur horaire, état visuel)"], "materiel": "VSRTU : groupe électrogène 3 kW et bidon, lot éclairage électrique (projecteur, lumaphore, 2 trépieds, touret de 25 m), projecteur portatif · FPTGP : projecteurs portatifs et chargeurs · formulaire « Control Groupe électrogène » du centre · étiquettes de puissance des appareils · objets « dangers » à cacher.", "activites": [{"titre": "Le fil rouge : groupe dedans ou dehors ?", "duree": "5 min", "prep": "Photo d'un garage avec un groupe électrogène.", "deroule": ["Question : « Porte ouverte, on peut le faire tourner dedans ? »", "Les JSP votent et justifient.", "Réponse : NON, le CO est invisible, sans odeur, il tue même porte ouverte."], "phrase": "Un moteur qui tourne, c'est toujours dehors.", "securite": ""}, {"titre": "Le contrôle du groupe", "duree": "10 min", "prep": "Groupe du VSRTU à l'arrêt et froid, formulaire « Control Groupe électrogène ».", "deroule": ["Avec l'animateur, les JSP remplissent le contrôle : niveau de gasoil, compteur horaire, état visuel, problème.", "Ils lisent la puissance du groupe et celle du projecteur, de la pompe, de l'aspirateur.", "Calcul : peut-on tout brancher en même temps sur 3 kW ?"], "phrase": "On ne demande jamais au groupe plus qu'il ne peut donner.", "securite": "Moteur arrêté et froid, pas de plein par les JSP."}, {"titre": "Éclairer une zone de nuit", "duree": "20 min", "prep": "Zone sombre (remise ou soirée), groupe démarré et branché par l'animateur dehors, 3 « dangers » cachés (trou simulé, câble, obstacle).", "deroule": ["Choisir où placer le groupe et la lumière.", "Dérouler entièrement le touret, câble à plat au sol.", "Monter le trépied (pieds écartés, réglages bloqués), fixer et orienter le projecteur sans éblouir.", "Repérer les dangers cachés une fois la lumière installée ; puis débrancher, arrêter, ranger, remettre en charge."], "phrase": "On éclaire le travail, pas les yeux des collègues.", "securite": "Seul l'animateur démarre le groupe, fait le plein et branche. Personne ne touche le pot d'échappement. Branchements au sec."}, {"titre": "Victime électrisée : que faire ?", "duree": "10 min", "prep": "Un JSP joue la victime « collée » à un câble (fictif).", "deroule": ["Un JSP arrive : il ne touche pas, fait couper le courant, alerte.", "Puis il porte secours une fois le courant coupé (bilan, lien prompt secours).", "Variante : câble tombé au sol, on fait reculer tout le monde."], "phrase": "Je me protège avant de protéger les autres.", "securite": "Câble factice, aucun appareil sous tension."}], "questions": [{"q": "Où place-t-on un groupe électrogène ?", "r": "Dehors, loin des portes et fenêtres, sur un sol stable."}, {"q": "Quel gaz dangereux rejette son moteur ?", "r": "Le monoxyde de carbone (CO)."}, {"q": "Pourquoi dérouler entièrement le touret ?", "r": "Un câble enroulé chauffe et peut prendre feu."}, {"q": "Quand fait-on le plein ?", "r": "Moteur arrêté et refroidi, sans flamme."}, {"q": "Quelle est la puissance du groupe du VSRTU ?", "r": "3 kW (3 000 watts)."}, {"q": "Dans quel ordre démarrer et brancher ?", "r": "On démarre le moteur, puis on branche les appareils un par un."}, {"q": "Que fait le courant électrique au corps ?", "r": "Il brûle, bloque les muscles et peut arrêter le cœur."}, {"q": "Une personne est électrisée : que faire d'abord ?", "r": "Ne pas la toucher, faire couper le courant, alerter."}, {"q": "Pourquoi ne pas éblouir avec un projecteur ?", "r": "On éclaire le travail : un collègue ou un conducteur ébloui ne voit plus le danger."}], "quiz": [{"q": "Où se place le groupe électrogène ?", "bonne": "Dehors, loin des ouvertures", "fausses": ["Dans le garage, porte ouverte", "Dans la cave inondée", "Dans la cabine de l'engin"], "expl": "Son moteur rejette du CO."}, {"q": "Le gaz toxique du moteur est…", "bonne": "Le monoxyde de carbone", "fausses": ["L'oxygène", "L'azote", "La vapeur d'eau"], "expl": "Invisible et sans odeur."}, {"q": "Pourquoi dérouler tout le touret ?", "bonne": "Enroulé, le câble chauffe", "fausses": ["Pour faire joli", "Pour avoir plus de puissance", "Pour économiser le carburant"], "expl": ""}, {"q": "Quand faire le plein du groupe ?", "bonne": "Moteur arrêté et refroidi", "fausses": ["Moteur en marche", "Pendant qu'il chauffe", "N'importe quand"], "expl": ""}, {"q": "Puissance du groupe électrogène du VSRTU ?", "bonne": "3 kW", "fausses": ["30 kW", "300 W", "3 W"], "expl": ""}, {"q": "Pour arrêter le groupe, on…", "bonne": "Débranche les appareils puis coupe le moteur", "fausses": ["Coupe le moteur puis tire sur les câbles", "Le renverse", "Verse de l'eau dessus"], "expl": ""}, {"q": "Une personne est collée à un câble électrique. Tu…", "bonne": "Ne la touches pas et fais couper le courant", "fausses": ["La tires par le bras", "Lui jettes de l'eau", "Attends qu'elle lâche"], "expl": "Puis tu alertes et portes secours."}, {"q": "Un câble électrique est abîmé. Tu…", "bonne": "Ne l'utilises pas et le signales", "fausses": ["Le répares avec du scotch", "L'utilises avec des gants", "Le caches"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les matériels électriques et d'éclairage » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 PPBE A2 · FAT VSRTU et FPTGP (04/2026) · RDSMES SDIS 34 v2 § 2.4 · RDEB v2 § 5.3 (CO) · notice du groupe électrogène du centre à vérifier"}, "JSP2|Les différents statuts des sapeurs-pompiers": {"cycle": "JSP2", "bloc": "S'impliquer dans son activité", "item": "Les différents statuts des sapeurs-pompiers", "objectif": "Citer les 3 familles de sapeurs-pompiers (civils, militaires, privés) et expliquer la différence entre SPV et SPP, sans erreur au jeu « Qui suis-je ? ».", "pointsCles": ["Environ 256 400 sapeurs-pompiers en France : 78 % de volontaires, 17 % de professionnels, 5 % de militaires (presque 8 sur 10 sont volontaires)", "Civils (dépendent du SDIS) : SPV = un citoyen qui a un autre métier ou fait ses études, dès 16 ans, engagé pour 5 ans renouvelables, reçoit des indemnités (pas un salaire)", "SPP = pompier, c'est son métier à plein temps : recruté par concours, fonctionnaire employé par le SDIS, travaille par gardes", "SPV et SPP : même formation, mêmes grades, mêmes engins, même mission — « Chacun à sa façon, tous pompiers ! »", "Le SSSM (service de santé et de secours médical) : médecins, infirmiers, pharmaciens, vétérinaires, psychologues sapeurs-pompiers ; c'est le médecin SP qui fait la visite d'aptitude", "SDIS de l'Hérault : 4 513 SPV, 852 SPP, 73 centres de secours, 22 écoles de JSP dont la nôtre", "Militaires : BSPP (Paris, armée de Terre, créée par Napoléon en 1811), BMPM (Marseille, Marine nationale, 1939), FORMISC (sécurité civile, renforts en France et à l'étranger, feux de forêts l'été)", "Privés : agents SSIAP (grands bâtiments), pompiers d'aéroport SSLIA (Montpellier, Béziers), pompiers d'entreprise : ils interviennent tout de suite en attendant le SDIS", "Le parcours : JSP → brevet JSP → SPV dès 16 ans → plus tard SPP ou militaire par concours ou engagement"], "materiel": "Cartes « Qui suis-je ? », grandes étiquettes CIVILS / MILITAIRES / PRIVÉS, chiffres du cours à afficher · si possible un SPV et un SPP (ou un membre du SSSM) du centre pour témoigner.", "activites": [{"titre": "Le grand tri", "duree": "10 min", "prep": "Brainstorming noté au tableau, 3 grandes étiquettes au sol : CIVILS / MILITAIRES / PRIVÉS.", "deroule": ["Les JSP citent tous les statuts qu'ils connaissent.", "Chacun va poser sa carte (SPV, SPP, SSSM, BSPP, BMPM, FORMISC, SSIAP, SSLIA) sous la bonne famille.", "Devinette : quel pourcentage de volontaires en France ? (78 %)"], "phrase": "Chacun à sa façon, tous pompiers !", "securite": ""}, {"titre": "Qui suis-je ?", "duree": "15 min", "prep": "Cartes du cours (« J'ai un autre métier mais je pars quand je suis disponible »…).", "deroule": ["L'animateur lit une carte, les binômes trouvent le statut.", "Puis chaque JSP invente sa propre carte « Qui suis-je ? » pour le groupe.", "Un point par bonne réponse."], "phrase": "", "securite": ""}, {"titre": "Rencontre", "duree": "15 min", "prep": "Inviter un SPV et un SPP (ou un infirmier SP) du centre ; questions préparées par les JSP.", "deroule": ["Chaque invité raconte son parcours (beaucoup ont commencé JSP !).", "Les JSP posent leurs questions : formation, gardes, autre métier, grades.", "On retrouve ensemble ce qu'ils ont en commun : formation, grades, engins, mission."], "phrase": "Sur une intervention, on ne voit pas la différence.", "securite": ""}], "questions": [{"q": "Cite les 3 familles de sapeurs-pompiers.", "r": "Civils, militaires, privés."}, {"q": "Quel est le statut le plus nombreux ?", "r": "Volontaire : près de 8 sur 10."}, {"q": "À partir de quel âge peut-on être SPV ?", "r": "16 ans."}, {"q": "Pour combien de temps s'engage un SPV ?", "r": "5 ans, renouvelables."}, {"q": "Comment devient-on SPP ?", "r": "Par concours : c'est un métier à plein temps."}, {"q": "Qu'ont en commun SPV et SPP ?", "r": "La même formation, les mêmes grades, les mêmes engins, la même mission."}, {"q": "Qui protège Paris ? Et Marseille ?", "r": "La BSPP (armée de Terre) ; le BMPM (Marine nationale)."}, {"q": "Qu'est-ce que le SSSM ?", "r": "Le service de santé : médecins, infirmiers, pharmaciens, vétérinaires, psychologues."}, {"q": "Qui sont les pompiers d'aéroport ?", "r": "Des pompiers privés (SSLIA) employés par l'aéroport."}], "quiz": [{"q": "Quel statut est le plus nombreux en France ?", "bonne": "Volontaire", "fausses": ["Professionnel", "Militaire", "Privé"], "expl": "Près de 8 sapeurs-pompiers sur 10."}, {"q": "Âge minimum pour s'engager comme SPV ?", "bonne": "16 ans", "fausses": ["12 ans", "25 ans", "18 ans seulement"], "expl": "Avec l'accord des parents."}, {"q": "Un SPP est recruté…", "bonne": "Par concours", "fausses": ["Par tirage au sort", "Sans formation", "Seulement à 50 ans"], "expl": ""}, {"q": "Qui protège Paris ?", "bonne": "La BSPP", "fausses": ["Le BMPM", "Le SSSM", "Le SSLIA"], "expl": "Brigade de sapeurs-pompiers de Paris, armée de Terre."}, {"q": "Les marins-pompiers de Marseille dépendent de…", "bonne": "La Marine nationale", "fausses": ["L'armée de l'Air", "La mairie de Paris", "Une entreprise privée"], "expl": ""}, {"q": "Le SSSM regroupe…", "bonne": "Les SP qui ont un métier de santé", "fausses": ["Les pompiers militaires", "Les pompiers d'aéroport", "Les JSP"], "expl": ""}, {"q": "SPV et SPP ont…", "bonne": "Les mêmes grades", "fausses": ["Des engins différents", "Des missions différentes", "Des grades différents"], "expl": ""}, {"q": "Un SPV reçoit pour ses heures…", "bonne": "Des indemnités", "fausses": ["Un salaire de fonctionnaire", "Rien du tout", "Des médailles seulement"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les statuts des sapeurs-pompiers » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 SC B1 · statistiques DGSCGC édition 2025 · sdis34.fr « Nos moyens humains » (déc. 2025) · BSPP rapport 2024"}, "JSP2|Les risques d'incendie": {"cycle": "JSP2", "bloc": "Diffuser la culture du service public", "item": "Les risques d'incendie", "objectif": "Citer les 5 grandes causes d'incendie à la maison, expliquer le rôle et l'installation du DAAF et donner la bonne conduite à tenir (évacuation ou confinement, feu de poêle, odeur de gaz), sans erreur.", "pointsCles": ["Quand on dort, on ne sent pas la fumée : 70 % des incendies mortels ont lieu la nuit et 8 victimes sur 10 meurent à cause des fumées", "5 grandes causes : électricité, gaz, chauffage, flamme nue, cuisson — et des appareils laissés en marche sans surveillance", "Prévenir : une seule multiprise par prise, robinet de gaz fermé, rien sur les radiateurs, ramonage chaque année, bougie jamais sans surveillance, on ne quitte pas la cuisine", "DAAF (détecteur avertisseur autonome de fumée) obligatoire dans tous les logements depuis 2015 ; il sonne fort (85 dB) pour nous réveiller", "DAAF : au plafond, dans le couloir des chambres, au moins un par étage, pas dans la cuisine ni la salle de bain ; testé chaque mois, dépoussiéré, jamais débranché", "Autres détecteurs : de chaleur (cuisine, garage), de CO (près d'une chaudière ou d'un poêle)", "Feu chez moi : je sors avec tout le monde, je ferme la porte, je ne reviens jamais, j'appelle le 18 ou le 112 dehors ; fumée dans l'escalier : je reste, je ferme, linges mouillés, je me montre à la fenêtre ; jamais l'ascenseur, à quatre pattes dans la fumée", "Feu de poêle : couper le feu, couvercle ou linge humide, laisser refroidir ; JAMAIS d'eau (boule de feu)", "Odeur de gaz : ouvrir, fermer le robinet si possible, sortir, appeler dehors ; pas d'interrupteur, de sonnette, de flamme ni de téléphone dans la maison", "Plan d'évacuation familial : deux sorties par pièce si possible, un point de rassemblement dehors, numéros 18, 112, 114 affichés, exercice une fois par an"], "materiel": "DAAF de démonstration (et un détecteur de CO si possible), photos ou pièce « piégée » (multiprise surchargée, linge sur radiateur, bougie près d'un rideau, poêle sur le feu…), couvercle et poêle froide, feuilles quadrillées, crayons.", "activites": [{"titre": "Qu'est-ce qui te réveille ?", "duree": "5 min", "prep": "DAAF de démonstration.", "deroule": ["Question de l'accroche : l'odeur ? la chaleur ? le bruit ?", "Réponse : rien ! Seul le DAAF réveille à temps.", "Chaque JSP appuie sur le bouton test et écoute le signal."], "phrase": "Un DAAF qui marche sauve des vies.", "securite": "Protéger les oreilles, pas collé à l'oreille."}, {"titre": "La maison piégée", "duree": "15 min", "prep": "Pièce aménagée ou photos avec 6 à 8 dangers cachés.", "deroule": ["Par binôme, les JSP repèrent un maximum de dangers en 5 min.", "Pour chacun : quelle cause (électricité, gaz, chauffage, flamme, cuisson) ?", "Ils donnent le bon geste de prévention."], "phrase": "", "securite": ""}, {"titre": "Sortir ou rester ?", "duree": "10 min", "prep": "Cartes situations : feu dans ma cuisine, fumée dans l'escalier, poêle en feu, odeur de gaz.", "deroule": ["L'animateur tire une carte, un binôme mime la bonne conduite.", "Les autres valident ou corrigent (porte fermée, 18/112 dehors, couvercle, pas d'interrupteur…).", "Démonstration à froid : poser le couvercle sur une poêle sans se pencher."], "phrase": "Feu chez moi : je sors et je ferme. Fumée dans l'escalier : je reste et je calfeutre.", "securite": "Aucune flamme réelle, poêle froide."}, {"titre": "Mon plan d'évacuation", "duree": "15 min", "prep": "Feuilles quadrillées, crayons.", "deroule": ["Chaque JSP dessine son logement, les sorties, son point de rassemblement et les numéros 18, 112, 114.", "Il le présente à son binôme.", "Défi : faire l'exercice en famille avant la prochaine séance."], "phrase": "Le point de rassemblement dit tout de suite si quelqu'un manque.", "securite": ""}], "questions": [{"q": "Pourquoi installer un DAAF ?", "r": "Pour être réveillé : quand on dort, on ne sent pas la fumée."}, {"q": "Où placer le DAAF ?", "r": "Au plafond, dans le couloir des chambres, au moins un par étage."}, {"q": "Cite les 5 grandes causes d'incendie à la maison.", "r": "Électricité, gaz, chauffage, flamme nue, cuisson."}, {"q": "Qu'est-ce qui tue le plus dans un incendie ?", "r": "Les fumées (8 victimes sur 10)."}, {"q": "Le feu est chez toi : que fais-tu ?", "r": "Je sors avec tout le monde, je ferme la porte, j'appelle le 18 ou le 112 dehors."}, {"q": "La fumée est dans l'escalier : que faire ?", "r": "Rester chez soi, fermer la porte, linges mouillés, se montrer à la fenêtre, appeler."}, {"q": "Une poêle prend feu : que faire ?", "r": "Couper le feu et poser un couvercle. Jamais d'eau."}, {"q": "Ça sent le gaz : que ne faut-il surtout pas faire ?", "r": "Toucher un interrupteur, allumer une flamme, téléphoner dedans."}, {"q": "Qu'est-ce qu'un point de rassemblement ?", "r": "Un endroit dehors où toute la famille se retrouve pour savoir si quelqu'un manque."}], "quiz": [{"q": "Que veut dire DAAF ?", "bonne": "Détecteur avertisseur autonome de fumée", "fausses": ["Dispositif d'alarme anti-feu", "Détecteur automatique d'air frais", "Disjoncteur anti-accident de feu"], "expl": ""}, {"q": "Où installer le DAAF ?", "bonne": "Au plafond du couloir des chambres", "fausses": ["Dans la cuisine, au-dessus de la plaque", "Dans la salle de bain", "Au sol, derrière une porte"], "expl": "La fumée monte."}, {"q": "La plupart des incendies mortels ont lieu…", "bonne": "La nuit", "fausses": ["Le matin", "À midi", "L'après-midi"], "expl": "70 % des incendies mortels."}, {"q": "Ta poêle d'huile prend feu. Tu…", "bonne": "Coupes le feu et poses un couvercle", "fausses": ["Jettes un verre d'eau", "Cours dehors avec la poêle", "Souffles dessus"], "expl": "Jamais d'eau : boule de feu."}, {"q": "La fumée envahit l'escalier de ton immeuble. Tu…", "bonne": "Restes chez toi, porte fermée et calfeutrée", "fausses": ["Descends par l'escalier", "Prends l'ascenseur", "Ouvres la porte pour voir"], "expl": ""}, {"q": "Ça sent le gaz chez toi. Tu ne dois PAS…", "bonne": "Allumer la lumière", "fausses": ["Ouvrir les fenêtres", "Sortir", "Appeler le 18 dehors"], "expl": "Une étincelle peut faire exploser le gaz."}, {"q": "Combien de fois teste-t-on son DAAF ?", "bonne": "Chaque mois", "fausses": ["Jamais", "Tous les 10 ans", "Seulement quand il y a le feu"], "expl": ""}, {"q": "Qu'est-ce qui tue le plus dans un incendie ?", "bonne": "Les fumées", "fausses": ["Les flammes", "Le bruit", "L'eau des pompiers"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les risques de la vie courante » (charte SDIS 34), partie 1 · RNF JSP/JMP v1.1 fiche JSP2 SC A1 · statistiques DGSCGC 2025 · loi n° 2010-238 (DAAF) · GDO « Interventions en présence de gaz »"}, "JSP2|Les risques domestiques": {"cycle": "JSP2", "bloc": "Diffuser la culture du service public", "item": "Les risques domestiques", "objectif": "Citer les principaux accidents de la vie courante (maison, extérieur, loisirs, école) et, pour chacun, un geste de prévention ; réaliser en équipe un message de prévention à transmettre à son entourage.", "pointsCles": ["Accident de la vie courante = à la maison, dehors ou pendant les loisirs (pas la route, pas le travail) : plus de 20 000 décès par an en France", "1 décès sur 2 est dû à une chute ; c'est la 1re cause de décès chez les enfants de 1 à 4 ans", "Chutes : escabeau, escalier, tapis, sol mouillé ; personnes âgées et petits les plus touchés", "Bricolage : coupures, projections, chutes d'échelle → lunettes et gants · jardinage : tondeuse, taille-haie, produits → chaussures fermées, enfants à l'écart", "Produits ménagers hors de portée, jamais transvasés dans une bouteille à boire · cache-prises et appareils loin de l'eau", "Piscine : barrière, alarme, surveillance permanente des enfants (la noyade peut être silencieuse et rapide)", "Loisirs : casque à vélo, trottinette, skate ; baignade en zone surveillée, pas après un gros effort ou en plein soleil ; prévenir où l'on va", "École : pas de course ni de bousculade, prévenir un adulte, connaître les consignes d'évacuation", "En cas d'accident : se protéger, alerter (18 ou 112), secourir", "Le JSP est ambassadeur de la prévention : DAAF et plan d'évacuation en famille, bons gestes expliqués aux proches, exemple à l'école"], "materiel": "Photos ou pièce aménagée avec des dangers (escabeau instable, produit dans une bouteille d'eau, tapis qui glisse, prise sans cache, piscine sans barrière…), cartes « lieux » (maison, jardin, piscine, loisirs, école), grandes feuilles et feutres pour les affiches.", "activites": [{"titre": "La visite de la maison", "duree": "15 min", "prep": "Pièce aménagée ou photos avec 8 dangers cachés.", "deroule": ["Par binôme, repérer un maximum de dangers en 5 min.", "Pour chaque danger : quel accident ? qui est le plus touché (petit, ado, personne âgée) ?", "Donner le geste de prévention."], "phrase": "Un danger repéré, c'est un accident évité.", "securite": ""}, {"titre": "Le jeu des lieux", "duree": "10 min", "prep": "5 cartes lieux au sol : maison, jardin, piscine, loisirs, école ; cartes « gestes ».", "deroule": ["L'animateur lit un geste (casque à vélo, produits en hauteur, barrière de piscine…).", "Les JSP courent vers le bon lieu.", "Un JSP raconte un accident vécu ou vu (sans obligation)."], "phrase": "", "securite": "Sol dégagé, on ne se bouscule pas."}, {"titre": "Mon message de prévention", "duree": "20 min", "prep": "Grandes feuilles, feutres (ou une tablette pour une courte vidéo).", "deroule": ["Par équipe, choisir un risque (chute, noyade, produits, bricolage…).", "Créer une affiche ou une vidéo de 30 s avec un message simple et un geste.", "Présentation au groupe ; les meilleures servent lors des manifestations de la section."], "phrase": "Je suis ambassadeur : je protège ma famille et mes amis.", "securite": ""}], "questions": [{"q": "Qu'est-ce qu'un accident de la vie courante ?", "r": "Un accident à la maison, dehors ou pendant les loisirs (pas la route, pas le travail)."}, {"q": "Quelle est la 1re cause de décès par accident de la vie courante ?", "r": "Les chutes."}, {"q": "Qui sont les plus touchés par les chutes ?", "r": "Les personnes âgées et les petits enfants."}, {"q": "Comment se protéger en bricolant ?", "r": "Lunettes et gants."}, {"q": "Pourquoi ne jamais mettre un produit ménager dans une bouteille d'eau ?", "r": "Quelqu'un pourrait le boire par erreur."}, {"q": "Comment sécuriser une piscine ?", "r": "Barrière, alarme et surveillance permanente des enfants."}, {"q": "Que porter à vélo ou à trottinette ?", "r": "Un casque."}, {"q": "Que fais-tu face à un accident ?", "r": "Je me protège, j'alerte (18 ou 112), je secours."}, {"q": "Que veut dire être « ambassadeur de la prévention » ?", "r": "Expliquer les bons gestes à ses proches et donner l'exemple."}], "quiz": [{"q": "1re cause de décès par accident de la vie courante ?", "bonne": "Les chutes", "fausses": ["Les piqûres d'insectes", "Les coups de soleil", "Les rhumes"], "expl": "Près d'1 décès sur 2."}, {"q": "Un produit ménager se range…", "bonne": "Hors de portée, dans son emballage d'origine", "fausses": ["Dans une bouteille d'eau", "Sous l'évier ouvert à tous", "Sur la table de la cuisine"], "expl": ""}, {"q": "Pour bricoler en sécurité, on porte…", "bonne": "Lunettes et gants", "fausses": ["Des tongs", "Un bonnet", "Rien du tout"], "expl": ""}, {"q": "Une piscine privée doit avoir…", "bonne": "Une barrière ou une alarme et une surveillance", "fausses": ["Un toboggan", "De l'eau chaude", "Un plongeoir"], "expl": ""}, {"q": "Pour la trottinette, on met…", "bonne": "Un casque", "fausses": ["Des écouteurs", "Un bonnet", "Des lunettes de soleil"], "expl": ""}, {"q": "Pas de baignade…", "bonne": "Après un gros effort ou en plein soleil", "fausses": ["Dans une zone surveillée", "Avec un adulte", "Le matin"], "expl": ""}, {"q": "Un accident de la route est-il un accident de la vie courante ?", "bonne": "Non", "fausses": ["Oui, toujours", "Seulement à vélo", "Seulement la nuit"], "expl": "La route et le travail sont à part."}, {"q": "Face à un accident, l'ordre est…", "bonne": "Protéger, alerter, secourir", "fausses": ["Secourir, protéger, alerter", "Alerter, partir, revenir", "Filmer, alerter, secourir"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les risques de la vie courante » (charte SDIS 34), parties 2 et 3 · RNF JSP/JMP v1.1 fiche JSP2 SC A1 · Santé publique France (mortalité par accident de la vie courante 2012-2016)"}, "JSP3|Les règles d'emploi et de sécurité de l'échelle à crochet": {"cycle": "JSP3", "bloc": "Réaliser un sauvetage ou une mise en sécurité", "item": "Les règles d'emploi et de sécurité de l'échelle à crochet", "objectif": "Avec l'aide du conducteur, descendre l'échelle à crochets du FPT, la porter, la déplier, la verrouiller et l'accrocher au 1er étage ; puis monter assuré par une corde avec 3 points de contact jusqu'au 1er étage maximum, sans erreur de sécurité.", "pointsCles": ["Éléments : crochets, pointes, montants, échelons, entretoise, dispositif d'écartement ; modèle 2 plans (celui du FPTGP) avec verrou et anti-dérapant", "Capacités : environ 4,20 m dépliée, 2,40 m repliée, 15 kg au plus (un seul porteur), 14 échelons, échelons et crochets résistants à 300 kg, aucune résistance sur le côté : elle pend toujours à la verticale", "On l'utilise quand les escaliers sont impraticables, quand une échelle à coulisse ou un moyen aérien n'est pas possible, ou pour prolonger une échelle à coulisse trop courte", "Descendre l'échelle de l'engin à deux, avec le conducteur ; la porter repliée et verrouillée, le plus bas possible, en regardant autour (câbles, passants)", "Accrocher : se placer sous la fenêtre, déplier et verrouiller, lever verticalement crochets vers le mur, crochets bien à plat sur l'appui ou la rambarde", "Test de suspension avant toute montée : un sapeur-pompier se suspend par les bras (en formation JSP : un formateur) ; ça bouge = on accroche ailleurs", "L'échelle est plaquée contre la façade ou tenue en bas (derrière, jambes en appui, bras tendus sur les montants) pour éviter le ballant", "Monter : 3 points de contact, corps près de l'échelle, genoux à l'extérieur, mains le long des montants, sans à-coups ; entrée par enroulement ou enjambement", "Dangers : câbles électriques, vent, chaleur (aluminium qui fond vers 660 °C), éclats de verre : tenue, casque jugulaire serrée, gants", "JSP : toujours assuré (sangle en haut, sangle et descendeur en bas, harnais, formateur au garant) et jamais au-delà du 1er étage"], "materiel": "Échelle à crochets 2 plans du FPTGP, LSPCC (sangles, descendeur, harnais, connecteur automatique) pour la sécurisation, façade de la tour de manœuvre ou fenêtre du 1er étage du centre, petit escabeau ou échelle télescopique pour atteindre le 1er échelon, EPI complets.", "activites": [{"titre": "Connaître et descendre l'échelle", "duree": "10 min", "prep": "FPT avec le conducteur ; échelle posée au sol après descente.", "deroule": ["Le conducteur montre le rangement ; on descend l'échelle à deux, le JSP la reçoit par la base sans la lâcher.", "Au sol : nommer crochets, pointes, montants, échelons, verrou ; la déplier et la verrouiller, puis la replier.", "Questions flash : poids, longueur, nombre d'échelons."], "phrase": "Légère, maniée seul, accrochée par ses crochets.", "securite": "Dos droit, jambes fléchies ; personne seul sur le toit de l'engin."}, {"titre": "Porter et accrocher", "duree": "15 min", "prep": "Façade du 1er étage du centre ; formateur en haut à l'étage.", "deroule": ["Chaque JSP porte l'échelle repliée, le plus bas possible, jusqu'à la façade en regardant en l'air (câbles).", "Il la déplie, vérifie le verrou, la lève verticalement crochets vers le mur et pose les crochets bien à plat.", "Le formateur réalise le test de suspension ; un autre JSP montre comment tenir l'échelle en bas."], "phrase": "On regarde, on vérifie, puis on teste.", "securite": "Test de suspension par un formateur uniquement ; zone sous l'échelle dégagée."}, {"titre": "Monter assuré au 1er étage", "duree": "20 min", "prep": "Sécurisation LSPCC installée par les formateurs (sangle en haut, sangle + descendeur en bas), harnais ; un formateur au garant, un en haut, un au pied.", "deroule": ["Le JSP s'équipe du harnais, connecteur automatique sur la demi-lune ; contrôle par le formateur.", "Il monte avec 3 points de contact, genoux à l'extérieur ; l'observateur compte les points de contact.", "Entrée par enroulement ou enjambement, puis redescente face à l'échelle.", "Rotation : porteur, teneur d'échelle, observateur."], "phrase": "Échelle tenue, 3 points de contact, toujours assuré.", "securite": "JSP toujours assuré par une corde, 1er étage maximum, EPI complets ; pas de vitre cassée en formation."}], "questions": [{"q": "Quand utilise-t-on l'échelle à crochets ?", "r": "Quand les escaliers sont impraticables et qu'une échelle à coulisse ou un moyen aérien n'est pas possible ou ne suffit pas."}, {"q": "Combien de personnes pour la porter ?", "r": "Une seule (15 kg au plus)."}, {"q": "Avec qui descend-on l'échelle de l'engin ?", "r": "Avec le conducteur."}, {"q": "Comment porte-t-on l'échelle ?", "r": "Repliée et verrouillée, le plus bas possible, en regardant autour."}, {"q": "Où posent les crochets ?", "r": "Bien à plat sur l'appui de fenêtre ou la rambarde du balcon."}, {"q": "Que fait-on avant que quelqu'un monte ?", "r": "On la teste : un sapeur-pompier se suspend dessus."}, {"q": "Comment l'empêcher de se balancer ?", "r": "Plaquée contre la façade ou tenue en bas par un sapeur-pompier."}, {"q": "Combien de points de contact en montant ?", "r": "Trois : deux mains et un pied, ou deux pieds et une main."}, {"q": "À quelle température l'aluminium fond-il ?", "r": "Vers 660 °C."}, {"q": "Jusqu'où monte un JSP ?", "r": "Le 1er étage, toujours assuré par une corde."}], "quiz": [{"q": "L'échelle à crochets pèse au maximum…", "bonne": "15 kg", "fausses": ["5 kg", "40 kg", "80 kg"], "expl": "Un seul porteur suffit."}, {"q": "Dépliée, elle mesure environ…", "bonne": "4,20 m", "fausses": ["2 m", "8 m", "12 m"], "expl": ""}, {"q": "Sur le côté, l'échelle à crochets…", "bonne": "Ne résiste pas", "fausses": ["Résiste à 300 kg", "Se bloque toute seule", "Est plus solide que de face"], "expl": "Elle doit pendre à la verticale."}, {"q": "Avant toute montée, on…", "bonne": "Fait un test de suspension", "fausses": ["Monte vite pour tester", "Secoue l'échelle", "Retire les crochets"], "expl": "En formation JSP : par un formateur."}, {"q": "On porte l'échelle…", "bonne": "Le plus bas possible", "fausses": ["Au-dessus de la tête", "En courant", "À deux sur les épaules"], "expl": "Pour ne blesser personne en se retournant."}, {"q": "En montant, on garde…", "bonne": "3 points de contact", "fausses": ["1 point de contact", "2 points de contact", "Les mains dans les poches"], "expl": ""}, {"q": "Un JSP sur l'échelle à crochets monte…", "bonne": "Au 1er étage maximum, assuré", "fausses": ["Jusqu'au toit", "Au 3e étage sans corde", "Seul sans formateur"], "expl": ""}, {"q": "En levant l'échelle, on regarde d'abord…", "bonne": "En l'air (câbles électriques)", "fausses": ["Sa montre", "Le sol uniquement", "L'engin"], "expl": "Et attention au vent."}], "statut": "brouillon", "source": "Cours 2026 « L'échelle à crochets » (charte SDIS 34) · RDEP SDIS 34 « Échelles portables » v1 (juin 2023) ; RDLSPCC SDIS 34 v1 annexe 4.1 ; RDSMES SDIS 34 v2 §3.3 ; FAT FPTGP"}, "JSP3|Le matériel d'épuisement hydraulique et thermique": {"cycle": "JSP3", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Le matériel d'épuisement hydraulique et thermique", "objectif": "Pour 4 situations d'inondation, choisir le bon matériel (électrique, thermique ou hydraulique) en justifiant, puis préparer, attacher et démarrer la motopompe flottante dans une réserve sécurisée, sans erreur de sécurité.", "pointsCles": ["Trois familles de pompes : électrique (câble, groupe ou prise, vu en JSP2), thermique (moteur à essence : motopompe), hydraulique (eau sous pression de l'engin : hydro-éjecteur, vide-cave, turbopompe)", "Le chef d'agrès choisit selon la quantité d'eau, l'accès, l'électricité disponible et l'air du local", "Marche générale : reconnaître (origine, hauteur, dessous), mettre en sécurité (couper électricité et gaz, éloigner), protéger (surélever, bâcher), épuiser puis assécher, rendre compte", "Courant pas coupé = on ne met pas un pied dans l'eau ; attention aux trous et regards invisibles, eaux souillées", "Motopompe flottante : environ 1 000 l/min, sans électricité ni engin ; sur les CCF (CCFM, CCFU, CCGC)", "Mise en œuvre : vérifier essence et huile, raccorder le refoulement, mettre à l'eau attachée par la commande, démarrer, surveiller (essence, grille, tuyau sans pli), arrêter et rincer", "Moteur thermique JAMAIS dans un local fermé (monoxyde de carbone mortel) ; plein moteur arrêté et froid, loin de toute flamme ; échappement brûlant ; bruit ; jamais seul au bord de l'eau", "Matériels hydrauliques : pas d'électricité ni de gaz d'échappement (utilisables en cave), mais ils consomment l'eau de l'engin : l'engin doit être alimenté", "Hydro-éjecteur et vide-cave : effet Venturi, l'eau rapide dans un passage étroit aspire l'eau de la cave ; pas de pièce qui tourne, supporte la boue", "Turbopompe (sur les CCF du centre) : l'eau de l'engin fait tourner une turbine qui entraîne la pompe ; au point le plus bas, ouverture douce sur ordre, sortie dirigée loin du local"], "materiel": "Motopompe flottante et turbopompe des CCFM / CCFU / CCGC avec leurs notices, bidon d'essence, commande (cordage), tuyaux de refoulement, engin-pompe avec le conducteur ; hydro-éjecteur ou vide-cave si disponible (sinon photo) ; pailles et verres d'eau ; réserve ou bassin sécurisé ; protections auditives, gants ; cartes-situations.", "activites": [{"titre": "La paille magique (effet Venturi)", "duree": "5 min", "prep": "Pailles coupées en deux, verres d'eau.", "deroule": ["Une demi-paille dans le verre, l'autre souffle fort perpendiculairement au sommet de la première.", "L'eau monte : c'est le principe de l'hydro-éjecteur et du vide-cave."], "phrase": "L'eau rapide aspire l'eau de la cave.", "securite": ""}, {"titre": "Le bon choix", "duree": "10 min", "prep": "Cartes-situations : cave inondée sans électricité, garage inondé avec voiture, jardin sous 20 cm d'eau, bassin à vider, sous-sol d'immeuble avec odeur d'essence ; tableau électrique / thermique / hydraulique à compléter.", "deroule": ["Par binôme, tirer une carte et choisir le matériel en justifiant (électricité ? air du local ? engin alimenté ?).", "Compléter ensemble le tableau des avantages et contraintes.", "Rappeler la marche générale : reconnaître, sécuriser, protéger, épuiser, rendre compte."], "phrase": "Moteur thermique : toujours dehors.", "securite": ""}, {"titre": "La motopompe flottante", "duree": "15 min", "prep": "Réserve ou bassin sécurisé, formateur et conducteur présents, notice du modèle du centre.", "deroule": ["Vérifier essence et huile, raccorder le tuyau de refoulement.", "Attacher la commande, mettre la pompe à l'eau depuis le bord.", "Démarrage par l'encadrant (ou le JSP guidé selon la notice), surveillance de la grille et du tuyau.", "Arrêt, sortie de l'eau avec la commande, rinçage ; plein moteur froid."], "phrase": "La commande retient la pompe : on ne va pas la chercher dans l'eau.", "securite": "Jamais seul au bord de l'eau, jamais dans l'eau ; pot d'échappement brûlant ; protections auditives."}, {"titre": "La turbopompe", "duree": "10 min", "prep": "Turbopompe, engin-pompe, tuyaux d'arrivée et de sortie, sortie dirigée vers un caniveau ; faible pression.", "deroule": ["Poser la turbopompe au point le plus bas d'une fosse ou d'un bac.", "Raccorder l'arrivée (engin) et la sortie (dehors).", "Sur ordre, le conducteur ouvre l'eau doucement ; on observe l'évacuation, puis fermeture progressive."], "phrase": "L'eau de l'engin fait le travail.", "securite": "Faible pression, raccords tenus à l'écart du visage, ouverture et fermeture progressives."}], "questions": [{"q": "Quelles sont les trois familles de pompes ?", "r": "Électrique, thermique et hydraulique."}, {"q": "Pourquoi pas de motopompe dans une cave ?", "r": "Les gaz d'échappement contiennent du monoxyde de carbone, mortel."}, {"q": "Débit d'une motopompe flottante ?", "r": "Environ 1 000 litres par minute."}, {"q": "Pourquoi attacher la motopompe ?", "r": "Pour qu'elle ne parte pas et pour la récupérer sans entrer dans l'eau."}, {"q": "Quand fait-on le plein d'essence ?", "r": "Moteur arrêté et froid, loin de toute flamme."}, {"q": "Comment fonctionne un matériel hydraulique ?", "r": "Avec l'eau sous pression envoyée par l'engin."}, {"q": "Que veut dire « effet Venturi » ?", "r": "L'eau rapide qui passe dans un passage étroit crée une aspiration."}, {"q": "Quelle contrainte pour les matériels hydrauliques ?", "r": "Ils consomment l'eau de l'engin : il faut l'alimenter."}, {"q": "Que fait-on avant d'entrer dans un local inondé ?", "r": "On fait couper l'électricité (et le gaz) ; sinon on n'entre pas dans l'eau."}], "quiz": [{"q": "La motopompe flottante fonctionne avec…", "bonne": "Un moteur à essence", "fausses": ["L'électricité du bâtiment", "L'eau de l'engin", "La force des bras"], "expl": ""}, {"q": "Dans une cave fermée, on n'utilise pas la motopompe car…", "bonne": "Elle rejette du monoxyde de carbone", "fausses": ["Elle est trop lourde", "Elle fait trop peu de débit", "Elle ne flotte pas"], "expl": "Invisible, sans odeur, mortel."}, {"q": "Débit d'une motopompe flottante :", "bonne": "Environ 1 000 l/min", "fausses": ["10 l/min", "100 l/min", "10 000 l/min"], "expl": ""}, {"q": "Le plein d'essence se fait…", "bonne": "Moteur arrêté et froid", "fausses": ["Moteur en marche", "Pendant le pompage", "Dans la cave"], "expl": ""}, {"q": "L'hydro-éjecteur fonctionne grâce…", "bonne": "À l'eau sous pression de l'engin", "fausses": ["À une batterie", "À l'essence", "Au vent"], "expl": "Effet Venturi."}, {"q": "Inconvénient des matériels hydrauliques :", "bonne": "Ils consomment l'eau de l'engin", "fausses": ["Ils rejettent des gaz", "Ils ont besoin d'électricité", "Ils ne marchent pas dans la boue"], "expl": "L'engin doit être alimenté."}, {"q": "Le courant n'est pas coupé dans la cave inondée :", "bonne": "On n'entre pas dans l'eau", "fausses": ["On entre avec des bottes", "On entre vite", "On pompe à la main"], "expl": ""}, {"q": "Où trouve-t-on la turbopompe au centre ?", "bonne": "Sur les camions-citernes feux de forêt", "fausses": ["Dans le VSAV", "Sur l'échelle", "Dans le local JSP"], "expl": "FAT CCFM-BP et CCFU."}], "statut": "brouillon", "source": "Cours 2026 « L'épuisement thermique et hydraulique » (charte SDIS 34) · FAT CCFM-BP, CCFU et CCGC ; notices constructeur ; RNF JSP/JMP fiche PPBE A1 – matériels non détaillés dans les référentiels SDIS 34 : principes généraux à confirmer avec les notices du centre"}, "JSP3|Typologie des ascenseurs": {"cycle": "JSP3", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Typologie des ascenseurs", "objectif": "Reconnaître les deux familles d'ascenseurs, dire dans quels cas les pompiers interviennent et remettre dans l'ordre les 8 étapes S.E.C.U.R.I.T.E. en moins de 2 minutes, sans erreur.", "pointsCles": ["Deux familles : à traction électrique (moteur, poulie, câbles, cabine et contrepoids, le plus répandu) et hydraulique (piston poussé par de l'huile sous pression, moins de 18 m) ; un monte-charge ne transporte jamais de personnes", "Sécurités : serrures des portes palières (ne s'ouvrent que si la cabine est là), limiteur de vitesse, parachute, éclairage de secours, alarme vers l'ascensoriste, trappe dans les cabines de 8 personnes et plus", "Incendie : le public ne prend jamais l'ascenseur ; les pompiers le ramènent au rez-de-chaussée porte calée ouverte et vérifient que personne n'est dedans avant de couper le courant", "Les pompiers interviennent si la personne bloquée va mal (malaise, panique, femme enceinte), si c'est un mineur, ou si une porte palière est ouverte sans cabine ; sinon c'est l'ascensoriste (délai accepté 1 h), puis intervention payante", "Risques : malaise et panique, chute (reconnaissance, sortie de cabine), électricité de la machinerie (220 à 380 V) ; tenue complète, casque, radios : des accidents mortels sont arrivés par excès de confiance", "Procédure S.E.C.U.R.I.T.E. : Situation, Électricité, Contact, Utilisation radio, Ramener la cabine, Inviter à sortir, Technicien, Empêcher l'accès", "Le 1er équipier reste près des personnes et leur parle ; le chef d'agrès et le 2e équipier vont en machinerie ; hydraulique : on redescend la cabine avec la vanne de purge", "Sortie de préférence vers le haut (pas de chute dans la gaine) ; on ne sort jamais quelqu'un d'une cabine mal placée", "Jamais : remettre l'ascenseur en marche (c'est l'ascensoriste), débloquer un parachute, partir sans avoir vérifié toutes les portes palières", "Rassurer : parler tout de suite, poser des questions (combien ? quelqu'un a mal ? un enfant ?), expliquer, consigne « restez calmes, reculez au fond de la cabine »"], "materiel": "Lot ascenseur du VSRTU : trousseau ascenseur (clé triangulaire), avis de passage, rubalise ; clé triangulaire du trousseau du FPTGP ; 2 radios portatives ; 8 cartes S.E.C.U.R.I.T.E. ; schémas ou vidéo des deux familles d'ascenseurs ; une porte de salle pour le jeu de rôle.", "activites": [{"titre": "Câbles ou piston ?", "duree": "10 min", "prep": "Schémas, photos ou vidéo des deux familles ; cartes « organes de sécurité ».", "deroule": ["Les binômes classent les photos : traction électrique ou hydraulique.", "Ils associent chaque organe de sécurité à son rôle (serrure, limiteur, parachute, éclairage, alarme, trappe).", "Question flash : feu dans l'immeuble, je prends l'ascenseur ? (jamais)."], "phrase": "En cas d'incendie, on prend l'escalier.", "securite": ""}, {"titre": "S.E.C.U.R.I.T.E. au chrono", "duree": "10 min", "prep": "8 cartes mélangées par équipe.", "deroule": ["Remettre les 8 cartes dans l'ordre le plus vite possible.", "Pour chaque lettre, un JSP dit ce qu'on fait concrètement.", "Bonus : 3 « jamais » de l'intervention ascenseur."], "phrase": "On ne remet jamais l'ascenseur en marche.", "securite": ""}, {"titre": "Jeu de rôle : bloqué !", "duree": "15 min", "prep": "Un JSP « bloqué » derrière une porte avec une fiche secrète (nombre, état, enfant, malaise) ; 2 radios ; un « chef d'agrès » plus loin.", "deroule": ["Le 1er équipier parle à la personne : se présenter, questions, consignes.", "Il transmet par radio les informations au « chef d'agrès ».", "Le chef décide : intervention pompiers ou ascensoriste ? quel départ ?", "On rejoue en changeant la fiche (mineur, femme enceinte, porte palière ouverte)."], "phrase": "Rassurer, c'est déjà secourir.", "securite": ""}, {"titre": "Le lot ascenseur", "duree": "5 min", "prep": "Lot ascenseur du VSRTU.", "deroule": ["Découvrir les clés du trousseau, les avis de passage et la rubalise.", "Dire à quoi sert chaque élément."], "phrase": "On ferme et on balise avant de partir.", "securite": "Les JSP ne manipulent jamais une vraie machinerie ; visite seulement avec un technicien, ascenseur consigné."}], "questions": [{"q": "Quelles sont les deux grandes familles d'ascenseurs ?", "r": "À traction électrique (câbles) et hydraulique."}, {"q": "Un monte-charge peut-il transporter des personnes ?", "r": "Non, jamais."}, {"q": "Un enfant bloqué sans malaise : les pompiers viennent ?", "r": "Oui : un mineur bloqué est un motif d'intervention."}, {"q": "Une personne bloquée sans urgence : qui appelle-t-on d'abord ?", "r": "L'ascensoriste (délai accepté : 1 heure)."}, {"q": "Que veut dire le premier « E » de S.E.C.U.R.I.T.E. ?", "r": "Électricité : couper le courant de l'ascenseur en gardant la lumière."}, {"q": "Ascenseur hydraulique : comment ramener la cabine ?", "r": "On la descend avec la vanne de purge."}, {"q": "Pourquoi sortir de préférence vers le haut ?", "r": "Pour éviter la chute dans la gaine."}, {"q": "Qui remet l'ascenseur en marche ?", "r": "L'ascensoriste, jamais les pompiers."}, {"q": "Que vérifie-t-on avant de partir ?", "r": "Que toutes les portes palières sont fermées et verrouillées, et la machinerie fermée."}, {"q": "Que fait-on de l'ascenseur lors d'un incendie ?", "r": "On le ramène au rez-de-chaussée, porte calée ouverte ; le public ne le prend pas."}], "quiz": [{"q": "L'ascenseur hydraulique fonctionne avec…", "bonne": "Un piston et de l'huile sous pression", "fausses": ["Des câbles et un contrepoids", "Un moteur à essence", "Des ressorts"], "expl": "Pour les petites hauteurs (moins de 18 m)."}, {"q": "Le parachute de l'ascenseur…", "bonne": "Bloque la cabine si elle tombe", "fausses": ["Ouvre les portes", "Allume la lumière", "Appelle les pompiers"], "expl": ""}, {"q": "Feu dans l'immeuble, je…", "bonne": "Prends l'escalier", "fausses": ["Prends l'ascenseur", "Attends dans l'ascenseur", "Monte au dernier étage"], "expl": ""}, {"q": "Les pompiers interviennent si…", "bonne": "La personne bloquée est un mineur", "fausses": ["La personne veut juste sortir plus vite", "L'ascenseur fait du bruit", "Le gardien est absent"], "expl": "Ou si elle va mal, ou si une porte palière est ouverte."}, {"q": "Le « C » de S.E.C.U.R.I.T.E. veut dire…", "bonne": "Contact : parler aux personnes", "fausses": ["Câbles", "Coupure du gaz", "Casque"], "expl": ""}, {"q": "On sort les personnes de préférence…", "bonne": "Vers le haut", "fausses": ["Vers le bas", "Par la trappe toujours", "Par la gaine"], "expl": "Risque de chute dans la gaine."}, {"q": "Qui remet l'ascenseur en service ?", "bonne": "L'ascensoriste", "fausses": ["Le chef d'agrès", "Le JSP", "Le gardien"], "expl": ""}, {"q": "Tension dans la machinerie :", "bonne": "220 à 380 V", "fausses": ["12 V", "1 000 V", "Aucune"], "expl": "Risque électrique."}], "statut": "brouillon", "source": "Cours 2026 « Les ascenseurs » (JSP4, charte SDIS 34) · FOD n°14 « Procédure ascenseur bloqué » du SDIS 34 (12/2022) ; RDEB SDIS 34 v2 §5.10 ; RDMI SDIS 34 v6 §6.4 ; FAT VSRTU (lot ascenseur) – cours JSP4 utilisé pour un item JSP3"}, "JSP3|Organisation et missions du SDIS 34": {"cycle": "JSP3", "bloc": "S'impliquer dans son activité", "item": "Organisation et missions du SDIS 34", "objectif": "Expliquer qui gère, qui commande et qui envoie les secours dans l'Hérault, et citer les 4 missions du SDIS avec un exemple chacune (sans erreur, 10 min).", "pointsCles": ["Le SDIS (service départemental d'incendie et de secours) est un service public du département, financé par le Département, les communes et les intercommunalités ; un par département", "Le siège du SDIS 34 est à Vailhauquès : direction, état-major et CTA-CODIS, qui reçoit les appels et envoie les secours", "Double autorité : le conseil d'administration (élus) gère le budget, les casernes, les engins, le personnel ; le préfet est responsable des opérations", "Le directeur départemental (DDSIS) commande tous les sapeurs-pompiers de l'Hérault ; sur intervention, le maire dirige les secours dans sa commune", "Organisation : groupements fonctionnels (opérations, technique et logistique, formation, prévention, santé…), groupements territoriaux Est et Ouest, compagnies, centres dont Cruzy-Quarante", "Chiffres (sdis34.fr, à mettre à jour) : environ 400 000 appels par an, une intervention toutes les 7 min, 4 513 volontaires, 852 professionnels, 22 écoles de JSP", "Mission propre (loi, CGCT L1424-2) : prévention, protection et lutte contre les incendies ; avec les autres services : accidents, catastrophes, risques naturels et technologiques, secours et soins d'urgence", "4 missions : prévenir et évaluer les risques ; préparer les secours ; protéger les personnes, animaux, biens et environnement ; secourir, soigner, évacuer", "Partenaires : SAMU (15), police / gendarmerie (17), mairies, GRDF / Enedis, associations, préfecture", "Le collectif est une chaîne (opérateur CTA, conducteur, chef d'agrès, binômes, technicien) : entraide, bienveillance, fiabilité, communication ; devise « Courage et dévouement »"], "materiel": "Organigramme simplifié du SDIS 34 imprimé (sdis34.fr), carte de l'Hérault avec les groupements Est / Ouest, étiquettes « qui fait quoi », cartes-missions, engins du CIS pour la présentation (FPTGP, CCFU, CCFM, CCGC, FMOGP, VSRTU, VSAV), feuilles et feutres.", "activites": [{"titre": "Qui décide ? Qui commande ?", "duree": "10 min", "prep": "Étiquettes : conseil d'administration, préfet, DDSIS, CTA-CODIS, maire, chef de centre ; cartes d'actions (vote le budget, achète les engins, reçoit l'appel, commande les sapeurs-pompiers, responsable des opérations…).", "deroule": ["Par binôme, associer chaque action à la bonne étiquette.", "Construire ensemble l'organigramme du siège jusqu'au centre de Cruzy-Quarante.", "Placer le centre sur la carte de l'Hérault."], "phrase": "Les élus paient, le préfet est responsable des opérations, le directeur commande.", "securite": ""}, {"titre": "Les 4 missions en exemples", "duree": "10 min", "prep": "4 panneaux « Prévenir / Préparer / Protéger / Secourir », cartes-situations (contrôle d'un ERP, entretien des engins, feu de garrigue, malaise à domicile, formation, inondation…).", "deroule": ["Chaque JSP place une carte sous la bonne mission et explique.", "Chacun donne un exemple vécu ou observé.", "On cite les partenaires possibles pour chaque situation (SAMU, gendarmerie, mairie, GRDF…)."], "phrase": "L'incendie avant tout, et avec les autres pour tout le reste.", "securite": ""}, {"titre": "La chaîne des secours", "duree": "10 min", "prep": "Une corde ou des cartes « maillons » : opérateur CTA, conducteur, chef d'agrès, binômes, technicien.", "deroule": ["Les JSP forment la chaîne en se tenant par la main, chacun dit son rôle.", "L'animateur retire un maillon : que se passe-t-il ?", "En petits groupes : forces et faiblesses de notre section JSP, puis une action d'amélioration commune."], "phrase": "Chacun est un maillon.", "securite": "Restitution bienveillante : on parle des faits, pas des personnes."}, {"titre": "Présente ton centre", "duree": "10 min", "prep": "Engins du CIS.", "deroule": ["Les JSP les plus anciens présentent le centre à un « nouveau » : chef de centre, engins et leur rôle, section JSP.", "Préparer 3 questions pour une future visite du CTA-CODIS ou du groupement technique."], "phrase": "Courage et dévouement.", "securite": "On ne monte pas sur les engins sans un encadrant."}], "questions": [{"q": "Que veut dire SDIS ?", "r": "Service départemental d'incendie et de secours."}, {"q": "Qui finance le SDIS ?", "r": "Le Département, les communes et les intercommunalités."}, {"q": "Où est le siège du SDIS 34 ?", "r": "À Vailhauquès, près de Montpellier."}, {"q": "Qui est responsable des opérations ?", "r": "Le préfet."}, {"q": "Qui gère le budget et achète les engins ?", "r": "Le conseil d'administration (des élus)."}, {"q": "Qui commande les sapeurs-pompiers ?", "r": "Le directeur départemental (DDSIS)."}, {"q": "Que fait le CTA-CODIS ?", "r": "Il reçoit les appels et envoie les secours."}, {"q": "La mission propre des sapeurs-pompiers ?", "r": "Prévenir, protéger et lutter contre l'incendie."}, {"q": "Cite les 4 missions du SDIS.", "r": "Prévenir et évaluer les risques, préparer les secours, protéger, secourir et soigner."}, {"q": "Une force du collectif ?", "r": "L'entraide, se relayer, se protéger mutuellement."}], "quiz": [{"q": "Le SDIS est financé par…", "bonne": "Le Département et les communes", "fausses": ["Les amendes routières", "Les dons uniquement", "Les entreprises privées"], "expl": ""}, {"q": "Qui est responsable des opérations de secours dans le département ?", "bonne": "Le préfet", "fausses": ["Le chef de centre", "Le président de la République", "Le maire de Montpellier"], "expl": ""}, {"q": "Qui commande tous les sapeurs-pompiers de l'Hérault ?", "bonne": "Le directeur départemental (DDSIS)", "fausses": ["Le préfet", "Le président du conseil d'administration", "Le chef de centre"], "expl": ""}, {"q": "Le CTA-CODIS…", "bonne": "Reçoit les appels et envoie les secours", "fausses": ["Répare les engins", "Forme les JSP", "Vote le budget"], "expl": ""}, {"q": "Le siège du SDIS 34 est à…", "bonne": "Vailhauquès", "fausses": ["Béziers", "Cruzy", "Paris"], "expl": ""}, {"q": "La mission propre des sapeurs-pompiers est…", "bonne": "La lutte contre l'incendie", "fausses": ["La circulation routière", "Les soins à l'hôpital", "La surveillance des plages uniquement"], "expl": "Prévention, protection et lutte contre les incendies."}, {"q": "Dans l'Hérault, les volontaires sont…", "bonne": "Plus de 8 sapeurs-pompiers sur 10", "fausses": ["Moins de 1 sur 10", "La moitié", "Inexistants"], "expl": "4 513 SPV et 852 SPP (sdis34.fr)."}, {"q": "La devise des sapeurs-pompiers :", "bonne": "Courage et dévouement", "fausses": ["Toujours plus vite", "Toujours prêts", "Prêts à tout"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « L'organisation et les missions du SDIS » (charte SDIS 34) · sdis34.fr (« Notre organisation », « Nos missions », « Nos moyens humains », oct. 2026) ; CGCT art. L1424-2 ; RNF JSP/JMP fiche SC B1"}, "JSP3|Les moyens radio": {"cycle": "JSP3", "bloc": "Sécuriser la zone d'intervention", "item": "Les moyens radio", "objectif": "Avec un poste portatif sur le groupe d'exercice, réaliser un échange radio complet (appel, réponse, message, « reçu, terminé ») en épelant un nom avec l'alphabet phonétique et en décomposant un nombre, sans erreur de procédure.", "pointsCles": ["Numéros d'urgence : 18 pompiers, 15 SAMU, 17 police / gendarmerie, 112 européen, 114 par SMS ; les centres sont interconnectés", "Chemin de l'alerte : appel au 18 / 112 → CTA (opérateur, choix des secours) → déclenchement du centre → départ ; le CODIS suit toutes les interventions et envoie les renforts (CTA-CODIS regroupés dans l'Hérault)", "ANTARES : réseau radio national partagé (pompiers, SAMU, police, gendarmerie) ; mode relayé (antennes, loin, avec le CODIS) et mode direct (poste à poste, sur l'intervention)", "Dans l'engin : le boîtier émetteur-récepteur envoie les statuts (1 = parti, 2 = sur les lieux…) et la position ; au FPT, 6 portatifs : TPH 900 (chef d'agrès ↔ CODIS) et TTH 900 (chef d'agrès, chefs d'équipe, conducteur) avec bouton de détresse", "Utiliser le poste : allumer et vérifier (batterie, volume, groupe), écouter avant de parler, appuyer sur l'alternat, attendre 1 s, parler à 5 cm, relâcher pour écouter", "Règles d'or : préparer, faire court, parler clairement, faire répéter, rester discret (pas de nom de victime), pas de bavardage", "Alphabet phonétique (Alpha, Bravo, Charlie…) pour épeler ; décomposition des chiffres (« six comme deux fois trois »)", "Mots de procédure : parlez, reçu, terminé, attendez, répétez, je répète, collationnez, fort et clair ; on ne dit pas « oui » ou « ok »", "Appel : d'abord qui on appelle, puis qui on est (« CODIS 34 de FPT Cruzy-Quarante, parlez ») ; compte rendu : je suis, je vois, je fais, je demande", "Urgence : « Urgent, urgent, urgent », silence radio pour les autres ; bouton de détresse uniquement en cas de vrai danger, jamais en exercice"], "materiel": "Postes portatifs du centre (TTH 900 / TPH 900) chargés et réglés sur le groupe d'exercice validé par le chef de centre, boîtier émetteur-récepteur du FPTGP (démonstration des statuts), affiche de l'alphabet phonétique et des chiffres décomposés, cartes-messages (adresses de Cruzy et Quarante, plaques, numéros), bandeaux pour les yeux, plots.", "activites": [{"titre": "Découvrir le poste", "duree": "10 min", "prep": "Un portatif par binôme, éteint ; le BER du FPT.", "deroule": ["Nommer les parties : antenne, marche / volume, sélecteur de groupe, alternat, bouton de détresse, écran, batterie, micro déporté.", "Allumer, vérifier batterie, volume et groupe d'exercice.", "Au FPT : montrer l'envoi des statuts 1 et 2 (sans transmission réelle si non autorisé)."], "phrase": "Écouter avant de parler, attendre une seconde après l'appui.", "securite": "Jamais de bouton de détresse ni de groupe opérationnel."}, {"titre": "Course à l'épellation", "duree": "10 min", "prep": "Cartes avec prénoms, rues de Cruzy / Quarante, plaques, numéros.", "deroule": ["Chaque JSP épelle son prénom avec l'alphabet phonétique.", "Par équipe : épeler une rue et décomposer un numéro au poste ; l'autre équipe écrit ce qu'elle reçoit.", "Point si le message reçu est exact."], "phrase": "J'épelle, je décompose, je fais répéter.", "securite": ""}, {"titre": "Le bon échange et le compte rendu", "duree": "15 min", "prep": "Deux postes ; un JSP « CODIS 34 », un JSP « FPT Cruzy-Quarante ».", "deroule": ["Jouer l'échange complet : appel, réponse, message, « reçu, terminé ».", "Puis un compte rendu « je suis / je vois / je fais / je demande » à partir d'une carte-situation.", "Variantes : message mal reçu à faire répéter, « collationnez », message urgent avec silence radio."], "phrase": "Qui j'appelle, puis qui je suis.", "securite": "Groupe d'exercice uniquement."}, {"titre": "Le binôme aveugle", "duree": "10 min", "prep": "Parcours de plots, bandeau, deux postes.", "deroule": ["Un JSP aux yeux bandés est guidé uniquement à la radio par son binôme.", "Messages courts, « reçu » à chaque consigne.", "Débrief : qu'est-ce qui a aidé ou gêné ?"], "phrase": "Court, clair, compris.", "securite": "Parcours sans obstacle dangereux, un animateur accompagne le JSP aux yeux bandés."}], "questions": [{"q": "Quels sont les numéros d'urgence ?", "r": "18 pompiers, 15 SAMU, 17 police / gendarmerie, 112 européen, 114 par SMS."}, {"q": "Que fait le CTA ? Et le CODIS ?", "r": "Le CTA reçoit les appels et engage les secours ; le CODIS suit toutes les interventions et envoie les renforts."}, {"q": "Comment s'appelle le réseau radio des secours ?", "r": "ANTARES."}, {"q": "Différence entre mode relayé et mode direct ?", "r": "Relayé : par les antennes, sur de longues distances ; direct : de poste à poste, sur l'intervention."}, {"q": "À quoi sert le statut 2 ?", "r": "À signaler au CODIS que l'engin est arrivé sur les lieux."}, {"q": "Comment épelle-t-on « JSP » ?", "r": "Juliett, Sierra, Papa."}, {"q": "Comment décompose-t-on le 6 ?", "r": "Six comme deux fois trois."}, {"q": "Que veut dire « parlez » ?", "r": "J'ai fini, à toi de parler."}, {"q": "Qui dit-on en premier dans un appel ?", "r": "Celui qu'on appelle, puis qui on est."}, {"q": "Quand utiliser le bouton de détresse ?", "r": "Seulement en cas de vrai danger ; jamais en exercice sans accord."}], "quiz": [{"q": "Le numéro européen d'urgence est le…", "bonne": "112", "fausses": ["18", "15", "114"], "expl": "Partout en Europe, aussi depuis un portable."}, {"q": "Le réseau radio partagé par les secours s'appelle…", "bonne": "ANTARES", "fausses": ["WIFI", "GPS", "SMS"], "expl": ""}, {"q": "Le statut 1 signifie…", "bonne": "L'engin quitte le centre", "fausses": ["L'engin est sur les lieux", "L'engin est en panne", "L'engin est disponible au centre"], "expl": "Statut 2 = sur les lieux."}, {"q": "À la radio, « B » se dit…", "bonne": "Bravo", "fausses": ["Bernard", "Bateau", "Bêta"], "expl": ""}, {"q": "Pour être sûr que l'autre a bien compris, je demande…", "bonne": "« Collationnez »", "fausses": ["« Terminé »", "« Attendez »", "« Parlez »"], "expl": "Il me répète mon message."}, {"q": "Pour dire « oui, j'ai compris », on dit…", "bonne": "« Reçu »", "fausses": ["« OK »", "« Ouais »", "« D'accord »"], "expl": ""}, {"q": "Un appel commence par…", "bonne": "L'indicatif de celui qu'on appelle", "fausses": ["Son propre prénom", "« Allô »", "Le message directement"], "expl": "« CODIS 34 de FPT Cruzy-Quarante »."}, {"q": "« Urgent, urgent, urgent » signifie que…", "bonne": "Le message passe avant tous les autres", "fausses": ["On teste la radio", "On a fini de parler", "La batterie est vide"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les systèmes d'information et de communication » (charte SDIS 34) · OBNSIC / OBDSIC 34 ; RDMI SDIS 34 v6 ch.6 (liaisons tactiques, statuts) ; RDEB SDIS 34 v2 §2.10 (TTH 900, détresse) ; FAT FPTGP"}, "JSP3|L'hygiène de vie": {"cycle": "JSP3", "bloc": "S'impliquer dans son activité", "item": "L'hygiène de vie", "objectif": "Appliquer sans rappel les bons gestes d'hygiène à la fin d'une manœuvre (lingettes, mains lavées avant de boire ou manger, tenue sale à part) et composer un repas équilibré avant une compétition, en citant les repères sommeil et hydratation.", "pointsCles": ["Les toxiques des fumées entrent par la respiration, la peau (cou, visage, mains, poignets), la bouche (mains sales) et les yeux ; les suies sur la tenue continuent à libérer des toxiques", "Après une intervention, le nettoyage dépend de la salissure (RDEB) : « je sais » (pas ou peu exposé : rien ou aération), « je sens » (la tenue sent la fumée : aérer, brosser), « je vois » (suie visible : tenue en sac et changée, matériel lavé)", "Bons gestes : lingettes mains / visage / cou, mains lavées avant de boire ou manger, tenue sale dans un sac (jamais dans la cabine propre ni à la maison), douche au centre, tenue propre", "Hygiène de sportif : douche après le sport, tenue et chaussettes propres, pieds secs et ongles courts, casquette / crème / eau en été, dents brossées, casque et gants entretenus", "Assiette équilibrée : moitié légumes, féculents (énergie), protéines (muscles), plus un laitage et un fruit ; 3 repas et un goûter, petit-déjeuner obligatoire ; peu de sucreries, fritures, sodas", "Boire de l'eau avant, pendant, après le sport, par petites gorgées ; urines claires = bien hydraté ; boissons énergisantes déconseillées aux jeunes ; une gourde à chaque séance", "Sommeil : 8 à 10 heures par nuit à ton âge, écrans coupés 1 h avant, horaires réguliers, bouger chaque jour", "Addiction = ne plus pouvoir s'en passer même si ça fait du mal ; avec produits (tabac, vapoteuse, alcool, cannabis, dopage) ou sans (écrans, jeux, sport excessif, réseaux sociaux)", "Zéro alcool, zéro drogue en activité ; tabac et alcool interdits à la vente avant 18 ans", "Savoir dire non sans se justifier, demander de l'aide : parents, animateurs, infirmière scolaire, médecin, SSSM, Fil Santé Jeunes 0 800 235 236"], "materiel": "Lingettes de décontamination, sac pour tenue sale, savon et point d'eau, gourdes ; images d'aliments ou emballages pour composer des repas, assiette dessinée ; carnet de sommeil ; cartes-situations « dire non » ; tenue d'exercice salie à la craie pour l'atelier hygiène ; si possible présence d'un infirmier ou médecin du SSSM.", "activites": [{"titre": "Après la manœuvre", "duree": "10 min", "prep": "À la fin d'une manœuvre : lingettes, savon, sac, gourdes.", "deroule": ["Les JSP appliquent les 5 bons gestes dans l'ordre : lingettes, mains lavées, tenue sale à part, (douche), tenue propre.", "Un observateur coche la check-list.", "Cartes « je sais / je sens / je vois » : les binômes associent une situation au bon nettoyage."], "phrase": "Mains propres avant de manger ou de boire.", "securite": ""}, {"titre": "Mon repas de compétition", "duree": "15 min", "prep": "Images d'aliments, assiette dessinée.", "deroule": ["Par binôme, composer le repas de la veille et le repas 2 à 3 h avant une épreuve.", "Présenter : où sont les légumes, les féculents, les protéines, le laitage, le fruit, l'eau ?", "Bonus : classer les boissons (eau, soda, boisson énergisante, boisson de l'effort)."], "phrase": "Bien manger, bien boire, bien dormir : le carburant du pompier.", "securite": "Aucune remarque sur le physique d'un JSP ; on parle d'aliments, pas de poids."}, {"titre": "Savoir dire non", "duree": "10 min", "prep": "Cartes-situations : on te propose une cigarette, une vapoteuse, une bière, un « complément miracle »…", "deroule": ["En petits groupes, un JSP propose, l'autre refuse (« Non merci, je fais du sport »).", "On change les rôles ; on liste les phrases qui marchent.", "On termine par les personnes à qui demander de l'aide."], "phrase": "Un vrai ami respecte mon choix.", "securite": "Rester bienveillant, ne pas stigmatiser ; toute confidence est écoutée et remontée au chef de section / SSSM."}, {"titre": "Mon carnet de sommeil", "duree": "5 min", "prep": "Carnet ou feuille pour la semaine.", "deroule": ["Expliquer le carnet : heure de coucher, de lever, écrans le soir.", "Retour à la séance suivante, sans jugement : qui atteint 8 à 10 h ?"], "phrase": "Le corps récupère et grandit la nuit.", "securite": ""}], "questions": [{"q": "Par où les toxiques des fumées entrent-ils dans le corps ?", "r": "Respiration, peau, bouche, yeux."}, {"q": "Que fait-on en rentrant au centre après une intervention ?", "r": "On remet l'engin en état, puis on prend une douche."}, {"q": "Où range-t-on une tenue sale ?", "r": "Dans un sac fermé, jamais dans la cabine propre ni à la maison."}, {"q": "Que veut dire « je vois » ?", "r": "Des traces de suie sont visibles : tenue en sac et changée, matériel lavé."}, {"q": "La moitié de l'assiette, c'est quoi ?", "r": "Des légumes."}, {"q": "Comment savoir si on est bien hydraté ?", "r": "Les urines sont claires."}, {"q": "Pourquoi éviter les boissons énergisantes ?", "r": "Trop de caféine et de sucre pour les jeunes."}, {"q": "Combien d'heures de sommeil à ton âge ?", "r": "8 à 10 heures."}, {"q": "Qu'est-ce qu'une addiction ?", "r": "Ne plus pouvoir s'en passer, même si ça fait du mal."}, {"q": "À qui demander de l'aide ?", "r": "Parents, animateurs, infirmière scolaire, médecin, SSSM, Fil Santé Jeunes."}], "quiz": [{"q": "Les toxiques des fumées peuvent entrer par…", "bonne": "La respiration, la peau, la bouche et les yeux", "fausses": ["Uniquement la bouche", "Uniquement les cheveux", "Nulle part si on porte un casque"], "expl": ""}, {"q": "Une tenue avec des traces de suie visibles, c'est…", "bonne": "« Je vois »", "fausses": ["« Je sais »", "« Je sens »", "Rien à faire"], "expl": "Tenue en sac et changée."}, {"q": "Avant de manger après une manœuvre, je…", "bonne": "Me lave les mains", "fausses": ["Mange vite", "Garde mes gants", "M'essuie sur ma tenue"], "expl": ""}, {"q": "Dans une assiette équilibrée, la moitié est faite de…", "bonne": "Légumes", "fausses": ["Frites", "Bonbons", "Pain uniquement"], "expl": ""}, {"q": "Combien d'heures de sommeil à ton âge ?", "bonne": "8 à 10 heures", "fausses": ["4 à 5 heures", "6 heures", "12 à 14 heures"], "expl": ""}, {"q": "Les boissons énergisantes sont…", "bonne": "Déconseillées aux jeunes", "fausses": ["Idéales pour le sport", "Meilleures que l'eau", "Obligatoires en compétition"], "expl": "Trop de caféine et de sucre."}, {"q": "Avant de dormir, les écrans…", "bonne": "Se coupent une heure avant", "fausses": ["Aident à s'endormir", "Se gardent toute la nuit", "N'ont aucun effet"], "expl": ""}, {"q": "Une addiction, c'est…", "bonne": "Ne plus pouvoir s'en passer", "fausses": ["Faire du sport une fois par semaine", "Avoir faim à midi", "Aimer un bon repas"], "expl": "Avec ou sans produit."}], "statut": "brouillon", "source": "Cours 2026 « L'hygiène de vie » (charte SDIS 34) · RNF JSP/JMP fiche APS A2 ; RDEB SDIS 34 v2 §3.15 et chapitre 4 (nettoyage, lot DECOPI)"}, "JSP3|Préserver son potentiel psychologique": {"cycle": "JSP3", "bloc": "S'impliquer dans son activité", "item": "Préserver son potentiel psychologique", "objectif": "Citer 3 signes du stress et 3 personnes ressources, et réaliser 4 cycles de respiration carrée de façon autonome.", "pointsCles": ["Le stress est une alarme du corps : normal et utile s'il est contrôlé (alerte, rapidité, concentration), dangereux s'il déborde (panique, blocage, erreurs, oubli de la sécurité)", "Signes : dans le corps (cœur qui s'emballe, souffle court, mains moites, tremblements, ventre noué), les émotions (peur, colère, envie de pleurer), la tête (idées confuses, vision « en tunnel »), le comportement (agitation ou blocage)", "Causes chez le pompier : être débutant, interventions difficiles (victimes, enfants, collègue blessé), milieu difficile (chaleur, bruit, fumée, sous ARI), trop d'activité, violence, la vie à côté", "Avant : s'entraîner jusqu'aux automatismes, anticiper, apprendre des retours d'expérience (RETEX), prendre soin de soi (sommeil, alimentation, sport)", "Pendant : respiration carrée (inspirer 4, bloquer 4, souffler 4, bloquer 4 ; 3 à 4 cycles), suivre la procédure, compter sur son binôme, se parler positivement, dire stop au chef si besoin", "Un porteur d'ARI qui perd son calme respire plus vite et épuise son air plus vite", "Après : en parler à l'équipe, se reposer, faire du sport, retrouver ses proches ; signes d'alerte : cauchemars, images qui reviennent, isolement, tristesse ou colère qui durent", "Personnes ressources : camarades, animateurs et chefs, SSSM (médecins, infirmiers, psychologues du SDIS), famille ; en parler est un réflexe de professionnel, pas une faiblesse", "Veiller les uns sur les autres : un camarade change → aller vers lui, écouter sans juger, prévenir un animateur ; face à la violence : garder ses distances, alerter son chef, signaler"], "materiel": "Salle calme, chronomètre, matériel d'un geste connu (corde pour un nœud ou tapis pour la PLS), cartes « signes du stress » et « personnes ressources », affiche de la respiration carrée ; si possible intervention d'un membre du SSSM.", "activites": [{"titre": "Mon stress, mes signes", "duree": "10 min", "prep": "Cartes « signes » à classer en 4 colonnes : corps, émotions, tête, comportement.", "deroule": ["Chacun cite un signe qu'il ressent avant un contrôle ou une compétition.", "En binôme, classer les cartes dans les 4 colonnes.", "Discussion : bon stress ou stress débordé ?"], "phrase": "Le but n'est pas de ne jamais stresser, mais de garder le contrôle.", "securite": "Sujet sensible : on ne force personne à parler de son vécu."}, {"titre": "Respiration carrée", "duree": "5 min", "prep": "Salle calme, affiche des 4 temps.", "deroule": ["Tous ensemble, yeux fermés : 4 cycles guidés (inspirer 4, bloquer 4, souffler 4, bloquer 4).", "Chacun dit comment il se sent après."], "phrase": "Calmer sa respiration, c'est calmer son cœur et économiser son air.", "securite": ""}, {"titre": "Sous pression", "duree": "15 min", "prep": "Geste connu (nœud, PLS sur un camarade volontaire ou mannequin), chronomètre.", "deroule": ["Un JSP réalise le geste chronométré pendant que le groupe l'encourage bruyamment.", "On recommence après une respiration carrée.", "Débrief : qu'as-tu ressenti ? qu'est-ce qui t'a aidé à rester concentré ?"], "phrase": "Sous stress, on fait ce qu'on a appris.", "securite": "Encouragements positifs uniquement, jamais de moquerie."}, {"titre": "Qui peut m'aider ?", "duree": "10 min", "prep": "Situations courtes : un camarade s'isole depuis une intervention, un JSP fait des cauchemars, quelqu'un est insulté sur intervention…", "deroule": ["Par binôme, dire ce qu'on fait et à qui on en parle.", "Construire ensemble la liste des personnes ressources (camarades, animateurs, chefs, SSSM, famille)."], "phrase": "En parler, c'est un réflexe de professionnel.", "securite": "Proposer un échange individuel à tout JSP qui semble touché."}], "questions": [{"q": "Le stress, c'est grave ?", "r": "Non, c'est normal ; il faut apprendre à le gérer."}, {"q": "Cite deux signes du stress dans le corps.", "r": "Cœur qui s'emballe, mains moites, souffle court, tremblements, ventre noué."}, {"q": "Cite deux causes de stress chez le sapeur-pompier.", "r": "Être débutant, une intervention difficile, la chaleur ou la fumée, la fatigue, la violence."}, {"q": "Comment se préparer avant ?", "r": "S'entraîner, anticiper, étudier les RETEX, avoir une bonne hygiène de vie."}, {"q": "Comment fait-on la respiration carrée ?", "r": "4 temps de 4 secondes : inspirer, bloquer, souffler, bloquer."}, {"q": "Pourquoi rester calme sous ARI ?", "r": "Perdre son calme fait respirer plus vite et épuise l'air."}, {"q": "Un camarade s'isole depuis une intervention : que fais-tu ?", "r": "Je vais vers lui, je l'écoute sans juger et j'en parle à un animateur."}, {"q": "Qui sont les psychologues du SDIS ?", "r": "Le SSSM (service de santé et de secours médical)."}, {"q": "Face à une personne agressive sur intervention ?", "r": "Je garde mes distances, je me protège, j'alerte mon chef et je signale."}], "quiz": [{"q": "Le stress, c'est…", "bonne": "Une alarme normale du corps", "fausses": ["Une maladie grave", "Une faiblesse", "Interdit chez les pompiers"], "expl": "Utile s'il est contrôlé."}, {"q": "Un signe du stress dans le corps :", "bonne": "Le cœur qui s'emballe", "fausses": ["Avoir chaud au soleil", "Bien dormir", "Avoir faim à midi"], "expl": ""}, {"q": "La respiration carrée se fait en…", "bonne": "4 temps", "fausses": ["2 temps", "10 temps", "1 seul souffle"], "expl": "Inspirer, bloquer, souffler, bloquer."}, {"q": "Pour être moins stressé en intervention, le mieux est de…", "bonne": "S'entraîner jusqu'aux automatismes", "fausses": ["Ne jamais y penser", "Improviser", "Éviter les manœuvres"], "expl": ""}, {"q": "Je ne me sens plus capable pendant l'intervention :", "bonne": "Je le dis au chef d'agrès", "fausses": ["Je ne dis rien", "Je pars seul", "Je fais semblant"], "expl": ""}, {"q": "Les psychologues du SDIS font partie…", "bonne": "Du SSSM", "fausses": ["Du CTA", "Du groupement technique", "De la mairie"], "expl": ""}, {"q": "Parler de ce qui ne va pas, c'est…", "bonne": "Un réflexe de professionnel", "fausses": ["Une faiblesse", "Interdit", "Inutile"], "expl": ""}, {"q": "Un camarade s'isole et s'énerve depuis une intervention :", "bonne": "Je vais vers lui et j'en parle à un animateur", "fausses": ["Je me moque de lui", "Je l'évite", "J'attends que ça passe sans rien dire"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La gestion du stress » (JSP4, charte SDIS 34) · RDEB SDIS 34 v2 §1.6 et §2.3 (préparation psychologique) ; RDSMES SDIS 34 v2 (gestion de l'affect) ; RNF JSP/JMP fiche SC B2 – cours JSP4 utilisé pour un item JSP3"}, "JSP3|Les risques majeurs": {"cycle": "JSP3", "bloc": "Diffuser la culture du service public", "item": "Les risques majeurs", "objectif": "Définir un risque majeur, citer 3 risques de Cruzy-Quarante, reconnaître le signal de la sirène (début, fin, essai) et donner les 4 réflexes de base, sans erreur.", "pointsCles": ["Risque majeur = un aléa (crue, feu, séisme…) qui touche des enjeux (personnes, maisons, routes) ; rare mais très grave (beaucoup de victimes, secours débordés)", "Familles : météorologique (pluies, orages, tempête, neige), sismique, feu de forêt, industriel / transport de matières dangereuses ; chacune a ses causes et ses conséquences", "Chez nous (Géorisques, DICRIM) : inondation, feu de forêt, transport de matières dangereuses, mouvements de terrain, séisme faible (zone 2), sécheresse et canicule", "Épisode méditerranéen (automne) : orages bloqués qui donnent des crues éclair ; 30 cm d'eau suffisent à emporter une voiture : on ne traverse jamais une route inondée", "Vigilance Météo-France : vert, jaune (attentifs), orange (très vigilants), rouge (vigilance absolue)", "Moyens d'alerte : sirène (SNA), FR-Alert sur les téléphones même en silencieux, radio, panneaux lumineux (PMV), porte-à-porte, réseaux sociaux officiels uniquement", "Sirène : début = 3 sons montants et descendants de 1 min 41 s séparés de 5 s ; fin = son continu de 30 s ; essai le 1er mercredi du mois à midi", "Réflexes : se mettre à l'abri, écouter la radio, ne pas téléphoner, ne pas aller chercher les enfants à l'école ; puis le bon geste selon le risque (étage si inondation, maison volets fermés si feu de forêt, calfeutrer si nuage toxique, sous une table si séisme)", "Plan familial de mise en sûreté et kit d'urgence pour 3 jours (radio et lampe à piles, eau, nourriture, médicaments, papiers, couverture)", "Le maire informe (DICRIM) et organise la commune (plan communal de sauvegarde) ; le préfet informe le département (DDRM) et dirige les secours si c'est grave ; le SDIS analyse les risques (SDACR)"], "materiel": "Enregistrement officiel du signal national d'alerte, tablette avec Géorisques et la carte de vigilance Météo-France du jour, DICRIM de Cruzy et de Quarante, modèle de plan familial de mise en sûreté, cartes-risques et cartes-réflexes, feuilles et feutres pour l'affiche.", "activites": [{"titre": "Aléa + enjeux = risque", "duree": "10 min", "prep": "Cartes « aléas » (crue, feu, séisme, nuage toxique) et cartes « enjeux » (désert, village, école, forêt vide).", "deroule": ["Les binômes associent un aléa et un enjeu : risque majeur ou non ?", "Recherche sur Géorisques (« Mes risques ») à partir de l'adresse du centre ou du collège.", "On compare avec le DICRIM de la commune."], "phrase": "Le même orage sur un village : risque majeur.", "securite": ""}, {"titre": "La sirène", "duree": "10 min", "prep": "Enregistrement officiel du signal (début, fin, essai) et carte de vigilance du jour.", "deroule": ["Faire écouter les trois signaux dans le désordre : les JSP disent lequel c'est.", "Ils donnent le bon réflexe : à l'abri, radio, pas de téléphone.", "Lire ensemble la carte de vigilance du jour : quelle couleur pour l'Hérault ?"], "phrase": "Je l'entends : je me mets à l'abri et j'écoute la radio.", "securite": ""}, {"titre": "Le bon geste au bon moment", "duree": "10 min", "prep": "4 panneaux (inondation, feu de forêt, nuage toxique, séisme), cartes-réflexes mélangées.", "deroule": ["Les JSP placent chaque carte sous le bon risque (monter à l'étage, volets fermés, calfeutrer, sous une table…).", "Piège : « je traverse la route inondée en voiture, je connais le chemin » → jamais (30 cm suffisent).", "On ajoute les 4 réflexes de base communs à tous les risques."], "phrase": "On ne traverse jamais une route inondée.", "securite": ""}, {"titre": "Le messager de sécurité civile", "duree": "15 min", "prep": "Feuilles, feutres, modèle de plan familial.", "deroule": ["Par groupe, réaliser une affiche « bons réflexes » pour le collège.", "Ou jouer l'annonce d'une alerte inondation à la classe (JSP / assistant de sécurité).", "Travail à la maison : remplir le plan familial de mise en sûreté avec ses parents."], "phrase": "Un JSP transmet la culture de sécurité civile autour de lui.", "securite": ""}], "questions": [{"q": "Qu'est-ce qu'un risque majeur ?", "r": "Un événement rare mais très grave, qui touche beaucoup de personnes."}, {"q": "Cite 3 risques de notre secteur.", "r": "Inondation, feu de forêt, transport de matières dangereuses, mouvements de terrain, séisme faible."}, {"q": "Qu'est-ce qu'un épisode méditerranéen ?", "r": "Des orages d'automne bloqués par le relief qui donnent des pluies énormes et des crues éclair."}, {"q": "Combien d'eau pour emporter une voiture ?", "r": "Environ 30 cm."}, {"q": "Que fait-on quand la sirène sonne ?", "r": "Se mettre à l'abri et écouter la radio."}, {"q": "Comment reconnaît-on la fin d'alerte ?", "r": "Un son continu de 30 secondes."}, {"q": "Quand a lieu l'essai de la sirène ?", "r": "Le 1er mercredi du mois à midi."}, {"q": "Pourquoi ne pas téléphoner pendant l'alerte ?", "r": "Pour laisser les lignes libres aux secours."}, {"q": "Pourquoi ne pas aller chercher les enfants à l'école ?", "r": "L'école les protège avec son plan de mise en sûreté ; on ne s'expose pas sur la route."}, {"q": "Que contient le kit d'urgence ?", "r": "Radio et lampe à piles, eau et nourriture pour 3 jours, médicaments, papiers, vêtements chauds."}], "quiz": [{"q": "Un risque majeur est…", "bonne": "Rare mais très grave", "fausses": ["Fréquent et sans gravité", "Toujours industriel", "Limité à une seule personne"], "expl": ""}, {"q": "Dans notre secteur, un risque très présent en automne :", "bonne": "Les inondations (épisodes méditerranéens)", "fausses": ["Les avalanches", "Les cyclones", "Les volcans"], "expl": ""}, {"q": "Combien d'eau suffit à emporter une voiture ?", "bonne": "Environ 30 cm", "fausses": ["2 m", "1 m", "5 cm"], "expl": "On ne traverse jamais une route inondée."}, {"q": "La sirène sonne (son montant et descendant) : je…", "bonne": "Me mets à l'abri et j'écoute la radio", "fausses": ["Sors voir ce qui se passe", "Téléphone à mes amis", "Vais chercher mon frère à l'école"], "expl": ""}, {"q": "L'essai de la sirène a lieu…", "bonne": "Le 1er mercredi du mois à midi", "fausses": ["Tous les jours à 8 h", "Le dimanche soir", "Une fois par an"], "expl": ""}, {"q": "FR-Alert, c'est…", "bonne": "Un message d'alerte sur les téléphones de la zone", "fausses": ["Une application de jeux", "Une sirène de pompiers", "Une radio locale"], "expl": "Il s'affiche même en mode silencieux."}, {"q": "En vigilance rouge, il faut…", "bonne": "Une vigilance absolue", "fausses": ["Rien faire de spécial", "Juste être un peu attentif", "Partir en voiture"], "expl": ""}, {"q": "Nuage toxique : le bon réflexe est de…", "bonne": "S'enfermer et boucher portes et aérations", "fausses": ["Sortir respirer", "Allumer un feu", "Ouvrir toutes les fenêtres"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les risques majeurs et l'information de la population » (charte SDIS 34) · RNF JSP/JMP fiche SC A1 ; DDRM de l'Hérault, DICRIM de Cruzy et Quarante, Géorisques, IFFO-RME"}, "JSP4|Matériel de forcement et de dégagement": {"cycle": "JSP4", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Matériel de forcement et de dégagement", "objectif": "Pour 6 situations (cadenas, porte d'appartement, vitre de voiture, ceinture bloquée, branche sur la route, local dont la clé est disponible), choisir la solution la moins destructrice et l'outil du FPTGP ou du VSRTU, puis réaliser sur mannequin une traction par les poignets et par les chevilles — 25 min, aucune erreur de sécurité.", "pointsCles": ["Forcer, c'est le dernier recours : d'abord ouvrir sans casser (poignée, autre porte, fenêtre ouverte, clé d'un voisin ou du gardien, trousseau opérationnel du VSRTU)", "C'est le chef d'agrès qui décide de forcer et comment ; on choisit ce qui casse le moins (protéger les biens) et on laisse un avis de passage si personne n'est là", "Trois façons d'ouvrir : faire levier (grande pince, Halligan tool, outil de force), frapper (masse, hache à plat de frappe), couper (coupe-boulons, scie, découpeuse) ; on combine souvent : la masse enfonce le Halligan, puis on fait levier", "FPTGP : Halligan tools, grande pince, masse, coupe-boulons grand modèle, 3 outils de force et de déblai (sur la bouteille d'ARI des chefs d'équipe, pour ouvrir pendant la reconnaissance), découpeuse thermique à disque diamant, outil hydraulique", "VSRTU : sacoche secours techniques (brise-vitre, coupe-ceinture, pince coupante, outils pour retirer les garnitures), coupe pare-brise, scie sabre et outil combiné sur batterie, 2 étais à sangle, lot de gestion du verre, tronçonneuse avec pantalon de protection, trousseau opérationnel", "Le Halligan tool : lame et pointe (glisser, soulever, percer), fourche (levier entre la porte et le cadre), corps (on frappe dessus) ; avec une sangle, il sert aussi à sortir un pompier en difficulté", "Sécurité : visière baissée, gants, personne dans l'axe de l'outil ni derrière la porte, pas de découpeuse s'il y a du gaz ou de l'essence, tronçonneuse et découpeuse réservées aux pompiers formés, outil rangé propre et en état", "Dégagement d'urgence (GTO Sauvetages et mises en sécurité) : déplacer la victime de quelques mètres, en quelques secondes, vers un lieu sûr — seulement si le danger est réel et immédiat ; ensuite on surveille la victime", "Sans matériel : traction par les poignets, par les chevilles, sortie de véhicule, avec un équipier-relais, « porter pompier » ; avec matériel : plan dur, grande sangle du LSPCC, Halligan tool + sangle (pour un pompier)", "Victime coincée dans une voiture : sécuriser (balisage, moteur coupé, calage avec les étais), rassurer et protéger la victime, gérer le verre, créer de l'espace — la désincarcération est réservée aux pompiers formés, les JSP observent"], "materiel": "FPTGP et VSRTU coffres ouverts (Halligan tool, grande pince, masse, coupe-boulons, outil de force et de déblai, sacoche secours techniques, coupe pare-brise, étais à sangle), cartes situations « Quel outil ? », mannequin de secourisme, plan dur ou grande sangle du LSPCC (démonstration), gants pour tous, casques avec visière.", "activites": [{"titre": "La voisine ne répond plus", "duree": "5 min", "prep": "Situation d'accroche du cours.", "deroule": ["L'animateur lit : volets fermés depuis deux jours, la voisine ne répond pas, porte fermée à clé. Tu fais quoi en premier ?", "Attendu : frapper, appeler, faire le tour (fenêtre, porte arrière), chercher une clé (famille, voisin, gardien).", "Si on doit entrer vite : c'est le chef qui décide comment, en cassant le moins possible."], "phrase": "Forcer, c'est le dernier recours.", "securite": ""}, {"titre": "Chasse aux outils", "duree": "15 min", "prep": "Au pied du FPTGP et du VSRTU, coffres ouverts.", "deroule": ["L'animateur nomme un outil ; le binôme le montre sans le sortir.", "Il explique à quoi il sert (levier, frappe ou coupe) et la règle de sécurité.", "Zoom sur le Halligan tool (lame, pointe, fourche, corps) et sur les outils de force portés sur la bouteille d'ARI des chefs d'équipe."], "phrase": "", "securite": "Aucun outil motorisé, thermique ni hydraulique pour les JSP ; outils à main seulement à vide, sans frapper, sous le contrôle d'un animateur ; gants pour tous ; engins à l'arrêt."}, {"titre": "Quel outil ?", "duree": "10 min", "prep": "Cartes : cadenas de portail, porte d'appartement, vitre de voiture, ceinture bloquée, branche sur la route, local dont la clé est disponible.", "deroule": ["Chaque binôme tire une carte, choisit l'outil et explique.", "Correction : coupe-boulons ; Halligan tool + masse (sur ordre) ; brise-vitre ; coupe-ceinture ; tronçonneuse (pompier formé) ; trousseau ou clé du voisin, sans rien casser."], "phrase": "La meilleure ouverture est celle qui casse le moins.", "securite": ""}, {"titre": "Dégagement d'urgence", "duree": "15 min", "prep": "Mannequin au sol, espace dégagé ; plan dur ou grande sangle du LSPCC pour la démonstration.", "deroule": ["Rappel : seulement si le danger est réel et immédiat.", "Sur mannequin, sur quelques mètres : traction par les poignets, puis par les chevilles.", "Après le dégagement : on surveille la victime.", "L'animateur montre (sans faire pratiquer) le dégagement avec un plan dur ou la grande sangle."], "phrase": "Quelques mètres, quelques secondes, si le danger est réel et immédiat.", "securite": "Mannequin uniquement ; gants ; jambes fléchies, dos droit ; sol dégagé."}], "questions": [{"q": "Avant de forcer une porte, je fais quoi ?", "r": "J'essaie d'ouvrir sans casser et j'attends l'ordre du chef."}, {"q": "Quelles sont les 3 façons d'ouvrir ?", "r": "Faire levier, frapper, couper."}, {"q": "Quel outil pour un cadenas ?", "r": "Le coupe-boulons."}, {"q": "Où sont les outils de force du FPTGP ?", "r": "Sur la bouteille d'ARI des chefs d'équipe."}, {"q": "Cite les parties du Halligan tool.", "r": "La lame, la pointe, la fourche et le corps sur lequel on frappe."}, {"q": "Pourquoi pas de découpeuse s'il y a de l'essence ou du gaz ?", "r": "Elle fait des étincelles."}, {"q": "Qu'est-ce qu'un dégagement d'urgence ?", "r": "Déplacer vite une victime de quelques mètres vers un lieu sûr."}, {"q": "Quand le faire ?", "r": "Seulement si le danger est réel et immédiat."}, {"q": "Victime coincée dans une voiture : les 4 étapes ?", "r": "Sécuriser, rassurer et protéger, gérer le verre, créer de l'espace."}], "quiz": [{"q": "Avant de forcer une porte :", "bonne": "J'essaie d'ouvrir sans casser et j'attends l'ordre du chef", "fausses": ["Je casse la fenêtre directement", "Je décide seul pour gagner du temps", "J'attends le lendemain"], "expl": ""}, {"q": "Les 3 façons d'ouvrir :", "bonne": "Faire levier, frapper, couper", "fausses": ["Pousser, tirer, sauter", "Chauffer, geler, mouiller", "Crier, frapper, attendre"], "expl": ""}, {"q": "Pour un cadenas de portail :", "bonne": "Le coupe-boulons", "fausses": ["Le brise-vitre", "Le coupe-ceinture", "Le coupe pare-brise"], "expl": ""}, {"q": "Les outils de force et de déblai du FPTGP sont :", "bonne": "Sur la bouteille d'ARI des chefs d'équipe", "fausses": ["Dans la cabine du conducteur", "Dans le VSAV", "Au CIS"], "expl": "Pour ouvrir pendant la reconnaissance."}, {"q": "Avec une sangle, le Halligan tool sert aussi à :", "bonne": "Sortir un pompier en difficulté", "fausses": ["Couper une ceinture", "Éclairer une pièce", "Mesurer une distance"], "expl": ""}, {"q": "Pas de découpeuse thermique quand :", "bonne": "Il y a du gaz ou de l'essence", "fausses": ["Il fait jour", "La porte est en bois", "Il y a des témoins"], "expl": "Risque d'étincelles."}, {"q": "Un dégagement d'urgence se fait :", "bonne": "Seulement si le danger est réel et immédiat", "fausses": ["Pour toutes les victimes", "Quand la victime le demande", "Pour partir plus vite"], "expl": ""}, {"q": "La désincarcération d'une victime coincée :", "bonne": "Est réservée aux pompiers formés", "fausses": ["Peut être faite par un JSP", "Se fait sans caler la voiture", "Commence par tirer la victime"], "expl": "Les JSP observent."}], "statut": "brouillon", "source": "Cours 2026 « Le matériel de forcement et de dégagement » (charte SDIS 34) · FAT SDIS 34 FPTGP et VSRTU (04/2026) ; GTO « Sauvetages et mises en sécurité » (dégagements d'urgence, sauvetage par un binôme avec la hache Halligan tool) – à valider : item sans fiche RNF JSP/JMP dédiée ; règles d'ouverture de porte et techniques d'emploi (connaissances générales, chef de centre) ; présence des forces de l'ordre pour une ouverture de domicile (règle locale) ; principes de désincarcération avec un formateur secours routier"}, "JSP4|Procédure d'intervention sur ascenseur": {"cycle": "JSP4", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Procédure d'intervention sur ascenseur", "objectif": "Remettre dans l'ordre et expliquer les 8 étapes S.E.C.U.R.I.T.E. en moins de 2 minutes, puis en jeu de rôle rassurer une personne « bloquée » et faire remonter par radio son nombre et son état au chef d'agrès — 15 min, 1 erreur admise.", "pointsCles": ["Deux familles (FOD n°14) : à traction électrique (moteur, poulie, câbles, contrepoids, le plus répandu) et hydraulique (piston poussé par de l'huile, moins de 18 m) ; un monte-charge ne transporte jamais de personnes", "Sécurités de l'ascenseur : serrures des portes palières, limiteur de vitesse, parachute, éclairage de secours, alarme, trappe dans les grandes cabines (8 personnes et plus)", "En incendie : jamais l'ascenseur pour le public ; les pompiers le ramènent au RDC porte calée ouverte et vérifient que personne n'est dedans avant de couper le courant", "Les pompiers interviennent si la personne bloquée va mal (malaise, panique, femme enceinte), si c'est un mineur, si une porte palière est ouverte sans cabine, ou si l'ascensoriste ne vient pas (délai accepté 1 h, intervention alors payante)", "Risques : malaise et panique, chute dans la gaine, électricité dans la machinerie (220 à 380 V) ; tenue complète, casque, radio pour tous : des accidents mortels sont arrivés par excès de confiance", "S.E.C.U.R.I.T.E. : Situation, Électricité (couper, garder la lumière), Contact, Utilisation radio, Ramener la cabine à un étage, Inviter à sortir (de préférence vers le haut), Technicien, Empêcher l'accès", "Le 1er équipier reste près des victimes et leur parle ; le chef d'agrès et le 2e équipier vont en machinerie ; hydraulique : on descend la cabine avec la vanne de purge", "Jamais : remettre l'ascenseur en marche (c'est l'ascensoriste), sortir quelqu'un d'une cabine mal placée, débloquer un parachute, partir sans avoir vérifié toutes les portes palières", "Rassurer : « Les pompiers sont là, on va vous sortir », combien êtes-vous ? quelqu'un a mal ? un enfant ? « reculez au fond de la cabine »", "Compte rendu : adresse et bâtiment, n° de l'ascenseur, nombre de personnes mises en sécurité, ascensoriste présent ou non, portes vérifiées, signalisation posée"], "materiel": "8 cartes S.E.C.U.R.I.T.E., lot ascenseur du VSRTU (trousseau de clés, avis de passage, rubalise), 2 radios portatives (éteintes ou canal d'exercice), une porte de local pour le jeu de rôle, photos d'une machinerie (traction et hydraulique), chronomètre.", "activites": [{"titre": "Le mot S.E.C.U.R.I.T.E.", "duree": "10 min", "prep": "8 cartes mélangées par équipe, chronomètre.", "deroule": ["Au top, chaque équipe remet les cartes dans l'ordre.", "Elle explique chaque lettre en une phrase.", "Question bonus : pourquoi le « E » d'Électricité vient-il avant de bouger la cabine ?"], "phrase": "Une seule porte palière mal fermée peut tuer quelqu'un.", "securite": ""}, {"titre": "Le jeu de rôle", "duree": "15 min", "prep": "Un JSP « bloqué » derrière une porte avec une carte secrète (nombre, état, enfant, malaise), radios.", "deroule": ["Le « 1er équipier » parle à travers la porte : il se présente, rassure, pose les questions.", "Il transmet par radio les infos au « chef d'agrès ».", "Le chef d'agrès dit si l'intervention relève des pompiers et si un VSAV est nécessaire."], "phrase": "Rassurer, c'est déjà secourir.", "securite": "Radios éteintes ou canal d'exercice validé."}, {"titre": "Le lot ascenseur", "duree": "10 min", "prep": "Lot ascenseur du VSRTU.", "deroule": ["Les JSP découvrent les clés du trousseau et leur usage.", "Ils citent ce qu'on laisse en partant (avis de passage, rubalise).", "Rappel : on ne manipule jamais une vraie machinerie."], "phrase": "", "securite": "Aucune manipulation d'ascenseur réel ; visite de machinerie seulement avec le gestionnaire et un technicien, ascenseur consigné."}], "questions": [{"q": "Quelles sont les deux grandes familles d'ascenseurs ?", "r": "À traction électrique (câbles) et hydraulique."}, {"q": "Un enfant bloqué sans malaise : les pompiers viennent-ils ?", "r": "Oui : un mineur bloqué est un motif d'intervention."}, {"q": "Que veut dire le « E » de S.E.C.U.R.I.T.E. au début ?", "r": "Électricité : couper le courant."}, {"q": "Ascenseur hydraulique : comment ramener la cabine ?", "r": "On la descend avec la vanne de purge."}, {"q": "Pourquoi sortir de préférence vers le haut ?", "r": "Pour éviter la chute dans la gaine."}, {"q": "Qui remet l'ascenseur en marche ?", "r": "L'ascensoriste, jamais les pompiers."}, {"q": "Que fait-on si la cabine est bloquée par le parachute ?", "r": "On attend le dépanneur ; urgence vitale : sortie par l'étage du dessus sans bouger la cabine."}, {"q": "Que vérifie-t-on avant de partir ?", "r": "Que toutes les portes palières sont fermées et verrouillées, machinerie fermée."}], "quiz": [{"q": "En cas d'incendie, l'ascenseur pour le public :", "bonne": "Jamais", "fausses": ["Toujours", "Seulement pour descendre", "Seulement la nuit"], "expl": "On prend l'escalier."}, {"q": "Une porte palière ouverte sans cabine derrière :", "bonne": "Les pompiers interviennent", "fausses": ["On attend l'ascensoriste demain", "Ce n'est pas grave", "On la laisse ouverte pour aérer"], "expl": "Risque de chute dans la gaine."}, {"q": "Dans S.E.C.U.R.I.T.E., le « C » veut dire…", "bonne": "Contact avec les personnes", "fausses": ["Couper la cabine", "Casser la porte", "Clé"], "expl": ""}, {"q": "Avant de bouger la cabine, on…", "bonne": "Coupe le courant de l'ascenseur", "fausses": ["Remet l'ascenseur en marche", "Ouvre la trappe du plafond", "Force la porte cabine"], "expl": ""}, {"q": "La cabine n'est pas au niveau de l'étage :", "bonne": "On la ramène d'abord à un étage", "fausses": ["On fait sauter les gens", "On les tire par le bas", "On force la porte"], "expl": ""}, {"q": "Ascenseur hydraulique, la cabine se ramène…", "bonne": "En descendant par la vanne de purge", "fausses": ["En montant à la main", "En coupant les câbles", "Avec le parachute"], "expl": ""}, {"q": "Qui remet l'ascenseur en service ?", "bonne": "L'ascensoriste", "fausses": ["Les pompiers", "Le gardien", "Le premier habitant"], "expl": ""}, {"q": "Combien d'étapes dans S.E.C.U.R.I.T.E. ?", "bonne": "8", "fausses": ["4", "6", "10"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les ascenseurs – personne bloquée, porte palière ouverte » (charte SDIS 34) · RNF PPBE A2 · FOD n°14 « Procédure ascenseur bloqué » du SDIS 34 (12/2022) · RDEB v2 (avril 2026) § 5.10 · RDMI v6 § 6.4 · FAT VSRTU (04/2026) – vérifier qu'aucune version plus récente de la FOD n°14 n'a été diffusée"}, "JSP4|Les différentes espèces d'animaux": {"cycle": "JSP4", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Les différentes espèces d'animaux", "objectif": "Sur photos, identifier pour le chien et le chat l'état de l'animal (calme, peur, menace) et citer pour chaque grande famille (chien, chat, ferme, NAC) un risque et une règle d'approche — 10 min, 2 erreurs tolérées.", "pointsCles": ["Situations : animal menaçant (échappé, agressif), en difficulté (arbre, eau, trou), blessé, sur demande de la police, pendant une autre intervention ; un animal sans danger relève d'autres services", "Deux familles de risques : physiques (morsures, griffures, coups, écrasement) et infectieux (plaies qui s'infectent, maladies transmises à l'homme, parasites)", "Règles d'approche : ne pas se précipiter, ne pas fixer dans les yeux, rester calme, pas de geste brusque, parler doucement ; un animal agressif est souvent un animal qui a peur", "Ligne de fuite (chien ≈ 10 m) : l'animal s'enfuit s'il peut ; ligne critique (chien ≈ 1,50 à 3 m) : coincé, il attaque ou se soumet ; toujours lui laisser une issue tant qu'on n'est pas prêt", "Chien : oreilles droites = sûr de lui, couchées = peur ; babines retroussées = menace ; poil hérissé = méfiance, colère ; tête basse = soumission", "Chat : calme (oreilles en avant, ronronne), effrayé (oreilles couchées, cherche à se cacher), agressif (nez plissé, dos rond, poils hérissés) ; s'il crache : stop ! jamais à mains nues", "Ferme : cheval craintif (coups de pied, écrasement : nourriture puis licol) ; vache (coups de tête et de corne : enclos, sans stress) ; mouton jamais par la laine ; cochon : cœur fragile, manœuvre courte ; sanglier blessé : il mord", "NAC : dans la région surtout la couleuvre de Montpellier, vipère venimeuse plutôt en altitude ; mygale jamais touchée ; animal inconnu ou dangereux : on l'enferme dans la pièce et on appelle les spécialistes ou le vétérinaire"], "materiel": "Photos de chiens et chats dans différentes postures (tablette), photos d'animaux de ferme et de NAC, plots et rubalise pour matérialiser ligne de fuite et ligne critique, un animateur qui joue l'animal.", "activites": [{"titre": "Quelle posture ?", "duree": "10 min", "prep": "Série de photos de chiens et de chats.", "deroule": ["Tu montres une photo.", "Les binômes disent : calme, peur ou menace ? à quoi le voit-on ?", "Ils annoncent ce qu'ils font : approcher, attendre, reculer, demander du matériel."], "phrase": "Un animal agressif est souvent un animal qui a peur.", "securite": ""}, {"titre": "Les distances", "duree": "15 min", "prep": "Deux cercles de plots autour d'un animateur « chien » : ligne de fuite (≈ 10 m) et ligne critique (≈ 2 m).", "deroule": ["Chaque JSP approche lentement, sans regard fixe, en parlant doucement.", "L'animateur annonce « je m'enfuis », « je gronde » ou « j'attaque » selon la distance, la vitesse et le regard du JSP.", "Débrief : pourquoi laisser une issue à l'animal ?"], "phrase": "Calme, lent, sans regard fixe.", "securite": "Animateur uniquement, jamais d'animal réel agressif."}, {"titre": "Qui est qui ? Les familles d'animaux", "duree": "10 min", "prep": "Cartes photos (cheval, vache, mouton, cochon, sanglier, couleuvre, vipère, mygale, iguane…).", "deroule": ["Chaque binôme tire une carte.", "Il cite le risque principal et la règle d'approche.", "Il dit s'il faut appeler un spécialiste ou le vétérinaire."], "phrase": "Inconnu ou dangereux ? On enferme et on appelle les spécialistes.", "securite": ""}], "questions": [{"q": "Quelles sont les deux familles de risques ?", "r": "Physiques (morsure, coup…) et infectieux."}, {"q": "Faut-il regarder un chien dans les yeux ?", "r": "Non : pour lui, c'est un défi."}, {"q": "Que se passe-t-il si on franchit la ligne critique ?", "r": "L'animal se sent coincé : il attaque ou se soumet."}, {"q": "Un chat qui crache, ça veut dire quoi ?", "r": "Point critique : on s'arrête."}, {"q": "Que veulent dire des babines retroussées chez le chien ?", "r": "Une menace."}, {"q": "Comment attrape-t-on un mouton ?", "r": "Jamais par la laine : on le parque."}, {"q": "Quel serpent trouve-t-on surtout dans la région ?", "r": "La couleuvre de Montpellier."}], "quiz": [{"q": "Pour un chien, être fixé dans les yeux, c'est…", "bonne": "Un défi", "fausses": ["Une caresse", "Un jeu", "Sans effet"], "expl": ""}, {"q": "Chien oreilles couchées :", "bonne": "Il a peur", "fausses": ["Il est sûr de lui", "Il dort", "Il veut jouer à coup sûr"], "expl": ""}, {"q": "On franchit la ligne de fuite :", "bonne": "L'animal s'enfuit s'il le peut", "fausses": ["Il attaque toujours", "Il s'endort", "Rien ne se passe"], "expl": ""}, {"q": "Un chat crache :", "bonne": "On s'arrête", "fausses": ["On l'attrape vite à mains nues", "On le fixe dans les yeux", "On crie pour l'effrayer"], "expl": "Point critique atteint."}, {"q": "Un mouton s'attrape…", "bonne": "Jamais par la laine, on le parque", "fausses": ["Par la laine", "Par la queue", "Couché sur le dos"], "expl": ""}, {"q": "Animal exotique inconnu dans un appartement :", "bonne": "On l'enferme dans la pièce et on appelle un spécialiste", "fausses": ["On l'attrape à la main", "On le laisse s'enfuir dehors", "On le fait sortir avec un balai"], "expl": ""}, {"q": "Un animal agressif est souvent…", "bonne": "Un animal qui a peur", "fausses": ["Un animal qui joue", "Un animal qui a faim", "Un animal endormi"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les animaux – approcher, capturer, se protéger » (charte SDIS 34) · RNF PPBE B1 · FAT VSRTU (04/2026) – lot animalier · ancien support SDIS « Interventions animalières » (DIV-B, 2014) et support JSP4 « Les EPI et le rôle du vétérinaire » — à faire valider par le vétérinaire SP ou l'équipe animalière du SDIS 34"}, "JSP4|Les EPI et le matériel de capture": {"cycle": "JSP4", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Les EPI et le matériel de capture", "objectif": "Choisir les EPI et le matériel du lot animalier adaptés à 4 situations, puis capturer une peluche avec la pince, la mettre en cage et retirer ses gants sans se contaminer — 15 min, aucune erreur d'hygiène admise.", "pointsCles": ["EPI : casque avec visière ou lunettes (masque si besoin), veste textile, gants latex dessous et gants anti-morsure ou cuir dessus, pantalon, rangers ou bottes", "Lot animalier du VSRTU : cage, drap, gants anti-morsure, pince animalière, crochet à reptile (seulement après formation spéciale), sacs de 100 L", "Autres moyens : lasso (chien, gros lézard ; vérifier câble et blocage avant usage), épuisette, filet, couverture, nourriture ou jouet pour gagner la confiance", "Contention mécanique : muselière (ou lien plat d'1 m) toujours posée à deux, licol et longe pour cheval ou vache, cage pour transporter ; les sangles servent à soulever, pas à tenir", "Contention chimique (endormir à distance) : c'est le vétérinaire qui décide, avec des sapeurs-pompiers formés", "Vétérinaire sapeur-pompier : il conseille le chef et le directeur, soigne (dont les chiens cynotechniques), neutralise un animal dangereux, forme les pompiers", "Hygiène après la capture : retirer les gants sans se toucher, les jeter en sac fermé, se laver les mains, nettoyer et désinfecter cage, pince, lasso, drap", "Mordu ou griffé : on nettoie, on désinfecte et on le signale tout de suite au chef, même si c'est petit"], "materiel": "Lot animalier du VSRTU (cage, drap, gants anti-morsure, pince animalière, sacs), gants latex, lasso et épuisette si disponibles, peluches, gel hydroalcoolique, savon, cartes situations ; si possible intervention d'un vétérinaire SP ou d'un SP animalier.", "activites": [{"titre": "Quel matériel pour quelle situation ?", "duree": "10 min", "prep": "Cartes situations (chien agressif dans un jardin, chat coincé sous une voiture, couleuvre dans une cuisine, cheval sur la route) et le lot animalier étalé.", "deroule": ["Chaque binôme tire une carte.", "Il choisit les EPI et le matériel, et dit ce qu'il ne doit surtout pas faire.", "Correction : qui appeler si c'est trop dangereux (vétérinaire, spécialiste) ?"], "phrase": "", "securite": ""}, {"titre": "Capture de la peluche", "duree": "20 min", "prep": "Peluche « animal », pince animalière, cage, drap, gants latex + gants anti-morsure.", "deroule": ["Le binôme s'équipe (deux paires de gants) et se contrôle.", "Il approche calmement, capture la peluche à la pince ou avec le drap.", "Il la met en cage, ferme, puis retire ses gants sans se toucher et les jette dans un sac fermé.", "Lavage des mains."], "phrase": "La contention se fait à deux.", "securite": "Jamais d'animal réel : peluches uniquement ; pince manipulée doucement, pas vers le visage d'un camarade."}, {"titre": "Le vétérinaire SP", "duree": "10 min", "prep": "Rencontre ou questions préparées (si un vétérinaire SP ou un SP animalier est disponible), sinon cartes « missions ».", "deroule": ["Les JSP posent leurs questions ou classent les cartes : conseiller, soigner, neutraliser, former.", "Ils citent un cas où on l'appelle.", "Rappel hygiène : que fait-on après une morsure ?"], "phrase": "", "securite": ""}], "questions": [{"q": "Quels gants met-on pour capturer un animal ?", "r": "Gants latex dessous, gants anti-morsure ou en cuir dessus."}, {"q": "Cite 3 éléments du lot animalier du VSRTU.", "r": "Cage, drap, gants anti-morsure, pince animalière, crochet à reptile, sacs."}, {"q": "Qui peut utiliser le crochet à reptile ?", "r": "Seulement un sapeur-pompier formé par un spécialiste."}, {"q": "Comment pose-t-on une muselière ?", "r": "Toujours à deux."}, {"q": "Qui décide d'endormir un animal à distance ?", "r": "Le vétérinaire sapeur-pompier."}, {"q": "Mordu par un animal : que faire ?", "r": "Nettoyer, désinfecter, le signaler au chef."}, {"q": "Que fait-on après la capture ?", "r": "Retirer les gants sans se toucher, sac fermé, se laver les mains, désinfecter le matériel."}], "quiz": [{"q": "Sous les gants anti-morsure, on porte…", "bonne": "Des gants latex", "fausses": ["Rien", "Des mitaines", "Des gants de vaisselle troués"], "expl": ""}, {"q": "Pour transporter un chat capturé :", "bonne": "La cage", "fausses": ["Les bras", "Un sac fermé", "La poche de la veste"], "expl": ""}, {"q": "La muselière se pose…", "bonne": "À deux", "fausses": ["Seul", "Par le propriétaire uniquement", "Sans approcher, en la lançant"], "expl": ""}, {"q": "Endormir un animal à distance, c'est décidé par…", "bonne": "Le vétérinaire", "fausses": ["Le JSP le plus âgé", "Le propriétaire", "Le conducteur"], "expl": ""}, {"q": "Les sangles servent à…", "bonne": "Soulever un gros animal", "fausses": ["Le tenir en laisse", "Le museler", "Le frapper"], "expl": ""}, {"q": "Une petite griffure pendant la capture :", "bonne": "Je nettoie, désinfecte et le dis au chef", "fausses": ["Je ne dis rien", "J'attends demain", "Je remets des gants par-dessus"], "expl": ""}, {"q": "Le crochet à reptile s'utilise…", "bonne": "Après une formation spéciale", "fausses": ["Par tout le monde", "Pour attraper les chats", "Pour ouvrir les cages"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les animaux – approcher, capturer, se protéger » (charte SDIS 34) · RNF PPBE B1 · FAT VSRTU (04/2026) – lot animalier · ancien support SDIS « Interventions animalières » (DIV-B, 2014) et support JSP4 « Les EPI et le rôle du vétérinaire » — à faire valider par le vétérinaire SP ou l'équipe animalière du SDIS 34"}, "JSP4|Les hyménoptères": {"cycle": "JSP4", "bloc": "Intervenir pour une mission de protection des personnes, des biens et de l'environnement", "item": "Les hyménoptères", "objectif": "Reconnaître sur photos l'abeille, la guêpe, le frelon européen et le frelon asiatique, citer les 3 cas où une piqûre devient grave et remettre dans l'ordre les 5 étapes d'une neutralisation — 10 min, 1 erreur admise.", "pointsCles": ["Abeille : poilue, brune et dorée ; on ne la détruit pas, on appelle un apiculteur", "Guêpe : jaune rayée de noir, taille fine, nid en papier sous un toit ou dans le sol ; frelon européen : 3 à 4 cm, roux et jaune ; frelon asiatique : presque noir, pattes jaunes, 2,5 à 3 cm, gros nid rond haut dans les arbres", "Calmes loin du nid, ils attaquent en groupe à 5 à 10 m du nid ; le frelon asiatique peut projeter son venin vers les yeux", "Une piqûre devient grave : piqûres multiples, piqûre dans la bouche, la gorge ou les yeux, personne allergique", "Gonflement du visage, gêne pour respirer, malaise, plaques sur la peau après une piqûre : urgence vitale, on appelle tout de suite", "Un sapeur-pompier qui a déjà fait une allergie grave ne participe plus aux interventions sur les hyménoptères ; un JSP allergique le dit aux animateurs", "Tenue : combinaison par-dessus la tenue, casque F2 + grille + lunettes, gants épais sous les manches, rangers ou bottes, scotch aux jonctions, contrôle croisé ; lot hyménoptères du VSRTU (tenue « frelons », pulvérisateur, produit, 4 sacs de 100 L)", "Déroulement : se garer loin et reconnaître, éloigner les gens, s'équiper en binôme, pulvériser à l'entrée du nid, finir proprement ; tôt le matin ou le soir ; jamais d'essence ni de feu", "Limites : les pompiers interviennent en cas d'urgence (école, personne allergique, lieu public) ; sinon entreprise spécialisée, essaim d'abeilles = apiculteur (politique SDIS 34 à vérifier)"], "materiel": "Photos d'abeille, guêpe, frelon européen, frelon asiatique et de leurs nids (tablette), tenue « frelons » du lot VSRTU si disponible (sinon tenue de feu + gants + masque), pulvérisateur rempli d'eau, faux nid (carton ou ballon en papier mâché) à hauteur d'homme, 5 cartes « étapes ».", "activites": [{"titre": "Qui est-ce ?", "duree": "10 min", "prep": "Photos des 4 insectes et de nids.", "deroule": ["Tu montres une photo.", "Les JSP nomment l'insecte et le type de nid.", "Pour chacun : qui intervient (pompiers, entreprise, apiculteur) ?"], "phrase": "L'abeille, on ne la détruit pas.", "securite": ""}, {"titre": "L'habillage et la faille", "duree": "15 min", "prep": "Tenues « frelons » ou tenues de feu, gants, masque, scotch.", "deroule": ["Chaque binôme s'équipe.", "L'animateur glisse une faille (manche relevée, gant sous la manche, grille ouverte).", "L'autre JSP la trouve au contrôle croisé."], "phrase": "Pas un centimètre de peau à l'air.", "securite": "Rappeler la règle allergie avant l'atelier."}, {"titre": "La pulvérisation + le bon ordre", "duree": "15 min", "prep": "Faux nid à hauteur d'homme, pulvérisateur rempli d'eau, 5 cartes étapes.", "deroule": ["Les binômes remettent les 5 étapes dans l'ordre.", "Puis, en tenue, ils visent l'entrée du faux nid avec de l'eau.", "Débrief : pourquoi viser l'entrée ? pourquoi le matin ou le soir ?"], "phrase": "Ni essence, ni feu.", "securite": "Jamais de vrai nid ni de vrai produit : de l'eau et un faux nid ; JSP allergiques prévenus et surveillés."}], "questions": [{"q": "À quelle distance du nid deviennent-ils agressifs ?", "r": "Environ 5 à 10 mètres."}, {"q": "Un essaim d'abeilles : qui appeler ?", "r": "Un apiculteur."}, {"q": "Les 3 cas où une piqûre devient grave ?", "r": "Piqûres multiples, bouche/gorge/yeux, personne allergique."}, {"q": "Où pulvérise-t-on le produit ?", "r": "À l'entrée du nid."}, {"q": "Le meilleur moment pour intervenir ?", "r": "Tôt le matin ou le soir."}, {"q": "Peut-on brûler un nid avec de l'essence ?", "r": "Jamais."}, {"q": "Comment reconnaître le frelon asiatique ?", "r": "Presque noir, pattes jaunes, plus petit que le frelon européen."}, {"q": "Que fais-tu si tu es allergique aux piqûres ?", "r": "Je le dis aux animateurs ; je ne participe pas."}], "quiz": [{"q": "Un essaim d'abeilles chez un particulier :", "bonne": "On appelle un apiculteur", "fausses": ["On brûle l'essaim", "On pulvérise de l'essence", "On l'arrose à la lance"], "expl": ""}, {"q": "Frelon presque noir aux pattes jaunes :", "bonne": "Frelon asiatique", "fausses": ["Frelon européen", "Abeille", "Guêpe"], "expl": ""}, {"q": "Ils deviennent agressifs à…", "bonne": "5 à 10 m du nid", "fausses": ["100 m du nid", "Seulement s'ils sont dans le nid", "Jamais"], "expl": ""}, {"q": "Une piqûre devient grave si…", "bonne": "La personne est allergique", "fausses": ["Elle est sur le pied", "Il fait chaud", "Elle a lieu l'après-midi"], "expl": "Aussi : piqûres multiples, bouche ou yeux."}, {"q": "Le produit se pulvérise…", "bonne": "À l'entrée du nid", "fausses": ["Sur les passants", "Sous le nid au hasard", "Sur la tenue du binôme"], "expl": "Les insectes l'emportent à l'intérieur."}, {"q": "Meilleur moment pour neutraliser un nid (hors urgence) :", "bonne": "Tôt le matin ou le soir", "fausses": ["À midi", "En plein après-midi", "N'importe quand"], "expl": "Tous les insectes sont rentrés."}, {"q": "Un pompier qui a déjà fait une allergie grave à une piqûre…", "bonne": "Ne participe plus à ces interventions", "fausses": ["Y va en premier", "Y va sans tenue", "Y va seul"], "expl": ""}, {"q": "Pour détruire un nid dans une cheminée :", "bonne": "Jamais de feu ni d'essence", "fausses": ["On allume un feu", "On verse de l'essence", "On ferme la cheminée et on attend"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Guêpes et frelons – la neutralisation des hyménoptères » (charte SDIS 34) · RNF PPBE B2 · FAT VSRTU (04/2026) – lot hyménoptères · ancien support SDIS « Neutralisation d'hyménoptères » (JSP4) · RDLSPCC § 3.8 — politique SDIS 34 (urgence, entreprises privées, produit) à vérifier avec le CIS"}, "JSP4|Les principaux risques locaux": {"cycle": "JSP4", "bloc": "Diffuser la culture du service public", "item": "Les principaux risques locaux", "objectif": "Sur la carte du secteur Cruzy-Quarante, placer au moins 5 risques locaux, les ranger par saison et rédiger en équipe un message de prévention de 3 lignes pour les habitants — 35 min.", "pointsCles": ["Connaître son secteur pour mieux intervenir : gagner du temps (routes, accès, points d'eau), anticiper selon la saison et la météo, avoir le bon matériel, connaître les pièges pour ne pas devenir victime", "Le SDIS analyse les risques du département dans le SDACR, arrêté par le préfet : il décide où sont placés les centres et les engins", "RDMI SDIS 34 : risque courant = ce qui arrive souvent (feux de maison, accidents, secours à personne ; faible, ordinaire ou important) ; risque particulier = rare mais très grave, beaucoup d'enjeux, étude et moyens spécifiques (ex. cave coopérative, grand feu de garrigue)", "Les risques de Cruzy et Quarante : feux de forêt, inondations (crues éclair), vignes et caves, routes, mouvements de terrain (argiles et sécheresse), canicule ; séisme (zone 2, faible) et radon existent mais sont rares en intervention", "Feux de forêt et de garrigue (été) : sécheresse, chaleur, vent fort (cers / tramontane) et surtout imprudence humaine ; le vent envoie des braises loin devant ; engins CCFM et CCFU ; prévention : débroussailler et respecter les interdictions de feu", "Crues éclair (automne) : épisodes méditerranéens, le ruisseau devient torrent en quelques heures ; missions : sauvetages, reconnaissances, mises en sécurité, épuisement ; pièges : courant, eau trouble, plaques d'égout ouvertes — 30 cm d'eau suffisent à emporter une voiture", "Vendanges : la fermentation produit du CO2, invisible, sans odeur, plus lourd que l'air, qui remplit le fond des cuves, caves et fosses ; la victime s'effondre en quelques respirations — on ne descend jamais, on alerte le 18 ; les pompiers interviennent sous ARI", "Toute l'année : routes de campagne (virages, vitesse), engins agricoles lents et larges, boue des vendanges, engrais et produits de traitement stockés dans les hangars", "Le pompier (et le JSP) est ambassadeur de la prévention : détecteur de fumée et plan familial, débroussaillement, jamais seul dans une cave en fermentation, on ne traverse pas une route inondée, on partage ce qu'on apprend"], "materiel": "Carte IGN ou impression Géorisques du secteur Cruzy-Quarante, gommettes de couleur (bleu inondation, rouge feu, violet caves, orange routes), frise des saisons, DICRIM de Cruzy et de Quarante, feuilles pour les messages ; si possible un sapeur-pompier ancien du CIS pour raconter des interventions marquantes.", "activites": [{"titre": "Le piège de la cuve", "duree": "5 min", "prep": "Situation d'accroche du cours.", "deroule": ["L'animateur lit : un vigneron s'effondre dans une cuve, son fils descend l'aider… et s'effondre aussi. Que s'est-il passé ?", "Réponse : le CO2 de la fermentation, plus lourd que l'air, remplit le fond de la cuve.", "Réflexe : on ne descend jamais, on alerte le 18 ; les pompiers interviennent sous ARI."], "phrase": "Un sauveteur sans protection devient la 2e victime.", "securite": ""}, {"titre": "La carte des risques du secteur", "duree": "20 min", "prep": "Carte du secteur, gommettes de couleur.", "deroule": ["Par équipe, placer : zones inondables (bleu), massifs et garrigue (rouge), caves (violet), routes dangereuses (orange).", "Pour chaque gommette : risque courant ou particulier ? quel engin du CIS ?", "Un ancien du CIS raconte une intervention marquante du secteur."], "phrase": "Connaître son secteur, c'est gagner du temps.", "securite": ""}, {"titre": "Le calendrier des risques", "duree": "5 min", "prep": "Frise des saisons.", "deroule": ["Ranger les risques par saison : été = feux ; septembre-octobre = vendanges (CO2, boue, engins) et épisodes méditerranéens ; hiver = feux de cheminée, CO ; toute l'année = routes."], "phrase": "", "securite": ""}, {"titre": "Le message", "duree": "10 min", "prep": "Feuilles, crayons.", "deroule": ["Par équipe, écrire un message de prévention de 3 lignes pour les habitants (débroussaillement, cave en fermentation, route inondée…).", "Lecture et vote ; les meilleurs messages peuvent être affichés au CIS ou publiés par la section avec l'accord du chef de section."], "phrase": "Le pompier, ambassadeur de la prévention.", "securite": ""}], "questions": [{"q": "Pourquoi connaître les risques de son secteur ?", "r": "Pour intervenir plus vite, mieux et en sécurité."}, {"q": "Un feu de maison : risque courant ou particulier ?", "r": "Courant."}, {"q": "Donne un exemple de risque particulier du secteur.", "r": "Une cave coopérative, un grand feu de garrigue."}, {"q": "Quel gaz se forme pendant les vendanges ?", "r": "Le dioxyde de carbone (CO2)."}, {"q": "Quelqu'un est inconscient au fond d'une cuve : je fais quoi ?", "r": "Je ne descends pas, j'alerte le 18."}, {"q": "À quelle saison les crues éclair ?", "r": "À l'automne (épisodes méditerranéens)."}, {"q": "Combien d'eau suffit à emporter une voiture ?", "r": "30 cm."}, {"q": "Quelle est la principale cause des départs de feu ?", "r": "L'imprudence humaine."}, {"q": "Comment protéger une maison du feu de forêt ?", "r": "En débroussaillant autour."}], "quiz": [{"q": "Pourquoi connaître les risques de son secteur ?", "bonne": "Pour intervenir plus vite, mieux et en sécurité", "fausses": ["Pour faire du tourisme", "Pour éviter d'intervenir", "Ce n'est pas utile"], "expl": ""}, {"q": "Pour le RDMI, un feu de maison est un risque :", "bonne": "Courant", "fausses": ["Particulier", "Exceptionnel", "Technologique"], "expl": "Ce qui arrive souvent."}, {"q": "Une cave coopérative est plutôt un risque :", "bonne": "Particulier", "fausses": ["Courant faible", "Sans enjeu", "Domestique"], "expl": "Rare mais avec de gros enjeux."}, {"q": "Pendant les vendanges, le gaz dangereux des caves est :", "bonne": "Le dioxyde de carbone (CO2)", "fausses": ["L'oxygène", "L'hélium", "La vapeur d'eau"], "expl": "Plus lourd que l'air, il remplit le fond des cuves."}, {"q": "Quelqu'un est inconscient au fond d'une cuve :", "bonne": "Je ne descends pas, j'alerte le 18", "fausses": ["Je descends vite le chercher", "J'envoie un copain", "Je lui jette de l'eau"], "expl": "Les pompiers interviennent sous ARI."}, {"q": "Les crues éclair arrivent surtout :", "bonne": "À l'automne", "fausses": ["En hiver avec la neige", "Au printemps", "Jamais chez nous"], "expl": "Épisodes méditerranéens."}, {"q": "Route inondée devant toi :", "bonne": "Tu ne la traverses jamais", "fausses": ["Tu passes vite", "Tu passes à pied", "Tu passes si l'eau est calme"], "expl": "30 cm d'eau peuvent emporter une voiture."}, {"q": "Pour protéger une maison du feu de forêt :", "bonne": "Débroussailler autour", "fausses": ["Planter des pins contre la maison", "Stocker du bois contre le mur", "Ouvrir les fenêtres"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les principaux risques locaux de notre secteur » (charte SDIS 34) · RDMI v6 SDIS 34 § 2.3 à 2.5 (risque courant / particulier) ; Géorisques Cruzy et Quarante (repris du cours JSP3 « Les risques majeurs et l'information de la population », RNF JSP3 SC A1) ; SDACR et DDRM de l'Hérault, DICRIM des communes – à valider : item sans fiche RNF JSP4 dédiée ; risque CO2 en vinification et débroussaillement (connaissances générales, chef de centre) ; exemples locaux de risque particulier ; obligations de débroussaillement applicables à Cruzy et Quarante"}, "JSP4|Prévention des risques routiers": {"cycle": "JSP4", "bloc": "Diffuser la culture du service public", "item": "Prévention des risques routiers", "objectif": "Dans la cour du CIS, repérer les angles morts du FPTGP, poser un balisage (cônes, triangle, gilet) derrière l'engin et justifier 6 règles de sécurité routière (trajet sur alerte, engin, chaussée, deux-roues) — 40 min, aucune erreur de sécurité.", "pointsCles": ["La route tue (ONISR, bilan 2024) : 3 193 tués en métropole, environ 16 000 blessés graves ; 1 tué sur 6 a entre 18 et 24 ans ; 23 % des tués étaient en deux-roues motorisé", "Les grands facteurs d'accident : vitesse, alcool et drogues, téléphone, fatigue (après une nuit d'intervention), pas de ceinture ou de casque, météo (pluie, brouillard, boue des vendanges)", "Sur l'alerte, le volontaire qui rejoint le centre avec sa voiture n'est pas prioritaire : il respecte le Code de la route, ne se précipite pas, lit l'alerte à l'arrêt et se gare sans gêner la sortie des engins", "L'engin (feux bleus et deux-tons) est un véhicule d'intérêt général prioritaire : il peut passer au feu rouge ou dépasser la vitesse seulement sans mettre les autres en danger — la priorité ne se prend pas, elle se demande", "L'équipage reste assis et ceinturé tant que l'engin roule ; on s'équipe avant le départ ou à l'arrêt ; on aide le conducteur (on regarde à droite, on annonce les dangers)", "Sur la chaussée, le danger vient de la circulation : gilet haute visibilité, balisage (engin en protection, cônes, triangle, feux allumés), jamais dos aux voitures, descendre côté bas-côté, éclairage la nuit, curieux éloignés — le sur-accident est le principal danger", "Angles morts : on ne passe jamais derrière un engin qui manœuvre, on se fait voir du conducteur", "À vélo et en scooter : casque obligatoire en deux-roues motorisé (et à vélo avant 12 ans, fortement conseillé après), gants obligatoires en deux-roues motorisé, lumières et gilet la nuit, écouteurs interdits en conduisant, même à vélo", "Vers le permis : AM dès 14 ans, conduite accompagnée dès 15 ans, permis B dès 17 ans ; permis probatoire de 6 points (alcool : 0,2 g/l maximum) ; plus tard les permis poids lourd pour conduire les engins"], "materiel": "FPTGP à l'arrêt dans l'enceinte du CIS (moteur coupé, clés retirées), craie ou plots pour marquer les angles morts, cônes, triangle et gilets haute visibilité (lot de balisage des engins), cartes « vrai ou faux ».", "activites": [{"titre": "Le bip sonne", "duree": "5 min", "prep": "Situation d'accroche du cours.", "deroule": ["Un volontaire file au centre en voiture : a-t-il le droit d'aller plus vite ?", "Réponse : non, sa voiture n'est pas prioritaire ; un pompier accidenté sur le trajet, c'est un pompier en moins… et parfois une victime de plus.", "On cite les grandes causes d'accident : vitesse, alcool, téléphone, fatigue."], "phrase": "Arriver vite, mais arriver.", "securite": ""}, {"titre": "Les angles morts", "duree": "15 min", "prep": "FPTGP à l'arrêt, craie ou plots.", "deroule": ["Un JSP au poste de conduite regarde dans les rétroviseurs.", "Les autres se placent à l'avant, sur les côtés, à l'arrière.", "On marque au sol les zones où personne n'est visible.", "Message : on ne passe jamais derrière un engin qui manœuvre, on se fait voir du conducteur."], "phrase": "Si je ne vois pas le conducteur, il ne me voit pas.", "securite": "Engin à l'arrêt, moteur coupé, clés retirées, dans l'enceinte du CIS ; un animateur près de l'engin."}, {"titre": "Le balisage", "duree": "15 min", "prep": "Cônes, triangle, gilets.", "deroule": ["Gilet sur le dos, les JSP placent cônes et triangle derrière l'engin.", "Ils descendent côté bas-côté et restent face à la circulation.", "Correction : où était le danger ? qui tournait le dos aux voitures ?"], "phrase": "Un secouriste blessé, c'est une victime de plus.", "securite": "Dans la cour, jamais sur la voie publique."}, {"titre": "Vrai ou faux", "duree": "10 min", "prep": "Cartes affirmations (quiz du cours).", "deroule": ["L'animateur lit : « le volontaire sur l'alerte peut griller un feu », « on peut détacher sa ceinture pour s'équiper en roulant », « les écouteurs sont autorisés à vélo », « on passe le permis B à 17 ans »…", "Les JSP se placent côté vrai ou côté faux, puis justifient."], "phrase": "", "securite": ""}], "questions": [{"q": "Le pompier volontaire qui rejoint le centre est-il prioritaire ?", "r": "Non : il respecte le Code de la route."}, {"q": "Quand peut-on détacher sa ceinture dans l'engin ?", "r": "Seulement à l'arrêt."}, {"q": "Un engin prioritaire peut-il passer au feu rouge ?", "r": "Oui, mais seulement sans mettre les autres en danger : la priorité se demande."}, {"q": "Sur la chaussée, je porte quoi ?", "r": "Le gilet haute visibilité."}, {"q": "De quel côté descend-on de l'engin ?", "r": "Côté bas-côté, pas côté circulation."}, {"q": "Écouteurs à vélo ?", "r": "Interdits en conduisant."}, {"q": "Cite 4 grandes causes d'accident.", "r": "Vitesse, alcool ou drogues, téléphone, fatigue."}, {"q": "Combien de tués sur les routes en 2024 (métropole) ?", "r": "Environ 3 200."}, {"q": "À partir de quel âge le permis B ?", "r": "17 ans."}], "quiz": [{"q": "Le volontaire qui rejoint le centre sur l'alerte :", "bonne": "N'est pas prioritaire, il respecte le Code de la route", "fausses": ["Peut dépasser la vitesse", "Peut griller les feux rouges", "Peut rouler sur la bande d'arrêt d'urgence"], "expl": ""}, {"q": "Dans l'engin, la ceinture se détache :", "bonne": "Seulement à l'arrêt", "fausses": ["Pour s'équiper en roulant", "Dès que la sirène est allumée", "Jamais besoin de l'attacher"], "expl": "On s'équipe avant le départ ou à l'arrêt."}, {"q": "Feux bleus et deux-tons : l'engin peut passer au rouge…", "bonne": "Seulement sans mettre les autres en danger", "fausses": ["Toujours, même si quelqu'un traverse", "Jamais", "Seulement la nuit"], "expl": "La priorité ne se prend pas, elle se demande."}, {"q": "Sur une intervention routière, je descends de l'engin…", "bonne": "Côté bas-côté", "fausses": ["Côté circulation", "Par où je veux", "Par la fenêtre"], "expl": ""}, {"q": "Je travaille près de la chaussée :", "bonne": "Jamais dos à la circulation", "fausses": ["Dos à la circulation", "Au milieu de la voie", "Sans regarder"], "expl": ""}, {"q": "En 2024, combien de tués sur les routes de métropole ?", "bonne": "Environ 3 200", "fausses": ["Environ 300", "Environ 30 000", "Environ 100"], "expl": "ONISR, bilan 2024."}, {"q": "À vélo, les écouteurs :", "bonne": "Sont interdits en conduisant", "fausses": ["Sont autorisés", "Sont autorisés si le son est bas", "Sont obligatoires la nuit"], "expl": ""}, {"q": "Le permis B se passe à partir de :", "bonne": "17 ans", "fausses": ["14 ans", "16 ans", "21 ans"], "expl": "Conduite accompagnée dès 15 ans."}], "statut": "brouillon", "source": "Cours 2026 « La prévention des risques routiers » (charte SDIS 34) · ONISR, bilan définitif 2024 ; Code de la route art. R311-1 et R432-1 (véhicules d'intérêt général prioritaires), R412-1 (ceinture), équipements des deux-roues ; cours 2026 SDIS 34 pour le balisage (prompt secours, PEI, prévention appliquée à l'opération) – à valider : item sans fiche RNF dédiée ; règles internes SDIS 34 (conduite des engins, trajets sur alerte, stationnement au CIS) par le chef de centre ; chiffres ONISR à mettre à jour chaque année"}, "JSP4|Les indicateurs de la condition physique": {"cycle": "JSP4", "bloc": "S'impliquer dans son activité", "item": "Les indicateurs de la condition physique", "objectif": "Citer les six tests ICP et la qualité mesurée par chacun, puis, en binôme, réaliser un passage d'entraînement en jugeant son camarade selon le protocole (« non compté » si mouvement incorrect) — 40 min.", "pointsCles": ["Les ICP servent à savoir où j'en suis, voir ma progression, être prêt en mission (ARI, échelle, porter une victime) et éviter les blessures ; tous les sapeurs-pompiers les passent chaque année", "Six tests, cinq qualités : Luc Léger ou Vaméval (endurance), Killy (force des jambes), pompes (bras et pectoraux), tractions (dos et bras), gainage (tronc), souplesse (mobilité)", "Luc Léger : allers-retours entre deux lignes à 20 m, toucher la ligne au bip, le rythme augmente à chaque palier ; on note le dernier palier atteint (Vaméval : même principe avec des plots)", "Killy : dos plaqué au mur, cuisses à l'horizontale, genoux à 90°, mains libres, tenir le plus longtemps possible ; gainage : avant-bras et pointe des pieds, corps droit des épaules aux talons", "Pompes : mains à largeur d'épaules, corps gainé, poitrine près du sol, remonter bras tendus ; tractions : départ bras tendus, menton au-dessus de la barre, sans élan", "Souplesse : assis jambes tendues, pousser doucement les mains vers l'avant, sans à-coup ; toujours après l'échauffement, jamais de rebonds", "Le jour des tests : s'échauffer, être en forme (sommeil, manger léger, boire), respecter le protocole (une répétition mal faite ne compte pas), arrêter en cas de douleur ou malaise ; endurance en dernier", "Suivi début, milieu et fin d'année dans l'onglet ICP du Carnet JSP ; je me compare à moi-même, pas aux autres ; aucun classement affiché", "Barèmes officiels différenciés par sexe : aucun chiffre en séance, on se réfère au document officiel et à l'appli sans les modifier"], "materiel": "Plots, décamètre, bande sonore Luc Léger (ou piste Vaméval), mur lisse pour le Killy, barre de traction, tapis de sol, repère/boîte de souplesse, chronomètres, fiches de résultats (sans barème) ; encadrement par un animateur APS JSP ou un EAP.", "activites": [{"titre": "Quelle qualité, quel geste ?", "duree": "5 min", "prep": "Cartes des 6 tests et cartes « gestes du sapeur-pompier » (monter les étages, porter une victime, se hisser, porter l'ARI…).", "deroule": ["Les JSP associent chaque test à une qualité physique.", "Puis à un geste du sapeur-pompier.", "Débrief : pourquoi un corps entraîné se blesse moins ?"], "phrase": "", "securite": ""}, {"titre": "Atelier juge – exécutant", "duree": "25 min", "prep": "Échauffement collectif, puis ateliers Killy, pompes, tractions, gainage, souplesse.", "deroule": ["Par binôme : l'un réalise, l'autre juge et compte à voix haute.", "Le juge dit « non compté » si le mouvement est mal fait.", "On inverse ; les résultats sont notés pour le prochain passage."], "phrase": "Seul un mouvement correct compte.", "securite": "Échauffement obligatoire ; arrêt immédiat en cas de douleur ou malaise ; souplesse sans rebonds."}, {"titre": "Endurance tous ensemble", "duree": "10 min", "prep": "Lignes à 20 m (ou piste Vaméval), bande sonore.", "deroule": ["Tous les JSP courent ensemble au bip.", "Chacun note son dernier palier atteint.", "Retour au calme et étirements doux."], "phrase": "Je me compare à moi-même.", "securite": "Test d'endurance en dernier, eau à disposition, surveillance des signes de malaise ; aucun classement affiché."}], "questions": [{"q": "Cite les six tests des ICP.", "r": "Luc Léger ou Vaméval, Killy, pompes, tractions, gainage, souplesse."}, {"q": "Que mesure le Luc Léger ?", "r": "L'endurance (cœur et souffle)."}, {"q": "Le Killy, c'est quoi ?", "r": "Tenir assis contre un mur, cuisses à l'horizontale."}, {"q": "Une traction est valide quand… ?", "r": "Le menton passe au-dessus de la barre, sans élan."}, {"q": "Avant les tests, on fait quoi ?", "r": "Un échauffement."}, {"q": "À qui je compare mes résultats ?", "r": "À moi-même, d'un passage à l'autre."}, {"q": "Pourquoi le test d'endurance se fait-il en dernier ?", "r": "Parce qu'il épuise : les autres tests seraient faussés."}, {"q": "Que fais-tu si tu as mal pendant un test ?", "r": "J'arrête et je préviens l'animateur."}], "quiz": [{"q": "Le Luc Léger mesure…", "bonne": "L'endurance", "fausses": ["La souplesse", "La force des bras", "L'équilibre"], "expl": ""}, {"q": "Le Killy, c'est…", "bonne": "Tenir assis contre un mur, cuisses horizontales", "fausses": ["Des sauts sur place", "Courir 20 m", "Grimper à la corde"], "expl": ""}, {"q": "Une traction compte si…", "bonne": "Le menton passe au-dessus de la barre, sans élan", "fausses": ["On balance les jambes pour monter", "On monte à moitié", "On saute pour attraper la barre"], "expl": ""}, {"q": "Pour le test de souplesse :", "bonne": "Sans rebonds, après l'échauffement", "fausses": ["Avec des rebonds pour aller plus loin", "À froid", "Genoux pliés"], "expl": ""}, {"q": "Je compare mes résultats ICP…", "bonne": "À moi-même", "fausses": ["Au plus fort du groupe", "Aux adultes", "À personne, ça ne sert à rien"], "expl": ""}, {"q": "Le gainage fait travailler surtout…", "bonne": "Le tronc (abdos, dos)", "fausses": ["Les mollets", "Les doigts", "Le cou"], "expl": ""}, {"q": "Combien de tests ICP dans le programme JSP ?", "bonne": "6", "fausses": ["3", "4", "10"], "expl": "Luc Léger ou Vaméval, Killy, pompes, tractions, gainage, souplesse."}], "statut": "brouillon", "source": "Cours 2026 « Les indicateurs de la condition physique (ICP) » (charte SDIS 34) · RNF JSP/JMP v1.1 APS A1 · note DGSCGC relative aux ICP des sapeurs-pompiers · classeur « La préparation physique des JSP » — barèmes officiels non reproduits (onglet ICP du Carnet JSP) ; protocoles simplifiés à valider par l'équipe pédagogique / filière EAP"}, "JSP4|La prise de garde": {"cycle": "JSP4", "bloc": "S'impliquer dans son activité", "item": "La prise de garde", "objectif": "Réaliser une prise de garde simulée : appel et affectation, inventaire d'un coffre du FPTGP avec l'extrait de FAT (retrouver les 3 matériels retirés), vérification de son EPI, puis compte rendu clair et court au « chef de garde » — 40 min, aucun oubli de signalement.", "pointsCles": ["Trois façons de répondre présent (SDIS 34) : garde postée (au centre, en tenue, prêt à partir), astreinte (chez soi ou au travail, départ dès que le bip sonne), disponible (sans obligation) ; disponibilités saisies dans Webdag", "La prise de garde (relève) : l'équipe qui arrive (garde montante) prend le relais de celle qui part (garde descendante)", "Une garde se prépare la veille : une bonne nuit de sommeil, repas équilibrés et hydratation, tenue complète propre et EPI en bon état, arriver avant l'heure", "Les 5 étapes : rassemblement et appel par le chef de garde, répartition (engin et poste : chef, conducteur, équipier), consignes de la garde qui part (engins indisponibles, matériel manquant, infos du jour), vérifications, compte rendu au chef de garde", "Mon EPI : casque, visière, jugulaire, cagoule, veste, surpantalon, gants, bottes — complets, propres, en bon état", "Mon ARI : pression de la bouteille, étanchéité du masque, serrages du masque desserrés au maximum, masque à filet déposé dans l'engin si j'en ai besoin", "L'engin : inventaire coffre par coffre avec la fiche d'armement (FAT), niveaux (carburant, eau, émulseur), radios chargées et essayées, feux et sirène, sac de secours, défibrillateur et oxygène complets ; toute anomalie est signalée", "Rendre compte : un problème signalé à la prise de garde, c'est un problème réglé avant le départ", "Pendant la garde : prêt en quelques minutes ; après chaque intervention on reconditionne tout de suite (pleins, matériel, bouteilles d'ARI, nettoyage je sais / je sens / je vois) ; manœuvres, sport, entretien du centre", "Fin de garde : tout est reconditionné, je transmets ce qui manque ou est en panne, je range et je nettoie, je pars seulement quand la relève est faite"], "materiel": "FPTGP à l'arrêt (moteur coupé, clés retirées) avec 3 matériels retirés ou déplacés par l'animateur, extraits de la FAT 04/2026 (un coffre par binôme), EPI des JSP, un ARI et un masque pour montrer les vérifications (sans capelage), fiche de compte rendu « engin, coffre, ce qui manque, ce que j'ai fait ».", "activites": [{"titre": "La bouteille presque vide", "duree": "5 min", "prep": "Situation d'accroche du cours.", "deroule": ["8 h 05, départ pour un feu ; sur place, la bouteille d'ARI d'un équipier est presque vide. Qu'est-ce qui n'a pas été fait ?", "Réponse : la vérification de l'ARI à la prise de garde, ou le reconditionnement après la dernière intervention."], "phrase": "La prise de garde, ce n'est pas de la paperasse.", "securite": ""}, {"titre": "L'appel", "duree": "10 min", "prep": "Accord du chef de centre (l'engin doit rester disponible pour un départ).", "deroule": ["Rassemblement en tenue ; un JSP joue le chef de garde et fait l'appel.", "Il contrôle les tenues et donne à chacun un poste sur un engin (chef, conducteur, équipier).", "La « garde descendante » transmet ses consignes : un matériel en panne, une info du jour."], "phrase": "", "securite": ""}, {"titre": "Le matériel manquant", "duree": "20 min", "prep": "Un coffre du FPTGP et l'extrait de FAT par binôme ; 3 matériels retirés ou déplacés.", "deroule": ["Par binôme, faire l'inventaire du coffre avec la FAT et retrouver ce qui manque ou n'est pas à sa place.", "Chacun vérifie aussi son EPI (complet, propre, en bon état).", "L'animateur montre sur un ARI : pression de la bouteille, étanchéité du masque, serrages desserrés au maximum."], "phrase": "Ce qui n'est pas signalé n'est pas réparé.", "securite": "Engin à l'arrêt, moteur coupé, clés retirées ; on ne monte pas sur le toit ; matériels lourds portés à deux ; pas de capelage d'ARI ; tout est remis en place et contrôlé par l'animateur."}, {"titre": "Le compte rendu", "duree": "10 min", "prep": "Fiche « engin, coffre, ce qui manque, ce que j'ai fait ».", "deroule": ["Chaque binôme rend compte au chef de garde, de façon claire et courte.", "Le groupe juge : tout y est ? c'est court ?", "Fin de garde : on remet tout en place et on passe le relais."], "phrase": "Un problème signalé à la prise de garde, c'est un problème réglé avant le départ.", "securite": ""}], "questions": [{"q": "À quoi sert la prise de garde ?", "r": "À s'assurer que le personnel et le matériel sont prêts à partir."}, {"q": "Garde postée, astreinte, disponible : quelle différence ?", "r": "Au centre en tenue / chez soi ou au travail, départ au bip / possible sans obligation."}, {"q": "Que faire la veille d'une garde ?", "r": "Bien dormir, bien manger, préparer sa tenue."}, {"q": "Quelles sont les 5 étapes de la prise de garde ?", "r": "Rassemblement, répartition, consignes, vérifications, compte rendu."}, {"q": "Que vérifie-t-on sur son masque ?", "r": "L'étanchéité et les serrages desserrés au maximum."}, {"q": "Avec quel document fait-on l'inventaire ?", "r": "La fiche d'armement de l'engin (FAT)."}, {"q": "Je trouve un matériel cassé : je fais quoi ?", "r": "Je rends compte au chef de garde."}, {"q": "Après une intervention ?", "r": "On reconditionne tout de suite l'engin."}, {"q": "Quand la garde qui termine peut-elle partir ?", "r": "Quand la relève est faite et qu'on la libère."}], "quiz": [{"q": "À quoi sert la prise de garde ?", "bonne": "S'assurer que le personnel et le matériel sont prêts à partir", "fausses": ["Se reposer avant les interventions", "Choisir son engin préféré", "Remplir des papiers sans intérêt"], "expl": ""}, {"q": "L'astreinte, c'est…", "bonne": "Être chez soi ou au travail, prêt à partir dès que le bip sonne", "fausses": ["Être au centre toute la nuit", "Ne jamais partir", "Être en vacances"], "expl": ""}, {"q": "La veille d'une garde :", "bonne": "Bien dormir, bien manger, préparer sa tenue", "fausses": ["Faire une nuit blanche", "Sauter les repas", "Laisser sa tenue sale dans le sac"], "expl": ""}, {"q": "Sur son masque d'ARI, à la prise de garde, on vérifie :", "bonne": "L'étanchéité et les serrages desserrés au maximum", "fausses": ["Sa couleur", "Le nom du fabricant", "Rien, c'est fait une fois par an"], "expl": ""}, {"q": "Pour faire l'inventaire d'un engin, on utilise…", "bonne": "La FAT", "fausses": ["Le DICRIM", "Le plan d'évacuation", "La carte routière"], "expl": "Fiche d'armement type."}, {"q": "Je trouve un matériel cassé :", "bonne": "Je rends compte au chef de garde", "fausses": ["Je le cache", "Je le répare seul en secret", "Je le laisse sans rien dire"], "expl": ""}, {"q": "Après une intervention :", "bonne": "On reconditionne tout de suite l'engin", "fausses": ["On attend la garde suivante", "On range le lendemain", "Rien à faire"], "expl": "Un engin qui rentre est un engin prêt à repartir."}, {"q": "La garde qui termine peut partir :", "bonne": "Quand la relève est faite et qu'on la libère", "fausses": ["À l'heure pile, même si personne n'est arrivé", "Quand elle veut", "Avant l'appel"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La prise de garde » (charte SDIS 34) · RDEB SDIS 34 v2 (avril 2026) § 1.1 (étanchéité du masque, masque à filet), § 2.1-2.2 (préparation physique et physiologique), § 2.7-2.8 (serrages du masque déverrouillés à la prise de garde) ; FAT des engins (04/2026) ; journée d'intégration SPV 2026 (garde postée, astreinte, disponibilité) ; complète le cours JSP4 « L'intégration en CIS » (RNF SC B1) – à valider : item sans fiche RNF dédiée ; déroulé local de la prise de garde au CIS de Cruzy-Quarante (horaires, appel, feuille de garde, logiciel, vérifications par poste, pression minimale de la bouteille) par le chef de centre"}, "JSP2|Les engins d'incendie et de secours. Contrôle et reconditionnement": {"cycle": "JSP2", "bloc": "Eteindre un incendie", "item": "Les engins d'incendie et de secours. Contrôle et reconditionnement", "objectif": "Citer la signification des sigles des engins du CIS, décrire le FPT et le CCF, puis réaliser en binôme l'inventaire d'un engin avec sa FAT (sans oubli de matériel).", "pointsCles": ["Un sigle = un nom = une mission : chaque lettre est un mot (VSAV = véhicule de secours et d'assistance aux victimes, FPT = fourgon pompe-tonne, CCF = camion-citerne feux de forêts)", "Engins du CIS Cruzy-Quarante : FPTGP, CCFU, CCFM-BP, CCFM-HP, CCGC, FMOGP, VSRTU, VSAV", "Au SDIS 34, le VSRTU réunit le secours routier ET les opérations diverses (animaux, inondations, frelons, bâchage…)", "Le FPTL (≈ 2 000 L d'eau) est l'engin d'attaque ; le FPT ou FPTGP est l'engin d'appui (RDMI)", "FPT chez nous : départ à 6 SP (chef d'agrès, conducteur, 2 binômes) ; au complet le FPTGP emporte 8 SP (8 ARI)", "1er binôme : attaque et extinction · 2e binôme : prise d'eau et alimentation de l'engin", "CCF : 4 SP, tout-terrain, autoprotection (lance rideau, air respirable en cabine) ; le CCFU part à 6 SP avec 4 ARI : forêts ET bâtiments", "La FAT (fiche armement type) liste chaque matériel, sa quantité et sa place : on fait l'inventaire avec elle", "Retour au centre en 5 étapes : nettoyer, contrôler (FAT), reconditionner, compléter (eau, additif, carburant), signaler", "Un matériel défectueux : on ne l'utilise plus, on le met de côté et on le signale au chef d'agrès"], "materiel": "FPTGP et CCFU (ou CCFM) du CIS ouverts, moteur coupé, frein de parc serré · FAT imprimées des engins · tuyaux mouillés d'une manœuvre · crayons, ardoises · cartes « sigles ».", "activites": [{"titre": "Le tour de l'engin", "duree": "10 min", "prep": "Un engin par groupe (FPTGP, CCFU ou VSAV), sigle visible, cartes avec les mots des sigles.", "deroule": ["Chaque groupe lit le sigle de son engin et le dit en entier.", "Il compte les places de l'équipage et dit qui s'assoit où (CA, COD, binômes).", "Il retrouve la citerne et l'additif.", "Question : « Il part sur un feu de maison, de garrigue ou un accident ? »"], "phrase": "Un sigle bien lu, c'est déjà savoir à quoi sert l'engin.", "securite": "Moteur coupé, frein de parc serré, un animateur par engin."}, {"titre": "L'inventaire avec la FAT", "duree": "15 min", "prep": "FAT de l'engin imprimée par binôme ; l'animateur a retiré 3 matériels en douce.", "deroule": ["En binôme, les JSP ouvrent les coffres avec la FAT.", "Ils cochent chaque matériel trouvé à sa place.", "Ils notent ce qui manque et le signalent au « chef d'agrès » (l'animateur).", "On compare : quel binôme a trouvé les 3 manques ?"], "phrase": "Si un matériel manque, on le voit tout de suite avec la FAT.", "securite": "Pas de montée sur le toit de l'engin, coffres ouverts et fermés par l'animateur."}, {"titre": "Le reconditionnement", "duree": "15 min", "prep": "Tuyaux mouillés d'une manœuvre, aire de lavage, séchoir, tuyaux secs.", "deroule": ["Rincer et contrôler les tuyaux (coupures, raccords).", "Les mettre à sécher.", "Remettre des tuyaux secs à leur place dans l'engin.", "Annoncer au chef d'agrès : « Engin prêt à repartir ! »"], "phrase": "Après chaque intervention, on prépare la suivante.", "securite": "Gants, attention aux glissades sur l'aire de lavage."}, {"titre": "Quiz des sigles", "duree": "5 min", "prep": "Cartes des sigles du cours.", "deroule": ["L'animateur montre un sigle, les binômes écrivent la signification.", "Un point par mot juste."], "phrase": "", "securite": ""}], "questions": [{"q": "Que veut dire VSAV ?", "r": "Véhicule de secours et d'assistance aux victimes."}, {"q": "Quel engin combat les feux de forêts ?", "r": "Le CCF (camion-citerne feux de forêts)."}, {"q": "Combien de SP partent dans notre FPTGP ?", "r": "6 : chef d'agrès, conducteur et 2 binômes (8 au complet)."}, {"q": "Combien de SP dans un CCF ?", "r": "4 (le CCFU : 6)."}, {"q": "Que fait le VSRTU au SDIS 34 ?", "r": "Secours routier et opérations diverses (animaux, inondations, frelons, bâchage…)."}, {"q": "Que veut dire FAT ?", "r": "Fiche armement type : la liste du matériel de l'engin, avec sa quantité et sa place."}, {"q": "Quelles sont les 5 étapes au retour au centre ?", "r": "Nettoyer, contrôler, reconditionner, compléter, signaler."}, {"q": "Un matériel est cassé : que fais-tu ?", "r": "Je le mets de côté et je le signale au chef d'agrès."}], "quiz": [{"q": "Que veut dire VSAV ?", "bonne": "Véhicule de secours et d'assistance aux victimes", "fausses": ["Véhicule de sauvetage avec ambulance", "Voiture de secours d'assistance verte", "Véhicule de sécurité et d'appui aux volontaires"], "expl": ""}, {"q": "Quel engin est fait pour les feux de forêts ?", "bonne": "Le CCF", "fausses": ["Le VSAV", "Le VSRTU", "Le FMOGP"], "expl": "CCF = camion-citerne feux de forêts : tout-terrain."}, {"q": "Combien de SP partent dans le FPTGP de Cruzy-Quarante ?", "bonne": "6", "fausses": ["2", "4", "12"], "expl": "Chef d'agrès, conducteur et 2 binômes (8 au complet)."}, {"q": "Combien de SP dans l'équipage d'un CCFM ?", "bonne": "4", "fausses": ["2", "6", "8"], "expl": "Chef d'agrès, conducteur et 2 équipiers."}, {"q": "Quel engin du SDIS 34 fait secours routier ET opérations diverses ?", "bonne": "Le VSRTU", "fausses": ["Le CCGC", "Le FPTGP", "Le VSAV"], "expl": "VSR + VTU = VSRTU."}, {"q": "À quoi sert la FAT ?", "bonne": "Faire l'inventaire du matériel de l'engin", "fausses": ["Conduire l'engin", "Appeler les secours", "Remplir la citerne"], "expl": "Fiche armement type : chaque matériel, sa quantité, sa place."}, {"q": "De retour au centre, que fais-tu d'un tuyau mouillé ?", "bonne": "Je le rince, le contrôle et le mets à sécher", "fausses": ["Je le range mouillé", "Je le jette", "Je le laisse dans l'engin"], "expl": "Puis on remet des tuyaux secs."}, {"q": "Un matériel est défectueux. Que fais-tu ?", "bonne": "Je le mets de côté et je le signale au chef d'agrès", "fausses": ["Je l'utilise quand même", "Je le répare seul", "Je n'en parle à personne"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les engins d'incendie et de secours » (charte SDIS 34) · RNF JSP/JMP v1.1 fiche JSP2 SC B2 · RDMI SDIS 34 v6 (avril 2026) · FAT FPTGP 04/2026, CCFM-BP 02/2026, CCFU 04/2026"}, "JSP3|Les risques liés à la toxicité des fumées d'incendies": {"cycle": "JSP3", "bloc": "Sécuriser la zone d'intervention", "item": "Les risques liés à la toxicité des fumées d'incendies", "objectif": "Retirer une veste « contaminée » (farine) avec gants jetables sans transfert sur la peau, puis choisir et réaliser le bon niveau de nettoyage (je sais / je sens / je vois) pour 6 situations — 30 min, au moins 5 sur 6 justes.", "pointsCles": ["Les 5 dangers des fumées (RDEB § 2.24) : chaudes, opaques, mobiles, inflammables, toxiques ; plastiques et mousses rendent les fumées plus toxiques, et un feu qui manque d'air produit plus de CO", "Les toxiques : CO (invisible, sans odeur, prend la place de l'oxygène dans le sang), HCN (plastiques, mousses : les cellules ne peuvent plus utiliser l'oxygène), gaz irritants (yeux, gorge, poumons), suies (certaines cancérogènes ; en 2022 le CIRC a classé l'exposition professionnelle des pompiers cancérogène)", "Exposition directe (le toxique entre dans le corps) ou indirecte (par une tenue, un matériel ou une cabine pollués) — RDEB § 4.1", "Quatre voies d'entrée : respiration (inhalation), peau (cou, visage, mains, poignets), bouche (ingestion, mains sales), yeux", "Après le feu, les toxiques se fixent sur la tenue, le casque, les gants, le matériel, puis se libèrent peu à peu (cabine, vestiaire) et voyagent jusqu'à la maison — une tenue qui sent la fumée n'est pas une tenue propre", "Pendant l'intervention : ARI dès qu'il y a de la fumée et jusqu'à la fin du déblai, EPI complets (cagoule, col fermé, gants : pas de peau à l'air), vent dans le dos dehors, ni manger ni boire en zone enfumée", "Le COS adapte le nettoyage (RDEB § 4.2) : JE SAIS (exposition courte à l'air libre : aérer les EPI, rincer le matériel à l'eau), JE SENS (déblai, reconnaissance, attaque : brosser à sec et aérer les EPI, brosser le matériel à l'eau), JE VOIS (exposition longue, traces visibles : EPI dans un sac, tenue propre au retour)", "Se décontaminer : demi-masque P3 et gants jetables pour se déshabiller et nettoyer le matériel sale, sacs rouges et lingettes du lot DECOPI ; le conducteur prépare une zone matériels propres / matériels souillés", "Retour au centre : douche obligatoire avant de rentrer chez soi ; mains et visage lavés avant de boire, manger ou téléphoner ; cabine nettoyée et engin rangé vitres ouvertes", "Reconnaître une intoxication : mal de tête, vertiges, nausées, toux, suies au nez et à la bouche, somnolence jusqu'à la perte de connaissance → se protéger, alerter le 18, gestes du PSC"], "materiel": "Veste de feu et casque d'exercice + farine ou talc (suies), gants jetables, demi-masque P3, sacs rouges et lingettes du lot DECOPI (FPTGP), bâche, plots rouges / verts (matériels souillés / propres), 6 cartes-situations ou photos d'interventions, 4 pancartes « respiration / peau / bouche / yeux », ARI du FPTGP pour montrer.", "activites": [{"titre": "Les 4 portes et le voyage des toxiques", "duree": "10 min", "prep": "4 pancartes au sol (respiration, peau, bouche, yeux), liste de situations.", "deroule": ["L'animateur lit une situation (je mange un sandwich après le déblai sans me laver les mains ; j'enlève ma cagoule dans la fumée ; je rentre chez moi avec mon tee-shirt de garde ; je me frotte les yeux avec mes gants sales…).", "Les JSP vont vers la porte d'entrée concernée et disent le geste qui protège.", "On explique : exposition directe ou indirecte ; les toxiques se collent, se libèrent, voyagent."], "phrase": "Une tenue qui sent la fumée n'est pas une tenue propre.", "securite": "Espace dégagé, on marche."}, {"titre": "Le défi de la farine", "duree": "15 min", "prep": "Veste et casque saupoudrés de farine aux épaules et aux manches, gants jetables, sac rouge, demi-masque P3 pour montrer.", "deroule": ["Le JSP, gants jetables, retire la veste en la roulant, la met dans le sac rouge, puis retire ses gants en les retournant.", "On vérifie cou, poignets et mains : où reste-t-il de la « suie » ?", "On recommence en corrigeant ; l'animateur montre le demi-masque P3 qu'on porterait en vrai pour se déshabiller et nettoyer le matériel."], "phrase": "La suie se laisse dans le sac, pas sur la peau.", "securite": "Farine non toxique, pas de masque ; on ne secoue pas la tenue ; aucun produit ni fumée réels."}, {"titre": "Zone propre / zone souillée", "duree": "15 min", "prep": "Plots rouges et verts, bâche, sacs rouges, lingettes, 6 cartes-situations.", "deroule": ["Un binôme « conducteur » installe la zone : parc matériels propres, parc matériels souillés.", "Chaque binôme tire une situation et annonce le niveau (je sais / je sens / je vois).", "Il fait le geste correspondant : aérer et rincer, brosser à sec et aérer, mettre les EPI en sac et le matériel sous bâche.", "On termine par le retour au centre : douche, mains et visage lavés, cabine nettoyée, engin rangé vitres ouvertes."], "phrase": "Je sais, je sens, je vois : le nettoyage suit l'exposition.", "securite": ""}], "questions": [{"q": "Quelle différence entre exposition directe et indirecte ?", "r": "Directe : le toxique entre dans le corps ; indirecte : par une tenue, un matériel ou une cabine pollués."}, {"q": "Cite les 4 voies d'entrée.", "r": "Respiration, peau, bouche, yeux."}, {"q": "Quelles zones de peau sont les plus exposées ?", "r": "Le cou, le visage, les mains, les poignets."}, {"q": "Pourquoi une tenue sale reste dangereuse après le feu ?", "r": "Les toxiques s'y fixent puis se libèrent peu à peu : cabine, vestiaire, maison."}, {"q": "D'où vient le HCN ?", "r": "Des plastiques et des mousses qui brûlent."}, {"q": "Jusqu'à quand garde-t-on l'ARI ?", "r": "Tant qu'il y a de la fumée, jusqu'à la fin du déblai."}, {"q": "Ma tenue sent la fumée après une reconnaissance : quel niveau, quels gestes ?", "r": "« Je sens » : brosser à sec et aérer les EPI, brosser le matériel à l'eau."}, {"q": "Que veut dire « JE VOIS » ?", "r": "Exposition longue ou traces visibles : EPI dans un sac, tenue propre au retour."}, {"q": "Que porte-t-on pour se déshabiller et nettoyer le matériel sale ?", "r": "Un demi-masque P3 et des gants jetables."}, {"q": "Que fait-on toujours au retour au centre ?", "r": "On prend une douche avant de rentrer chez soi."}], "quiz": [{"q": "Les toxiques fixés sur une tenue sale…", "bonne": "Se libèrent peu à peu dans la cabine, le vestiaire, la maison", "fausses": ["Disparaissent dès qu'on sort de la fumée", "Ne sont dangereux que mouillés", "Restent collés pour toujours"], "expl": ""}, {"q": "Une exposition « indirecte », c'est :", "bonne": "Par une tenue, un matériel ou une cabine pollués", "fausses": ["Respirer directement la fumée", "Regarder le feu de loin", "Boire de l'eau propre"], "expl": ""}, {"q": "Combien de voies d'entrée des toxiques dans le corps ?", "bonne": "4", "fausses": ["1", "2", "6"], "expl": "Respiration, peau, bouche, yeux."}, {"q": "Pendant le déblai, l'ARI…", "bonne": "Se garde jusqu'à la fin du déblai", "fausses": ["S'enlève toujours", "Se prête au voisin", "Reste dans l'engin"], "expl": ""}, {"q": "Ma tenue sent la fumée après une attaque : c'est le niveau…", "bonne": "« Je sens »", "fausses": ["« Je sais »", "« Je vois »", "Néant"], "expl": "Brossage à sec et aération des EPI, brossage du matériel à l'eau."}, {"q": "Ma tenue a des traces visibles de suie : c'est le niveau…", "bonne": "« JE VOIS »", "fausses": ["« JE SAIS »", "« JE SENS »", "Néant"], "expl": "EPI isolés dans un sac, tenue propre au retour."}, {"q": "Pour se déshabiller et nettoyer le matériel souillé, on porte :", "bonne": "Un demi-masque P3 et des gants jetables", "fausses": ["Rien de particulier", "Un masque en tissu", "Ses gants de feu sales"], "expl": ""}, {"q": "Au retour au centre après un feu :", "bonne": "Douche obligatoire avant de rentrer chez soi", "fausses": ["Douche à la maison plus tard", "Pas de douche si on ne voit rien", "Repas d'abord, douche ensuite"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La toxicité des fumées d'incendie » (charte SDIS 34 ; cours commun JSP2 / JSP3, en JSP3 insister sur les parties 2 et 3) · RDEB SDIS 34 v2 (avril 2026) § 2.24, § 4.1 (exposition directe / indirecte, fixation et libération des toxiques), § 4.2 (je sais / je sens / je vois), § 4.3 (lot DECOPI) ; GDO « prévention des risques liés à la toxicité des fumées » (2020) – à valider : item sans fiche RNF dédiée ; contenu sur les gaz toxiques (CO, HCN, irritants, suies) issu de connaissances générales (chef de section) ; le cours JSP3 « L'hygiène de vie » place « je sais » à « pas d'exposition » : le RDEB fait foi"}, "JSP4|Les différents types de risques et actions adaptées": {"cycle": "JSP4", "bloc": "Sécuriser la zone d'intervention", "item": "Les différents types de risques et actions adaptées", "objectif": "Face à une photo ou une mise en situation, citer le bon réflexe d'approche (arrêt à distance, vent dans le dos, observer, compter, rendre compte), identifier le risque particulier et la spécialité à demander — 10 min, 1 erreur admise.", "pointsCles": ["Avant d'agir : je m'arrête à distance, vent dans le dos (en hauteur si possible), j'observe, je compte les victimes, je rends compte", "Zonage (RDEB § 2.18-2.21) : zone d'exclusion (équipes équipées seulement), zone contrôlée (zone tampon), zone de soutien (commandement, soins, matériel) ; les JSP restent toujours en zone de soutien", "Analyse source → flux → cibles (RDMI § 6.7) et balance bénéfice-risque (RDMI § 6.8) : on accepte plus de risques pour une vie que pour des biens", "Risque chimique : pictogrammes en losange rouge (CLP) ; panneau orange : en haut le code danger (33 = liquide très inflammable), en bas le numéro ONU (1203 = essence)", "Radiologique : trèfle jaune et noir ; se protéger par le temps, la distance, l'écran", "Bouteille de gaz : on ne la manipule pas sauf absolue nécessité ; butane/propane dangereux dès 80 °C ; bouteille dans le feu : 100 m (acétylène : 200 m) ; les bouteilles composites ne peuvent pas éclater", "Fuite de gaz : aucune flamme, aucun interrupteur, pas de téléphone ; fermer la vanne si possible, aérer, faire sortir, périmètre 50 m / 100 m. Le CO : sans couleur, sans odeur, sans goût, mesuré au détecteur", "Électricité : plus il y a d'isolateurs, plus la tension est forte ; câble au sol : au moins 10 m (HTB : 50 m) ; on ne coupe que le disjoncteur de la maison, les lignes = technicien", "Photovoltaïque : sous tension tant qu'il y a de la lumière (≈ 60 V continu par panneau) ; voie ferrée : caténaire 25 000 V, rester à plus de 3 m ; effondrement : fissures, craquements → on s'éloigne", "Spécialités : risques chimiques, radiologiques, milieux périlleux, sauvetage aquatique, sauvetage-déblaiement, cynotechnie — les premiers arrivés observent, zonent et demandent les spécialistes"], "materiel": "Emballages vides et rincés (produits ménagers, jardin, bricolage), plaques « panneau orange » imprimées (33/1203, 30/1202, 23/1965, 80/1789, 268/1005) avec table simplifiée des codes, photos de situations (tablette), rubalise et plots pour matérialiser les 3 zones, manche à air ou ruban pour lire le vent.", "activites": [{"titre": "Le détective des pictogrammes", "duree": "10 min", "prep": "Emballages vides et rincés étalés sur une table, ardoises.", "deroule": ["Par binôme, les JSP retrouvent chaque pictogramme en losange rouge.", "Ils notent le danger correspondant (inflammable, corrosif, toxique, environnement…).", "Mise en commun : où trouve-t-on ces produits à la maison ?"], "phrase": "Le dessin te dit le danger avant que tu le sentes.", "securite": "Emballages vides et rincés uniquement, jamais de vrais produits dangereux."}, {"titre": "Décode le panneau orange", "duree": "10 min", "prep": "Plaques imprimées et table simplifiée des codes danger / numéros ONU.", "deroule": ["Tu montres une plaque (ex. 33/1203).", "Les binômes lisent : en haut le code danger, en bas le produit.", "Ils disent quel zonage et quelle spécialité il faudrait demander (risques chimiques)."], "phrase": "En haut le danger, en bas le produit.", "securite": ""}, {"titre": "Les 3 zones et le vent", "duree": "10 min", "prep": "Un plot « source » (camion couché), rubalise de 2 couleurs, ruban pour le vent.", "deroule": ["Les JSP observent le ruban : d'où vient le vent ?", "Ils placent l'engin (FPTGP) vent dans le dos, à distance.", "Ils matérialisent zone d'exclusion, zone contrôlée et zone de soutien, et se placent en zone de soutien."], "phrase": "Le vent décide où va le danger.", "securite": "Exercice à pied dans la cour, engins à l'arrêt."}, {"titre": "Que fais-tu ? — source, flux, cibles", "duree": "10 min", "prep": "4 photos : fuite de gaz dans la rue, feu de poubelle contre une façade, câble tombé, panneaux solaires sur un toit en feu.", "deroule": ["Chaque binôme tire une photo.", "Il annonce la source, le flux, les cibles.", "Il donne la distance de sécurité et la spécialité à appeler, puis fait son compte rendu au « chef d'agrès »."], "phrase": "Bien observer et bien transmettre, c'est faire venir vite les bons spécialistes.", "securite": "Sortie terrain possible pour compter les isolateurs : rester sur le trottoir, encadrement par un animateur."}], "questions": [{"q": "Quelles sont les 3 zones autour d'un danger ?", "r": "Zone d'exclusion, zone contrôlée, zone de soutien."}, {"q": "Où se placer face à un nuage toxique ?", "r": "Loin, vent dans le dos, en hauteur si possible."}, {"q": "Que lit-on en haut et en bas d'un panneau orange ?", "r": "En haut le code danger, en bas le numéro ONU du produit."}, {"q": "Quelles sont les 3 protections contre la radioactivité ?", "r": "Le temps, la distance, l'écran."}, {"q": "Un câble électrique est tombé au sol : à quelle distance reste-t-on ?", "r": "Au moins 10 m, 50 m pour la haute tension B."}, {"q": "Le compteur est coupé : un panneau solaire est-il sans danger ?", "r": "Non, il produit du courant tant qu'il y a de la lumière."}, {"q": "Que faut-il éviter près d'une fuite de gaz ?", "r": "Toute flamme, interrupteur ou téléphone (étincelle)."}, {"q": "Cite 3 spécialités des sapeurs-pompiers.", "r": "Risques chimiques, radiologiques, milieux périlleux, sauvetage aquatique, sauvetage-déblaiement, cynotechnie."}], "quiz": [{"q": "En arrivant près d'un camion qui fuit, je me place…", "bonne": "Vent dans le dos, à distance", "fausses": ["Vent dans le visage pour sentir l'odeur", "Au plus près pour lire l'étiquette", "Sous le nuage pour l'arrêter"], "expl": "Le vent emporte les gaz loin de moi."}, {"q": "Dans quelle zone restent toujours les JSP ?", "bonne": "Zone de soutien", "fausses": ["Zone d'exclusion", "Zone contrôlée", "Au contact du produit"], "expl": ""}, {"q": "Panneau orange 33 / 1203 : que signifie 33 ?", "bonne": "Liquide très inflammable", "fausses": ["Le numéro du produit", "Le poids du camion", "Un gaz toxique"], "expl": "1203 = essence (numéro ONU)."}, {"q": "Les 3 protections contre la radioactivité :", "bonne": "Temps, distance, écran", "fausses": ["Eau, mousse, poudre", "Casque, gants, bottes", "Alerter, baliser, secourir"], "expl": ""}, {"q": "Une bouteille de gaz est prise dans le feu (hors acétylène). Périmètre ?", "bonne": "100 m", "fausses": ["10 m", "25 m", "1 km"], "expl": "Acétylène : 200 m."}, {"q": "Câble électrique tombé au sol (basse tension) :", "bonne": "Au moins 10 m", "fausses": ["2 m", "On peut le pousser avec un bâton sec", "Aucune distance si le temps est sec"], "expl": "50 m pour la haute tension B."}, {"q": "Le monoxyde de carbone (CO) est…", "bonne": "Sans couleur, sans odeur, sans goût", "fausses": ["Jaune et piquant", "Odeur d'œuf pourri", "Visible comme une fumée noire"], "expl": "On le mesure avec un détecteur."}, {"q": "Victimes sous des décombres : quelle spécialité ?", "bonne": "Sauvetage-déblaiement", "fausses": ["Risques chimiques", "Sauvetage aquatique", "Risques radiologiques"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les risques particuliers et les spécialités » (charte SDIS 34) · RNF INC A2 · RDEB v2 (avril 2026) § 2.18-2.21, annexes 5.3, 5.5-5.9 · RDMI v6 § 6.7-6.8 · sdis34.fr (spécialités) — panneau orange, radioprotection, voie ferrée, photovoltaïque et effondrement : à valider avec un conseiller technique"}, "JSP4|Les premières mesures conservatoires et techniques d'autoprotection": {"cycle": "JSP4", "bloc": "Sécuriser la zone d'intervention", "item": "Les premières mesures conservatoires et techniques d'autoprotection", "objectif": "En binôme, s'équiper sans aucune peau exposée avec contrôle croisé, puis appliquer à l'annonce « ça chauffe ! » la séquence alerter – se baisser – refroidir – se protéger – se replier, sans perdre le contact — aucune erreur de sécurité admise.", "pointsCles": ["EPI complets : casque avec visière, cagoule, veste et surpantalon, gants d'attaque (type C en ambiance thermique), bottes ; pas de bijoux, piercings ni montre", "Aucune peau à l'air : cagoule ajustée autour du masque et rentrée dans le col, veste fermée, col relevé, gants sur les poignets", "Contrôle croisé obligatoire après l'habillage (RDEB § 2.9) : mon binôme voit ce que je ne vois pas", "Limites de la tenue : elle retarde la brûlure sans l'empêcher ; mouillée, elle peut transmettre chaleur et vapeur ; pas de protection contre l'électricité ni les produits chimiques", "Oreilles ou mains qui brûlent = il fait trop chaud : on se baisse ou on recule", "Entretien (RDEB § 4.2) : nettoyage selon la souillure « je sais, je sens, je vois » ; tenue très sale au sac, tenue propre ; EPI abîmé signalé et changé ; jamais de tenue sale à la maison", "Préparation à l'engagement (RDEB § 2.1-2.4) : physique, hygiène de vie, mentale, connaissance du métier", "Vigilance : regarder autour de soi, garder le contact avec son binôme, rendre compte tout de suite, connaître et dire ses limites", "Signes d'alerte : chaleur qui monte vite, fumées qui descendent et s'épaississent, flammes dans les fumées, sifflements", "Réaction du binôme : alerter, se baisser, refroidir les fumées par impulsions, faire écran en diffusé large, se replier ensemble par le chemin d'entrée en suivant le tuyau ; bloqué : se mettre à l'abri, message « URGENT », fenêtre, économiser l'air"], "materiel": "Tenues de feu complètes (casque, cagoule, veste, surpantalon, gants, bottes), un JSP « piégé » avec 5 erreurs (cagoule, col, gant, montre, jugulaire), chronomètre, établissement en eau à faible débit depuis le FPTGP (une lance), plots pour le couloir et la cible, sac « EPI sales ».", "activites": [{"titre": "Trouve les 5 erreurs", "duree": "10 min", "prep": "Un JSP habillé avec 5 erreurs : cagoule mal mise, col ouvert, gant manquant, montre, jugulaire défaite.", "deroule": ["Les JSP observent leur camarade 1 minute.", "Ils annoncent les erreurs et expliquent le danger de chacune.", "Le camarade corrige devant eux."], "phrase": "Une montre chauffe, brûle et accroche.", "securite": ""}, {"titre": "Habillage chrono + contrôle croisé", "duree": "10 min", "prep": "Tenues complètes posées au sol, chronomètre.", "deroule": ["Au top, chaque binôme s'équipe.", "Contrôle croisé obligatoire : aucune peau visible, tout fermé, jugulaire, gants.", "Le temps ne compte que si le contrôle est parfait."], "phrase": "Aucune peau à l'air.", "securite": "Pas de course : on s'équipe vite mais bien, sans se bousculer."}, {"titre": "« Ça chauffe ! » — le repli", "duree": "20 min", "prep": "Couloir de plots dans la cour, une cible « foyer », binôme avec une lance en eau à faible débit.", "deroule": ["Le binôme progresse vers la cible, en contact permanent.", "À l'annonce « ça chauffe ! », il applique : alerter, se baisser, refroidir (impulsions vers le haut), écran en diffusé large.", "Il se replie ensemble par le chemin d'entrée, lance face au feu, l'équipier guide en suivant le tuyau.", "Variante « Que fais-tu ? » : tu annonces un signe (fumées qui descendent, porte chaude, sifflement), le binôme dit et mime sa réaction."], "phrase": "La lance, c'est la vie : on ne la lâche jamais.", "securite": "À froid, sans feu réel, lance à faible débit, jamais de jet vers un camarade."}], "questions": [{"q": "Pourquoi enlever montre et bijoux ?", "r": "Ils chauffent, brûlent et s'accrochent."}, {"q": "Une tenue mouillée protège-t-elle mieux ?", "r": "Non, elle peut transmettre la chaleur et la vapeur."}, {"q": "Les oreilles qui brûlent, ça veut dire quoi ?", "r": "Il fait trop chaud : on se baisse ou on recule."}, {"q": "Premier geste si ça chauffe d'un coup ?", "r": "Alerter son binôme et son chef."}, {"q": "Quel jet pour faire écran ?", "r": "Le jet diffusé large de protection."}, {"q": "Par où se replier ?", "r": "Par le chemin d'entrée, en suivant le tuyau."}, {"q": "Que veut dire « je sais, je sens, je vois » ?", "r": "Les niveaux de souillure de la tenue qui décident du nettoyage."}, {"q": "Bloqué sans sortie possible, que fais-tu ?", "r": "Je me mets à l'abri porte fermée, message « URGENT », je vais à la fenêtre, j'économise l'air."}], "quiz": [{"q": "Avant d'entrer, qui vérifie mes EPI ?", "bonne": "Mon binôme (contrôle croisé)", "fausses": ["Personne", "Le conducteur seulement", "Moi seul dans le rétroviseur"], "expl": ""}, {"q": "Une tenue de feu…", "bonne": "Retarde la brûlure, ne l'empêche pas", "fausses": ["Protège de tout", "Protège de l'électricité", "Protège mieux quand elle est trempée"], "expl": ""}, {"q": "Mes mains et oreilles brûlent sous la tenue :", "bonne": "Il fait trop chaud, je me baisse ou je recule", "fausses": ["C'est normal, je continue", "J'enlève mes gants", "J'ouvre ma veste pour avoir de l'air"], "expl": ""}, {"q": "Premier geste quand ça chauffe d'un coup ?", "bonne": "Alerter le binôme et le chef", "fausses": ["Courir vers la sortie seul", "Lâcher la lance", "Ouvrir les fenêtres"], "expl": ""}, {"q": "Pour faire écran au-dessus du binôme, j'utilise…", "bonne": "Le jet diffusé large", "fausses": ["Le jet droit", "La lance fermée", "Un extincteur à poudre"], "expl": ""}, {"q": "Pour se replier, on suit…", "bonne": "Le tuyau, vers le point d'entrée", "fausses": ["Le chemin le plus court au hasard", "La fumée", "Le bruit du feu"], "expl": "C'est le chemin de repli."}, {"q": "Tenue très sale après un feu :", "bonne": "Au sac, je prends une tenue propre", "fausses": ["Je la lave à la maison", "Je la garde pour la prochaine fois", "Je remonte en cabine avec"], "expl": "Nettoyage selon la souillure (RDEB § 4.2)."}], "statut": "brouillon", "source": "Cours 2026 « L'autoprotection – protéger son binôme » (charte SDIS 34) · RNF INC C4 · RDEB v2 (avril 2026) § 2.1-2.10, 3.3-3.6, 4.2, 5.8 · RDSMES v2 § 4-5 · RDLSPCC § 2.6 — techniques de protection face au phénomène thermique : doctrine nationale, à valider avec le formateur"}, "JSP4|Le prompt secours (bilans, traumatismes, noyade, relevage)": {"cycle": "JSP4", "bloc": "Prompt secours", "item": "Le prompt secours (bilans, traumatismes, noyade, relevage)", "objectif": "Sur mannequin ou camarade volontaire, réaliser un bilan complet (circonstanciel, urgence vitale, complémentaire), immobiliser un membre traumatisé, transmettre le bilan dans l'ordre et repérer 6 victimes avec les couleurs — 45 min, sans oubli d'étape.", "pointsCles": ["Les bilans toujours dans le même ordre : circonstanciel, urgence vitale, complémentaire, surveillance, transmission (PSE)", "Le bilan complémentaire ne commence que lorsque les détresses vitales sont prises en charge (PSE 02PR03/02PR04)", "Après un malaise : interroger (où, depuis quand, déclencheur, douleur de 0 à 10, maladies, médicaments, allergies) et examiner ; visage, bras ou parole anormaux = peut-être un AVC, on le dit tout de suite", "Après un traumatisme : mécanisme (hauteur de chute, type de choc, casque, ceinture), plaintes (fourmillements, « décharges »), palpation de la tête aux pieds ; choc violent ou trouble de conscience : maintien de la tête d'abord", "Surveillance jusqu'à la fin (respiration, pouls, couleur, conscience, plaintes), surtout après relevage ou transport ; transmission : motif, victime (sexe, âge), plainte principale, résultats des bilans, gestes faits (PSE 02PR06)", "Membre douloureux = on le considère comme fracturé : ne pas le bouger, couvrir une plaie, retirer bagues et bracelets, immobiliser en prenant les articulations au-dessus et au-dessous, vérifier le bout du membre avant et après ; froid enveloppé sur une entorse", "Réaligner un membre déformé : pas pour les JSP (geste réservé aux équipes formées)", "Noyade : 4 niveaux (aquastress, petit hypoxique, grand hypoxique, anoxique) ; ne jamais plonger seul ; ne respire pas = 5 insufflations puis RCP et DAE (thorax séché) ; respire = protéger du froid, PLS si inconsciente ; toujours un avis médical", "Relevage : à plusieurs, un seul chef (en général à la tête), axe tête-cou-tronc, dos droit ; brancardage à 4, pieds devant, tête en haut dans l'escalier", "Nombreuses victimes : renforts en disant « nombreuses victimes » ; noir, rouge, jaune, vert (PSE 02FT10)"], "materiel": "VSAV du CIS (attelles à dépression 3 tailles, colliers cervicaux, matelas immobilisateur et pompe, plan dur, brancard cuillère, chaise portoir, brancard avec sangles, couverture), mannequins de RCP adulte/enfant, DAE de formation, cartes situations, fiches victimes et matériel de maquillage, rubans ou étiquettes de couleur (noir, rouge, jaune, vert), tapis de sol.", "activites": [{"titre": "La chute : du bilan à la transmission", "duree": "12 min", "prep": "Un JSP joue la victime (chute d'un mur, jambe douloureuse) avec une fiche, un formateur premiers secours observe.", "deroule": ["Le binôme sécurise, fait le bilan circonstanciel puis d'urgence vitale.", "Il fait le bilan complémentaire : mécanisme, plaintes, palpation de la tête aux pieds.", "Il maintient la jambe dans la position trouvée et l'immobilise avec une attelle à dépression, en vérifiant le bout du pied avant et après.", "Il transmet le bilan à voix haute dans l'ordre (motif, victime, plainte, bilans, gestes)."], "phrase": "Je ne bouge pas un membre douloureux : je l'immobilise.", "securite": "Aucun réalignement de membre. Victime simulée, gestes doux, encadrement par un formateur premiers secours."}, {"titre": "La piscine : noyé qui respire / ne respire pas", "duree": "10 min", "prep": "Mannequin RCP au sol sur une couverture « mouillée », DAE de formation, cartes « respire » / « ne respire pas ».", "deroule": ["Rappel : on ne plonge pas seul, on tend, on lance, on appelle.", "Carte « ne respire pas » : alerte, 5 insufflations, RCP, DAE après avoir séché le thorax.", "Carte « respire » : retirer le mouillé, sécher, couvrir, PLS si inconscient, alerter, surveiller.", "Conclure : toute personne qui a avalé de l'eau voit un médecin."], "phrase": "Un sauveteur qui se noie, c'est deux victimes.", "securite": "RCP et insufflations uniquement sur mannequin. Activité à sec, pas de mise à l'eau."}, {"titre": "Le VSAV : préparer, relever, brancarder", "duree": "13 min", "prep": "Brancard, matelas immobilisateur, pompe et couverture sortis du VSAV ; mannequin ou camarade volontaire de corpulence adaptée.", "deroule": ["En binôme, préparer le dispositif de portage : brancard vérifié, couverture et drap, matelas étalé, billes réparties, robinet fermé (chronométré).", "Relevage à 4 sous les ordres de celui qui tient la tête : « Attention pour lever… Levez ! ».", "Mouler le matelas, faire le vide, sangler, couvrir.", "Brancardage à 4 au pas, pieds devant, en parlant à la victime."], "phrase": "Un seul chef, tête-cou-tronc alignés.", "securite": "Dos droit, jambes fléchies. Engin à l'arrêt, clés retirées. Victime : mannequin ou camarade volontaire, encadrement par un formateur PSE."}, {"titre": "L'accident de car : repérage en 3 minutes", "duree": "10 min", "prep": "6 JSP maquillés avec une fiche victime (une décédée, une inconsciente qui respire, une hémorragie, une fracture de jambe, deux impliqués qui marchent), rubans de couleur.", "deroule": ["Le binôme annonce « nombreuses victimes » et demande des renforts.", "Il aborde les victimes en commençant par la plus proche, bilan d'urgence vitale rapide.", "Il pose la bonne couleur (noir, rouge, jaune, vert) en 3 minutes.", "Débriefing : la couleur de chaque victime et pourquoi."], "phrase": "", "securite": "Maquillage non irritant ; aucun geste invasif, simple repérage."}], "questions": [{"q": "Dans quel ordre fait-on les bilans ?", "r": "Circonstanciel, urgence vitale, complémentaire, puis surveillance et transmission."}, {"q": "Quand commence le bilan complémentaire ?", "r": "Une fois les détresses vitales prises en charge."}, {"q": "Visage, bras ou parole anormaux : à quoi penses-tu ?", "r": "Une atteinte du cerveau (AVC) : on le signale tout de suite."}, {"q": "Que fais-tu d'un membre douloureux et déformé ?", "r": "Je ne le bouge pas, je le maintiens dans la position trouvée et je l'immobilise."}, {"q": "Que vérifies-tu au bout du membre, avant et après l'immobilisation ?", "r": "La couleur, la chaleur et la sensibilité des doigts ou des orteils."}, {"q": "Que transmets-tu au chef ?", "r": "Motif réel, victime (sexe et âge), plainte principale, résultats des bilans, gestes faits."}, {"q": "Un noyé ne respire pas : par quoi commences-tu ?", "r": "5 insufflations, puis la RCP et le défibrillateur, thorax séché."}, {"q": "Pourquoi un noyé qui va bien doit-il voir un médecin ?", "r": "Son état peut s'aggraver plus tard."}, {"q": "Qui donne les ordres au relevage ?", "r": "Un seul équipier, en général celui qui tient la tête."}, {"q": "Quelle couleur pour une victime consciente, sans détresse, qui marche ?", "r": "Vert."}], "quiz": [{"q": "Quand fait-on le bilan complémentaire ?", "bonne": "Après le bilan d'urgence vitale, détresses prises en charge", "fausses": ["Avant tout autre bilan", "Seulement à l'hôpital", "Pendant le bilan circonstanciel"], "expl": "PSE 02PR03/02PR04."}, {"q": "Un noyé ne respire pas : on commence par…", "bonne": "5 insufflations", "fausses": ["30 compressions", "Le faire vomir", "Le mettre en PLS"], "expl": "Puis RCP et DAE, thorax séché."}, {"q": "Un membre douloureux et déformé, on…", "bonne": "Le maintient dans la position trouvée et l'immobilise", "fausses": ["Le remet droit", "Fait marcher la victime", "Le masse doucement"], "expl": "Réaligner : pas pour les JSP."}, {"q": "Qui commande le relevage ?", "bonne": "Celui qui tient la tête", "fausses": ["Le plus âgé", "Celui qui tient les pieds", "Chacun à son tour"], "expl": ""}, {"q": "Dans un escalier, la tête de la victime brancardée reste…", "bonne": "En haut", "fausses": ["En bas", "À l'horizontale, peu importe", "Tournée sur le côté"], "expl": ""}, {"q": "Victime inconsciente qui respire, en cas de nombreuses victimes :", "bonne": "Rouge", "fausses": ["Vert", "Jaune", "Noir"], "expl": "PSE 02FT10."}, {"q": "Visage asymétrique, bras qui tombe, parole bizarre :", "bonne": "Penser à un AVC et le signaler tout de suite", "fausses": ["Attendre que ça passe", "Lui donner à boire", "La faire marcher"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Le prompt secours – Bilans, traumatismes, noyade, relevage » (charte SDIS 34) · Recommandations PSE (02PR03, 02PR04, 02PR05, 02PR06, 02FT10, noyade, traumatisme des membres, relevage) · FAT VSAV SDIS 34 (matériel de brancardage et d'immobilisation) · RNF JSP/JMP v1.1 PS A1 — classification de la noyade à valider avec le formateur PSE du centre"}, "JSP4|La mise en œuvre de l'ARI": {"cycle": "JSP4", "bloc": "Protection individuelle et collective", "item": "La mise en œuvre de l'ARI", "objectif": "Capeler, coiffer et faire le contrôle croisé RAPACE sans hésiter, puis réaliser en binôme un parcours sans visibilité avec obstacles, retrouver un mannequin, le sortir et passer un message de détresse « URGENT » complet — 45 min, sans erreur de sécurité.", "pointsCles": ["Réflexes automatiques : capeler, coiffer sans fuite à l'air frais, RAPACE (Robinet, Armement, Pression ≥ 270 bars, Ajustement, Code, Étanchéité), codes, lecture du manomètre ; binôme indissociable (RDEB § 2.6-2.10)", "Règle des minimums : minimum de personnes (avec un binôme de sécurité prêt), de temps (selon l'air et la consommation), de risque (danger connu et mesuré) (RDSMES § 2.3)", "Progresser sans visibilité : relié à la ligne de vie, main gauche ou main droite ; accroupi ou à 4 pattes s'il fait chaud ; fils et câbles : passer dessous, bouteille dans l'angle mur/sol ; escalier dangereux en marche arrière (RDEB § 3.11, RDSMES § 5.5)", "Sauvetage = danger de mort immédiat, la personne ne peut pas s'en sortir seule ; mise en sécurité = évacuation (on accompagne) ou confinement (à l'abri sur place, porte fermée) (RDSMES § 1)", "Rassurer la victime : « Pompiers ! », la toucher, expliquer, ne plus la lâcher ; elle marche = on l'accompagne, sinon on la porte seul ou à deux (RDSMES § 2.1, § 3.1)", "Cagoule d'évacuation : pour un long chemin enfumé, pas si la sortie est à vue ; l'air vient de la bouteille du sauveteur, qui consomme plus ; rassurer pendant la pose (RDSMES § 3.7)", "Rechercher : main gauche / main droite, pièce par pièce, marquage R, méthode AIDES ; chercher sous les lits, placards, salle de bain, derrière les portes, près des fenêtres", "En difficulté : S-P-A (Signalement, Positionnement au sol contre un mur, Air) ; « saut d'inspiration » ; en économie d'air, une bouteille de 6 L à 300 bars dure environ 3 h ; le sifflet consomme aussi de l'air (RDSMES § 5.2-5.3)", "Message de détresse : « URGENT, URGENT, URGENT » puis je suis, je vois (avec la pression), je fais, je demande (RDSMES § 5.7)", "Équipier qui manque d'air : cagoule d'évacuation ou raccordement à sa bouteille, on ressort tout de suite et on prévient (RDSMES § 5.4)"], "materiel": "ARI du FPTGP (ARI-CO, bouteilles, masques), cagoule d'évacuation, ligne guide / ligne de vie, masques occultés (cagoules opaques), lampes, craie, caméra thermique, mannequin de sauvetage, tables, chaises, cordes tendues pour figurer des câbles, tapis de sol, chronomètre, tableau de contrôle (pressions et heure), postes radio portatifs.", "activites": [{"titre": "Prêt à s'engager : capelage chrono", "duree": "10 min", "prep": "ARI du FPTGP vérifiés, chronomètre, formateur ARI.", "deroule": ["Chaque binôme capelle et coiffe le masque à l'air frais, chronométré.", "Contrôle croisé RAPACE à voix haute avec le chef d'équipe.", "Annonce de la pression au contrôleur, qui la note avec l'heure.", "On recommence jusqu'à l'automatisme."], "phrase": "Sous le masque, on n'a plus le temps de réfléchir.", "securite": "ARI capelé uniquement en air sain, sous la conduite d'un formateur, selon les règles d'emploi des ARI à l'entraînement du SDIS 34 (âge, aptitude, encadrement)."}, {"titre": "Le parcours opérationnel", "duree": "20 min", "prep": "Local sûr balisé : table, cordes tendues (câbles), passage bas, quelques marches ; masques occultés ; ligne guide ; mannequin caché ; contrôleur au point d'engagement ; binôme de sécurité équipé.", "deroule": ["Le binôme s'engage relié à la ligne, main droite, sans visibilité.", "Il franchit les obstacles (passer sous les câbles, marches en marche arrière) et marque R les pièces faites.", "Il trouve le mannequin, le « rassure », rend compte et le sort par le chemin de repli.", "À mi-parcours, l'animateur simule un incident (masque « en panne », équipier « coincé ») : le binôme se positionne (S-P-A) et passe le message « URGENT » complet."], "phrase": "Je suis, je vois, je fais, je demande.", "securite": "Aucune fumée réelle, aucune évolution sous fumée. Air sain, contrôleur et binôme de sécurité en place, arrêt immédiat au moindre malaise. Victime = mannequin."}, {"titre": "Sortir une victime", "duree": "10 min", "prep": "Tapis de sol, JSP de gabarit proche, sans ARI.", "deroule": ["Démonstration : accompagner, porter à dos, porter dans les bras, porter en chaise à deux.", "Les binômes s'entraînent sur quelques mètres, en parlant à la « victime ».", "Discussion : sauvetage, évacuation ou confinement ? cagoule d'évacuation ou non ?"], "phrase": "", "securite": "Sans ARI, entre JSP de gabarit proche, sur tapis, dos droit."}, {"titre": "Quiz express S-P-A et NELAR", "duree": "5 min", "prep": "Cartes situations.", "deroule": ["Tu lis une situation (« je suis coincé, 80 bars »).", "Les binômes donnent la bonne réaction et formulent le message à la radio."], "phrase": "", "securite": ""}], "questions": [{"q": "Que veut dire RAPACE ?", "r": "Robinet, Armement, Pression ≥ 270 bars, Ajustement, Code, Étanchéité."}, {"q": "Quelle est la règle des minimums ?", "r": "Le minimum de personnes, de temps et de risque."}, {"q": "Sauvetage ou mise en sécurité : quelle différence ?", "r": "Sauvetage : danger de mort immédiat ; mise en sécurité : on éloigne la personne avant le danger."}, {"q": "Que fais-tu en premier face à une victime qui panique ?", "r": "Je la rassure : je me présente, je la touche, je lui explique."}, {"q": "D'où vient l'air de la cagoule d'évacuation ?", "r": "De la bouteille du sauveteur."}, {"q": "Comment passer sous des câbles tombés ?", "r": "Au plus près du sol, bouteille dans l'angle mur/sol."}, {"q": "Que veut dire S-P-A ?", "r": "Signalement, Positionnement, Air."}, {"q": "Comment commence un message de détresse ?", "r": "« URGENT, URGENT, URGENT »."}, {"q": "Quelles sont les 4 parties du message ?", "r": "Je suis, je vois, je fais, je demande."}], "quiz": [{"q": "La cagoule d'évacuation prend son air…", "bonne": "Sur la bouteille du sauveteur", "fausses": ["Dans l'air ambiant", "Sur une bouteille à part", "Sur l'engin"], "expl": "Le sauveteur consomme plus."}, {"q": "Une personne non menacée qu'on fait sortir en l'accompagnant, c'est…", "bonne": "Une évacuation", "fausses": ["Un sauvetage", "Un confinement", "Un dégagement d'urgence"], "expl": "RDSMES § 1.2."}, {"q": "Dans S-P-A, le P veut dire…", "bonne": "Positionnement", "fausses": ["Pression", "Prévenir", "Porter"], "expl": "Au plus près du sol, contre un mur."}, {"q": "Un message de détresse commence par…", "bonne": "« URGENT, URGENT, URGENT »", "fausses": ["« ÉVACUATION » trois fois", "« Allô, ici… »", "« Message prioritaire »"], "expl": ""}, {"q": "Un escalier dangereux sous ARI se descend…", "bonne": "En marche arrière", "fausses": ["En courant", "Sur le dos", "En sautant les marches"], "expl": "RDEB § 3.11."}, {"q": "La cagoule d'évacuation n'est pas conseillée quand…", "bonne": "La sortie est tout près et visible", "fausses": ["Le chemin est long et enfumé", "La victime tousse", "Il fait très chaud"], "expl": ""}, {"q": "Pour économiser l'air en attendant les secours :", "bonne": "Le saut d'inspiration", "fausses": ["Courir vers la sortie", "Respirer très vite", "Enlever le masque"], "expl": "Inspirer, retenir, expirer."}], "statut": "brouillon", "source": "Cours 2026 « L'ARI en action – Chercher, sauver, se sauver » (charte SDIS 34) · RDEB v2 (avril 2026) § 2.6-2.11, § 3.10-3.12 · RDSMES v2 (avril 2026) § 1, § 2.1, § 2.3, § 3.1, § 3.7, § 5.1-5.8 · RNF JSP/JMP v1.1 INC A5"}, "JSP4|La gestion du stress": {"cycle": "JSP4", "bloc": "Organisation et missions du SIS", "item": "La gestion du stress", "objectif": "Citer deux signes du stress dans le corps, réaliser 4 cycles de respiration carrée et nommer les personnes ressources (camarades, chefs, SSSM, famille) — 40 min, sans aide.", "pointsCles": ["Le stress est une réaction normale d'alarme du corps, pas une faiblesse : le bon stress met en alerte, le stress débordé fait paniquer, figer ou oublier la sécurité", "Le but n'est pas de ne jamais stresser, mais de garder le contrôle", "Les signes : dans le corps (cœur qui s'emballe, souffle court, mains moites), les émotions, la tête (trous de mémoire, vision « en tunnel »), le comportement (agitation ou blocage)", "Les causes du pompier : être débutant, interventions difficiles, milieu contraint (chaleur, bruit, fumée, sous ARI), trop d'activité, violence, la vie à côté", "Avant : s'entraîner jusqu'aux automatismes, anticiper, étudier les RETEX, prendre soin de soi (RDEB § 2.3 « La préparation psychologique »)", "Pendant : respiration carrée (4 temps de 4 : inspirer, bloquer, souffler, bloquer, 3 à 4 cycles) ; sous ARI, on ne bloque pas, on ralentit et on allonge l'expiration", "Pendant : suivre la procédure, compter sur son binôme, se parler positivement, dire stop au chef d'agrès si on n'est plus capable", "Après : en parler à l'équipe, se reposer ; signes d'alerte : cauchemars, images qui reviennent, envie de s'isoler, tristesse ou colère qui durent", "Personnes ressources : camarades, animateurs et chefs, SSSM (médecins, infirmiers, psychologues), famille : en parler est un réflexe de professionnel", "Veille collective : un camarade change, je vais vers lui, je l'écoute, j'en parle à un animateur ; face à la violence, le JSP ne s'interpose jamais : il se met en retrait et alerte"], "materiel": "Tableau ou paperboard, post-it, chronomètre, mannequin de secourisme ou cordage pour le geste « sous pression », fiche des personnes ressources du SDIS 34 (à faire compléter par le chef de centre).", "activites": [{"titre": "Mes signes du stress", "duree": "10 min", "prep": "Paperboard divisé en 4 zones : corps, émotions, tête, comportement.", "deroule": ["Chacun cite un signe ressenti avant un contrôle ou une compétition.", "On le range dans la bonne zone.", "Bon stress ou stress débordé ? On en discute."], "phrase": "Le pompier n'est pas quelqu'un qui n'a jamais peur, c'est quelqu'un qui a appris à gérer son stress.", "securite": "Sujet sensible : pas d'obligation de parler, pas de moquerie."}, {"titre": "Respiration carrée", "duree": "8 min", "prep": "Les JSP assis, chronomètre.", "deroule": ["Chacun prend son pouls.", "4 cycles de respiration carrée yeux fermés (inspirer 4, bloquer 4, souffler 4, bloquer 4).", "On reprend le pouls et on compare."], "phrase": "Je respire, je reprends le contrôle.", "securite": "Ne pas forcer les blocages ; arrêter en cas de malaise."}, {"titre": "Sous pression", "duree": "15 min", "prep": "Un geste maîtrisé (PLS sur camarade volontaire ou mannequin, nœud), chronomètre.", "deroule": ["Un JSP fait la respiration carrée puis réalise le geste chronométré, encouragé bruyamment par le groupe.", "On change de JSP.", "Débriefing : qu'as-tu ressenti ? Qu'est-ce qui t'a aidé à rester concentré ?"], "phrase": "", "securite": "Stress léger et bienveillant : jamais de moquerie, jamais de mise en échec."}, {"titre": "Qui peut m'aider ?", "duree": "7 min", "prep": "Cartes situations (un camarade s'isole depuis une intervention, une personne agressive, cauchemars après un accident).", "deroule": ["Les binômes tirent une carte.", "Ils disent ce qu'ils font et à qui ils en parlent."], "phrase": "En parler, c'est un réflexe de professionnel.", "securite": "Si un JSP évoque un vécu difficile, proposer un échange individuel après la séance."}], "questions": [{"q": "Le stress, c'est grave ?", "r": "Non, c'est normal ; il faut apprendre à le gérer."}, {"q": "Cite deux signes du stress dans le corps.", "r": "Cœur qui s'emballe, mains moites, souffle court, ventre noué…"}, {"q": "Comment se préparer avant ?", "r": "S'entraîner, anticiper, étudier les RETEX, hygiène de vie."}, {"q": "Comment fait-on la respiration carrée ?", "r": "4 temps de 4 : inspirer, bloquer, souffler, bloquer."}, {"q": "Sous ARI, peut-on bloquer sa respiration ?", "r": "Non : on ralentit et on allonge l'expiration."}, {"q": "Tu ne te sens plus capable en intervention : que fais-tu ?", "r": "Je le dis au chef d'agrès."}, {"q": "Un camarade s'isole depuis une intervention ?", "r": "Je vais vers lui, je l'écoute et j'en parle à un animateur."}, {"q": "Qui sont les psychologues du SDIS ?", "r": "Le SSSM (service de santé et de secours médical)."}], "quiz": [{"q": "Le stress, c'est…", "bonne": "Une réaction normale du corps", "fausses": ["Une maladie grave", "Une faiblesse", "Réservé aux débutants"], "expl": "Le but : garder le contrôle."}, {"q": "La respiration carrée se fait en…", "bonne": "4 temps : inspirer, bloquer, souffler, bloquer", "fausses": ["2 temps très rapides", "En retenant son souffle 1 minute", "En soufflant le plus fort possible"], "expl": ""}, {"q": "Où trouver les psychologues du SDIS ?", "bonne": "Au SSSM", "fausses": ["Au CTA-CODIS", "Au service habillement", "À la mairie"], "expl": ""}, {"q": "Lequel est un signe d'alerte après une intervention ?", "bonne": "Des images qui reviennent sans cesse", "fausses": ["Avoir faim au retour", "Être fatigué le soir même", "Discuter avec l'équipe"], "expl": "Si ça dure, on en parle à un professionnel."}, {"q": "Face à une personne violente, le JSP…", "bonne": "Se met en retrait et alerte son chef", "fausses": ["S'interpose", "Répond aux insultes", "Filme la scène"], "expl": ""}, {"q": "Pour se préparer psychologiquement, on peut…", "bonne": "Étudier les retours d'expérience (RETEX)", "fausses": ["Éviter de s'entraîner", "Ne jamais en parler", "Dormir moins"], "expl": "RDEB § 2.3."}], "statut": "brouillon", "source": "Cours 2026 « La gestion du stress » (charte SDIS 34) · RNF JSP/JMP v1.1 SC B2 · RDEB v2 (avril 2026) § 2.2-2.3 · RDSMES v2 (avril 2026) « gestion de l'affect » — contenu de portée générale, à valider avec le SSSM / psychologue du SDIS 34"}, "JSP4|Les valeurs et l'éthique des sapeurs-pompiers": {"cycle": "JSP4", "bloc": "Engagement citoyen", "item": "Les valeurs et l'éthique des sapeurs-pompiers", "objectif": "Citer les 6 valeurs et les 4 règles d'éthique des sapeurs-pompiers et choisir la conduite juste dans 4 cas concrets de la vie de la section — 40 min, en nommant la valeur en jeu.", "pointsCles": ["Six valeurs : honnêteté, discipline, courage, dévouement, honneur, respect de l'autre (RNF SC A1)", "Les valeurs se voient au quotidien : dire qu'on a cassé du matériel, arriver à l'heure en tenue, empêcher une moquerie, aider à ranger, bien se tenir en tenue, écouter tout le monde", "La charte du sapeur-pompier volontaire, signée à l'engagement : servir avec dévouement et neutralité, respecter les règles et la hiérarchie, se former et rester apte, être discret, avoir une conduite exemplaire", "Quatre règles d'éthique : altruisme (aider tout le monde sans rien attendre), efficience (bien faire avec ce qu'on a), discrétion (ce qu'on voit reste secret), devoir de réserve (ne pas critiquer le service en public ni parler en son nom)", "Réseaux sociaux : jamais de photo d'intervention ou de victime, de moquerie, de critique du SDIS, de photo des engins ou locaux sans autorisation ; on peut partager les publications officielles", "Face au public : rassurer les victimes, respecter leur pudeur et leurs affaires, rester calme avec les familles, aider chacun sans distinction d'origine, de religion ou d'opinion", "Le collectif : diversité, intelligence collective, entraide des anciens envers les nouveaux, bienveillance (encourager plutôt que moquer)", "SPP et SPV : une seule équipe, mêmes valeurs, mêmes interventions ; près de 8 sapeurs-pompiers sur 10 sont volontaires en France", "En JSP4, on est des modèles pour les JSP1 et JSP2"], "materiel": "Paperboard, post-it ou feuilles, 4 cartes « Que ferais-tu ? », la charte du sapeur-pompier volontaire (document SDIS 34) et le règlement de la section JSP.", "activites": [{"titre": "Un bon pompier en 3 mots", "duree": "8 min", "prep": "Post-it, paperboard avec les 6 valeurs en colonnes.", "deroule": ["Chacun écrit 3 mots pour décrire un bon pompier.", "On les colle sous la valeur qui correspond.", "On constate qu'on retrouve les valeurs officielles."], "phrase": "Les valeurs, c'est ce que tout le monde attend déjà d'un pompier.", "securite": ""}, {"titre": "Que ferais-tu ?", "duree": "20 min", "prep": "4 cartes : vidéo d'une manœuvre ratée à poster, portefeuille trouvé pendant un exercice, nouveau JSP seul à la pause, erreur de sécurité du binôme non vue.", "deroule": ["Chaque groupe reçoit un cas et discute 5 minutes.", "Il présente sa réponse et la valeur en jeu.", "Le groupe complète ; on cherche ensemble la conduite juste."], "phrase": "", "securite": "Pas de mauvaise réponse sanctionnée."}, {"titre": "Poster ou pas poster ?", "duree": "12 min", "prep": "Une série d'exemples de publications (photo de victime, photo officielle de la cérémonie, selfie devant le FPTGP sans autorisation, critique d'un chef…).", "deroule": ["Tu lis un exemple.", "Les JSP lèvent le pouce (je peux) ou croisent les bras (jamais).", "Ils justifient avec la discrétion ou le devoir de réserve."], "phrase": "Ce qu'on voit en intervention reste secret, aussi sur Internet.", "securite": ""}], "questions": [{"q": "Cite les 6 valeurs.", "r": "Honnêteté, discipline, courage, dévouement, honneur, respect de l'autre."}, {"q": "C'est quoi l'altruisme ?", "r": "Penser d'abord aux autres, aider sans rien attendre."}, {"q": "La discrétion, c'est quoi ?", "r": "Garder secret ce qu'on voit et entend."}, {"q": "Le devoir de réserve, c'est quoi ?", "r": "Ne pas critiquer le service en public ni parler en son nom."}, {"q": "Peut-on poster la photo d'une victime ?", "r": "Jamais."}, {"q": "SPP et SPV, qui fait quoi ?", "r": "Les mêmes missions, côte à côte : une seule équipe."}, {"q": "Tu trouves un portefeuille pendant un exercice : quelle valeur est en jeu ?", "r": "L'honnêteté."}, {"q": "Qu'est-ce que l'efficience ?", "r": "Bien faire avec ce qu'on a : ni gaspiller, ni bâcler."}], "quiz": [{"q": "Laquelle N'EST PAS une des 6 valeurs du cours ?", "bonne": "La richesse", "fausses": ["Le courage", "L'honneur", "La discipline"], "expl": "Honnêteté, discipline, courage, dévouement, honneur, respect de l'autre."}, {"q": "Garder secret ce qu'on voit en intervention, c'est…", "bonne": "La discrétion", "fausses": ["L'efficience", "Le dévouement", "Le courage"], "expl": ""}, {"q": "Ne pas critiquer le SDIS sur Internet, c'est…", "bonne": "Le devoir de réserve", "fausses": ["L'altruisme", "La discipline", "L'honneur"], "expl": ""}, {"q": "Une photo d'une victime sur les réseaux :", "bonne": "Jamais", "fausses": ["Oui si elle est floue", "Oui en story seulement", "Oui avec un filtre"], "expl": ""}, {"q": "En France, les sapeurs-pompiers volontaires sont…", "bonne": "Près de 8 sur 10", "fausses": ["Environ 1 sur 10", "La moitié", "Presque aucun"], "expl": ""}, {"q": "Aider chacun sans distinction d'origine ou de religion, c'est…", "bonne": "La neutralité et le respect de l'autre", "fausses": ["Le devoir de réserve", "L'efficience", "La discipline"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « Les valeurs et l'éthique des sapeurs-pompiers » (charte SDIS 34) · RNF JSP/JMP v1.1 SC A1 · Charte nationale du sapeur-pompier volontaire · Règlement intérieur du SDIS 34 · Règlement de la section JSP"}, "JSP4|La préparation physique aux épreuves du brevet de JSP": {"cycle": "JSP4", "bloc": "Activités physiques et sportives", "item": "La préparation physique aux épreuves du brevet de JSP", "objectif": "Citer les 4 épreuves sportives du brevet et leurs règles, passer un brevet blanc sur une épreuve et fixer avec l'animateur un objectif personnel par épreuve — 45 min.", "pointsCles": ["Quatre épreuves : natation 50 m, course de 12 minutes, force des bras (tractions ou pompes), parcours sportif du sapeur-pompier (RNE p. 33-37)", "Chaque épreuve est notée A, B ou C ; pour valider : au moins 3 A et 1 B, en respectant les critères du règlement technique", "Barèmes officiels différenciés filles/garçons (RNE p. 37) : à présenter tels quels, sans les modifier ni les arrondir", "Natation : départ plongé ou sauté, toutes les nages, interdit de s'arrêter, toucher le mur, sortir seul sans échelle ni marche", "Course de 12 min : sans s'arrêter, je gère mon allure ; repère du cours : 2 000 m en 12 min = un tour de 400 m toutes les 2 min 24", "Tractions en supination, bras tendus en bas, menton au-dessus de la barre ; pompes mains et pieds largeur d'épaules, descente bras pliés, remontée bras tendus", "Parcours sportif : sauter, ramper, franchir, s'équilibrer, tirer un dévidoir, porter un sac ; 6 lancers de commande au maximum ; chrono jusqu'à la ligne d'arrivée", "Bien s'entraîner : régulièrement (2 à 3 séances par semaine), progressivement, avec récupération, et se tester de temps en temps", "Porter sans se blesser : plier les jambes, dos droit, charge près du corps, pas de torsion (PRAP)", "Jour J : bien dormir, manger léger 2 à 3 h avant, boire, s'échauffer ; après : récupérer en marchant, s'étirer, encourager les autres"], "materiel": "Piste ou terrain plat mesuré, plots tous les 100 m, chronomètres, barre de tractions, tapis, aire et agrès du PSSP (dévidoir, sac, commande), fiches individuelles d'objectifs, barème officiel RNE p. 37 imprimé tel quel.", "activites": [{"titre": "Les 4 épreuves et les bonnes règles", "duree": "10 min", "prep": "Barème officiel imprimé, barre de tractions, tapis.", "deroule": ["Présenter les 4 épreuves et la règle 3 A + 1 B.", "Démonstration d'une traction valide et d'une pompe valide ; les JSP jugent des exemples « valide / pas valide ».", "Rappel des règles de la natation (pas d'arrêt, sortie seule)."], "phrase": "", "securite": "Parade assurée par l'encadrement aux tractions."}, {"titre": "Course : apprendre son allure", "duree": "15 min", "prep": "Piste de 400 m (ou boucle mesurée), plots tous les 100 m, chronomètre, sifflet toutes les 36 s.", "deroule": ["Après échauffement, les JSP courent en essayant d'arriver à chaque plot au coup de sifflet (allure 2 000 m en 12 min).", "Ceux qui le souhaitent ralentissent sur une allure plus confortable.", "Retour : ai-je tenu le rythme ? trop vite au début ?"], "phrase": "Je gère mon allure moi-même.", "securite": "Échauffement systématique ; chacun court à son niveau, arrêt en cas de malaise."}, {"titre": "Porter sans se blesser + mini-parcours", "duree": "12 min", "prep": "Sac et dévidoir du PSSP, commande, 2-3 agrès.", "deroule": ["Rappel des 4 règles du port de charge, chaque JSP soulève le sac correctement sous l'œil d'un camarade.", "Enchaînement de 2-3 agrès avec dévidoir et lancer de commande (6 lancers au maximum)."], "phrase": "Je plie les jambes, pas le dos.", "securite": "Agrès vérifiés, réception sur tapis, encadrement par un animateur APS ou EAP."}, {"titre": "Mes objectifs", "duree": "8 min", "prep": "Fiches individuelles d'objectifs.", "deroule": ["Chaque JSP note l'épreuve qui l'inquiète le plus et son objectif pour le brevet blanc.", "Entretien rapide avec l'animateur, sans classement."], "phrase": "", "securite": "Résultats individuels, jamais affichés."}], "questions": [{"q": "Quelles sont les 4 épreuves sportives du brevet ?", "r": "Natation 50 m, course de 12 min, tractions ou pompes, parcours sportif."}, {"q": "Combien de A et de B pour valider ?", "r": "Au moins 3 A et 1 B."}, {"q": "En natation, peut-on s'arrêter ?", "r": "Non, et on sort seul de l'eau, sans échelle ni marche."}, {"q": "Quand une traction est-elle valide ?", "r": "Bras tendus en bas, menton au-dessus de la barre."}, {"q": "Combien de lancers de commande au maximum au parcours ?", "r": "6."}, {"q": "Pour porter le sac, que fais-tu ?", "r": "Je plie les jambes, dos droit, charge près du corps."}, {"q": "Combien de séances d'entraînement par semaine conseille le cours ?", "r": "2 à 3 séances régulières plutôt qu'une grosse."}, {"q": "Que fais-tu la veille et le jour du brevet ?", "r": "Bien dormir, manger léger 2 à 3 h avant, boire, s'échauffer."}], "quiz": [{"q": "Pour valider les épreuves sportives, il faut au minimum…", "bonne": "3 A et 1 B", "fausses": ["4 A", "2 A et 2 B", "1 A et 3 B"], "expl": "RNE, module APS."}, {"q": "Au parcours sportif, les lancers de commande sont limités à…", "bonne": "6", "fausses": ["3", "10", "Illimités"], "expl": ""}, {"q": "À l'épreuve de natation, le JSP…", "bonne": "Nage 50 m sans s'arrêter puis sort seul", "fausses": ["Peut s'accrocher à la ligne d'eau", "Sort par l'échelle", "Nage uniquement en crawl"], "expl": ""}, {"q": "Une traction est valide quand…", "bonne": "Le menton passe au-dessus de la barre, bras tendus en bas", "fausses": ["Le front touche la barre", "On monte à moitié", "On s'aide des jambes"], "expl": "Prise en supination."}, {"q": "Pour porter le sac du parcours, je…", "bonne": "Plie les jambes et garde le dos droit", "fausses": ["Me penche dos rond", "Tourne le dos en portant", "Tiens le sac bras tendus"], "expl": "PRAP."}, {"q": "Bien s'entraîner, c'est…", "bonne": "Régulièrement et progressivement, avec récupération", "fausses": ["Une grosse séance la veille", "Sans échauffement", "Sans jamais se reposer"], "expl": ""}], "statut": "brouillon", "source": "Cours 2026 « La préparation physique aux épreuves du brevet » (charte SDIS 34) · RNF JSP/JMP v1.1 APS A2 · Référentiel national d'évaluation JSP/JMP v1.1 (avril 2026), module APS et « Règlement technique des épreuves physiques » p. 33-37 (barèmes p. 37, à reproduire à l'identique) — conseils d'entraînement à valider par un EAP"}, "JSP4|L'intégration en centre d'incendie et de secours": {"cycle": "JSP4", "bloc": "Organisation et missions du SIS", "item": "L'intégration en centre d'incendie et de secours", "objectif": "Expliquer les conditions et les étapes pour devenir SPV, le parcours après l'engagement (formation, grades, disponibilités) et jouer correctement une situation de « premier jour au centre » — 40 min.", "pointsCles": ["Le SDIS 34 : 5 396 agents dont 4 276 volontaires et 859 professionnels, 85 000 interventions en 2025 (233 par jour), 350 JSP dans 17 sections (chiffres 2026, à revérifier)", "Conditions : de 16 à 55 ans (accord écrit des parents avant 18 ans), résider légalement en France, jouir de ses droits civiques, être apte (visite médicale), signer la charte du SPV", "Procédure : se présenter au chef de centre, compléter le dossier, visite médicale, avis du comité de centre puis décision du SDIS, engagement de 5 ans renouvelable", "Journée d'intégration : accueil, lecture de la charte, disponibilité et outils, parcours de formation, remise de l'écusson ; visite de la salle des appels et ateliers", "Formation initiale : journée d'intégration puis équipier prompt secours, incendie, VSAV, feux de forêts, interventions diverses, secours routiers… puis formation toute la carrière (FMA)", "Le brevet de JSP permet de valider une partie de la formation initiale (équivalences à préciser avec le service formation)", "Grades : sapeur 2e classe à l'engagement, sapeur 1re classe après 1 an, caporal après 3 ans, caporal-chef après 3 ans de caporal ; avancement selon ancienneté, formations et avis du comité de centre", "Disponibilité : garde postée, astreinte (prêt à partir dès que le bip sonne), disponible ; tenir ses disponibilités à jour (Webdag)", "Réussir son arrivée : se présenter, écouter et observer, oser demander, participer, être fiable, rendre compte (matériel, erreur, blessure)", "Échanges entre générations : les anciens apportent l'expérience du terrain, les jeunes des connaissances récentes et un regard neuf"], "materiel": "Post-it, paperboard, dossier d'engagement SPV, charte du sapeur-pompier volontaire, règlement intérieur du SDIS 34, cartes de jeux de rôle ; idéalement intervention du chef de centre ou d'un jeune SPV ancien JSP de la section.", "activites": [{"titre": "Mes craintes, mes envies", "duree": "8 min", "prep": "Post-it de deux couleurs.", "deroule": ["Chaque JSP note anonymement une crainte et une envie pour son arrivée au centre.", "On les colle au tableau ; on y répondra pendant la séance."], "phrase": "", "securite": "Anonymat respecté."}, {"titre": "Le parcours en cartes", "duree": "15 min", "prep": "Cartes mélangées : étapes de l'engagement (chef de centre, dossier, visite médicale, comité de centre, engagement 5 ans, journée d'intégration) et grades (sapeur 2e classe, 1re classe, caporal, caporal-chef).", "deroule": ["Par équipes, remettre les étapes dans l'ordre.", "Puis placer les grades avec le temps nécessaire.", "Correction avec le chef de centre ou l'animateur."], "phrase": "Parles-en tôt au chef de centre : il connaît déjà ton travail de JSP.", "securite": ""}, {"titre": "Mon premier jour au centre", "duree": "17 min", "prep": "4 cartes : première manœuvre, ancien qui montre une technique différente, disponibilités oubliées, matériel abîmé à l'entretien.", "deroule": ["En binôme, un JSP joue le nouveau, l'autre l'ancien ou le chef d'agrès, 3 minutes par cas.", "Débriefing collectif : se présenter, écouter, demander poliment, prévenir, rendre compte.", "Pour finir, on relit les post-it et on vérifie qu'on a répondu à chaque crainte."], "phrase": "Mieux vaut poser une question que faire une erreur.", "securite": ""}], "questions": [{"q": "À partir de quel âge peut-on devenir SPV ?", "r": "16 ans, avec l'accord des parents avant 18 ans."}, {"q": "Combien de temps dure un engagement ?", "r": "5 ans, renouvelable."}, {"q": "Quel est le premier module de la formation initiale ?", "r": "La journée d'intégration, puis l'équipier prompt secours."}, {"q": "Être d'astreinte, c'est quoi ?", "r": "Être prêt à partir dès que le bip sonne."}, {"q": "Après combien de temps devient-on sapeur 1re classe ?", "r": "Après 1 an."}, {"q": "Qui donne son avis sur l'engagement ?", "r": "Le comité de centre, puis le SDIS décide."}, {"q": "J'ai abîmé du matériel : je fais quoi ?", "r": "Je rends compte tout de suite au responsable."}, {"q": "Un ancien montre une technique différente du cours JSP ?", "r": "J'écoute, je demande poliment pourquoi, j'en parle ensuite au formateur."}], "quiz": [{"q": "Un engagement de SPV dure…", "bonne": "5 ans, renouvelable", "fausses": ["1 an", "10 ans", "Toute la vie"], "expl": ""}, {"q": "À l'engagement, le grade est…", "bonne": "Sapeur 2e classe", "fausses": ["Caporal", "Sapeur 1re classe", "Sergent"], "expl": "1re classe après 1 an."}, {"q": "Être prêt à partir de chez soi dès que le bip sonne, c'est…", "bonne": "L'astreinte", "fausses": ["La garde postée", "Le congé", "La FMA"], "expl": ""}, {"q": "Qui faut-il aller voir en premier pour s'engager ?", "bonne": "Le chef de centre", "fausses": ["Le préfet", "Le maire", "Le CTA-CODIS"], "expl": ""}, {"q": "Tu as abîmé un matériel à l'entretien :", "bonne": "Tu rends compte tout de suite", "fausses": ["Tu le ranges sans rien dire", "Tu attends qu'on le remarque", "Tu le répares seul en cachette"], "expl": "L'honnêteté passe avant la gêne."}, {"q": "Au SDIS 34, la majorité des agents sont…", "bonne": "Des volontaires", "fausses": ["Des militaires", "Des administratifs", "Des professionnels"], "expl": "4 276 SPV sur 5 396 agents."}], "statut": "brouillon", "source": "Cours 2026 « L'intégration en centre d'incendie et de secours » (charte SDIS 34) · RNF JSP/JMP v1.1 SC B1 · SDIS 34 – « Documents de la matinée de la journée d'intégration SPV » (2026) · Charte du sapeur-pompier volontaire — chiffres et procédures SDIS 34 à revérifier auprès du chef de centre"}}, "seances": {"2026-09-27": {"deroule": [{"duree": "10'", "quoi": "Rassemblement devant les engins", "comment": "Appel, tenue, consignes : on n'ouvre rien sans encadrant, on reste hors de la zone de manœuvre."}, {"duree": "45'", "quoi": "Ateliers par niveau (1 encadrant / groupe)", "comment": "Accroche 5' → découverte active 25' → défi / évaluation 10' → retour 5'."}, {"duree": "10'", "quoi": "Pause", "comment": "Eau, on remet en place le matériel sorti."}, {"duree": "10'", "quoi": "« Prof d'un jour »", "comment": "Chaque niveau explique en 3' ses 3 idées clés aux autres."}, {"duree": "20'", "quoi": "Exercice fil rouge commun", "comment": "« Feu dans un garage, fumées vers la route » : JSP 4 fumées et sécurité, JSP 3 les moyens, JSP 2 l'établissement."}, {"duree": "10'", "quoi": "Débriefing + rangement", "comment": "1 mot par JSP : « ce que je retiens ». Tuyaux rincés, séchés, reconditionnés."}], "materiel": "Tuyaux 45/70, division, lance, protège-tuyaux, rubalise, lingettes + savon + gants, sac EPI sales, tablette avec photos, ardoises, chrono.", "notes": "Déroulé prévu pour 1 encadrant par niveau."}, "2026-10-04": {"deroule": [{"duree": "10'", "quoi": "Rassemblement", "comment": "Appel, tenue, consignes. Annonce du programme : cours puis Hyrox caserne."}, {"duree": "45'", "quoi": "Cours par niveau (1 encadrant / groupe)", "comment": "JSP 2 établissements de lances · JSP 3 explosimétrie et fluides · JSP 4 traces et indices. Voir les fiches."}, {"duree": "10'", "quoi": "Pause + mise en tenue de sport", "comment": "Eau, gourdes remplies. Rangement du matériel des ateliers."}, {"duree": "10'", "quoi": "Hyrox — échauffement", "comment": "Footing 3', mobilité chevilles / hanches / épaules, 5 squats + 5 fentes + 3 burpees lents, 2 accélérations. Démonstration de chaque geste."}, {"duree": "25'", "quoi": "Hyrox caserne — 1 tour", "comment": "5 × (200 m de course + 1 station) : burpees, air squats, fentes, mountain climbers, sit-ups. Chacun choisit son niveau R / S / C avant de partir. Départs par binômes toutes les 30 s : l'un travaille, l'autre compte et vérifie le geste, puis on inverse (2e vague)."}, {"duree": "5'", "quoi": "Retour au calme", "comment": "Marche, étirements doux, on boit."}, {"duree": "10'", "quoi": "Débriefing + rangement", "comment": "1 mot par JSP. Noter le niveau choisi et le temps de chacun pour la prochaine fois."}], "materiel": "Affiche Hyrox caserne + 5 repères de station, plots pour la boucle de 200 m (dans l'enceinte de la caserne, jamais sur la route), chrono ou tablette, tapis ou sol propre pour sit-ups et burpees, eau. Matériel des cours : voir les fiches.", "notes": "Hyrox : qualité du geste avant la vitesse, douleur = arrêt immédiat. Repères de niveau : Reprise pour ceux qui reprennent ou les moins à l'aise, Standard pour la majorité, Confirmé seulement si le geste est propre (souvent les JSP 4). Un encadrant sur la boucle, un aux stations. Sit-ups : le binôme tient les pieds. Fentes : le genou arrière frôle le sol sans taper."}}};
